/* T-978 review fold (2026-11-03) wiring: B2 only toward this game's own player character, keeping the parked line and noting the
   start; the drain re-finds both characters by id, re-checks the NPC's game, counts the 30 s from the window emptying and puts the
   parked line back before the engine's talk event; the slot is emptied at the teardown; the later of two same-frame opens is refused
   in setInDialog before anything else runs and ended at the safe point; the portrait refresh is skipped on both roads; the forwarded
   conversations hold their NPC from the forwarded table's insert to every erase, with a back-stop; the counters reach the REPORT */
/* T978Def: the body of a function also declared earlier (its definition: the signature followed by a line-start brace) */
static std::string T978Def(const std::string& src, const char* sig)
{
    const std::string a = T978Body(src, (std::string(sig) + "\r\n{").c_str());
    return a.empty() ? T978Body(src, (std::string(sig) + "\n{").c_str()) : a;
}
void t_t978_fold_wiring()
{
    const std::string sp = T313ReadFile("../coop-plugin/speech.cpp");
    if (sp.empty()) { Fail("t978 fold wiring: could not read speech.cpp"); return; }
    const std::string sb = T978Body(sp, "unsigned long long detour_startPlayerConv(void* dlg, void* who, void* line)");
    const size_t keep = sb.find("OwQueueKeep(SayReadPtr(dlg, kDlgMe), who, kept)");
    if (sb.find("const int towardMine = TkOrderIsMine(who);") == std::string::npos || sb.find("talkonewin::KeptLine(line, SayReadPtr(dlg, kDlgParkedLine))") == std::string::npos
        || keep == std::string::npos || sb.find("if (towardMine) OwStartNote(dlg, who, kept);") == std::string::npos || sb.find("(g_tkOn && TkPeerTarget(who)) ? 1 : 0))") != std::string::npos)
        Fail("t978 fold wiring: B2 is not limited to this game's own player character, or does not keep the parked line / note the start");
    if (sp.find("const size_t kDlgParkedLine = 0xC8;") == std::string::npos) Fail("t978 fold wiring: the parked line's offset");
    const std::string db = T978Body(sp, "static void TalkOneWinDrain()");
    const size_t put = db.find("SayWritePtr(ndlg, kDlgParkedLine, const_cast<void*>(q.line))"), send = db.find("TalkSendPod(");
    if (db.find("OwEndLaterDrain();") == std::string::npos || db.find("FindSpawned(q.npcUid)") == std::string::npos || db.find("FindSpawned(q.whoUid)") == std::string::npos
        || db.find("talkonewin::OwnerSame(q.npcUid, q.npcMine,") == std::string::npos || db.find("talkonewin::EmptySince(q.emptyMs, empty, now)") == std::string::npos
        || db.find("OwQueueSetEmpty(&q, em)") == std::string::npos || db.find("talkonewin::ResendStep(1, now, em, empty,") == std::string::npos
        || put == std::string::npos || send == std::string::npos || put > send || db.find("talkonewin::ParkedLineStep(q.line, SayReadPtr(ndlg, kDlgParkedLine))") == std::string::npos)
        Fail("t978 fold wiring: the drain does not re-find by id, re-check the game, age from the window emptying, or put the parked line back before the talk event");
    const std::string tb = T978Body(sp, "void TalkFreezeWorldTeardown()");
    if (tb.find("OwQueueForget();") == std::string::npos || tb.find("g_owEndLater[k].dlg = 0;") == std::string::npos) Fail("t978 fold wiring: the queued talk is not emptied at the teardown");
    const std::string ib = T978Body(sp, "void detour_setInDialog(void* dlg, bool on)");
    const size_t ro = ib.find("if (on && SayOnMainThread() != 0 && OwRefuseOpen(dlg)) return;");
    if (ro == std::string::npos || ro > ib.find("TalkLogClose(dlg)") || ro > ib.find("orig_setInDialog(dlg, on)") || ro < ib.find("TkMarkSuppresses(dlg)"))
        Fail("t978 fold wiring: the later same-frame open is not refused after the mark test and before the window log and the original");
    const std::string ob = T978Body(sp, "static int OwRefuseOpen(void* dlg)");
    if (ob.find("talkonewin::RefuseOpen(") == std::string::npos || ob.find("OwQueueKeep(me, who,") == std::string::npos || ob.find("g_owEndLater[k].dlg = dlg;") == std::string::npos
        || ob.find("TkOrderIsMine(who)") == std::string::npos)
        Fail("t978 fold wiring: the refused open does not use the rule, queue its talk, or remember its end");
    /* re-check 2026-11-03 c: the start record is taken (and emptied) before either way out - let through or refused */
    const size_t tk = ob.find("const int rec = OwStartTake(dlg, &recWho, &recLine);");
    if (tk == std::string::npos || tk > ob.find("if (!talkonewin::ShownReal(shown) || shown == dlg) return 0;") || ob.find("OwStartFor(") != std::string::npos
        || T978Body(sp, "int OwStartTake(void* dlg, void** who, void** line)").find("g_owStartDlg = 0; g_owStartWho = 0; g_owStartLine = 0;") == std::string::npos)
        Fail("t978 fold wiring: the last-start record is not emptied once its window open is let through or refused");
    /* re-check 2026-11-03 a: the refused conversation's target is remembered, and only that conversation is ended */
    if (ob.find("TkHandWordsPod(who, kCharHand, g_owEndLater[k].tgt);") == std::string::npos) Fail("t978 fold wiring: the refused conversation's target is not remembered");
    const std::string eb = T978Body(sp, "static void OwEndLaterDrain()");
    const size_t idt = eb.find("if (TkMarkFind(dlg) >= 0 || !same)");
    if (eb.find("TkEndEntryPod(") == std::string::npos || eb.find("TkLiveOwner(dlg, me)") == std::string::npos || eb.find("TkWindowDlg() == dlg") == std::string::npos)
        Fail("t978 fold wiring: the refused open is not ended through the hooked entry, or without its owner / window checks");
    if (idt == std::string::npos || idt > eb.find("TkEndEntryPod(") || eb.find("TkHandWordsPod(dlg, kDlgTargetHand, now)") == std::string::npos
        || eb.find("if (now[w] != tgt[w]) same = 0;") == std::string::npos || eb.find("++g_owOpenEndNewer;") == std::string::npos)
        Fail("t978 fold wiring: a newer conversation the NPC started before the safe point would be ended (no mark / target-hand identity test before the end)");
    const std::string pb = T978Body(sp, "void detour_dlgWinPortrait(void* win, void* who, char slot)"), pd = T978Body(sp, "static void PortraitDrain()");
    const size_t ps = pb.find("OwSkipPortraitOn(TkWindowDlg(), who)");
    if (ps == std::string::npos || ps > pb.find("orig_dlgWinPortrait(win, who, slot)") || ps > pb.find("cooppd::Drop(") || pd.find("OwSkipPortraitOn(dlgNow, whoNow)") == std::string::npos
        || pd.find("OwSkipPortraitOn(dlgNow, whoNow)") > pd.find("PortraitCallPod("))
        Fail("t978 fold wiring: the portrait refresh is not skipped before the call-now road's drop and call, or before the replay");
    const std::string sk = T978Body(sp, "int OwSkipPortraitOn(void* shown, void* who)");
    if (sk.find("talkonewin::SkipPortrait(") == std::string::npos) Fail("t978 fold wiring: the portrait rule");
    if (sk.find("TkHandAtIs(shown, kDlgSpeakerHand3, who)") == std::string::npos || sk.find("TkHandAtIs(shown, kDlgSpeakerHand4, who)") == std::string::npos
        || sk.find("TkHandAtIs(shown, kDlgSpeakerHand5, who)") == std::string::npos || sp.find("const size_t kDlgSpeakerHand3   = 0x1C8;") == std::string::npos
        || sp.find("const size_t kDlgSpeakerHand4   = 0x1E8;") == std::string::npos || sp.find("const size_t kDlgSpeakerHand5   = 0x208;") == std::string::npos)
        Fail("t978 fold wiring (re-check 2026-11-03 b): the shown conversation's speakers (hands +0x1C8 / +0x1E8 / +0x208) are not let through");
    const std::string ab = T978Body(sp, "void TkAfterStart(void* dlg, void* who, int started, int ev, int mark, int created)");
    const size_t ins = ab.find("g_tkConvs[dlg] = c;"), frz = ab.find("OwFwdAfterForward(dlg, me, nuid);");
    if (ins == std::string::npos || frz == std::string::npos || frz < ins || ab.find("OwFwdRoad(talkonewin::kRelFwdEnded, dlg, 0);") == std::string::npos)
        Fail("t978 fold wiring: the forwarded hold is not taken after the forwarded table's insert, or not released when a restart replaces it");
    const std::string ob2 = T978Body(sp, "void TkEndOwn(void* dlg, void* me, int sendReason, const char* why, int callEnd, int endsType = 0,");
    if (ob2.find("if (had) OwFwdRoad(talkonewin::kRelFwdEnded, dlg, 0);") == std::string::npos) Fail("t978 fold wiring: the forwarded conversation's end does not release its NPC");
    if (T978Body(sp, "void TalkForgetPeer(unsigned int peer)").find("OwFwdRoad(talkonewin::kRelFwdEnded, own[k].dlg, 0);") == std::string::npos)
        Fail("t978 fold wiring: the link-later erase does not release the forwarded NPC");
    const std::string fb = T978Def(sp, "void OwFwdAfterForward(void* dlg, void* npc, unsigned int uid)");
    if (fb.find("talkonewin::FreezeWhy(") == std::string::npos || fb.find("net::IsUidMine(uid)") == std::string::npos || fb.find("IsSuppressed((::Character*)npc)") == std::string::npos
        || fb.find("SuppressCharacter((::Character*)npc, true)") == std::string::npos)
        Fail("t978 fold wiring: the forwarded freeze does not test as the window's does");
    if (T978Def(sp, "void OwFwdRoad(int road, void* dlg, const void* obj)").find("talkonewin::FwdRoad(road)") == std::string::npos
        || T978Def(sp, "void OwFrzRoad(int road, void* dlg, const void* obj)").find("OwFwdRoad(road, dlg, obj);") == std::string::npos
        || T978Body(sp, "static void OwFrzDrain()").find("OwFwdDrain();") == std::string::npos
        || T978Body(sp, "static void OwFwdDrain()").find("g_tkConvs.find(d) != g_tkConvs.end()") == std::string::npos
        || T978Body(sp, "void TalkFreezeForgetObject(const void* obj)").find("OwFwdHolds(obj)") == std::string::npos)
        Fail("t978 fold wiring: the forwarded holds are not on every existing road, the destroy road or the back-stop");
    if (sp.find("talkOneWin2[dropOwner,linePutBack,lineNewer,openRefused,openEnded,openEndFull,skipPortrait,openEndNewer]") == std::string::npos
        || sp.find("talkFreezeFwd[frozen,notLinked,offMain,notOpen,noNpc,notMine,player,alreadyHeld,alreadyFrozen,full,gateRefused,fwdEnded,backstop,freed,forgot]") == std::string::npos)
        Fail("t978 fold wiring: the fold's counters are not on the [TALK] REPORT");
}

/* T-978 (run T1944: talkFreeze offMain=4): off the main thread the freeze's session test calls neither StoreLiveReady (it runs
   LinkUp, main-thread only - store.cpp review-p5b CRASH-2) nor SessionLinked (CRASH-1): both freezes read 'linked' as 1 there, so
   FreezeWhy answers offMain and the counter stays; every such call sits inside the one gated line */
void t_t978_offmain_session()
{
    namespace tw = talkonewin;
    if (tw::FreezeWhy(1, 0, 0, 0, 0, 0, 0, 0) != tw::kFrzOffMain || tw::FreezeWhy(1, 0, 1, 1, 1, 0, 0, 0) != tw::kFrzOffMain)
        Fail("t978 off-main session: linked=1 off the main thread must answer offMain");
    if (tw::FreezeWhy(0, 1, 1, 1, 1, 0, 0, 0) != tw::kFrzNotLinked || tw::FreezeWhy(1, 1, 1, 1, 1, 0, 0, 0) != tw::kFrzFreeze)
        Fail("t978 off-main session: on the main thread the session test still decides");
    const std::string sp = T313ReadFile("../coop-plugin/speech.cpp");
    if (sp.empty()) { Fail("t978 off-main session: could not read speech.cpp"); return; }
    const char* const sigs[2] = { "static void OwFrzAfterOpen(void* dlg)", "void OwFwdAfterForward(void* dlg, void* npc, unsigned int uid)" };
    const std::string gateText = "const int linked = !onMain ? 1 : ((net::SessionLinked() || coop::StoreLiveReady()) ? 1 : 0);";
    for (int i = 0; i < 2; ++i)
    {
        const std::string b = T978Def(sp, sigs[i]);
        const size_t on = b.find("const int onMain = SayOnMainThread();"), gate = b.find(gateText);
        if (b.empty() || on == std::string::npos || gate == std::string::npos || gate < on)
        {
            Fail(std::string("t978 off-main session: no main-thread gate before the session test in ") + sigs[i]);
            continue;
        }
        const char* const calls[3] = { "StoreLiveReady(", "SessionLinked(", "LinkUp(" };
        for (int c = 0; c < 3; ++c)
            for (size_t p = b.find(calls[c]); p != std::string::npos; p = b.find(calls[c], p + 1))
                if (p < gate || p > gate + gateText.size())
                    Fail(std::string("t978 off-main session: ") + calls[c] + " outside the gated line in " + sigs[i]);
    }
}

/* T-978 BUBBLE (attempt 2, run T1949): the bubble-timer hold's pure decisions, and the T1949 case replayed - a 6.92 s bubble said
   before the window opened, the engine's per-frame step subtracting each frame and ending the conversation when the timer is below 0:
   without the hold it ends at 6.92 s, with the hold (re-applied each frame) it never does in 40 s */
void t_t978_bubble_hold()
{
    namespace tw = talkonewin;
    if (tw::BubbleHoldValue(0.5f) != tw::kBubbleHoldFloor || tw::BubbleHoldValue(6.92f) != 6.92f || tw::kBubbleHoldFloor < 1.0f)
        Fail("t978 bubble: the held value is the timer as the hold began, at least the floor (>= 1 s)");
    volatile float zero = 0.0f;
    const float nan = zero / zero;
    if (tw::BubbleHoldValue(nan) != tw::kBubbleHoldFloor) Fail("t978 bubble: a not-a-number timer holds the floor");
    if (tw::BubbleHoldOn(1, 1, 1, 1, 1, 0, 1) != 1 || tw::BubbleHoldOn(1, 1, 1, 0, 1, 0, 1) != 1)
        Fail("t978 bubble: a live player conversation with a bubble, shown, in a session, is held");
    if (tw::BubbleHoldOn(1, 1, 1, 0, 3, 0, 1) != 1 || tw::BubbleHoldOn(1, 1, 1, 0, 0, 0, 1) != 1)
        Fail("t978 bubble (review fold 2): the window's own hold takes any conversation event (an NPC-started window too)");
    if (tw::BubbleHoldOn(1, 1, 1, 1, 3, 0, 1) || tw::BubbleHoldOn(1, 1, 1, 1, 0, 0, 1))
        Fail("t978 bubble (review fold 2): a forwarded conversation is held only as a player conversation (event 1)");
    if (tw::BubbleHoldOn(0, 1, 1, 0, 1, 0, 1) || tw::BubbleHoldOn(1, 0, 1, 0, 1, 0, 1) || tw::BubbleHoldOn(1, 1, 0, 0, 1, 0, 1)
        || tw::BubbleHoldOn(1, 1, 1, 0, 1, 1, 1) || tw::BubbleHoldOn(1, 1, 1, 0, 1, -1, 1) || tw::BubbleHoldOn(1, 1, 1, 0, 1, 0, 0))
        Fail("t978 bubble: no hold out of a session, off the main thread, not shown, ended / unreadable, or with no bubble");
    int da = 1, db = 2;
    const void* const a = &da;
    const void* const b = &db;
    tw::BubbleHold h = { 0, 0.0f, 0, 0 };
    float o = -9.0f;
    if (tw::BubbleHoldStep(&h, a, 1, 6.92f, &o) != 0 || !h.set || h.dlg != a || h.hold != 6.92f || o != -9.0f) Fail("t978 bubble: the hold begins at the timer, nothing written");
    if (tw::BubbleHoldStep(&h, a, 1, 6.90f, &o) != 1 || o != 6.92f) Fail("t978 bubble: a timer below the held value is written back to it");
    if (tw::BubbleHoldStep(&h, a, 1, 8.0f, &o) != 0) Fail("t978 bubble: a fresh longer bubble (a new say) is left to run down to the held value");
    if (tw::BubbleHoldStep(&h, a, 1, nan, &o) != 1 || o != 6.92f) Fail("t978 bubble: a not-a-number timer is written");
    h.wrote = 1;
    if (tw::BubbleHoldStep(&h, b, 1, 0.3f, &o) != 1 || h.dlg != b || o != tw::kBubbleHoldFloor || h.wrote != 0) Fail("t978 bubble: another Dialogue starts a new hold, at least the floor");
    if (tw::BubbleHoldStep(&h, b, 0, 0.3f, &o) != 0 || h.set || h.dlg != 0) Fail("t978 bubble: the hold stops (the slot empties) when it no longer applies");
    if (tw::BubbleHoldStep(&h, 0, 1, 0.3f, &o) != 0 || h.set) Fail("t978 bubble: no Dialogue, no hold");
    if (tw::BubbleHoldStep(0, a, 1, 0.3f, &o) != 0 || tw::BubbleHoldStep(&h, a, 1, 0.3f, 0) != 0) Fail("t978 bubble: null slot / out");
    /* T1949 replayed: the Barman's 41-character line (2.0 + 0.12 x 41 = 6.92 s), the window opened at once; 30 frames a second */
    for (int held = 0; held < 2; ++held)
    {
        tw::BubbleHold s = { 0, 0.0f, 0, 0 };
        float timer = 2.0f + 0.12f * 41.0f;
        int endedAt = -1;
        for (int fr = 0; fr < 40 * 30 && endedAt < 0; ++fr)
        {
            float put = 0.0f;
            if (held && tw::BubbleHoldStep(&s, a, 1, timer, &put)) timer = put;   /* the safe point */
            timer -= 1.0f / 30.0f;                                                 /* the engine's step, the pause byte clear */
            if (timer < 0.0f) endedAt = fr;                                        /* both timers below 0: endDialogue */
        }
        if (!held && (endedAt < 6 * 30 || endedAt > 7 * 30)) Fail("t978 bubble: the T1949 replay without the hold should end near 6.92 s");
        if (held && endedAt >= 0) Fail("t978 bubble: the T1949 replay with the hold ended the conversation");
    }
}

/* T-978 BUBBLE wiring: the hold runs at every K2 safe point right after the window's NPC hold (OwFrzDrain), on the main thread, not in a
   blocked world; it reads the window's own Dialogue (TkWindowDlg) and the open forwarded ones (g_tkConvs); it tests +0x188 / +0x148 /
   +0x228 through the guarded readers and writes only +0x230 (never +0x234) under __try; the teardown empties it; the counters are on
   the [TALK] REPORT. Text read through T313ReadFile has its CR characters erased (the bench builds from a CRLF checkout). */
void t_t978_bubble_wiring()
{
    std::string sp = T313ReadFile("../coop-plugin/speech.cpp");
    if (sp.empty()) { Fail("t978 bubble wiring: could not read speech.cpp"); return; }
    sp.erase(std::remove(sp.begin(), sp.end(), '\r'), sp.end());
    if (sp.find("const size_t kDlgBubble         = 0x228;") == std::string::npos || sp.find("const size_t kDlgBubbleTimer    = 0x230;") == std::string::npos)
        Fail("t978 bubble wiring: the bubble (+0x228) and its timer (+0x230) offsets");
    const std::string dr = T978Body(sp, "void TalkTestDrain()\n{");
    const size_t fz = dr.find("    OwFrzDrain();"), bh = dr.find("    OwBubbleHoldTick();");
    if (fz == std::string::npos || bh == std::string::npos || bh < fz || bh > dr.find("g_talkTestPending"))
        Fail("t978 bubble wiring: the hold is not at the K2 safe point right after the window's NPC hold");
    const std::string tk = T978Body(sp, "static void OwBubbleHoldTick()\n{");
    const size_t g = tk.find("if (SayOnMainThread() == 0 || EngineWritesBlocked()) return;");
    if (tk.empty() || g == std::string::npos || g > tk.find("TkWindowDlg()") || tk.find("void* const w = TkWindowDlg();") == std::string::npos
        || tk.find("OwBubbleOnNow(shows ? w : 0, shows, winSession, 0, &now, &ev)") == std::string::npos
        || tk.find("OwBubbleApply(&g_bhWin, shows ? w : 0, on, now, ev, 0);") == std::string::npos)
        Fail("t978 bubble wiring: the window's hold is not on the main thread, or not on the window's own Dialogue (any event)");
    /* review fold 1: the window's hold also stands while its opening pause was skipped (a link dropped mid-window) */
    const size_t lk = tk.find("const int linked = (net::SessionLinked() || coop::StoreLiveReady()) ? 1 : 0;"),
                 ws = tk.find("const int winSession = (linked || coop::StoreDlgPauseSkipped()) ? 1 : 0;");
    if (lk == std::string::npos || ws == std::string::npos || ws < lk || ws > tk.find("OwBubbleOnNow(shows ? w : 0"))
        Fail("t978 bubble wiring (fold 1): the window's session test is not 'linked or its opening pause was skipped'");
    std::string st2 = T313ReadFile("../coop-plugin/store.cpp");
    st2.erase(std::remove(st2.begin(), st2.end(), '\r'), st2.end());
    if (st2.find("int StoreDlgPauseSkipped() { return g_dlgPauseSuppressed != 0 ? 1 : 0; }") == std::string::npos)
        Fail("t978 bubble wiring (fold 1): the getter does not read T-288's g_dlgPauseSuppressed");
    if (tk.find("g_tkConvs.find(d) == g_tkConvs.end()") == std::string::npos || tk.find("OwBubbleOnNow(d, 1, linked, 1, &now, &ev)") == std::string::npos
        || tk.find("++g_bhFwdFull;") == std::string::npos)
        Fail("t978 bubble wiring: the forwarded conversations' holds (event 1 only, linked; their stop when the conversation leaves the table)");
    const std::string on = T978Body(sp, "static int OwBubbleOnNow(void* dlg, int shown, int inSession, int needEvent1, float* now, int* ev)\n{");
    if (on.find("*ev = TkReadIntPod(dlg, kDlgConvEvent);") == std::string::npos
        || on.find("talkonewin::BubbleHoldOn(inSession, SayOnMainThread(), shown, needEvent1, *ev, TkReadBytePod(dlg, kDlgEnded),") == std::string::npos
        || on.find("(SayReadPtr(dlg, kDlgBubble) != 0) ? 1 : 0)") == std::string::npos || on.find("OwBubbleTimerPod(dlg, now, 0)) { ++g_bhReadFail;") == std::string::npos)
        Fail("t978 bubble wiring: the hold's test does not read the conversation event, the ended flag and the bubble through the guarded readers");
    const std::string ap = T978Body(sp, "static void OwBubbleApply(talkonewin::BubbleHold* h, void* dlg, int on, float now, int ev, int fwd)\n{");
    const size_t st = ap.find("talkonewin::BubbleHoldStep(h, dlg, on, now, &put)"), wr = ap.find("OwBubbleTimerPod(dlg, &put, 1)) { ++g_bhWriteFail;");
    const char* const after[4] = { "++g_bhWinWrites;", "++g_bhWinHeld;", "++g_bhFwdWrites;", "++g_bhFwdHeld;" };
    int order = (st != std::string::npos && wr != std::string::npos && wr > st) ? 1 : 0;
    for (int k = 0; k < 4 && order; ++k) if (ap.find(after[k]) == std::string::npos || ap.find(after[k]) < wr) order = 0;
    if (!order) Fail("t978 bubble wiring: the write follows the decision, and the window's and the forwarded counters follow the write");
    if (ap.find("(conversation event %d)") == std::string::npos) Fail("t978 bubble wiring (fold 2): the bubble line carries the conversation event");
    const std::string pd = T978Body(sp, "static int OwBubbleTimerPod(void* dlg, float* io, int write)\n{");
    if (pd.find("__try") == std::string::npos || pd.find("kDlgBubbleTimer") == std::string::npos || pd.find("0x234") != std::string::npos)
        Fail("t978 bubble wiring: the timer is read and written only at +0x230, under __try");
    const std::string td = T978Body(sp, "void TalkFreezeWorldTeardown()\n{");
    if (td.find("g_bhWin.set = 0;") == std::string::npos || td.find("g_bhFwd[k].set = 0;") == std::string::npos)
        Fail("t978 bubble wiring: the teardown does not empty the bubble holds");
    if (sp.find("talkBubbleHold[windowHeld,windowWrites,fwdHeld,fwdWrites,fwdFull,readFail,writeFail]=") == std::string::npos)
        Fail("t978 bubble wiring: the hold's counters are not on the [TALK] REPORT");
}

/* T-978 TEST-ONLY lever npcsay (owner 1463 a): the verb, its declaration and its code exist in a DEV build only; the pick is this
   game's own living non-player NPC and the say checks again that this game runs it; the line is the engine's own say at its entry
   (row DialogueSay - through the hook, so detour_say sends it as the NPC's own line) under __try; it is said at the K2 safe point
   before the bubble hold's tick. CR erased (CRLF checkout). */
static bool T978InDevBlock(const std::string& s, size_t at)   /* the nearest directive above `at` is #ifdef SW_DEV_BUILD */
{
    if (at == std::string::npos) return false;
    const size_t ifd = s.rfind("#ifdef SW_DEV_BUILD", at);
    const size_t end = s.rfind("#endif", at);
    const size_t els = s.rfind("#else", at);
    return ifd != std::string::npos && (end == std::string::npos || end < ifd) && (els == std::string::npos || els < ifd);
}
void t_t978_npcsay_lever()
{
    std::string sp = T313ReadFile("../coop-plugin/speech.cpp");
    if (sp.empty()) { Fail("t978 npcsay: could not read speech.cpp"); return; }
    sp.erase(std::remove(sp.begin(), sp.end(), '\r'), sp.end());
    const char* const sigArm = "std::string NpcSayArm(const std::string& arg)\n{";
    const char* const sigDrain = "static void NpcSayDrain()\n{";
    const char* const sigPod = "int NpcSayCallPod(void* dlg, const std::string* text)\n{";
    if (!T978InDevBlock(sp, sp.find(sigArm)) || !T978InDevBlock(sp, sp.find(sigDrain)) || !T978InDevBlock(sp, sp.find(sigPod)))
        Fail("t978 npcsay: the lever's code is DEV-only");
    const std::string a = T978Body(sp, sigArm);
    if (a.find("LeverNearestNamed(nameKey, kLeverPickOwnLiving, 0, kNpcSayNear, &nu, &nd, &nn, &why)") == std::string::npos
        || a.find("if (kDialogueSayRva == 0 || g_base == 0)") == std::string::npos)
        Fail("t978 npcsay: the pick is this game's own living non-player NPC, refused with no say row");
    const std::string d = T978Body(sp, sigDrain);
    const size_t mine = d.find("else if (!net::IsUidMine(u))"), call = d.find("NpcSayCallPod(dlg, &g_npcSayText)");
    if (d.find("if (EngineWritesBlocked())") == std::string::npos || mine == std::string::npos || call == std::string::npos || mine > call
        || d.find("SayReadPtr(dlg, kDlgMe) != (void*)c") == std::string::npos)
        Fail("t978 npcsay: the say runs only on the NPC's own game, on its own Dialogue, with the world loaded");
    const std::string p = T978Body(sp, sigPod);
    if (p.find("__try") == std::string::npos || p.find("((SayFn)(g_base + (uintptr_t)kDialogueSayRva))(dlg, *text, 0);") == std::string::npos)
        Fail("t978 npcsay: the line is the engine's own say at its entry, under __try");
    const std::string dr = T978Body(sp, "void TalkTestDrain()\n{");
    const size_t ns = dr.find("    NpcSayDrain();"), bh = dr.find("    OwBubbleHoldTick();");
    if (ns == std::string::npos || bh == std::string::npos || ns > bh || !T978InDevBlock(dr, ns))
        Fail("t978 npcsay: said at the K2 safe point (DEV-only), before the bubble hold's tick");
    std::string h = T313ReadFile("../coop-plugin/speech.h");
    h.erase(std::remove(h.begin(), h.end(), '\r'), h.end());
    if (!T978InDevBlock(h, h.find("std::string NpcSayArm(const std::string& arg);"))) Fail("t978 npcsay: the declaration is DEV-only");
    std::string c = T313ReadFile("../coop-plugin/command_channel.cpp");
    c.erase(std::remove(c.begin(), c.end(), '\r'), c.end());
    const size_t v = c.find("else if (verb == \"npcsay\")");
    if (!T978InDevBlock(c, v) || c.find("WriteStatus(coop::NpcSayArm(Trim(arg)));", v) == std::string::npos)
        Fail("t978 npcsay: the verb is DEV-only and arms the lever");
}

/* T-478 step 5 (T2017: B's confirm stayed disabled - the slaver's squad money below the price). The TEST-ONLY npcmoney lever's gate
   (coopsquad::NpcMoneyGate: the order of its refusals - a copy and a squad another game leads are refused), the B END line's money
   words (cooptalk::TalkSellCheapest / TalkSellMoneyWord), and the wiring: the verb and its code DEV-only, the write keepermoney's
   own (KeeperPotWritePod) after the gate, the pot marked known and announced, the END line's fields. CR erased (CRLF checkout). */
void t_t478_npcmoney()
{
    using namespace coopsquad;
    if (NpcMoneyGate(10000, 1, 1, 1, 1, 0) != kNpcMoneyOk || NpcMoneyGate(0, 1, 1, 1, 1, 0) != kNpcMoneyOk || NpcMoneyGate(kNpcMoneyMax, 1, 1, 1, 1, 0) != kNpcMoneyOk)
        Fail("t478 npcmoney: this game's own NPC squad, led here, its pot read, no shop record - set (0 and the max included)");
    if (NpcMoneyGate(-1, 1, 1, 1, 1, 0) != kNpcMoneyBadAmount || NpcMoneyGate(kNpcMoneyMax + 1, 1, 1, 1, 1, 0) != kNpcMoneyBadAmount
        || NpcMoneyGate(-1, 0, 0, 0, 0, 1) != kNpcMoneyBadAmount)
        Fail("t478 npcmoney: an amount outside 0..max is refused first");
    if (NpcMoneyGate(10000, 0, 0, 0, 0, 0) != kNpcMoneyNotHere || NpcMoneyGate(10000, 0, 1, 1, 1, 0) != kNpcMoneyNotHere)
        Fail("t478 npcmoney: no live character - refused");
    if (NpcMoneyGate(10000, 1, 0, 1, 1, 0) != kNpcMoneyCopy || NpcMoneyGate(10000, 1, 0, 0, 0, 1) != kNpcMoneyCopy)
        Fail("t478 npcmoney: a copy here is refused (the runner's game sets it), before the leader is asked");
    if (NpcMoneyGate(10000, 1, 1, 0, 1, 0) != kNpcMoneyLeaderCopy)
        Fail("t478 npcmoney: our own member of a squad another game leads is refused (that game announces the pot)");
    if (NpcMoneyGate(10000, 1, 1, 1, 0, 0) != kNpcMoneyNoPot || NpcMoneyGate(10000, 1, 1, 1, 0, 1) != kNpcMoneyNoPot)
        Fail("t478 npcmoney: a pot that is not an NPC squad's (player faction, stand-in, no squad) is refused");
    if (NpcMoneyGate(10000, 1, 1, 1, 1, 1) != kNpcMoneyShopRecord) Fail("t478 npcmoney: a keeper squad a shop record carries is keepermoney's");
    if (std::string(NpcMoneyWhy(kNpcMoneyCopy)).find("the game that runs it must set it") == std::string::npos
        || std::string(NpcMoneyWhy(kNpcMoneyShopRecord)).find("keepermoney") == std::string::npos || std::string(NpcMoneyWhy(99)) != "?")
        Fail("t478 npcmoney: the refusal words");
    using namespace cooptalk;
    const int p3[] = { 1250, 500, 2500 }, pNeg[] = { -1, 700 }, pNone[] = { -1, -5 };
    if (TalkSellCheapest(p3, 3) != 500 || TalkSellCheapest(pNeg, 2) != 700 || TalkSellCheapest(pNone, 2) != -1 || TalkSellCheapest(p3, 0) != -1)
        Fail("t478 npcmoney: the cheapest row is the lowest non-negative price, -1 for none");
    if (std::string(TalkSellMoneyWord(1, 10000, 500)) != "covers" || std::string(TalkSellMoneyWord(1, 500, 500)) != "covers"
        || std::string(TalkSellMoneyWord(1, 499, 500)) != "short" || std::string(TalkSellMoneyWord(0, 10000, 500)) != "unread"
        || std::string(TalkSellMoneyWord(1, 10000, -1)) != "unread")
        Fail("t478 npcmoney: covers when the pot pays the cheapest row (equal included, as the refresh's <=), short below, unread unknown");
    std::string it = T313ReadFile("../coop-plugin/items.cpp"), cc = T313ReadFile("../coop-plugin/command_channel.cpp"), sp = T313ReadFile("../coop-plugin/speech.cpp");
    if (it.empty() || cc.empty() || sp.empty()) { Fail("t478 npcmoney: could not read items.cpp / command_channel.cpp / speech.cpp"); return; }
    it.erase(std::remove(it.begin(), it.end(), '\r'), it.end());
    cc.erase(std::remove(cc.begin(), cc.end(), '\r'), cc.end());
    sp.erase(std::remove(sp.begin(), sp.end(), '\r'), sp.end());
    const char* const sig = "std::string NpcMoneyCommand(long long amount, const std::string& who)\n{";
    if (!T978InDevBlock(it, it.find(sig))) Fail("t478 npcmoney: the lever's code is DEV-only");
    const std::string b = T978Body(it, sig);
    const size_t gate = b.find("if (g != coopsquad::kNpcMoneyOk)"), write = b.find("KeeperPotWritePod(own, (int)amount)"),
                 mark = b.find("KeeperMoneyKnownMark(own, coopsquad::kMoneyEvRestockHere);"), ann = b.find("SquadCatsAnnounceNow((void*)leader);");
    if (gate == std::string::npos || write == std::string::npos || mark == std::string::npos || ann == std::string::npos || !(gate < write && write < mark && mark < ann))
        Fail("t478 npcmoney: gate, then keepermoney's write, then the known mark, then the announcement");
    if (b.find("KeeperPot((void*)leader, &own, &before)") == std::string::npos || b.find("net::IsUidMine(leaderUid)") == std::string::npos
        || b.find("net::IsUidMine(uid)") == std::string::npos)
        Fail("t478 npcmoney: the pot is the formal leader's, and both the named character and the leader must be run here");
    const size_t v = cc.find("else if (verb == \"npcmoney\")");
    if (!T978InDevBlock(cc, v) || cc.find("WriteStatus(coop::NpcMoneyCommand(amount, Trim(rest)));", v) == std::string::npos)
        Fail("t478 npcmoney: the verb is DEV-only and runs the lever");
    if (sp.find("\" slaverMoney=\" + (haveSlaverMoney != 0 ? TkI(slaverMoney) : std::string(\"unread\"))") == std::string::npos
        || sp.find("\" cheapestPrice=\" + TkI(cheapest)") == std::string::npos || sp.find("cooptalk::TalkSellMoneyWord(haveSlaverMoney, slaverMoney, cheapest)") == std::string::npos)
        Fail("t478 npcmoney: B's END line says the slaver's money, the cheapest price and the word");
}

#include "leverpick.h"   /* T-1218 (owner 1440 a): the one-target rule for TEST-ONLY picks by name, key or template */
/* T-1218: none / one / several / #k; the #k selector's forms; nearest-first and load order; an exact key's tier wins; the refusal
   words name the count and the first five matches */
void t_t1218_leverpick()
{
    namespace lp = leverpick;   /* qualified: short names like kNone / kOne exist elsewhere in the suite */
    std::string b; int k = -7;
    if (lp::SplitSelector("Dust Bandit", &b, &k) != 0 || b != "Dust Bandit" || k != 0) Fail("t1218 leverpick: no selector - the whole text, k 0");
    if (lp::SplitSelector("Dust Bandit#2", &b, &k) != 1 || b != "Dust Bandit" || k != 2) Fail("t1218 leverpick: Dust Bandit#2 - the 2nd");
    if (lp::SplitSelector("dust bandit #12", &b, &k) != 1 || b != "dust bandit" || k != 12) Fail("t1218 leverpick: a space before #12 is cut");
    if (lp::SplitSelector("wall#0", &b, &k) != -1 || lp::SplitSelector("wall#", &b, &k) != -1 || lp::SplitSelector("wall#1000", &b, &k) != -1
        || lp::SplitSelector("#3", &b, &k) != -1)
        Fail("t1218 leverpick: #0, a bare #, #1000 and no text before # are malformed");
    if (lp::SplitSelector("wall#0", &b, &k) != -1 || b != "wall#0" || k != 0) Fail("t1218 leverpick: a malformed selector leaves the text whole");
    if (lp::SplitSelector("a#b2", &b, &k) != 0 || b != "a#b2" || k != 0) Fail("t1218 leverpick: a # followed by other text is part of the text");
    if (lp::Verdict(0, 0) != lp::kNone || lp::Verdict(0, 2) != lp::kNone || lp::Verdict(1, 0) != lp::kOne || lp::Verdict(2, 0) != lp::kSeveral || lp::Verdict(1, 1) != lp::kOne
        || lp::Verdict(3, 2) != lp::kOne || lp::Verdict(3, 3) != lp::kOne || lp::Verdict(3, 4) != lp::kOutOfRange || lp::Verdict(1, 2) != lp::kOutOfRange)
        Fail("t1218 leverpick: the rule - none, one, several, #k in range, #k out of range");
    {   /* none: nothing set */
        lp::Picker<int> p(0); int out = -1; std::string why = "x";
        if (p.Decide(&out, "characters named 'x'", "nearest first", &why) != lp::kNone || out != -1 || why != "x" || p.Count() != 0)
            Fail("t1218 leverpick: no match - kNone, nothing set");
    }
    {   /* one */
        lp::Picker<int> p(0); p.Add(7, 1, 42.0, "a"); int out = -1; std::string why;
        if (p.Decide(&out, "characters named 'x'", "nearest first", &why) != lp::kOne || out != 7 || !why.empty()) Fail("t1218 leverpick: one match - picked");
    }
    const double d[7] = { 50, 10, 30, 70, 20, 60, 40 };
    const char* const nm[7] = { "n0", "n1", "n2", "n3", "n4", "n5", "n6" };
    {   /* several: refused, the count and the first five nearest first */
        lp::Picker<int> p(0); for (int i = 0; i < 7; ++i) p.Add(i, 1, d[i], nm[i]);
        int out = -1; std::string why;
        if (p.Decide(&out, "characters named 'x'", "nearest first", &why) != lp::kSeveral || out != -1
            || why != "7 characters named 'x' match (nearest first): n1, n4, n2, n6, n0 and 2 more - exactly one must match; add #1..#7 to pick one")
            Fail("t1218 leverpick: several - refused naming 7 and the five nearest: " + why);
    }
    {   /* #k: the k-th in the stable order; past the end refused naming the count */
        lp::Picker<int> p3(3), p7(7), p8(8);
        for (int i = 0; i < 7; ++i) { p3.Add(i, 1, d[i], nm[i]); p7.Add(i, 1, d[i], nm[i]); p8.Add(i, 1, d[i], nm[i]); }
        int o3 = -1, o7 = -1, o8 = -1; std::string w3, w7, w8;
        if (p3.Decide(&o3, "w", "nearest first", &w3) != lp::kOne || o3 != 2 || p7.Decide(&o7, "w", "nearest first", &w7) != lp::kOne || o7 != 3)
            Fail("t1218 leverpick: #3 is the third nearest, #7 the farthest");
        if (p8.Decide(&o8, "characters named 'x'", "nearest first", &w8) != lp::kOutOfRange || o8 != -1
            || w8 != "#8 asked but only 7 characters named 'x' match (nearest first): n1, n4, n2, n6, n0 and 2 more")
            Fail("t1218 leverpick: #8 of 7 - refused naming the count: " + w8);
    }
    {   /* load order: equal orders keep the order added */
        lp::Picker<int> p(2); p.Add(5, 1, 0.0, "a"); p.Add(6, 1, 0.0, "b"); p.Add(7, 1, 0.0, "c");
        int out = -1; std::string why;
        if (p.Decide(&out, "w", "load order", &why) != lp::kOne || out != 6) Fail("t1218 leverpick: #2 in load order is the second added");
        lp::Picker<int> q(0); q.Add(5, 1, 0.0, "a"); q.Add(6, 1, 0.0, "b");
        if (q.Decide(&out, "buildings whose key contains 'w'", "load order", &why) != lp::kSeveral
            || why != "2 buildings whose key contains 'w' match (load order): a, b - exactly one must match; add #1..#2 to pick one")
            Fail("t1218 leverpick: two keys - refused in load order: " + why);
    }
    {   /* an exact key (tier 0) wins over substring matches (tier 1); two exact ones are still several */
        lp::Picker<int> p(0); p.Add(1, 1, 0.0, "wall_a"); p.Add(2, 0, 0.0, "wall"); p.Add(3, 1, 0.0, "wall_b");
        int out = -1; std::string why;
        if (p.Decide(&out, "w", "load order", &why) != lp::kOne || out != 2 || p.Count() != 1 || p.Total() != 3) Fail("t1218 leverpick: the exact key wins");
        lp::Picker<int> q(0); q.Add(1, 0, 0.0, "a"); q.Add(2, 0, 0.0, "b"); q.Add(3, 1, 0.0, "c");
        if (q.Decide(&out, "w", "load order", &why) != lp::kSeveral || q.Count() != 2) Fail("t1218 leverpick: two exact keys - several");
    }
    std::vector<std::string> five; for (int i = 0; i < 5; ++i) five.push_back(nm[i]);
    if (lp::ShowList(five, 5) != "n0, n1, n2, n3, n4" || lp::ShowList(five, 9) != "n0, n1, n2, n3, n4 and 4 more") Fail("t1218 leverpick: the list - five, then 'and N more'");
    if (lp::BadSelector("wall#0") != "a malformed #<k> in 'wall#0' (#1..#999 after the name or key)") Fail("t1218 leverpick: the malformed selector's words");
    {   /* T-1262: the dead pick's miss words count the update list and the uid table; one " (" so P105NameUid keeps the whole tail */
        if (lp::NoneCountTail(3, 0, false) != " (3 such loaded at any distance)") Fail("t1262 leverpick: the tail without the uid-table walk");
        const std::string t = lp::NoneCountTail(1, 2, true);
        if (t != " (3 such loaded at any distance: 1 on the character update list + 2 dead off it in the uid table)") Fail("t1262 leverpick: the tail counts both lists");
        const std::string w = "no dead character named 'hungry bandit' within 300 units" + lp::NoneCountTail(0, 0, true);
        if (w.substr(w.rfind(" (")) != lp::NoneCountTail(0, 0, true)) Fail("t1262 leverpick: the tail holds one ' (' only");
    }
}
#include "hometest.h"   /* T-1334 (owner 1616 a): the TEST-ONLY `storetest home` lever's argument check */
void t_t1334_hometest_parse()
{
    namespace h = swhometest;
    std::string k, t;
    const std::string K1 = "3384-TwoStorey.mod@43,11@536196,-936043,10493", K2 = "3793-TwoStorey.mod@43,11@531470,-960783,10627";
    if (h::Parse("show " + K1, &k, &t) != h::kShow || k != K1) Fail("t1334 hometest: show <key>");
    if (h::Parse("  drop   " + K1 + "  ", &k, &t) != h::kDrop || k != K1) Fail("t1334 hometest: drop <key>, spaces around");
    t.clear();
    if (h::Parse("move " + K2 + " " + K1, &k, &t) != h::kMove || k != K2 || t != K1) Fail("t1334 hometest: move <key> <toKey>");
    k = "x"; t = "y";
    const std::string bad[] = { "", "show", "drop", "move " + K1, "move " + K1 + " " + K1, "show " + K1 + " " + K2, "drop " + K1 + " x",
                                "move " + K1 + " " + K2 + " " + K2, "blank " + K1, "show nokey", "move " + K1 + " nokey", "SHOW " + K1,
                                "show " + std::string(121, 'a') + "@" };
    for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); ++i)
        if (h::Parse(bad[i], &k, &t) != h::kBad) Fail("t1334 hometest: refused - '" + bad[i] + "'");
    if (k != "x" || t != "y") Fail("t1334 hometest: a refused form leaves the outputs alone");
    if (std::string(h::Usage()).find("storetest home") == std::string::npos) Fail("t1334 hometest: the usage names the form");
}

#include "levermade.h"   /* lever1 TEST-ONLY: the spawn lever's characters - `spawned:<Template>[#k]` and `made:<label>` */
/* lever1 (T2125, T2132): wild and taken-over spawns never enter a template's list; #k counts only lever spawns, newest first; a copy
   announced lever-made counts and learns its label from its name; the SPAWN's lever-made bit round-trips without touching the owner
   flags; the `as <label>` split and the label's shape; the plugin sites mark, carry and read the bit */
void t_lever1_levermade()
{
    namespace lm = levermade;
    {   /* the making game: only marked uids enter the list */
        lm::Book b;
        if (b.NoteSpawned("drifter", 50) != 0 || b.NoteSpawned("drifter", 51) != 0) Fail("lever1: a wild / taken-over spawn must be ignored");
        int known = 0;
        if (!b.Row("drifter", &known).empty() || known != 0) Fail("lever1: no lever spawn - no row");
        b.Mark(100, "");
        if (b.NoteSpawned("drifter", 100) != 1) Fail("lever1: a lever spawn is noted");
        for (unsigned int u = 52; u < 60; ++u) b.NoteSpawned("drifter", u);   /* a Tech Hunters squad taken over after it (T2132) */
        b.Mark(101, "");
        b.NoteSpawned("drifter", 101);
        std::vector<unsigned int> r = b.Row("drifter", &known);
        if (known != 1 || r.size() != 2 || r[0] != 101 || r[1] != 100) Fail("lever1: #1 / #2 are the two lever spawns, newest first");
        b.Mark(200, ""); b.NoteSpawned("skimmer", 200);
        for (unsigned int u = 300; u < 320; ++u) b.NoteSpawned("skimmer", u);   /* wild Skimmer squads (T2125) */
        r = b.Row("skimmer", &known);
        if (r.size() != 1 || r[0] != 200) Fail("lever1: wild Skimmers never push the lever's Skimmer out");
        for (unsigned int u = 1000; u < 1000 + (unsigned int)lm::kKeep + 3; ++u) { b.Mark(u, ""); b.NoteSpawned("bandit", u); }
        r = b.Row("bandit", &known);
        if ((int)r.size() != lm::kKeep || r[0] != 1000 + (unsigned int)lm::kKeep + 2) Fail("lever1: a full list keeps the newest kKeep");
        b.Mark(102, ""); b.NoteSpawned("drifter", 102); b.Unmark(102);
        r = b.Row("drifter", &known);
        if (b.IsMarked(102) || r.size() != 2 || r[0] != 101) Fail("lever1: an unmarked (unused) uid leaves the list");
        b.NoteSpawned("drifter", 100);
        r = b.Row("drifter", &known);
        if (r.size() != 2 || r[0] != 100 || r[1] != 101) Fail("lever1: a repeat note moves the uid to the front, once");
    }
    {   /* labels: the maker's mark carries it; a copy learns it from its name */
        lm::Book a, c;
        a.Mark(7, "pair a"); a.NoteSpawned("drifter", 7);
        a.Mark(8, "pair b"); a.NoteSpawned("drifter", 8);
        std::vector<unsigned int> n = a.Named("pair a");
        if (n.size() != 1 || n[0] != 7 || !a.Named("pair c").empty()) Fail("lever1: made:<label> names exactly one on the making game");
        c.Mark(7, ""); c.Mark(8, "");   /* the copies' SPAWNs said lever-made; no name yet */
        if (!c.Named("pair a").empty()) Fail("lever1: a copy with no name yet answers no label");
        c.SetNameKey(7, "pair a"); c.SetNameKey(8, "pair b");   /* their NAMEs arrived */
        c.SetNameKey(9, "pair a");   /* a character not lever-made is never named by made: */
        n = c.Named("pair a");
        if (n.size() != 1 || n[0] != 7 || c.IsMarked(9)) Fail("lever1: the label resolves on the copy side to the same uid");
        c.Mark(8, "pair a");   /* the same label twice: both named, newest mark first - the pick refuses without #k */
        n = c.Named("pair a");
        if (n.size() != 2 || n[0] != 8 || n[1] != 7) Fail("lever1: two characters named the same label are both counted, newest first");
        c.SetNameKey(8, "");
        if (c.NameKeyOf(8) != "pair a") Fail("lever1: an unread name keeps the last key");
    }
    {   /* the `as <label>` split and the label's shape */
        std::string r, l;
        if (lm::SplitAsLabel("Drifter 4 0 as PairA", &r, &l) != 1 || r != "Drifter 4 0" || l != "PairA") Fail("lever1: as <label> after the numbers");
        if (lm::SplitAsLabel("Hungry Bandit as hb_1", &r, &l) != 1 || r != "Hungry Bandit" || l != "hb_1") Fail("lever1: as <label> after a spaced name");
        if (lm::SplitAsLabel("Hungry Bandit 3", &r, &l) != 0 || r != "Hungry Bandit 3" || !l.empty()) Fail("lever1: no as - the whole text");
        if (lm::SplitAsLabel("Big Gas 3", &r, &l) != 0 || r != "Big Gas 3") Fail("lever1: a word ending in 'as' is no as");
        if (lm::SplitAsLabel("Drifter as", &r, &l) != -1) Fail("lever1: as with no label is refused");
        if (!lm::LabelOk("Pair-A_1") || lm::LabelOk("") || lm::LabelOk("a:b") || lm::LabelOk("a#2") || lm::LabelOk(std::string(41, 'x')))
            Fail("lever1: a label is 1-40 letters, digits, '_' or '-'");
    }
    {   /* the SPAWN's lever-made bit: carried, decoded apart from the owner flags; absent reads false */
        std::vector<char> f;
        coopspawn::EncodeSpawn(&f, 5u, 1.0f, 2.0f, 3.0f, "Drifter", "", false, 0.0f);
        coopspawn::AppendSpawnStats(&f, 0);
        coopspawn::AppendSpawnFlags(&f, coopspawn::kSpawnFlagDead | coopspawn::kSpawnFlagLeverMade);
        coopspawn::SpawnMsg d;
        if (coopspawn::DecodeSpawn(&f[0], f.size(), &d) != coopspawn::kSpawnDecodeOk || !d.leverMade || d.ownerFlags != coopspawn::kSpawnFlagDead)
            Fail("lever1: the lever-made bit rides the flags byte and stays out of ownerFlags");
        std::vector<char> g;
        coopspawn::EncodeSpawn(&g, 6u, 0, 0, 0, "Drifter", "", false, 0.0f);
        coopspawn::AppendSpawnStats(&g, 0);
        coopspawn::AppendSpawnFlags(&g, coopspawn::kSpawnFlagKo);
        coopspawn::SpawnMsg e;
        if (coopspawn::DecodeSpawn(&g[0], g.size(), &e) != coopspawn::kSpawnDecodeOk || e.leverMade || e.ownerFlags != coopspawn::kSpawnFlagKo)
            Fail("lever1: a SPAWN without the bit is not lever-made");
        std::vector<char> o(g.begin(), g.end() - 1);
        coopspawn::SpawnMsg a;
        if (coopspawn::DecodeSpawn(&o[0], o.size(), &a) != coopspawn::kSpawnDecodeOk || a.leverMade) Fail("lever1: no flags byte - not lever-made");
        if ((coopspawn::kSpawnFlagLeverMade & coopspawn::kSpawnFlagsKnown) != 0) Fail("lever1: the bit is a spare one, never an owner flag");
    }
    {   /* the plugin sites */
        const std::string sp = T313ReadFile("../coop-plugin/spawn.cpp"), it = T313ReadFile("../coop-plugin/items.cpp"),
                          ss = T313ReadFile("../coop-plugin/net/session.cpp"), cc = T313ReadFile("../coop-plugin/command_channel.cpp");
        const size_t st = sp.find("bool SpawnTemplate(const std::string& templateName, float dx, float dz,");
        const size_t mk = sp.find("LeverMarkMade(uid, label);", st);
        const size_t ca = sp.find("if (!CreateAt(uid, templateName, std::string(), pos, \"local\", g_spawnFactionName", st);
        const size_t nm = sp.find("NameSetOwn(lm, label)", st), ss1 = sp.find("net::SendSpawn(uid, templateName", st);
        if (st == std::string::npos || mk == std::string::npos || ca == std::string::npos || !(mk < ca) || nm == std::string::npos || !(nm < ss1))
            Fail("lever1: the spawn lever marks before CreateAt and names before its SPAWN");
        if (sp.find("+ \" (\" + who + \")\" + LeverMadeWords(uid));") == std::string::npos) Fail("lever1: the [M1] spawned line says lever-made");
        if (it.find("g_leverMade.NoteSpawned(coopsay::TalkPersonKey(templateName), uid);") == std::string::npos
            || it.find("if (w.compare(0, 5, \"made:\") == 0)") == std::string::npos) Fail("lever1: the pick reads the book; made: resolves");
        const size_t sm = ss.find("if (sm.leverMade) coop::LeverMarkMade(sm.uid, std::string());"), ap = ss.find("coop::ApplyRemoteSpawn(sm.uid,");
        if (sm == std::string::npos || ap == std::string::npos || !(sm < ap)
            || ss.find("coopspawn::AppendSpawnFlags(&b, spawnFlags | (leverMade ? coopspawn::kSpawnFlagLeverMade : 0u));") == std::string::npos)
            Fail("lever1: the SPAWN carries the bit and the copy is marked before it is made");
        if (cc.find("levermade::SplitAsLabel(whole, &rest, &spawnLabel)") == std::string::npos || cc.find("coop::LeverLabelTaken(spawnLabel)") == std::string::npos)
            Fail("lever1: spawn takes `as <label>` and refuses a taken label");
    }
}

/* T-1020 re-check (review LOW 4): StoreDiskDirs' is-a-folder rule (coopdir::AttrIsDir / MadeIsDir) against the REAL disk - a folder
   and a file made under this worktree's build folder (<worktree>\build\t1020_isdir: the exe's ..\..\build; never the system
   temp). Nothing is deleted: the folder and the file are made again or reused on every run. */
void t_t1020_disk_is_dir()
{
    char exe[MAX_PATH] = { 0 };
    const DWORD n = ::GetModuleFileNameA(0, exe, MAX_PATH);
    std::string root(exe, n);
    const std::string::size_type cut = root.find_last_of("\\/");
    if (n == 0 || n >= MAX_PATH || cut == std::string::npos) { Fail("t1020 disk: the exe's own path is unknown"); return; }
    root = root.substr(0, cut) + "\\..\\..\\build";
    if (!coopdir::AttrIsDir(::GetFileAttributesA(root.c_str()))) { Fail("t1020 disk: no build folder at " + root); return; }
    const std::string top = root + "\\t1020_isdir", dir = top + "\\a_folder", file = top + "\\a_file.txt", none = top + "\\not_there";
    ::CreateDirectoryA(top.c_str(), 0);
    ::CreateDirectoryA(dir.c_str(), 0);
    std::FILE* f = std::fopen(file.c_str(), "wb");
    if (f == 0) { Fail("t1020 disk: the test file could not be made: " + file); return; }
    std::fputs("t1020\n", f);
    std::fclose(f);
    if (!coopdir::AttrIsDir(::GetFileAttributesA(dir.c_str()))) Fail("t1020 disk: a real folder is a folder");
    if (coopdir::AttrIsDir(::GetFileAttributesA(file.c_str()))) Fail("t1020 disk: a real FILE is no folder");
    if (coopdir::AttrIsDir(::GetFileAttributesA(none.c_str()))) Fail("t1020 disk: a missing path is no folder");
    /* Make: CreateDirectory over what is there answers ERROR_ALREADY_EXISTS for a folder AND for a file - only the folder counts */
    const BOOL mkDir = ::CreateDirectoryA(dir.c_str(), 0);
    const bool dirAlready = mkDir == 0 && ::GetLastError() == ERROR_ALREADY_EXISTS;
    if (mkDir != 0 || !dirAlready || !coopdir::MadeIsDir(false, dirAlready, ::GetFileAttributesA(dir.c_str())))
        Fail("t1020 disk: making a folder that is there answers already-there, and that is ready");
    const BOOL mkFile = ::CreateDirectoryA(file.c_str(), 0);
    const bool fileAlready = mkFile == 0 && ::GetLastError() == ERROR_ALREADY_EXISTS;
    if (mkFile != 0 || !fileAlready || coopdir::MadeIsDir(false, fileAlready, ::GetFileAttributesA(file.c_str())))
        Fail("t1020 disk: making a folder where a FILE is answers already-there, and that is NOT ready (" + file + ")");
    if (!coopdir::MadeIsDir(true, false, 0xFFFFFFFFUL)) Fail("t1020 disk: a folder made now is ready");
}

/* ---- T-930 (owner decision 1436): TEAMMATES' CHARACTERS ON THE WORLD MAP - src/common/mapdots.h ---------------------------- */
void t_t930_mapdots_wire()
{
    using namespace mapdots;
    std::vector<char> b;
    Msg m;
    /* OPEN / CLOSE: exactly two bytes, both ways */
    if (!EncodeSignal(kOpen, &b) || b.size() != 2 || b[0] != 1 || b[1] != 0 || !Decode(&b[0], b.size(), &m) || m.kind != kOpen) Fail("t930: OPEN is not {1, 0}");
    if (!EncodeSignal(kClose, &b) || b.size() != 2 || b[1] != 1 || !Decode(&b[0], b.size(), &m) || m.kind != kClose) Fail("t930: CLOSE is not {1, 1}");
    if (EncodeSignal(kDots, &b)) Fail("t930: a DOTS was made as a two-byte signal");
    { const char open3[3] = { 1, 0, 0 }; if (Decode(open3, 3, &m)) Fail("t930: an OPEN with a trailing byte was taken"); }
    { const char v2[2] = { 2, 0 }; if (Decode(v2, 2, &m)) Fail("t930: a version-2 message was taken"); }
    { const char k3[2] = { 1, 3 }; if (Decode(k3, 2, &m)) Fail("t930: an unknown kind was taken"); }
    if (Decode(0, 0, &m) || Decode(b.empty() ? 0 : &b[0], 1, &m)) Fail("t930: an empty or one-byte message was taken");
    /* DOTS: a whole list with names, then a delta with a gone uid */
    std::vector<Row> rows;
    Row a; a.uid = 7; a.x = 1234.5f; a.z = -88.25f; a.hasNames = true; a.name = "Ruka"; rows.push_back(a);
    Row c; c.uid = 9; c.x = -1.0f; c.z = 2.0f; c.hasNames = false; rows.push_back(c);
    std::vector<unsigned> gone; gone.push_back(11);
    if (!EncodeDots(true, rows, gone, &b)) Fail("t930: a DOTS did not encode");
    const size_t want = 2 + 1 + 2 + 2 + (4 + 4 + 4 + 1 + 1 + 4) + (4 + 4 + 4 + 1) + 4;   /* a named row carries the character's name and nothing after it */
    if (b.size() != want) Fail("t930: a DOTS is not the documented length (a squad name travelled?)");
    if (!Decode(&b[0], b.size(), &m) || m.kind != kDots || !m.whole || m.rows.size() != 2 || m.gone.size() != 1 || m.gone[0] != 11
        || m.rows[0].uid != 7 || m.rows[0].x != 1234.5f || m.rows[0].z != -88.25f || !m.rows[0].hasNames || m.rows[0].name != "Ruka"
        || m.rows[1].uid != 9 || m.rows[1].hasNames || !m.rows[1].name.empty())
        Fail("t930: a DOTS did not come back as it went");
    for (size_t k = 0; k < b.size(); ++k) if (Decode(&b[0], k, &m)) { Fail("t930: a cut DOTS was taken"); break; }
    { std::vector<char> x(b); x.push_back(0); if (Decode(&x[0], x.size(), &m)) Fail("t930: a DOTS with a trailing byte was taken"); }
    { std::vector<char> x(b); x[2] = 2; if (Decode(&x[0], x.size(), &m)) Fail("t930: a whole byte of 2 was taken"); }
    { std::vector<char> x(b); x[7 + 12] = 3; if (Decode(&x[0], x.size(), &m)) Fail("t930: unknown row flags were taken"); }
    { std::vector<char> x(b); x[7] = 0; x[8] = 0; x[9] = 0; x[10] = 0; if (Decode(&x[0], x.size(), &m)) Fail("t930: a uid 0 was taken"); }
    { std::vector<char> x(b); x[11] = 0; x[12] = 0; x[13] = (char)0xC0; x[14] = (char)0x7F; if (Decode(&x[0], x.size(), &m)) Fail("t930: a NaN position was taken"); }
    /* refused when encoding */
    { std::vector<Row> r0(1); r0[0].uid = 0; if (EncodeDots(false, r0, std::vector<unsigned>(), &b) || !b.empty()) Fail("t930: a uid 0 was encoded"); }
    { std::vector<Row> big(kMaxRows); for (size_t i = 0; i < big.size(); ++i) big[i].uid = (unsigned)i + 1;
      if (!EncodeDots(false, big, std::vector<unsigned>(), &b)) Fail("t930: kMaxRows rows did not encode");
      if (EncodeDots(false, big, std::vector<unsigned>(1, 5u), &b)) Fail("t930: more than kMaxRows rows were encoded"); }
    /* a long name is cut at a character boundary, never inside one */
    std::string longName(kMaxNameBytes - 1, 'a'); longName += "\xC3\xA9xyz";
    const std::string cut = CutUtf8(longName, kMaxNameBytes);
    if (cut.size() != kMaxNameBytes - 1 || CutUtf8("abc", kMaxNameBytes) != "abc") Fail("t930: CutUtf8 cut inside a character or cut a short name");
    { std::vector<Row> r1(1); r1[0].uid = 3; r1[0].hasNames = true; r1[0].name = longName;
      if (!EncodeDots(false, r1, std::vector<unsigned>(), &b) || !Decode(&b[0], b.size(), &m) || m.rows[0].name != cut) Fail("t930: a long name did not travel cut"); }
}
void t_t930_mapdots_rules()
{
    using namespace mapdots;
    /* the delta: more than 5 m (50 game units) on the ground plane */
    if (MovedEnough(0.0f, 0.0f, 50.0f, 0.0f) || !MovedEnough(0.0f, 0.0f, 50.5f, 0.0f) || !MovedEnough(10.0f, 10.0f, 46.0f, 46.0f)
        || MovedEnough(10.0f, 10.0f, 40.0f, 40.0f) || kMoveMinUnits != 50.0f || kCheckMs != 500)
        Fail("t930: the delta is not 'more than 5 m, checked every 500 ms'");
    /* the team filter */
    if (!TeammateOnline(2, 1, true, 1) || TeammateOnline(2, 1, false, 1) || TeammateOnline(2, 1, true, 0) || TeammateOnline(2, 1, true, -1)
        || TeammateOnline(1, 1, true, 1) || TeammateOnline(-1, 1, true, 1) || TeammateOnline(2, -1, true, 1))
        Fail("t930: TeammateOnline is not 'another slot, same team, in the world'");
    if (!ViewerTakes(2, 1, true, 1, true, true) || ViewerTakes(2, 1, true, 1, false, true) || ViewerTakes(2, 1, true, 1, true, false)
        || ViewerTakes(2, 1, false, 1, true, true) || ViewerTakes(2, 1, true, 0, true, true))
        Fail("t930: a viewer takes DOTS it did not ask for, with its map closed, or from a non-teammate / offline player");
    /* the map's own sums (0x493040): (world - origin) / span x canvas, rounded */
    int px = 0, py = 0;
    if (!CanvasPixel(1000.0f, -500.0f, -1000.0f, -1500.0f, 4000.0f, 2000.0f, 800, 400, &px, &py) || px != 400 || py != 200)
        Fail("t930: CanvasPixel is not the map's sum");
    if (!CanvasPixel(-1000.0f, -1500.0f, -1000.0f, -1500.0f, 4000.0f, 2000.0f, 800, 400, &px, &py) || px != 0 || py != 0) Fail("t930: the origin is not pixel 0");
    if (!CanvasPixel(1.0f, 1.0f, 0.0f, 0.0f, 4.0f, 4.0f, 6, 6, &px, &py) || px != 2 || py != 2) Fail("t930: 1.5 does not round to 2");
    if (CanvasPixel(1.0f, 1.0f, 0.0f, 0.0f, 0.0f, 4.0f, 6, 6, &px, &py)) Fail("t930: a span of 0 placed a dot");
    /* the dot's size: the image's size times the scale, 4..128 */
    if (DotSide(16, 1.0f) != 16 || DotSide(16, 1.5f) != 24 || DotSide(16, 100.0f) != 128 || DotSide(16, 0.01f) != 4 || DotSide(0, 1.0f) != 16 || DotSide(16, -2.0f) != 16)
        Fail("t930: DotSide is not the image size times the scale, kept in 4..128");
    if (HoverText("Ruka", "Sam") != "Ruka\nSam's squad" || HoverText("Ruka", "") != "Ruka") Fail("t930: the hover note's lines are not the character's name and \"<player>'s squad\" (owner 1438)");
    /* the colour is the name tags' team blue (owner rule 2026-10-19), not the game's ally green */
    const nametag::Rgb tc = nametag::TeamColour();
    if ((int)(tc.r * 255.0f + 0.5f) != 0x5a || (int)(tc.g * 255.0f + 0.5f) != 0x9b || (int)(tc.b * 255.0f + 0.5f) != 0xe6)
        Fail("t930: the dot colour is not the team blue #5a9be6");
    /* the road: inner type 206, read by the store layer only; the game-to-game protocol 207 (198 on the branch before the merge with main) */
    if (cooplive::kInnerMapDots != 206u || !cooplive::LiveInnerRoadLocal(cooplive::kInnerMapDots) || cooplive::LiveInnerAccepted(cooplive::kInnerMapDots)
        || hovrec::kGameProtocol != 237u)
        Fail("t930: MAP_DOTS is not road-local inner type 206 on game-to-game protocol 222");
}
void t_t930_teammap_pins()
{
    const std::string tm = T313ReadFile("../coop-plugin/teammap.cpp");
    const std::string st = T313ReadFile("../coop-plugin/store.cpp");
    const std::string co = T313ReadFile("../coop-plugin/coop.cpp");
    const std::string bb = T313ReadFile("../coop-plugin/build.bat");
    const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
    const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
    if (tm.empty() || st.empty() || co.empty() || bb.empty() || t65.empty() || t68.empty()) { Fail("t930: a source file did not read"); return; }
    if (tm.find("AddrReg kTmFrameRva_reg(\"MapWindow_frame\"") == std::string::npos || tm.find("AddrReg kTmScaleXRva_reg(\"MapMarkerScaleX\"") == std::string::npos
        || tm.find("AddrReg kTmScaleYRva_reg(\"MapMarkerScaleY\"") == std::string::npos)
        Fail("t930: teammap.cpp does not bind its three rows");
    if (t65.find("MapWindow_frame                                code 0049AC50 0049AC50 40534883EC20488BD9488B4908FF15AD") == std::string::npos
        || t65.find("MapMarkerScaleX                                var  0213278C") == std::string::npos
        || t65.find("MapMarkerScaleY                                var  02132790") == std::string::npos
        || t68.find("MapWindow_frame                                code 0049B6E0 0049B6E0 40534883EC20488BD9488B4908FF153D") == std::string::npos
        || t68.find("MapMarkerScaleX                                var  021337EC") == std::string::npos
        || t68.find("MapMarkerScaleY                                var  021337F0") == std::string::npos)
        Fail("t930: the map rows are not in both address tables");
    if (tm.find("ib->setItemResource(std::string(\"Kenshi_MapMarkers\"));") == std::string::npos || tm.find("const std::string ch(\"Character\");") == std::string::npos
        || tm.find("ib->setNeedMouseFocus(false);") == std::string::npos || tm.find("nametag::TeamColour()") == std::string::npos)
        Fail("t930: the dot is not the game's Character map dot in team blue, taking no mouse");
    if (tm.find("if (c == 0 || DeadPod(c) != 0) continue;") == std::string::npos) Fail("t930: a dead character would keep its dot");
    {   /* owner 1438: no squad name is read, carried or shown - the second line is the player's name from the sender's slot */
        const std::string md = T313ReadFile("../common/mapdots.h");
        if (md.empty() || md.find("squad;") != std::string::npos || md.find("r.squad") != std::string::npos || md.find("w.squad") != std::string::npos
            || tm.find("getSquad") != std::string::npos || tm.find(".squad") != std::string::npos || tm.find("Platoon") != std::string::npos
            || tm.find("mapdots::HoverText(d.name, TeamPlayerName(d.slot))") == std::string::npos)
            Fail("t930: a squad's own name is read, sent or shown, or the hover's second line is not the player's name");
    }
    if (tm.find("cooplive::kRouteSlot, (unsigned)slot, cooplive::kInnerMapDots") == std::string::npos || tm.find("kRouteWorld") != std::string::npos)
        Fail("t930: a MAP_DOTS goes anywhere but to one player by slot");
    if (st.find("if (d.innerType == cooplive::kInnerMapDots)") == std::string::npos || st.find("coop::TeamMapWorldTeardown();") == std::string::npos)
        Fail("t930: store.cpp does not hand MAP_DOTS to teammap.cpp or forget the dots at a teardown");
    if (co.find("coop::TeamMapTick();") == std::string::npos || co.find("coop::InstallTeamMap();") == std::string::npos || bb.find(" teammap.cpp ") == std::string::npos)
        Fail("t930: teammap.cpp is not installed, ticked and built");
}

/* T-930 review folds: the sender's choice, the viewer's whole list and cap, the close's destroy mode, the CLOSE reply, the caption */
void t_t930_fold_sender_plan()
{
    using namespace mapdots;
    std::vector<OwnRow> own(3);
    own[0].uid = 1; own[0].x = 0.0f;   own[0].z = 0.0f;   own[0].name = "Ruka";
    own[1].uid = 2; own[1].x = 100.0f; own[1].z = 100.0f; own[1].name = "Beep";
    own[2].uid = 3; own[2].x = -5.0f;  own[2].z = 7.0f;   own[2].name = "Hob";
    std::map<unsigned, SentRow> sent;
    std::vector<Row> rows; std::vector<unsigned> gone;
    /* whole: every character with its name, no gone */
    if (!SendPlan(true, own, sent, &rows, &gone) || rows.size() != 3 || !gone.empty() || !rows[0].hasNames || rows[1].name != "Beep") Fail("t930 fold: a whole plan is not every character with its name");
    /* a failed send records nothing: the same plan again */
    std::vector<Row> rows2; std::vector<unsigned> gone2;
    if (!SendPlan(true, own, sent, &rows2, &gone2) || rows2.size() != 3) Fail("t930 fold: a plan after a failed send is not the same plan");
    SentApply(true, rows, gone, &sent);
    if (sent.size() != 3 || sent[2].name != "Beep") Fail("t930 fold: SentApply did not record the whole list");
    /* nothing moved: nothing to send */
    if (SendPlan(false, own, sent, &rows, &gone)) Fail("t930 fold: an unchanged list planned a message");
    /* one moved 4 m (not sent), one moved 6 m (sent, no name), one renamed (sent with its name), one gone */
    own[0].x = 40.0f; own[1].x = 160.0f; own[2].name = "Hobbs";
    std::vector<OwnRow> now(own.begin(), own.end());
    now.push_back(OwnRow()); now.back().uid = 9; now.back().name = "New";
    sent[7].x = 1.0f; sent[7].name = "Old";   /* sent earlier, no longer here */
    if (!SendPlan(false, now, sent, &rows, &gone) || rows.size() != 3 || gone.size() != 1 || gone[0] != 7) Fail("t930 fold: a delta plan is not 'moved over 5 m, renamed, new; and the gone'");
    for (size_t i = 0; i < rows.size(); ++i)
    {
        if (rows[i].uid == 1) Fail("t930 fold: a 4 m move was sent");
        if (rows[i].uid == 2 && rows[i].hasNames) Fail("t930 fold: a moved-only row carried its name");
        if ((rows[i].uid == 3 && (!rows[i].hasNames || rows[i].name != "Hobbs")) || (rows[i].uid == 9 && !rows[i].hasNames)) Fail("t930 fold: a renamed or new row lacks its name");
    }
    SentApply(false, rows, gone, &sent);
    if (sent.count(7) != 0 || sent[3].name != "Hobbs" || sent[2].x != 160.0f || sent[1].x != 0.0f) Fail("t930 fold: SentApply after a delta");
    /* over kMaxRows: gone kept, rows cut; the cut rows go at the next check */
    std::vector<OwnRow> many(kMaxRows + 10);
    for (size_t i = 0; i < many.size(); ++i) { many[i].uid = (unsigned)(1000 + i); many[i].name = "M"; }
    std::map<unsigned, SentRow> s2; s2[5].name = "gone one";
    if (!SendPlan(false, many, s2, &rows, &gone) || gone.size() != 1 || rows.size() + gone.size() != kMaxRows) Fail("t930 fold: an over-long plan is not cut to kMaxRows with the gone kept");
    SentApply(false, rows, gone, &s2);
    if (!SendPlan(false, many, s2, &rows, &gone) || rows.size() != 11 || !gone.empty()) Fail("t930 fold: the rows cut last time are not sent at the next check");
    std::vector<char> b;
    if (!EncodeDots(false, rows, gone, &b)) Fail("t930 fold: a planned message did not encode");
}
void t_t930_fold_viewer()
{
    using namespace mapdots;
    /* a whole list drops the dots it does not name */
    std::vector<unsigned> have; have.push_back(1); have.push_back(2); have.push_back(3);
    Msg m; m.kind = kDots; m.whole = true; m.rows.resize(2); m.rows[0].uid = 3; m.rows[1].uid = 4;
    std::vector<unsigned> drop;
    WholeDrops(have, m, &drop);
    if (drop.size() != 2 || drop[0] != 1 || drop[1] != 2) Fail("t930 fold: a whole list does not drop exactly the dots it leaves out");
    m.whole = false;
    WholeDrops(have, m, &drop);
    if (!drop.empty()) Fail("t930 fold: a delta dropped dots");
    /* the cap */
    if (!DotRoom(0) || !DotRoom(kMaxDotsPerSlot - 1) || DotRoom(kMaxDotsPerSlot) || kMaxDotsPerSlot != 256) Fail("t930 fold: the per-teammate cap is not 256");
    /* the close: through the pointers only under the holder read this frame; else by name */
    if (CloseDropMode(1, true) != kDropChecked || CloseDropMode(1, false) != kDropByName || CloseDropMode(0, true) != kDropByName || CloseDropMode(-1, true) != kDropByName)
        Fail("t930 fold: the close destroys through pointers without the holder proven alive");
    /* the CLOSE reply: at most once per 2 s per player */
    if (!CloseReplyDue(false, 0, 5) || CloseReplyDue(true, 1000, 2999) || !CloseReplyDue(true, 1000, 3000) || !CloseReplyDue(true, 0xFFFFFF00ul, 2000)) Fail("t930 fold: the CLOSE reply's rate");
    /* the caption: '#' doubled, line breaks made spaces, in both lines */
    if (HoverText("Ru#ka\nX", "S#m") != "Ru##ka X\nS##m's squad" || CaptionSafe("a\rb") != "a b" || HoverText("#", "") != "##") Fail("t930 fold: the hover note's words are not caption-safe");
}
void t_t930_fold_pins()
{
    const std::string tm = T313ReadFile("../coop-plugin/teammap.cpp");
    if (tm.empty()) { Fail("t930 fold: teammap.cpp did not read"); return; }
    const size_t li = tm.find("void TeamMapLiveIn("), le = tm.find("void TeamMapWorldTeardown(");
    if (li == std::string::npos || le == std::string::npos || le < li) { Fail("t930 fold: TeamMapLiveIn not found"); return; }
    const std::string live = tm.substr(li, le - li);
    if (live.find("estroyWidget") != std::string::npos || live.find("DropTip(") != std::string::npos || live.find("DropAllDots(") != std::string::npos
        || live.find("->set") != std::string::npos || live.find("ReplyClose(originSlot);") == std::string::npos || live.find("mapdots::DotRoom(count)") == std::string::npos)
        Fail("t930 fold: the network path touches a widget, or does not reply CLOSE / cap the dots");
    {   /* either line ending: single-line finds, in order */
        const size_t dd = tm.find("DrainDoomed(mapdots::kDropChecked);   /* review fold 3");
        const size_t rk = dd == std::string::npos ? std::string::npos : tm.rfind("    ReadKids(v.parent);", dd);
        const size_t pd = dd == std::string::npos ? std::string::npos : tm.find("    PlaceDots(v);", dd);
        if (dd == std::string::npos || rk == std::string::npos || pd == std::string::npos || dd - rk > 40)
            Fail("t930 fold: the frame does not read the holder's children before destroying or placing");
    }
    if (tm.find("if (d.w != 0 && (g_kids.count(d.w) == 0 || d.w->getName() != d.wname)) { d.w = 0;") == std::string::npos
        || tm.find("if (g_kids.count(w) != 0 && w->getName() == wname) { gui->destroyWidget(w);") == std::string::npos || tm.find("findWidgetT(std::string(kTipName), false) != g_tip") == std::string::npos)
        Fail("t930 fold: a dot or the note is used without the check that it still exists");
    if (tm.find("const int mode = mapdots::CloseDropMode(r, sameHolder);") == std::string::npos || tm.find("if (SendSignal(s, mapdots::kOpen)) g_asked.insert(s);") == std::string::npos
        || tm.find("if (g_window != 0 && window != g_window) { ++g_otherWindow; return; }") == std::string::npos || tm.find("const int dropped = DropAllByNamePod();") == std::string::npos
        || tm.find("it->second.whole = true; it->second.sent.clear();") == std::string::npos || tm.find("mapdots::SendPlan(vw->whole, own, vw->sent, &rows, &gone)") == std::string::npos)
        Fail("t930 fold: the close mode, the OPEN-sent rule, the window latch, the fault's CLOSE, the teardown's whole list or the pure plan is not used");
    {   /* re-check fold 2: the frame is counted after the latch filter (never in the detour), the latch is set only past the
           "map reads open" return and let go at the close */
        const size_t lf = tm.find("if (g_window != 0 && window != g_window) { ++g_otherWindow; return; }");
        const size_t hs = tm.find("    ++g_hookSeq;");
        const size_t ro = tm.find("    if (!open) return;", lf == std::string::npos ? 0 : lf);
        const size_t lw = tm.find("    g_window = window;");
        const size_t fd = tm.find("void FrameDetour(");
        if (lf == std::string::npos || hs == std::string::npos || hs < lf || hs > lf + 200 || ro == std::string::npos || lw == std::string::npos
            || lw < ro || lw > ro + 60 || fd == std::string::npos || tm.find("++g_hookSeq", fd) != std::string::npos
            || tm.find("    g_window = 0;   /* re-check fold 2") == std::string::npos)
            Fail("t930 re-check: the window is latched before its map reads open, kept past the close, or another window's frame is counted");
    }
}

/* T-930 (run T1925 fix 2): an OPEN refused because this game's team table had not come back yet is kept and answered when the table
   names the player an online teammate; dropped at a new link, a roster that says the player left, or that player's CLOSE */
void t_t930_t1925_pending()
{
    using namespace mapdots;
    /* B (slot 1) after its re-dial, link 7: A's (slot 0) OPEN came before B's team table */
    if (PendingOpenKeep(0, 1, 7, 0) != 1) Fail("T1925 fix 2: the early OPEN is not kept");
    if (PendingOpenStep(0, 1, false, 1, 7, 7) != kPendKeep || PendingOpenStep(0, 1, false, -1, 7, 7) != kPendKeep || PendingOpenStep(0, 1, true, -1, 7, 7) != kPendKeep)
        Fail("T1925 fix 2: a kept OPEN is dropped or answered before the table and the roster name the player an online teammate");
    if (PendingOpenStep(0, 1, true, 1, 7, 7) != kPendAccept) Fail("T1925 fix 2: the kept OPEN is not answered once the table names the player a teammate");
    if (PendingOpenStep(0, 1, true, 1, 7, 8) != kPendDrop || PendingOpenStep(0, 1, true, 1, 7, 0) != kPendDrop) Fail("T1925 fix 2: a kept OPEN outlives this game's link");
    if (PendingOpenStep(0, 1, false, 0, 7, 7) != kPendDrop || PendingOpenStep(0, 1, true, 0, 7, 7) != kPendDrop) Fail("T1925 fix 2: a kept OPEN outlives the player leaving the world");
    if (PendingOpenStep(1, 1, true, 1, 7, 7) != kPendDrop || PendingOpenStep(-1, 1, true, 1, 7, 7) != kPendDrop) Fail("T1925 fix 2: an OPEN from this game's own slot or no slot is kept");
    if (PendingOpenKeep(1, 1, 7, 0) != 0 || PendingOpenKeep(-1, 1, 7, 0) != 0 || PendingOpenKeep(0, -1, 7, 0) != 0 || PendingOpenKeep(0, 1, 0, 0) != 0
        || PendingOpenKeep(0, 1, 7, kMaxPendingOpens) != 0 || PendingOpenKeep(0, 1, 7, kMaxPendingOpens - 1) != 1)
        Fail("T1925 fix 2: an OPEN is kept from this game's own slot, with the link down or over the cap");
    const std::string tm = T313ReadFile("../coop-plugin/teammap.cpp");
    if (tm.empty()) { Fail("T1925 fix 2: teammap.cpp did not read"); return; }
    if (tm.find("const int keep = mapdots::PendingOpenKeep(originSlot, me, gen, g_pendingOpen.count(originSlot) != 0 ? 0 : g_pendingOpen.size());") == std::string::npos
        || tm.find("if (keep != 0) { g_pendingOpen[originSlot] = gen;") == std::string::npos)
        Fail("T1925 fix 2: a refused OPEN is not kept");
    if (tm.find("const int step = mapdots::PendingOpenStep(o, me, TeamSameAnyThread(me, o), inWorld, it->second, gen);") == std::string::npos
        || tm.find("    PendingTick();   /* T1925 fix 2") == std::string::npos || tm.find("            AcceptOpen(o);") == std::string::npos)
        Fail("T1925 fix 2: the kept OPENs are not stepped from the live team table every tick, or not answered");
    {   /* the viewer's CLOSE drops its kept OPEN; the stepping runs before the sender's check */
        const size_t cl = tm.find("    if (m.kind == mapdots::kClose)");
        const size_t pe = cl == std::string::npos ? std::string::npos : tm.find("        if (g_pendingOpen.erase(originSlot) != 0)", cl);
        const size_t pt = tm.find("    PendingTick();   /* T1925 fix 2"), st = pt == std::string::npos ? std::string::npos : tm.find("    SenderTick();", pt);
        if (cl == std::string::npos || pe == std::string::npos || pe > cl + 80 || pt == std::string::npos || st == std::string::npos || st > pt + 140)
            Fail("T1925 fix 2: a CLOSE does not drop the kept OPEN, or the stepping is not in the tick");
    }
    if (hovrec::kGameProtocol != 237u || cooplive::kInnerMapDots != 206u) Fail("T1925 fix 2: the wire moved (no protocol change is part of this fix)");
}

/* T-478 (owner 1447 b) TEST-ONLY: the `money [<amount>]` lever - its parse, its line, and that it moves the purse on the money road */
void t_t478_money_lever()
{
    using namespace moneyw;
    int a = -1;
    if (TestLeverParse("", &a) != kLeverShow || TestLeverParse("  \t ", &a) != kLeverShow || a != 0) Fail("t478 money: nothing after the verb prints");
    if (TestLeverParse("5000", &a) != kLeverSet || a != 5000) Fail("t478 money: 5000 sets 5000");
    if (TestLeverParse(" 0 ", &a) != kLeverSet || a != 0) Fail("t478 money: 0 sets 0 (spaces round it)");
    if (TestLeverParse("2000000000", &a) != kLeverSet || a != 2000000000) Fail("t478 money: the top amount");
    if (TestLeverParse("2000000001", &a) != kLeverBad || TestLeverParse("99999999999999999999999", &a) != kLeverBad || a != 0)
        Fail("t478 money: past the top amount is refused, nothing set");
    if (TestLeverParse("-5", &a) != kLeverBad || TestLeverParse("5k", &a) != kLeverBad || TestLeverParse("5 6", &a) != kLeverBad || TestLeverParse("c.500", &a) != kLeverBad)
        Fail("t478 money: only one whole number");
    if (TestLeverLine(120, 5000) != "[TEST] money before=120 after=5000" || TestLeverLine(-3, 0) != "[TEST] money before=-3 after=0") Fail("t478 money: the line");
    const std::string cc = T313ReadFile("../coop-plugin/command_channel.cpp"), mc = T313ReadFile("../coop-plugin/money.cpp"), st = T313ReadFile("../coop-plugin/store.cpp");
    if (cc.empty() || mc.empty() || st.empty()) { Fail("t478 money: could not read command_channel.cpp, money.cpp or store.cpp"); return; }
    if (cc.find("else if (verb == \"money\")") == std::string::npos || cc.find("WriteStatus(coop::MoneyTestCommand(Trim(rest)));") == std::string::npos)
        Fail("t478 money: command_channel.cpp has no `money` verb handing the rest of the line to MoneyTestCommand");
    const std::string::size_type b = mc.find("std::string MoneyTestCommand(const std::string& args)"), e = mc.find("int MoneyHave(int* money)");
    if (b == std::string::npos || e == std::string::npos || e < b) { Fail("t478 money: money.cpp has no MoneyTestCommand before MoneyHave"); return; }
    const std::string body = mc.substr(b, e - b);
    if (body.find("coop::StoreMoneyReady(&why) != 1") == std::string::npos || body.find("coop::StoreMoneyPay((int)pay)") == std::string::npos
        || body.find("coop::StoreMoneyWriteNow(&seq)") == std::string::npos || body.find("DebugLog(moneyw::TestLeverLine(before, after));") == std::string::npos)
        Fail("t478 money: the lever does not wait for StoreMoneyReady, take through the game's takeMoney, write pp.money and log the line");
    if (st.find("int StoreMoneyPay(int amount)") == std::string::npos || st.find("return own == 0 ? -1 : OwnPurseTakePod(own, amount);") == std::string::npos)
        Fail("t478 money: StoreMoneyPay is not the game's Ownerships::takeMoney (OwnPurseTakePod)");
}
/* T-1168 (owner 1425 a): the TEST-ONLY netthrottle switch's pure parts - the word, the terms (ENet's own figures), the request file, the line */
void t_t1168_netthrottle()
{
    using namespace netthrottle;
    if (Parse("off") != kOff || Parse("on") != kOn || Parse(" OFF\r\n") != kOff || Parse("\tOn ") != kOn) Fail("t1168: off / on in any case, spaces and line ends around ignored");
    if (Parse("") != kBad || Parse("of") != kBad || Parse("onn") != kBad || Parse("off on") != kBad || Parse("0") != kBad || Parse("o n") != kBad) Fail("t1168: any other word is refused");
    const Terms off = TermsFor(kOff), on = TermsFor(kOn), bad = TermsFor(kBad);
    if (off.interval != 5000 || off.accel != 32 || off.decel != 0) Fail("t1168: off = interval 5000, acceleration 32 (the full scale), deceleration 0");
    if (on.interval != 5000 || on.accel != 2 || on.decel != 2) Fail("t1168: on = ENet's defaults 5000 / 2 / 2");
    if (bad.interval != on.interval || bad.accel != on.accel || bad.decel != on.decel) Fail("t1168: a bad mode answers the defaults");
    if (kScale != 32) Fail("t1168: ENet's full throttle is 32");
    if (RequestText(kOff) != "off\r\n" || RequestParse(RequestText(kOff)) != kOff || RequestParse(RequestText(kOn)) != kOn) Fail("t1168: the request file's text reads back");
    if (RequestParse(std::string(kRequestMax - 3, ' ') + "off") != kOff) Fail("t1168: a request file at its longest is read");
    if (RequestParse(std::string(kRequestMax - 2, ' ') + "off") != kBad) Fail("t1168: a longer request file is refused whole");
    if (std::string(kRequestFile) != "netthrottle.request" || std::string(kRequestFileAside) != "netthrottle.request.taken") Fail("t1168: the request file names");
    if (Num(0) != "0" || Num(4294967295ul) != "4294967295") Fail("t1168: numbers written by hand");
    const std::string l1 = Line("[STORE]", kOff, 2, false);
    if (l1 != "[STORE] netthrottle off (TEST-ONLY): ENet throttle terms interval=5000 acceleration=32 deceleration=0, throttle set to its limit (full scale 32) - 2 live links")
        Fail("t1168: the off line: " + l1);
    const std::string l2 = Line("[NET]", kOn, 1, false);
    if (l2 != "[NET] netthrottle on (TEST-ONLY): ENet throttle terms interval=5000 acceleration=2 deceleration=2, throttle value left to ENet (ENet's defaults) - 1 live link")
        Fail("t1168: the on line: " + l2);
    const std::string l3 = Line("[NET]", kOff, 1, true);
    if (l3.find(" - a link that connected while off") == std::string::npos || l3.find("live link") != std::string::npos) Fail("t1168: the new-link line: " + l3);
    if (Line("[NET]", kOn, 0, false).find(" - 0 live links") == std::string::npos) Fail("t1168: no live link is said as 0");
    /* the world server follows a game's off through ENet's adopted terms */
    if (!IsOffTerms(32, 0) || IsOffTerms(2, 2) || IsOffTerms(32, 2) || IsOffTerms(2, 0) || IsOffTerms(31, 0)) Fail("t1168: only acceleration 32 with deceleration 0 are the off terms");
    if (!IsOffTerms(TermsFor(kOff).accel, TermsFor(kOff).decel) || IsOffTerms(TermsFor(kOn).accel, TermsFor(kOn).decel)) Fail("t1168: the off terms are what off sends, on's are not");
    if (!FollowRaise(32, 0, 0, 32) || !FollowRaise(32, 0, 31, 32) || FollowRaise(32, 0, 32, 32) || FollowRaise(2, 2, 0, 32)) Fail("t1168: the server raises a throttle below its limit on the off terms only");
    const std::string f = FollowLine(3, 0, 32);
    if (f != "[STORE] netthrottle: link slot3 follows the game's off terms - throttle 0 -> 32 (TEST-ONLY)") Fail("t1168: the follow line: " + f);
    if (FollowLine(-1, 4, 32).find("link slot-1 ") == std::string::npos) Fail("t1168: a link with no slot yet is slot-1");
    /* T-1168 design (c): the shipped terms are the held-full ones, set at each end's connect; `on` stays the control */
    const Terms sh = ShippedTerms();
    if (kShippedMode != kOff || sh.interval != 5000 || sh.accel != 32 || sh.decel != 0 || !IsOffTerms(sh.accel, sh.decel)) Fail("t1168 c: the shipped terms are not 5000 / 32 / 0");
    const std::string s1 = ShippedLine("[NET]");
    if (s1 != "[NET] netthrottle: ENet throttle held at full on this link - terms interval=5000 acceleration=32 deceleration=0, throttle at its limit (full scale 32)")
        Fail("t1168 c: the shipped line: " + s1);
    if (!OnNeedsReapply(kOn, 32, 0) || !OnNeedsReapply(kOn, 2, 0) || OnNeedsReapply(kOn, 2, 2) || OnNeedsReapply(kOff, 32, 0) || OnNeedsReapply(kBad, 32, 0))
        Fail("t1168 c: only an `on` link that adopted other terms gets the defaults back");
    if (ReapplyLine("[NET]", 32, 0) != "[NET] netthrottle on (TEST-ONLY): this link had adopted the far end's terms acceleration=32 deceleration=0 - ENet's defaults put back")
        Fail("t1168 c: the reapply line");
    /* source pins: the shipped terms are applied at the CONNECT event on both ends (never before - protocol.c 960-962), from the start */
    const std::string enet = T313ReadFile("../coop-plugin/net/enet_transport.cpp"), server = T313ReadFile("../coop-store/store_main.cpp");
    const size_t ec = enet.find("case ENET_EVENT_TYPE_CONNECT:"), ea = enet.find("NtApplyPeer(ev.peer, netthrottle::kShippedMode);"), ed = enet.find("case ENET_EVENT_TYPE_DISCONNECT:", ec);
    if (ec == std::string::npos || ea == std::string::npos || ed == std::string::npos || !(ec < ea && ea < ed) || enet.find("volatile LONG s_ntOff = 1;") == std::string::npos
        || enet.find("DebugLog(netthrottle::ShippedLine(\"[NET]\"));") == std::string::npos || enet.find("netthrottle::OnNeedsReapply(netthrottle::kOn,") == std::string::npos)
        Fail("t1168 c: the game does not set the shipped terms on each link at its CONNECT event, from the plugin's load");
    const size_t sc = server.find("g_connNo[ev.peer] = ++g_connNext;"), sa = server.find("NetThrottleOnConnect(ev.peer);", sc);
    if (sc == std::string::npos || sa == std::string::npos || sa > server.find("case ENET_EVENT_TYPE_DISCONNECT:", sc) || server.find("bool g_netThrottleOff = true;") == std::string::npos
        || server.find("NetThrottleApply(p, netthrottle::kShippedMode);") == std::string::npos)
        Fail("t1168 c: the world server does not set the shipped terms on each game's link at its CONNECT event, from the start");
    /* review LOW 1: a CONNECT handled late (held back by the backpressure) never configures a slot ENet already wiped */
    const size_t sf = server.find("void NetThrottleOnConnect(ENetPeer* p)"), sg = server.find("if (p == 0 || p->state != ENET_PEER_STATE_CONNECTED) return;", sf),
                 sn = server.find("NetThrottleApply(p, netthrottle::kShippedMode);", sf);
    if (sf == std::string::npos || sg == std::string::npos || sn == std::string::npos || !(sg < sn)) Fail("t1168 c LOW 1: the world server configures a link that is no longer connected");
    if (enet.find("lfRate_.NoteRoundTrip(now, ") == std::string::npos || server.find("s.rate.NoteRoundTrip(now, ") == std::string::npos)
        Fail("t1168 c LOW 2: an end does not date its round trips (the sliding window)");
    /* the allowance on both ends: the lowest round trip, and the world server counts acknowledged bytes against what ENet holds */
    if (enet.find("box_.SetBudget(lfRate_.BudgetLowest());") == std::string::npos || enet.find("lfRate_.NoteRoundTrip(") == std::string::npos
        || enet.find("lfRate_.ForgetRoundTrip();") == std::string::npos)
        Fail("t1168 c: the game's allowance does not use the link's lowest round trip");
    if (server.find("s.rate.Note(now, s.confirmed.Note(s.handed, s.netBytes, (unsigned int)p->reliableDataInTransit), s.box.RestWaiting());") == std::string::npos
        || server.find("s.box.SetBudget(s.rate.BudgetLowest());") == std::string::npos || server.find("s.box.Take(s.netCount, SbHeld(p, s), &x)") == std::string::npos
        || server.find("s.box.Direct(s.netCount, SbHeld(p, s), it,") == std::string::npos || server.find("sb.box.Direct(sb.netCount, SbHeld(d, sb), probe,") == std::string::npos)
        Fail("t1168 c: the world server's allowance does not measure acknowledged bytes, use the lowest round trip, or count what ENet holds until acknowledged");
}
/* T-1168 design (c): the allowance = the confirmed rate x (the LOWEST round trip + 100 ms); the confirmed count never goes back */
void t_t1168c_lowest_rtt_confirmed()
{
    livefirst::Rate r;
    if (r.LowestRoundTrip() != 0.0 || r.BudgetLowest() != livefirst::kBudgetMin) Fail("t1168 c: an unmeasured link - no round trip, the floor");
    r.Note(0.0, 0, true); r.Note(0.5, 500000, true);   /* 1 MB/s */
    r.NoteRoundTrip(1.0, 0.5);   /* ENet's starting figure before its first acknowledgement */
    r.NoteRoundTrip(1.1, 0.05); r.NoteRoundTrip(1.2, 0.0); r.NoteRoundTrip(1.3, -1.0);
    if (r.LowestRoundTrip() != 0.05) Fail("t1168 c: the lowest round trip is not the smallest positive one noted");
    r.NoteRoundTrip(3.0, 0.9);   /* the queue grows during a catch-up: the current round trip climbs */
    if (r.LowestRoundTrip() != 0.05) Fail("t1168 c: a grown round trip moved the lowest");
    const long long b = r.BudgetLowest();
    if (b != livefirst::BudgetOf(r.BytesPerSec(), 0.05) || b < 149999 || b > 150001) Fail("t1168 c: the allowance is not 1 MB/s x (50 ms + 100 ms)");
    if (r.Budget(0.9) <= b) Fail("t1168 c: setup - the current round trip would have given a larger allowance");
    r.ForgetRoundTrip();
    if (r.LowestRoundTrip() != 0.0 || r.BudgetLowest() != livefirst::BudgetOf(r.BytesPerSec(), 0.0)) Fail("t1168 c: a new connection kept the old lowest round trip");
    r.Note(1.0, 500000, true); r.Note(1.5, 100000000, true); r.NoteRoundTrip(4.0, 0.2);
    if (r.BudgetLowest() != livefirst::kBudgetMax) Fail("t1168 c: the 1 MB ceiling is not kept");
    /* review LOW 2 - the sliding window (kRttBucketSec 15 s: this bucket and the one before) */
    {
        if (livefirst::kRttBucketSec != 15.0) Fail("t1168 c: the round-trip bucket is not 15 s");
        /* a catch-up shorter than the window: the low is kept throughout */
        livefirst::Rate w; double t = 100.0;
        for (int i = 0; i < 50; ++i, t += 0.1) w.NoteRoundTrip(t, 0.03);
        for (int i = 0; i < 100; ++i, t += 0.1) w.NoteRoundTrip(t, 0.9);   /* 10 s of a grown queue */
        if (w.LowestRoundTrip() != 0.03) Fail("t1168 c: a 10 s catch-up moved the lowest round trip");
        /* a LASTING rise 30 -> 230 ms is followed within 15-30 s */
        livefirst::Rate u; t = 0.0; int ticks = 0;
        for (int i = 0; i < 50; ++i, t += 0.1) u.NoteRoundTrip(t, 0.03);
        while (u.LowestRoundTrip() < 0.23 && ticks < 1000) { u.NoteRoundTrip(t, 0.23); t += 0.1; ++ticks; }
        if (u.LowestRoundTrip() != 0.23 || ticks < 100 || ticks > 300) Fail("t1168 c: a lasting rise was not followed within 15-30 s (" + std::to_string((long long)ticks) + " ticks of 0.1 s)");
        if (u.BudgetLowest() != livefirst::BudgetOf(u.BytesPerSec(), 0.23)) Fail("t1168 c: the allowance does not follow the followed round trip");
        /* a brief dip (one tick at 10 ms among 30 ms) is kept at least one bucket, then let go */
        livefirst::Rate v; t = 0.0;
        for (int i = 0; i < 20; ++i, t += 0.1) v.NoteRoundTrip(t, 0.03);
        v.NoteRoundTrip(t, 0.01); t += 0.1;
        for (int i = 0; i < 149; ++i, t += 0.1) v.NoteRoundTrip(t, 0.03);   /* to 17 s */
        if (v.LowestRoundTrip() != 0.01) Fail("t1168 c: a brief dip was not kept for the window");
        for (int i = 0; i < 200; ++i, t += 0.1) v.NoteRoundTrip(t, 0.03);   /* to 37 s */
        if (v.LowestRoundTrip() != 0.03) Fail("t1168 c: a brief dip outlived two buckets");
        /* the clock goes back (a wrap of the tick count): a new bucket, the old one kept as the previous - no stuck or lost low */
        livefirst::Rate x;
        x.NoteRoundTrip(4294967.0, 0.04); x.NoteRoundTrip(4294967.2, 0.05);
        x.NoteRoundTrip(0.1, 0.2);   /* wrapped */
        if (x.LowestRoundTrip() != 0.04) Fail("t1168 c: a wrap lost the low of the bucket before it");
        for (double s = 0.2; s < 16.0; s += 0.1) x.NoteRoundTrip(s, 0.2);
        if (x.LowestRoundTrip() != 0.2) Fail("t1168 c: after a wrap the window does not move on (" + std::to_string((long long)(x.LowestRoundTrip() * 1000.0)) + " ms)");
        /* a gap of two buckets or more forgets the old low */
        livefirst::Rate g; g.NoteRoundTrip(0.0, 0.03); g.NoteRoundTrip(31.0, 0.2);
        if (g.LowestRoundTrip() != 0.2) Fail("t1168 c: a low older than the window was kept across a gap");
        g.ForgetRoundTrip();
        if (g.LowestRoundTrip() != 0.0) Fail("t1168 c: a new connection kept the window");
    }
    /* the confirmed count: handed less unsent less in transit, never back */
    livefirst::Confirmed c;
    if (c.Note(1000, 1000, 0) != 0) Fail("t1168 c: nothing sent is nothing confirmed");
    if (c.Note(1000, 400, 600) != 0) Fail("t1168 c: bytes sent but not acknowledged counted as confirmed");
    if (c.Note(1000, 400, 300) != 300) Fail("t1168 c: an acknowledgement of 300 bytes");
    if (c.Note(1000, 700, 0) != 300) Fail("t1168 c: a resend (in transit back to the unsent list) changed the count");   /* 300 timed out and wait again */
    if (c.Note(1000, 0, 700) != 300) Fail("t1168 c: the resend sent again changed the count");
    if (c.Note(1100, 150, 700) != 300) Fail("t1168 c: a bundle's header bytes made the count go back");   /* 50 header bytes ENet holds that were not handed */
    if (c.Note(1100, 0, 0x80000000u) != 300 || c.Note(1100, 0, 0xFFFFFFF0u) != 300) Fail("t1168 c: a wrapped in-transit read moved the count");
    if (c.Note(1100, 0, 100) != 1000 || c.Total() != 1000) Fail("t1168 c: acknowledgements after a wrap were not counted");
    if (livefirst::HeldBytes(500, 200) != 700 || livefirst::HeldBytes(500, 0xFFFFFFF0u) != 500) Fail("t1168 c: what ENet holds is unsent plus in transit");
    /* fed to Rate: a resend inside a window never restarts it */
    livefirst::Rate q; livefirst::Confirmed k;
    q.Note(0.0, k.Note(0, 0, 0), true);
    q.Note(0.1, k.Note(200000, 50000, 100000), true);
    q.Note(0.2, k.Note(200000, 120000, 30000), true);   /* resend: 70,000 back to unsent */
    q.Note(0.5, k.Note(200000, 0, 0), true);
    if (q.BytesPerSec() < 399999.0 || q.BytesPerSec() > 400001.0) Fail("t1168 c: 200 KB acknowledged in 0.5 s across a resend is not 400 KB/s");
}

/* T-1150 (owner 1491 a): the haul search's building owner test (0x59A240 at 1.0.65 0x59A39A / 1.0.68 0x59AE2A): the default
   8-byte test, then `je +0xBC` to the search loop's 'next building' (1.0.65 0x59A464 / 1.0.68 0x59AEF4). The constants policy.cpp
   checks, the two table rows (the same 16 bytes on both builds), the stub at both sites (the original test first - a player's
   building straight back; sixteen teammate cells, each read from its own cell and counted; a non-teammate gets the original test
   again; back to the je at site + 8), the cells' write (teammates only, emptied with no team), and the plugin's wiring. */
void t_t1150_haul_search_stub()
{
    using namespace coopcrime;
    const unsigned char* const orig = teamstub::kHaulSearchTestOrig;
    static const unsigned char test8[8] = { 0x48, 0x83, 0xB8, 0x50, 0x02, 0x00, 0x00, 0x00 };
    if (teamstub::kHaulSearchOrigLen != 10 || teamstub::kHaulSearchTestLen != 8) Fail("t1150: the checked length is the test + je opcode (10, re-done 8)");
    if (std::memcmp(orig, test8, 8) != 0 || orig[8] != 0x0F || orig[9] != 0x84) Fail("t1150: the haul search test is the default 8-byte test, then je");
    {   /* the je lands on 'next building' on both builds */
        const unsigned long long sites[2] = { 0x59A39AULL, 0x59AE2AULL }, skip[2] = { 0x59A464ULL, 0x59AEF4ULL };
        for (int s = 0; s < 2; ++s) if (sites[s] + 8 + 6 + (unsigned long long)teamstub::kHaulSearchSkipRel != skip[s]) Fail("t1150: the je skips to the search loop's next building");
    }
    {   /* the table rows: both builds, the test, the je's opcode and its rel32 */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        if (t65.find("HaulStoreSearchOwnerTest                       code 0059A39A 0059A39A 4883B850020000000F84BC0000004D85") == std::string::npos)
            Fail("t1150: the 1.0.65 table has no HaulStoreSearchOwnerTest row at 0x59A39A");
        if (t68.find("HaulStoreSearchOwnerTest                       code 0059AE2A 0059AE2A 4883B850020000000F84BC0000004D85") == std::string::npos)
            Fail("t1150: the 1.0.68 table has no HaulStoreSearchOwnerTest row at 0x59AE2A");
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        if (sig.find("\nHaulStoreSearchOwnerTest code ") == std::string::npos) Fail("t1150: the signatures have no HaulStoreSearchOwnerTest row");
    }
    {   /* the stub at both builds' sites, sixteen cells (policy.cpp's count) at 0x400 */
        const int off = 0x400, cells = 16;
        const unsigned long long sites[2] = { 0x14059A39AULL, 0x14059AE2AULL };
        for (int s = 0; s < 2; ++s)
        {
            std::vector<unsigned char> p(0x1000, 0xCC);
            const int len = SightStubBuild(&p[0], sites[s], cells, off);
            if (len != 50 + 13 * cells || len != SightStubLenFor(8, cells) || len > off) { Fail("t1150: stub length " + I(len)); continue; }
            if (off + 8 + 8 * cells > 0x1000) Fail("t1150: the cells fit the stub's page");
            const int H = 14, N = H + 13 * cells;
            if (std::memcmp(&p[0], test8, 8) != 0 || p[8] != 0x0F || p[9] != 0x85) Fail("t1150: the original test first, a player's building straight back");
            int d = 0;
            for (int k = 0; k < cells; ++k)
            {
                const int o = H + 13 * k;
                std::memcpy(&d, &p[o + 3], 4); if (p[o] != 0x48 || p[o + 1] != 0x3B || p[o + 2] != 0x05 || o + 7 + d != off + 8 + 8 * k) { Fail("t1150: cell compare " + I(k) + " reads its own cell"); break; }
                if (p[o + 7] != 0x0F || p[o + 8] != 0x84) { Fail("t1150: cell compare " + I(k) + " jumps on a match"); break; }
            }
            if (std::memcmp(&p[N], test8, 8) != 0) Fail("t1150: a non-teammate gets the original test again (ZF=1: skipped as before)");
            unsigned long long to = 0; std::memcpy(&to, &p[N + 28], 8);
            if (to != sites[s] + 8) Fail("t1150: back to the je at site + 8");
            if (p[len] != 0xCC) Fail("t1150: nothing written past the stub");
        }
    }
    {   /* the cells: this game's teammates' factions only, emptied with no team */
        void* volatile c[16];
        for (int k = 0; k < 16; ++k) c[k] = (void*)(size_t)(0x7000 + k);
        void* mates[2] = { (void*)0x2000, (void*)0x2100 };
        if (teamstub::MateCellsWrite(c, 16, mates, 2) != 2 || c[0] != (void*)0x2000 || c[1] != (void*)0x2100 || c[2] != 0) Fail("t1150 cells: two teammates held, the rest empty");
        if (teamstub::MateCellsWrite(c, 16, 0, 0) != 0 || c[0] != 0 || c[1] != 0) Fail("t1150 cells: leaving the team empties every cell");
    }
    {   /* the wiring: the row bound, the patch with this site's own constant, the cells written with the teammates' */
        const std::string pol = T313ReadFile("../coop-plugin/policy.cpp");
        if (pol.find("AddrReg kHaulSearchTestRva_reg(\"HaulStoreSearchOwnerTest\", &kHaulSearchTestRva)") == std::string::npos) Fail("t1150: policy.cpp does not bind the row");
        if (pol.find("Test8Patch(g_base + (uintptr_t)kHaulSearchTestRva, kHaulSearchTestOrig, g_haulCells, g_haulWhy)") == std::string::npos) Fail("t1150: policy.cpp does not patch the site with its own bytes");
        const size_t tf = pol.find("void PolicyTeammateFactions(void* const* facs, int n)");
        const size_t hw = pol.find("g_haulHeld = MateCellsWrite(g_haulCells, facs, n)");
        if (tf == std::string::npos || hw == std::string::npos || hw < tf) Fail("t1150: the haul cells are not written from the teammates' list");
        if (pol.find("teamHaul[patched,cellsHeld,hits]=") == std::string::npos) Fail("t1150: the report line has no teamHaul counter");
    }
}

/* T-1150 second gate: the storage search's candidate gather (1.0.65 0x8CAFD0 / 1.0.68 0x8CBEA0, called from the search 0x59A240 with
   return 0x59A2C7 / 0x59AD57) and the engine's owner filter (0x6207A0 / 0x621230) it asks, which drops another faction's building
   with an inventory. The pure answer (the engine's keep stays; a dropped building is kept only during the search's gather and
   only for a teammate's faction), the cells' lookup, the three rows on both builds and the signatures, and the plugin's wiring. */
/* ---- T-1260: a body part a player takes from a knocked-out animal another game runs kills it there, as in single player ---- */
static std::string T1260Flat(const char* path)
{
    std::string s = T313ReadFile(path);
    s.erase(std::remove(s.begin(), s.end(), '\r'), s.end());   /* a CRLF checkout reads the same as an LF one */
    return s;
}
/* ---- T-1309 (F-T1309-GATEISLAND): a copy gets an interior walking map only when the engine's own load test would give it one ---- */
void t_t1309_engine_interior()
{
    namespace cb = coopbuild;
    /* the engine's parts: read, vt+0x20, interior pointer, vt+0x2C8, vt+0x3D8 (isGate), interior +0x2C */
    if (cb::BuildEngineGivesInterior(1, 0, 1, 0, 0, 0) != 1) Fail("t1309 island: a house (interior pointer, no wall part, not a gate) gets its interior");
    if (cb::BuildEngineGivesInterior(1, 0, 1, 0, 1, 0) != 0) Fail("t1309 island: a gate (isGate answers itself) gets none though its interior pointer is set");
    if (cb::BuildEngineGivesInterior(1, 0, 1, 1, 0, 0) != 0) Fail("t1309 island: a wall (vt+0x2C8 answers) gets none though its interior pointer is set");
    if (cb::BuildEngineGivesInterior(0, 0, 1, 0, 0, 0) != 0) Fail("t1309 island: a fault / unreadable test gives none");
    if (cb::BuildEngineGivesInterior(1, 0, 0, 0, 0, 0) != 0) Fail("t1309 island: no interior pointer, none");
    if (cb::BuildEngineGivesInterior(1, 3, 1, 0, 0, 0) != 0 || cb::BuildEngineGivesInterior(1, 0, 1, 0, 0, 1) != 0)
        Fail("t1309 island: vt+0x20 non-zero or the interior's +0x2C byte set gives none (the engine's load test)");
    /* what the walking-map decision then queues for a solid copy made: the gate and the wall their box only, the house both */
    if (cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, cb::BuildEngineGivesInterior(1, 0, 1, 0, 1, 0), 0) != cb::kWmBox
        || cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, cb::BuildEngineGivesInterior(1, 0, 1, 1, 0, 0), 0, 1) != cb::kWmBox
        || cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, cb::BuildEngineGivesInterior(1, 0, 1, 0, 0, 0), 0) != (cb::kWmBox | cb::kWmInterior))
        Fail("t1309 island: a gate / wall copy made queues its box only, a house its box and interior");
    /* the engine's offsets (1.0.65 0x3ABF00 and 1.0.68 0x3AC040, byte-identical - the brief's check) */
    if (cb::kEngIntVtKind != 0x20 || cb::kEngIntVtWallPart != 0x2C8 || cb::kEngIntVtGate != 0x3D8 || cb::kEngIntFlag != 0x2C)
        Fail("t1309 island: the load test's offsets");
    /* the call site: BdWalkMapNote asks the engine's test, not the pointer alone */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1309 island: build.cpp not readable"); return; }
    if (src.find("const int interior = coopbuild::BuildEngineGivesInterior(eiRead, eiKind, eiPtr, eiWallPart, eiGate, eiFlag);") == std::string::npos
        || src.find("const int interior = (BdPtrAt(b, kBInterior) != 0) ? 1 : 0;") != std::string::npos)
        Fail("t1309 island: BdWalkMapNote decides the interior by the engine's load test");
    if (src.find("walkMapInterior[engineNo,faulted]") == std::string::npos) Fail("t1309 island: the counters on the build report");
}
/* ---- T-1428 (E1 vs E4): `buildtest cursor .. preview` leaves the preview standing for a later `commit` ---- */
void t_t1428_preview_probe()
{
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1428 preview: build.cpp not readable"); return; }
    const char* const need[] = {
        "const int pw = (a5 == \"preview\") ? 1 : 0;",
        "g_btCursorCommit = cw; g_btCursorPreview = pw; kind = 12;",
        "if (commit == 0 && g_btCursorPreview != 0) { r->held = 1; g_btHeldPreview = r->p; g_btHeldGd = gd; g_btHeldAt = ::GetTickCount(); }",
        "if (r->held != 0) return;",
        "if (commit == 0 || gd != g_btHeldGd) { r->refused = \"a held preview waits for its `commit` (the same record)\"; return; }",
        "{ r->p = g_btHeldPreview; r->reused = 1; r->heldMs = ::GetTickCount() - g_btHeldAt; g_btHeldPreview = 0; g_btHeldGd = 0; }",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1428 preview: missing ") + need[i]);
    /* the held preview is never destroyed by the lever before its commit: the hold's return comes before the destroy */
    const size_t h = src.find("if (r->held != 0) return;"), d = src.find("((BdPrevDestroyFn)(base + (uintptr_t)kBdPrevDestroyRva))(list, r->p);");
    if (h == std::string::npos || d == std::string::npos || h > d) Fail("t1428 preview: the hold returns before the destroy");
    /* the held check comes before the 'already on the cursor' refusal */
    const size_t c = src.find("if (g_btHeldPreview != 0)"), cur = src.find("r->refused = \"a building preview is already on the cursor\"");
    if (c == std::string::npos || cur == std::string::npos || c > cur) Fail("t1428 preview: the held check comes first");
}
/* ---- T-1426 (F1245): a furniture piece the mod makes or removes queues its HOST building's interior walking map, as the engine's
   confirm build step 0x4D6810 does (decomp_4d6810:365-373) ---- */
/* ---- T-1427 part 2 (owner request 2026-11-18, F1270): a copy is made in the town the builder's rule gives - its record's town, the
   outpost the PLACE names, the owner's town nearest within 5000 - else 'Nowhere', never the engine's town-0 fallback ---- */
void t_t1427_copy_town()
{
    namespace cb = coopbuild;
    int pick = 7;
    /* no candidate: Nowhere */
    const float spot[2] = { 1000.0f, 1000.0f };
    if (cb::CopyTownChoose(0, 0, 0, spot, 50.0f, 5000.0f, &pick) != cb::kCtNowhere || pick != -1) Fail("t1427 copy town: no town of the owner here - Nowhere");
    cb::CopyTownCand c[3];
    c[0].cx = 4000.0f; c[0].cz = 1000.0f;                       /* 3000 from the spot */
    c[1].cx = 1000.0f; c[1].cz = 5000.0f;                       /* 4000 from the spot */
    c[2].cx = 9000.0f; c[2].cz = 9000.0f; c[2].hasList = 1; c[2].listX = 20000.0f; c[2].listZ = 20000.0f;   /* far */
    /* near: the nearest, kept within 5000 */
    if (cb::CopyTownChoose(c, 3, 0, spot, 50.0f, 5000.0f, &pick) != cb::kCtNear || pick != 0) Fail("t1427 copy town: the owner's town nearest the spot within 5000");
    const float far[2] = { -20000.0f, -20000.0f };
    if (cb::CopyTownChoose(c, 3, 0, far, 50.0f, 5000.0f, &pick) != cb::kCtNowhere || pick != -1) Fail("t1427 copy town: the nearest town past 5000 - Nowhere (the confirm keeps only within 5000)");
    const float edge[2] = { 9000.0f, 1000.0f };   /* c[0] exactly 5000 away */
    if (cb::CopyTownChoose(c, 3, 0, edge, 50.0f, 5000.0f, &pick) != cb::kCtNear || pick != 0) Fail("t1427 copy town: 5000 itself is kept");
    /* named: by its own centre or the list centre, within the radius, before the spot's nearest */
    const float named[2] = { 20010.0f, 20000.0f };
    if (cb::CopyTownChoose(c, 3, named, spot, 50.0f, 5000.0f, &pick) != cb::kCtNamed || pick != 2) Fail("t1427 copy town: the outpost the PLACE names (list centre), at any distance from the piece");
    const float namedOwn[2] = { 1000.0f, 5030.0f };
    if (cb::CopyTownChoose(c, 3, namedOwn, spot, 50.0f, 5000.0f, &pick) != cb::kCtNamed || pick != 1) Fail("t1427 copy town: the outpost the PLACE names (its own centre)");
    /* named, not within the radius: the town whose area holds it; none - the near rule */
    const float namedOff[2] = { 30000.0f, 30000.0f };
    c[1].holdsNamed = 1;
    if (cb::CopyTownChoose(c, 3, namedOff, spot, 50.0f, 5000.0f, &pick) != cb::kCtNamedArea || pick != 1) Fail("t1427 copy town: a named centre that moved - the town whose area holds it");
    c[1].holdsNamed = 0;
    if (cb::CopyTownChoose(c, 3, namedOff, spot, 50.0f, 5000.0f, &pick) != cb::kCtNear || pick != 0) Fail("t1427 copy town: a named outpost not standing here - the near rule");
    /* record: first of all */
    c[2].recordNamed = 1;
    if (cb::CopyTownChoose(c, 3, named, spot, 50.0f, 5000.0f, &pick) != cb::kCtRecord || pick != 2) Fail("t1427 copy town: the record's town comes first");
    c[2].recordNamed = 0;
    for (int r = cb::kCtNowhere; r <= cb::kCtNear; ++r) if (std::string(cb::CopyTownRuleWord(r)) == "?") Fail("t1427 copy town: every rule has its words");
    /* wiring: no copy road passes town 0 any more; the judge at the link steps; the report token */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1427 copy town: build.cpp not readable"); return; }
    const char* const need[] = {
        "ct = BdCopyTownFor(recSlot, mySlot, m.townHand != 0 ? m.townPos : 0, pos, recT);",
        ": BdCallCreateTown(fn, factory, gd, pos, ct.town, (void*)want, rot, m.complete != 0, &faulted);",
        "if (furn == 0) BdCopyTownMade(m.key, b, ct, fresh);",
        "if (furn == 0) ct = BdCopyTownFor(-2, MySlotForWire(), 0, pos, town != 0 ? town : TlRecordFactTown(w.p.key));",
        ": BdCallCreateTown(fn, factory, gd, pos, ct.town, owner, rot, w.p.complete != 0, &faulted);",
        "void* b = BdKeptCreate(w, furn, host, pos, rot, (void*)to, town, &cwhy);",
        "r.rule = coopbuild::CopyTownChoose(",
        "__try { return *(void* const*)((const char*)tl + kTownListWild); }",
        "BdCopyTownJudge(r->first, town[row], \"the [SHOW] link step - already in it\", coopbuild::kSwAlready, 0);",
        "BdCopyTownJudge(r->first, t, \"the [SHOW] link step - linked to it\", coopbuild::kSwDone, 0);",
        "BdCopyTownJudge(key, t, \"the [TOWNLINK] record link\", r == baseshow::kRelinkDone ? coopbuild::kSwDone : coopbuild::kSwRefused, 0);",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1427 copy town: missing in build.cpp: ") + need[i]);
    /* the only town-0 creations left are the test levers' (buildtest place / into) */
    size_t at = 0;
    int plain = 0;
    while ((at = src.find("BdCallCreate(fn, factory,", at)) != std::string::npos) { ++plain; ++at; }
    if (plain != 1) Fail("t1427 copy town: one town-0 createBuilding left (the buildtest place lever)");
}
/* ---- T-1427 fold 1 (F1278; owner request 2026-11-18): the record carries the builder's ACTUAL town - an outpost, a world town, or
   'Nowhere' - the copy is made in it, and every DIFFER is switched ---- */
static int T1427FactRoundTrip(const piecerec::PieceLive& in, piecerec::PieceLive* out)
{
    std::vector<char> b;
    piecerec::PieceLivePut(&b, in);
    return piecerec::PieceLiveGet(b.empty() ? "" : &b[0], b.size(), out);
}
void t_t1427_town_fact()
{
    namespace pr = piecerec;
    namespace cb = coopbuild;
    if (pr::kPrLiveFlagTownFact != 256u || (pr::kPrLiveFlagsAll & pr::kPrLiveFlagTownFact) == 0u || (pr::kPrLiveFlagsBeforeTownFact & pr::kPrLiveFlagTownFact) != 0u
        || pr::kProtocol != 170u) Fail("t1427 fold 1: the town fact is bit 8 of world-server protocol 170 (165 when it came), refused by an older peer");
    /* each town kind round-tripped through the record's LIVE part */
    {
        pr::PieceLive l; l.have = 1; l.hasPower = 0;
        pr::PieceTownFact o; o.kind = pr::kPtfOutpost; o.id = 77u;
        if (pr::PieceTownFactPut(&l, o) != 1) Fail("t1427 fold 1: an outpost is carriable");
        pr::PieceLive r;
        if (T1427FactRoundTrip(l, &r) != 1 || pr::PieceTownFactSame(pr::PieceTownFactOf(r), o) == 0 || pr::PieceTownOf(r) != 77u || r.townFact != 0u)
            Fail("t1427 fold 1: an outpost round-trips as bit 5 (its id)");
        pr::PieceTownFact w; w.kind = pr::kPtfWorld; w.sid = "1234-gamedata.base";
        if (pr::PieceTownFactPut(&l, w) != 1 || l.hasTown != 0) Fail("t1427 fold 1: a world town replaces the outpost");
        if (T1427FactRoundTrip(l, &r) != 1 || pr::PieceTownFactSame(pr::PieceTownFactOf(r), w) == 0 || pr::PieceTownOf(r) != 0u) Fail("t1427 fold 1: a world town round-trips by its stringID");
        pr::PieceTownFact n; n.kind = pr::kPtfNowhere;
        if (pr::PieceTownFactPut(&l, n) != 1 || !l.townSid.empty()) Fail("t1427 fold 1: 'Nowhere' carries no id");
        if (T1427FactRoundTrip(l, &r) != 1 || pr::PieceTownFactOf(r).kind != pr::kPtfNowhere) Fail("t1427 fold 1: 'Nowhere' round-trips as an explicit kind");
        pr::PieceTownSet(&l, 9u);
        if (l.townFact != 0u || pr::PieceTownFactOf(l).kind != pr::kPtfOutpost) Fail("t1427 fold 1: an outpost link replaces a town fact");
        pr::PieceTownFact none;
        if (pr::PieceTownFactPut(&l, none) != 1 || pr::PieceTownFactOf(l).kind != pr::kPtfNone) Fail("t1427 fold 1: none clears both");
        if (T1427FactRoundTrip(l, &r) != 1 || pr::PieceTownFactOf(r).kind != pr::kPtfNone) Fail("t1427 fold 1: an older record (no town) reads 'not known'");
        /* with the variable tails before it: doors and a craft list */
        pr::PieceLive d; d.have = 1; d.hasPower = 0; d.hasDoors = 1; d.nd = 2; d.doorHealth[0] = 1.0f; d.doorHealth[1] = 2.0f;
        d.hasCraft = 1; d.craftIn = 1; d.craftTotal = 1; pr::PieceCraftEntry ce; ce.sid = "x"; d.craft.push_back(ce);
        pr::PieceTownFactPut(&d, w);
        if (T1427FactRoundTrip(d, &r) != 1 || pr::PieceTownFactSame(pr::PieceTownFactOf(r), w) == 0 || r.nd != 2 || r.craft.size() != 1u) Fail("t1427 fold 1: the fact after doors and a craft list");
        d.hasCraft = 0; d.craftIn = 0; d.craftTotal = 0; d.craft.clear();
        if (T1427FactRoundTrip(d, &r) != 1 || pr::PieceTownFactSame(pr::PieceTownFactOf(r), w) == 0 || r.nd != 2) Fail("t1427 fold 1: the fact after doors, no craft list");
    }
    /* refusals: never both an outpost and a fact; a bad kind or id; a byte after it */
    {
        pr::PieceLive l; l.have = 1; l.hasPower = 0;
        l.hasTown = 1; l.town = 5u; l.townFact = pr::kPrTownFactNowhere;
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: an outpost AND a fact is refused");
        l.hasTown = 0; l.town = 0u; l.townFact = 3u;
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: an unknown fact kind is refused");
        l.townFact = pr::kPrTownFactWorld; l.townSid = "";
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: a world town with no id is refused");
        l.townSid = std::string(65, 'a');
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: a world town id over 64 bytes is refused");
        l.townSid = std::string("a\x01b");
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: a control byte in the id is refused");
        l.townSid = std::string(64, 'a');
        if (!pr::PieceLiveValid(l)) Fail("t1427 fold 1: a 64-byte id is taken");
        l.townFact = pr::kPrTownFactNowhere; l.townSid = "x";
        if (pr::PieceLiveValid(l)) Fail("t1427 fold 1: 'Nowhere' with an id is refused");
        pr::PieceLive w; w.have = 1; w.hasPower = 0; w.townFact = pr::kPrTownFactWorld; w.townSid = "Squin";
        std::vector<char> b;
        pr::PieceLivePut(&b, w);
        pr::PieceLive r;
        std::vector<char> extra(b); extra.push_back('z');
        if (pr::PieceLiveGet(&extra[0], extra.size(), &r) != 0) Fail("t1427 fold 1: a byte after the fact is refused");
        std::vector<char> cut(b.begin(), b.end() - 1);
        if (pr::PieceLiveGet(&cut[0], cut.size(), &r) != 0) Fail("t1427 fold 1: a cut id is refused");
        std::vector<char> k0(b); k0[12] = 0; k0[13] = 0; k0[14] = 0; k0[15] = 0;   /* flags | battery | n | KIND */
        if (pr::PieceLiveGet(&k0[0], k0.size(), &r) != 0) Fail("t1427 fold 1: bit 8 with kind 0 is refused");
    }
    /* the builder's write: the owner's game writes its engine's world town / 'Nowhere'; any other writer keeps the stored one */
    {
        pr::PieceTownFact eng; eng.kind = pr::kPtfWorld; eng.sid = "Squin";
        pr::PieceTownFact kept; kept.kind = pr::kPtfNowhere;
        pr::PieceTownFact none, player; player.kind = pr::kPtfOutpost;
        if (pr::PieceTownFactSame(pr::PieceTownFactWrite(1, eng, kept), eng) == 0) Fail("t1427 fold 1: the owner's game writes its engine's town");
        if (pr::PieceTownFactSame(pr::PieceTownFactWrite(0, eng, kept), kept) == 0) Fail("t1427 fold 1: another writer keeps the stored fact");
        if (pr::PieceTownFactWrite(1, player, none).kind != pr::kPtfNone) Fail("t1427 fold 1: a player's town whose id is not known writes nothing (the outpost mark's)");
        if (pr::PieceTownFactWrite(1, none, kept).kind != pr::kPtfNowhere) Fail("t1427 fold 1: an unread engine town keeps the stored fact");
        /* the mark: owner, writer, no outpost on the record, a changed fact, not already marked */
        if (pr::PieceTownFactMarkDue(1, 1, 0u, eng, kept, none) != 1) Fail("t1427 fold 1: a moved building marks a write (Nowhere -> a world town)");
        if (pr::PieceTownFactMarkDue(1, 1, 0u, eng, eng, none) != 0) Fail("t1427 fold 1: the record already says it - no write");
        if (pr::PieceTownFactMarkDue(1, 1, 0u, eng, kept, eng) != 0) Fail("t1427 fold 1: a write of it already marked");
        if (pr::PieceTownFactMarkDue(1, 1, 4u, eng, kept, none) != 0) Fail("t1427 fold 1: a record naming an outpost is the outpost mark's (T-1332 moves the piece)");
        if (pr::PieceTownFactMarkDue(1, 0, 0u, eng, kept, none) != 0 || pr::PieceTownFactMarkDue(0, 1, 0u, eng, kept, none) != 0) Fail("t1427 fold 1: only the owner's game, as the writer");
        if (pr::PieceTownFactMarkDue(1, 1, 0u, player, kept, none) != 0) Fail("t1427 fold 1: a player's town is the outpost mark's");
    }
    /* part 2's rule (an older record): 'the named outpost gone, none near' - Nowhere; the near rule measures a shown town from the list */
    {
        int pick = 9;
        cb::CopyTownCand c[2];
        c[0].cx = 50000.0f; c[0].cz = 50000.0f;
        c[1].cx = 60000.0f; c[1].cz = 60000.0f; c[1].hasList = 1; c[1].listX = 61000.0f; c[1].listZ = 60000.0f;
        const float named[2] = { 30000.0f, 30000.0f }, spot[2] = { 1000.0f, 1000.0f };
        if (cb::CopyTownChoose(c, 2, named, spot, 50.0f, 5000.0f, &pick) != cb::kCtNowhere || pick != -1) Fail("t1427 fold 1: the named outpost gone, none near - Nowhere");
        cb::CopyTownCand s[2];
        s[0].cx = 3000.0f; s[0].cz = 1000.0f;                                           /* 2000 from the spot by its own centre */
        s[1].cx = 9000.0f; s[1].cz = 9000.0f; s[1].hasList = 1; s[1].listX = 2000.0f; s[1].listZ = 1000.0f;   /* its outpost's centre 1000 from the spot */
        if (cb::CopyTownChoose(s, 2, 0, spot, 50.0f, 5000.0f, &pick) != cb::kCtNear || pick != 1) Fail("t1427 fold 1: a shown town is measured from its outpost's centre (the builder's)");
    }
    /* the engine-override write after createBuilding */
    if (cb::CopyTownMadeStep(0, 0, 0) != cb::kCmEnginePick || cb::CopyTownMadeStep(1, 1, 0) != cb::kCmTook || cb::CopyTownMadeStep(1, 0, 1) != cb::kCmWritten
        || cb::CopyTownMadeStep(1, 0, -1) != cb::kCmWriteFailed) Fail("t1427 fold 1: the made step (engine pick / taken / written / write failed)");
    /* MATCH / DIFFER: every DIFFER switched; the four unswitched cases stay owed */
    if (cb::CopyTownJudgeStep(1, 0, cb::kSwRefused) != cb::kCjMatch || cb::CopyTownJudgeStep(1, 1, cb::kSwNone) != cb::kCjMatch) Fail("t1427 fold 1: same town - MATCH, whatever the switch did");
    if (cb::CopyTownJudgeStep(0, 0, cb::kSwDone) != cb::kCjSwitched || cb::CopyTownJudgeStep(0, 0, cb::kSwAlready) != cb::kCjSwitched) Fail("t1427 fold 1: DIFFER switched");
    if (cb::CopyTownJudgeStep(0, 0, cb::kSwRefused) != cb::kCjOwedRefused || cb::CopyTownJudgeStep(0, 0, cb::kSwFault) != cb::kCjOwedFault
        || cb::CopyTownJudgeStep(0, 0, cb::kSwInside) != cb::kCjOwedInside || cb::CopyTownJudgeStep(0, 0, cb::kSwNone) != cb::kCjOwedRefused) Fail("t1427 fold 1: the unswitched DIFFERs stay owed");
    if (cb::CopyTownJudgeStep(0, 1, cb::kSwDone) != cb::kCjOwnNoSwitch) Fail("t1427 fold 1: this game's own piece - compared, never switched (T-1047)");
    /* g_ctMade: an entry leaves when compared; only an owed switch keeps it */
    for (int s = 0; s <= cb::kCjMax; ++s)
    {
        const int keep = (s == cb::kCjOwedRefused || s == cb::kCjOwedFault || s == cb::kCjOwedInside) ? 1 : 0;
        if (cb::CopyTownJudgeKeeps(s) != keep) Fail("t1427 fold 1: the copy's entry stays only while a switch is owed");
        if (std::string(cb::CopyTownJudgeWord(s)) == "?") Fail("t1427 fold 1: every judge step has its words");
    }
    /* wiring */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1427 fold 1: build.cpp not readable"); return; }
    const char* const need[] = {
        "fact = piecerec::PieceTownFactWrite(own, eng, keptF);",
        "else piecerec::PieceTownFactPut(lv, fact);",
        "if (engineId == 0 && kept == 0) { TlFactMark(id, key, b, k, *w); return; }",
        "else recT = TlRecordFactTown(m.key);",
        "t = TlFactTownHere(fact);",
        "BdCopyTownJudge(key, t, \"the [TOWNLINK] record's town - already in it\", coopbuild::kSwAlready, 0);",
        "if (step == piecerec::kTlInside) { ++g_tlInside; if (owed != 0 && t != 0) BdCopyTownJudge(key, t, \"the [TOWNLINK] record's town\", coopbuild::kSwInside, 0); return 0; }",
        "if (set == 0) { ++g_slFault; BdCopyTownJudge(r->first, t, \"the [SHOW] link step\", coopbuild::kSwFault, 0); continue; }",
        "if (set < 0) { ++inside; BdCopyTownJudge(r->first, t, \"the [SHOW] link step\", coopbuild::kSwInside, 0); continue; }",
        "BdCopyTownSweep();",
        "BdCopyTownForgetWorld();",
        "g_ctMade[key] = mk;",
        "mk.made = coopbuild::CopyTownMadeStep(",
        "if (k.h.ownerSlot == mySlot && BdCopyTownOwed(k.h.key) == 0) return 0;",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1427 fold 1: missing in build.cpp: ") + need[i]);
    if (src.find("kCtMapCap") != std::string::npos || src.find("g_ctMapFull") != std::string::npos) Fail("t1427 fold 1: no silent cap on the copies awaiting their comparison");
}
/* ---- T-1427 fold 2 (F1284 re-review SHOULDs): every world town is looked at; the record's town wins over the [SHOW] link step ---- */
void t_t1427_fold2()
{
    namespace pr = piecerec;
    namespace cb = coopbuild;
    /* SHOULD 1: the pick sees EVERY world town - a list of 300 (past the old 256 walk cap) finds the last one */
    {
        std::vector<std::string> sids;
        for (int i = 0; i < 300; ++i) { char b[32]; _snprintf_s(b, sizeof(b), _TRUNCATE, "%d-town.base", i); sids.push_back(b); }
        int hits = -1;
        if (cb::WorldTownPick(sids, "299-town.base", &hits) != 299 || hits != 1) Fail("t1427 fold 2: a world town past the 256th is found");
        if (cb::WorldTownPick(sids, "0-town.base", &hits) != 0 || hits != 1) Fail("t1427 fold 2: the first world town is found");
        if (cb::WorldTownPick(sids, "Squin", &hits) != -1 || hits != 0) Fail("t1427 fold 2: no town with the id - none (worldMissing)");
        sids.push_back("7-town.base");
        if (cb::WorldTownPick(sids, "7-town.base", &hits) != -1 || hits != 2) Fail("t1427 fold 2: two towns with the id - none, never a guess (worldTwice)");
        if (cb::WorldTownPick(sids, "", &hits) != -1 || hits != 0) Fail("t1427 fold 2: an empty id names no town");
        std::vector<std::string> none;
        if (cb::WorldTownPick(none, "Squin", &hits) != -1 || hits != 0) Fail("t1427 fold 2: no world towns - none");
        if (cb::WorldTownPick(sids, "1-town.base", 0) != 1) Fail("t1427 fold 2: the hit count is optional");
    }
    /* SHOULD 2: one decider - the record's town (an outpost id, or a world town / 'Nowhere' fact) wins; [SHOW] only for no record's town */
    {
        pr::PieceLive l; l.have = 1; l.hasPower = 0;
        if (pr::PieceTownDecider(1, 0, l) != pr::kTownByShow) Fail("t1427 fold 2: a record naming no town (an older build's) - the [SHOW] step decides");
        pr::PieceTownFact o; o.kind = pr::kPtfOutpost; o.id = 12u; pr::PieceTownFactPut(&l, o);
        if (pr::PieceTownDecider(1, 0, l) != pr::kTownByOutpost) Fail("t1427 fold 2: an outpost link - the record link decides");
        pr::PieceTownFact w; w.kind = pr::kPtfWorld; w.sid = "Squin"; pr::PieceTownFactPut(&l, w);
        if (pr::PieceTownDecider(1, 0, l) != pr::kTownByFact) Fail("t1427 fold 2: a world town fact - the record decides, [SHOW] defers");
        pr::PieceTownFact n; n.kind = pr::kPtfNowhere; pr::PieceTownFactPut(&l, n);
        if (pr::PieceTownDecider(1, 0, l) != pr::kTownByFact) Fail("t1427 fold 2: 'Nowhere' - the record decides, [SHOW] never moves it into an outpost");
        if (pr::PieceTownDecider(0, 0, l) != pr::kTownByShow || pr::PieceTownDecider(1, 1, l) != pr::kTownByShow) Fail("t1427 fold 2: no record, or a removal mark - the [SHOW] step decides");
        pr::PieceLive gone; gone.have = 0;
        if (pr::PieceTownDecider(1, 0, gone) != pr::kTownByShow) Fail("t1427 fold 2: a record with no LIVE part - the [SHOW] step decides");
    }
    /* wiring: [SHOW] and the record walk use the one decider; the joiner's lookup has no cap; ids read once per look */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1427 fold 2: build.cpp not readable"); return; }
    const char* const need[] = {
        "const int by = TlTownDeciderOf(r->first);",
        "if (by != piecerec::kTownByShow) { TlShowYield(r->first, by); continue; }",
        "return piecerec::PieceTownDecider(1, 0, l) != piecerec::kTownByShow ? 1 : 0;",
        "return piecerec::PieceTownDecider(1, (k->second.h.flags & piecerec::kPrFlagRemoved) != 0 ? 1 : 0, k->second.b.live);",
        "const int at = coopbuild::WorldTownPick(*sids, f.sid, &hits);",
        "const int n = BdWorldTownsPod(&(*towns)[0], na);",
        "if (g_tfLookN == -2) g_tfLookN = BdWorldTownIds(&g_tfLookTowns, &g_tfLookSids);",
        "TlFactLookBegin();   /* T-1427 fold 2",
        "TlFactLookEnd();",
        "g_tlShowYieldSaid.clear();",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1427 fold 2: missing in build.cpp: ") + need[i]);
    if (src.find("BdWorldTownsPod(towns, kTownWalkCap)") != std::string::npos) Fail("t1427 fold 2: the world-town lookup still walks only kTownWalkCap towns");
    if (src.find("TlRecordLinkOf(r->first) != 0") != std::string::npos) Fail("t1427 fold 2: the [SHOW] link step still defers only to an outpost link");
    /* the [SHOW] decider check sits in the link step, before its town write */
    const size_t dec = src.find("const int by = TlTownDeciderOf(r->first);"), wr = src.find("const int set = BdBuildingSetTownPod(b, t);", dec == std::string::npos ? 0 : dec);
    if (dec == std::string::npos || wr == std::string::npos || wr - dec > 8000) Fail("t1427 fold 2: the [SHOW] link step's decider is not before its town write");
    /* the look's begin / end pair around the record walk */
    const size_t lb = src.find("TlFactLookBegin();   /* T-1427 fold 2"), ap = src.find("if (TlApplyPiece(k.h.key, b, k, mySlot, 0) != 0) ++writes;"), le = src.find("    TlFactLookEnd();");
    if (lb == std::string::npos || ap == std::string::npos || le == std::string::npos || !(lb < ap && ap < le)) Fail("t1427 fold 2: the look's id cache does not wrap the record walk");
}
/* ---- T-1427 (F1265): a re-towned building's floor parts move to its new town's floor store ---- */
void t_t1427_floor_store()
{
    namespace cb = coopbuild;
    const unsigned long long oldS = 0x1000250ull, newS = 0x2000250ull, third = 0x3000250ull;
    /* the host: a move only when its models are made, its store is set, and it is not already the new town's */
    if (cb::FloorStoreStep(1, oldS, newS) != cb::kFsMove) Fail("t1427: a made building linked to another town moves its floor records");
    if (cb::FloorStoreStep(1, newS, newS) != cb::kFsSame) Fail("t1427: a building already in the new town's store is left (same town)");
    if (cb::FloorStoreStep(0, oldS, newS) != cb::kFsNoModels) Fail("t1427: no models yet - createPhysical points it at its town's store then");
    if (cb::FloorStoreStep(0, 0, newS) != cb::kFsNoModels) Fail("t1427: a fresh copy (no models, no store) is left to createPhysical");
    if (cb::FloorStoreStep(1, 0, newS) != cb::kFsNoStore) Fail("t1427: models but no store set - nothing to move");
    if (cb::FloorStoreStep(1, oldS, 0) != cb::kFsNoTown || cb::FloorStoreStep(0, 0, 0) != cb::kFsNoTown) Fail("t1427: no new town (no store) - nothing moved");
    /* the pieces inside it */
    if (cb::FloorStoreInsideStep(1, oldS, oldS, newS) != cb::kFsInsideMove) Fail("t1427: an inside piece in its host's old store moves with it");
    if (cb::FloorStoreInsideStep(1, newS, oldS, newS) != cb::kFsInsideThere) Fail("t1427: an inside piece already in the new store stays (its parts count as the group's)");
    if (cb::FloorStoreInsideStep(0, oldS, oldS, newS) != cb::kFsInsideNone || cb::FloorStoreInsideStep(1, 0, oldS, newS) != cb::kFsInsideNone)
        Fail("t1427: an inside piece with no models or no store has no parts anywhere - not touched");
    if (cb::FloorStoreInsideStep(1, third, oldS, newS) != cb::kFsInsideForeign) Fail("t1427: an inside piece in a third store is not touched");
    /* the group: moved only when read whole, every part its own, the new store free of it and no sign highlight; a building without
       parts (no record) still moves (its pointer) */
    if (cb::FloorStoreGroupStep(1, 0, 0, 0, 0) != cb::kFsGroupGo) Fail("t1427: a whole, clean group (or a building without parts) is moved");
    if (cb::FloorStoreGroupStep(0, 0, 0, 0, 0) != cb::kFsGroupFault) Fail("t1427: a faulted read moves nothing");
    if (cb::FloorStoreGroupStep(1, 1, 0, 0, 0) != cb::kFsGroupCapped) Fail("t1427: a read cut short moves nothing");
    if (cb::FloorStoreGroupStep(1, 0, 1, 0, 0) != cb::kFsGroupNewHolds) Fail("t1427: the new store already holding a record moves nothing");
    if (cb::FloorStoreGroupStep(1, 0, 0, 2, 0) != cb::kFsGroupUnknownPart) Fail("t1427: a part of an owner outside the group moves nothing");
    if (cb::FloorStoreGroupStep(1, 0, 0, 0, 1) != cb::kFsGroupSigns) Fail("t1427: a sign highlight moves nothing (re-adding it is not read)");
    if (cb::FloorStoreGroupStep(0, 1, 1, 1, 1) != cb::kFsGroupFault || cb::FloorStoreGroupStep(1, 1, 1, 1, 1) != cb::kFsGroupCapped)
        Fail("t1427: a fault, then a cut-short read, decide first");
    for (int g = cb::kFsGroupGo; g <= cb::kFsGroupSigns; ++g)
        if (std::string(cb::FloorStoreGroupWord(g)) == "?") Fail("t1427: every group step has its words");
    /* wiring: every re-town road funnels through BdBuildingSetTownPod, which follows a written copy with the move; the engine rows */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1427: build.cpp not readable"); return; }
    const char* const need[] = {
        "AddrReg kFsRemoveRva_reg(\"TownFloorStoreRemove\", &kFsRemoveRva);",
        "AddrReg kFsAddRva_reg(\"TownFloorStoreAddPart\", &kFsAddRva);",
        "if (r == 1) BdFloorStoreFollow(b, t, nIn);",
        "const size_t kBFloorStore = 0x1F8, kTownFloorStore = 0x250, kBModels = 0x228, kInModels = 0x10;",
        "const int st = coopbuild::FloorStoreStep(models, (unsigned long long)oldS, (unsigned long long)newS);",
        "const int g = coopbuild::FloorStoreGroupStep(p.readOk, p.capped, p.newHolds, p.unknown, p.signs);",
        "if (BdOnMain() == 0) { ++g_fsOffMain;",
        "PcReportText() + BdWalkMapHostReportText() + BdFloorStoreReportText() + BdTownStoreReportText() + BdCopyTownReportText() + BdPurchaseHereReportText());",   /* merge of main: T-1430's purchase counts follow on the same line */
        /* decision 1782: the town / floor-store line at each road (log only) */
        "BdTownStoreNote(b, keyOk != 0 ? key : 0, via == 1 ?",
        "BdTownStoreNote(b, m.key.c_str(), p.restore != 0 ?",
        "if (event == coopbuild::kWmFinished) BdTownStoreNote(b, key, \"finished (by the mod)\");",
        "BdTownStoreNote(ObjectByPositionKey(e.key), e.key, \"finished (by the engine)\");",
        "if (r == 1 && townBefore != t) BdTownStoreNote(b, 0, \"moved to another town\");",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1427: missing in build.cpp: ") + need[i]);
    size_t at = 0;
    int writers = 0;
    while ((at = src.find("std::memcpy((char*)b + kBdTownHandWords", at)) != std::string::npos) { ++writers; ++at; }
    if (writers != 1) Fail("t1427: one writer of a building's town words (BdTownWordsCopyPod)");
    const size_t setTown = src.find("int BdBuildingSetTownPod(void* b, void* t, int* cycle = 0)\n{");
    const size_t copy = src.find("const int r = BdTownWordsCopyPod(b, t);", setTown == std::string::npos ? 0 : setTown);
    const size_t follow = src.find("if (r == 1) BdFloorStoreFollow(b, t, nIn);", copy == std::string::npos ? 0 : copy);
    if (setTown == std::string::npos || copy == std::string::npos || follow == std::string::npos) Fail("t1427: the move follows the host's written copy");
    const size_t apply = src.find("int FsApplyPod(char* oldS, char* newS, FsRemoveFn rm, FsAddFn add)");
    const size_t plan = src.find("void FsPlanPod(void* b, char* oldS, char* newS, int nIn, FsPlan* p)");
    if (apply == std::string::npos || plan == std::string::npos || src.find("__try", apply) > src.find("__except", apply) || src.find("__try", plan) > src.find("__except", plan))
        Fail("t1427: the read and the move are each under a guard");
}
void t_t1426_host_interior()
{
    namespace cb = coopbuild;
    const int owed[5] = { cb::kWmCopyMade, cb::kWmCopyRestored, cb::kWmKeptMade, cb::kWmFinished, cb::kWmRemoved };
    for (int i = 0; i < 5; ++i)
    {
        const std::string w = cb::BuildWalkMapEventWord(owed[i]);
        if (cb::BuildWalkMapHostInterior(owed[i], 1, 1, 1) != 1) Fail("t1426: furniture " + w + " in a host with an interior queues the host's interior");
        if (cb::BuildWalkMapHostInterior(owed[i], 1, 0, 1) != cb::kWmHostNone || cb::BuildWalkMapHostInterior(owed[i], 1, 0, 0) != cb::kWmHostNone)
            Fail("t1426: furniture " + w + " naming no host building queues nothing (none)");
        if (cb::BuildWalkMapHostInterior(owed[i], 1, 1, 0) != cb::kWmHostNoInterior) Fail("t1426: furniture " + w + " in a host the engine gives no interior queues nothing");
        if (cb::BuildWalkMapHostInterior(owed[i], 0, 1, 1) != 0 || cb::BuildWalkMapHostInterior(owed[i], 0, 0, 0) != 0)
            Fail("t1426: a piece that is not furniture owes no host interior on " + w + " (BuildWalkMapWhat has its own steps)");
        if (cb::BuildWalkMapWhat(owed[i], 1, 1, 1) != 0) Fail("t1426: furniture still owes nothing of its own on " + w);
    }
    /* a threshold crossing, a body's arrival (furniture never waits for one) and an unknown event owe nothing */
    const int other[4] = { cb::kWmThreshold, cb::kWmBodyArrived, 0, 99 };
    for (int i = 0; i < 4; ++i)
        if (cb::BuildWalkMapHostInterior(other[i], 1, 1, 1) != 0 || cb::BuildWalkMapHostInterior(other[i], 0, 1, 1) != 0)
            Fail(std::string("t1426: event ") + cb::BuildWalkMapEventWord(other[i]) + " owes no host interior");
    if (cb::BuildWalkMapBodyWait(cb::kWmCopyMade, 0, 1) != 0) Fail("t1426: furniture never waits for a body (no bodyArrived road)");
    /* the host's interior is decided by the engine's own load test (a gate or wall host gets none) */
    if (cb::BuildWalkMapHostInterior(cb::kWmCopyMade, 1, 1, cb::BuildEngineGivesInterior(1, 0, 1, 0, 1, 0)) != cb::kWmHostNoInterior
        || cb::BuildWalkMapHostInterior(cb::kWmCopyMade, 1, 1, cb::BuildEngineGivesInterior(1, 0, 1, 0, 0, 0)) != 1)
        Fail("t1426: the host's interior by the engine's test");
    if (cb::kWmHostNone == 0 || cb::kWmHostNoInterior == 0 || cb::kWmHostNone == 1 || cb::kWmHostNoInterior == 1 || cb::kWmHostNone == cb::kWmHostNoInterior)
        Fail("t1426: the outcomes are distinct");
    /* wiring: BdWalkMapNote asks it for every event, before the piece's own reads; the host by vt+0x1D8 and hand::asBuilding; the
       host's interior by the engine's test; queued through WalkMapDeferInterior's pod; the counters on the build report */
    const std::string src = T1260Flat("../coop-plugin/build.cpp");
    if (src.empty()) { Fail("t1426: build.cpp not readable"); return; }
    const size_t note = src.find("if (event == coopbuild::kWmRemoved) BdBodyWaitForget(b);");   /* inside BdWalkMapNote, before its reads */
    const size_t call = src.find("BdWalkMapHostNote(b, event, key);", note == std::string::npos ? 0 : note);
    const size_t reads = src.find("BdReadState(b, &p, &n, &c, &d, &x)", note == std::string::npos ? 0 : note);
    if (note == std::string::npos || call == std::string::npos || reads == std::string::npos || call > reads)
        Fail("t1426: BdWalkMapNote asks the host step for every event before its own reads");
    const char* const need[] = {
        "AddrReg kBdHostHandBldRva_reg(\"HandGetBuilding\", &kBdHostHandBldRva);",
        "const size_t kBVtHostHand = 0x1D8, kHostHandType = 0x08;",
        "const int kHostHandNone = 0xB;",
        "const int act = coopbuild::BuildWalkMapHostInterior(event, furn, host != 0 ? 1 : 0, hostInterior);",
        "hostInterior = coopbuild::BuildEngineGivesInterior(eiRead, eiKind, eiPtr, eiWallPart, eiGate, eiFlag);",
        "BdWalkMapPod(list, host, 0, coopbuild::kWmInterior,",
        "walkMapHost[queued,none,noInterior,sameTick,faulted,noList]",
        "PcReportText() + BdWalkMapHostReportText()",
        "++g_wmHostTickNo;",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (src.find(need[i]) == std::string::npos) Fail(std::string("t1426: missing in build.cpp: ") + need[i]);
    const size_t pod = src.find("int BdHostOfPod(void* b, void** host, int* type)");
    const size_t podEnd = (pod == std::string::npos) ? pod : src.find("__except (EXCEPTION_EXECUTE_HANDLER) { *host = 0; return 0; }", pod);
    if (pod == std::string::npos || podEnd == std::string::npos || src.find("__try", pod) > podEnd) Fail("t1426: the host read is under a guard");
}
/* ---- T-1294 design A: the mod's building copies, finishes and removals go on the engine's own deferred walking-map list ---- */
void t_t1294_walkmap()
{
    namespace cb = coopbuild;
    /* the decision per event: solid copies queue their box, a house its interior, finishes / crossings the box (+ interior),
       removals the box only, furniture nothing */
    if (cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, 0, 0) != cb::kWmBox) Fail("t1294: a solid copy made queues its box");
    if (cb::BuildWalkMapWhat(cb::kWmCopyMade, 0, 0, 0) != 0) Fail("t1294: a copy below its threshold queues nothing (the engine leaves it out)");
    if (cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, 1, 0) != (cb::kWmBox | cb::kWmInterior)) Fail("t1294: a house copy made queues its box and its interior");
    if (cb::BuildWalkMapWhat(cb::kWmCopyMade, 0, 1, 0) != cb::kWmInterior) Fail("t1294: an unfinished house copy still gets its interior");
    if (cb::BuildWalkMapWhat(cb::kWmCopyRestored, 1, 0, 0) != cb::kWmBox || cb::BuildWalkMapWhat(cb::kWmKeptMade, 1, 1, 0) != (cb::kWmBox | cb::kWmInterior))
        Fail("t1294: restored / kept pieces as copies made");
    if (cb::BuildWalkMapWhat(cb::kWmFinished, 0, 0, 0) != cb::kWmBox || cb::BuildWalkMapWhat(cb::kWmThreshold, 0, 1, 0) != (cb::kWmBox | cb::kWmInterior))
        Fail("t1294: a finish / threshold crossing queues the box (and the interior)");
    if (cb::BuildWalkMapWhat(cb::kWmRemoved, 1, 1, 0) != cb::kWmBox || cb::BuildWalkMapWhat(cb::kWmRemoved, 0, 0, 0) != cb::kWmBox)
        Fail("t1294: a removal queues the box only");
    if (cb::BuildWalkMapWhat(cb::kWmFinished, 1, 1, 1) != 0 || cb::BuildWalkMapWhat(99, 1, 1, 0) != 0) Fail("t1294: furniture / an unknown event queue nothing");
    /* solid: complete, or progress at / past needed x threshold; threshold 0 = solid from placement */
    if (cb::BuildWalkMapSolid(1, 0.0f, 1.0f, 0.5f) != 1 || cb::BuildWalkMapSolid(0, 0.49f, 1.0f, 0.5f) != 0 || cb::BuildWalkMapSolid(0, 0.5f, 1.0f, 0.5f) != 1
        || cb::BuildWalkMapSolid(0, 0.0f, 1.0f, 0.0f) != 1 || cb::BuildWalkMapSolid(0, 5.0f, 0.0f, 0.5f) != 0)
        Fail("t1294: BuildWalkMapSolid");
    if (cb::BuildWalkMapCrossed(0, 1) != 1 || cb::BuildWalkMapCrossed(1, 1) != 0 || cb::BuildWalkMapCrossed(0, 0) != 0 || cb::BuildWalkMapCrossed(1, 0) != 0)
        Fail("t1294: BuildWalkMapCrossed");
    /* the wall finish amount: finite (0x5594A0 skips its crossing for FLT_MAX) and under 9999 (its job) */
    if (!(cb::kWallFinishAmount < cb::kWallJobAmountLimit) || !(cb::kWallFinishAmount > 0.0f) || cb::kWallFinishAmount >= FLT_MAX * 0.5f)
        Fail("t1294: the wall finish amount is finite and under 9999");
    /* fold 1: walls finished / crossed by the mod are left to their own crossing (M3, L4); a wall copy is solid only complete; a late
       body queues again (M2) */
    if (cb::BuildWalkMapWhat(cb::kWmFinished, 1, 0, 0, 1) != 0 || cb::BuildWalkMapWhat(cb::kWmThreshold, 1, 0, 0, 1) != 0)
        Fail("t1294 fold 1: a wall finished / crossed by the mod queues nothing (its own crossing posts the job)");
    if (cb::BuildWalkMapWhat(cb::kWmRemoved, 0, 0, 0, 1) != cb::kWmBox || cb::BuildWalkMapWhat(cb::kWmBodyArrived, 1, 0, 0, 1) != cb::kWmBox
        || cb::BuildWalkMapWhat(cb::kWmBodyArrived, 1, 1, 0, 0) != (cb::kWmBox | cb::kWmInterior) || cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, 0, 0, 1) != cb::kWmBox
        || cb::BuildWalkMapWhat(cb::kWmBodyArrived, 0, 0, 0, 1) != cb::kWmBox)
        Fail("t1294 fold 1/2: a wall's removal, a body's arrival (any progress) and a complete wall copy queue its box");
    /* fold 2 (M2): a piece queued with its physics list empty waits for createPhysical - not a removal, not the arrival, not furniture,
       not with the list set or unreadable */
    if (cb::BuildWalkMapBodyWait(cb::kWmCopyMade, 0, 0) != 1 || cb::BuildWalkMapBodyWait(cb::kWmCopyRestored, 0, 0) != 1 || cb::BuildWalkMapBodyWait(cb::kWmKeptMade, 0, 0) != 1
        || cb::BuildWalkMapBodyWait(cb::kWmFinished, 0, 0) != 1 || cb::BuildWalkMapBodyWait(cb::kWmThreshold, 0, 0) != 1)
        Fail("t1294 fold 2 (M2): a copy made / restored / kept, a finish or a crossing with no body waits for it");
    if (cb::BuildWalkMapBodyWait(cb::kWmRemoved, 0, 0) != 0 || cb::BuildWalkMapBodyWait(cb::kWmBodyArrived, 0, 0) != 0 || cb::BuildWalkMapBodyWait(cb::kWmCopyMade, 0, 1) != 0
        || cb::BuildWalkMapBodyWait(cb::kWmCopyMade, 1, 0) != 0 || cb::BuildWalkMapBodyWait(cb::kWmCopyMade, -1, 0) != 0 || cb::BuildWalkMapBodyWait(99, 0, 0) != 0)
        Fail("t1294 fold 2 (M2): no wait for a removal, the arrival, furniture, a set or unreadable list, an unknown event");
    if (std::string(cb::BuildWalkMapEventWord(cb::kWmBodyArrived)) != "bodyArrived") Fail("t1294 fold 2: the arrival's word");
    /* fold 2 (H2(b)): the crossing replayed at the arrival only for an unfinished, standing wall at or past its line */
    if (cb::BuildWallCrossReplay(0, 0, 0.6f, 1.0f, 0.5f) != 1 || cb::BuildWallCrossReplay(0, 0, 0.5f, 1.0f, 0.5f) != 1)
        Fail("t1294 fold 2 (H2b): a wall past its line that waited is crossed at its body");
    if (cb::BuildWallCrossReplay(1, 0, 0.6f, 1.0f, 0.5f) != 0 || cb::BuildWallCrossReplay(0, 1, 0.6f, 1.0f, 0.5f) != 0 || cb::BuildWallCrossReplay(0, 0, 0.4f, 1.0f, 0.5f) != 0
        || cb::BuildWallCrossReplay(0, 0, 0.6f, 0.0f, 0.5f) != 0 || cb::BuildWallCrossReplay(0, 0, 0.6f, 1.0f, 0.0f) != 0)
        Fail("t1294 fold 2 (H2b): no replay for a finished, destroyed or below-the-line wall, or no needed / threshold");
    /* fold 2 (H2(c)): a neighbour the crossing lowered is put back; one it raised or left is not */
    if (cb::BuildWallNbrPutBack(1.0f, 0.51f) != 1 || cb::BuildWallNbrPutBack(0.3f, 0.51f) != 0 || cb::BuildWallNbrPutBack(0.51f, 0.51f) != 0)
        Fail("t1294 fold 2 (H2c): only a lowered neighbour is put back");
    if (!(cb::kWallNbrCap > 0) || !(cb::kWmBodyWaitCap > 0)) Fail("t1294 fold 2: caps");
    if (cb::BuildWalkMapSolidFor(1, 0, 0.9f, 1.0f, 0.5f) != 0 || cb::BuildWalkMapSolidFor(1, 1, 0.0f, 1.0f, 0.5f) != 1 || cb::BuildWalkMapSolidFor(0, 0, 0.9f, 1.0f, 0.5f) != 1)
        Fail("t1294 fold 1: a wall copy is solid only when complete");
    /* H1: the confirm's 1 survives the queue; M1: due set out of build mode only, with a held queue, from 0 */
    if (cb::BuildWalkMapStateAfter(1, 2) != 1 || cb::BuildWalkMapStateAfter(0, 2) != 2 || cb::BuildWalkMapStateAfter(2, 2) != 2 || cb::BuildWalkMapStateAfter(0, 0) != 0)
        Fail("t1294 fold 1 (H1): the confirm's state 1 is put back after the queue");
    if (cb::BuildWalkMapDueNow(1, 0, 0) != 1 || cb::BuildWalkMapDueNow(1, 1, 0) != 0 || cb::BuildWalkMapDueNow(0, 0, 0) != 0 || cb::BuildWalkMapDueNow(1, 0, 1) != 0 || cb::BuildWalkMapDueNow(1, 0, 2) != 0)
        Fail("t1294 fold 1 (M1): due set only with a held queue, out of build mode, state 0");
    /* H2: the crossing - a gradual build crossing in one STATE, help crossing it, a damaged wall re-finished; not for a write that stays
       below or starts above, not for a non-wall */
    if (cb::BuildWallCrossNeeded(1, 0.2f, 0.7f, 1.0f, 0.5f) != 1) Fail("t1294 fold 1 (H2): a gradual build crossing the line in one STATE");
    if (cb::BuildWallCrossNeeded(1, 0.4f, 0.4f + 0.3f, 1.0f, 0.5f) != 1) Fail("t1294 fold 1 (H2): help crossing the line");
    if (cb::BuildWallCrossNeeded(1, 0.3f, 0.999f, 1.0f, 0.5f) != 1) Fail("t1294 fold 1 (H2): a damaged wall (below its line) re-finished");
    if (cb::BuildWallCrossNeeded(1, 0.6f, 0.999f, 1.0f, 0.5f) != 0 || cb::BuildWallCrossNeeded(1, 0.1f, 0.4f, 1.0f, 0.5f) != 0
        || cb::BuildWallCrossNeeded(0, 0.2f, 0.7f, 1.0f, 0.5f) != 0 || cb::BuildWallCrossNeeded(1, 0.2f, 0.7f, 0.0f, 0.5f) != 0 || cb::BuildWallCrossNeeded(1, 0.0f, 0.7f, 1.0f, 0.0f) != 0)
        Fail("t1294 fold 1 (H2): no crossing for a write staying on one side, a non-wall, no needed or no threshold");
    {
        const float pre = cb::BuildWallCrossPre(4.0f, 0.5f);
        if (!(pre < 2.0f) || !(pre > 1.9f)) Fail("t1294 fold 1 (H2): the pre-write lands just below the line");
        const float a0 = cb::BuildWallCrossStep(4.0f, 2.0f, 0), a1 = cb::BuildWallCrossStep(4.0f, 2.0f, 1);
        if (!(a0 > 0.0f) || std::fabs(a1 - 4.0f * a0) > 1e-6f || !(a0 * 2.0f > 4.0f * cb::kWallCrossEps))
            Fail("t1294 fold 1 (H2): the crossing amounts (twice the gap over the rate, x4 per try)");
        if (cb::BuildWallCrossStep(4.0f, 0.0f, 0) != 0.0f || cb::BuildWallCrossStep(4.0f, -1.0f, 0) != 0.0f || cb::BuildWallCrossStep(4.0f, 2.0f, cb::kWallCrossTries) != 0.0f)
            Fail("t1294 fold 1 (H2): no crossing call at rate 0 (0x558B10 would complete it) or past the tries");
    }
    {   /* T-1294 test tool: `bldstate <key> complete` */
        std::string k;
        if (cb::BuildStateWantsComplete("3005-Walls.mod@16,33@-698000,79000 complete", &k) != 1 || k != "3005-Walls.mod@16,33@-698000,79000")
            Fail("t1294 tool: bldstate <key> complete asks for a finished piece");
        if (cb::BuildStateWantsComplete("3005-Walls.mod@16,33@-698000,79000", &k) != 0 || k != "3005-Walls.mod@16,33@-698000,79000")
            Fail("t1294 tool: a plain bldstate read is unchanged");
        if (cb::BuildStateWantsComplete("complete", &k) != 0 || k != "complete" || cb::BuildStateWantsComplete(" complete", &k) != 0)
            Fail("t1294 tool: the word alone is a key substring, not the ask");
    }
    {   /* fold 3 (T2222): where a crossing starts */
        int w = -1;
        if (cb::BuildWallCrossFrom(1, 0.5f, 0.9f, 0.3f, &w) != 0.3f || w != 1) Fail("t1294 fold 3: a replay starts just below the line");
        w = -1;
        if (cb::BuildWallCrossFrom(0, 0.0f, 54.9f, 0.3f, &w) != 0.0f || w != 1) Fail("t1294 fold 3: the helper's write starts from the progress before the step (the live value is the raised step's)");
        w = -1;
        if (cb::BuildWallCrossFrom(0, 0.29f, 54.9f, 0.3f, &w) != 0.29f || w != 1) Fail("t1294 fold 3: a `from` between pre and the line still writes pre first");
        w = -1;
        if (cb::BuildWallCrossFrom(0, -1.0f, 0.1f, 0.3f, &w) != 0.1f || w != 1) Fail("t1294 fold 3: a live value below pre is written to pre");
        w = -1;
        if (cb::BuildWallCrossFrom(0, -1.0f, 0.305f, 0.3f, &w) != 0.305f || w != 0) Fail("t1294 fold 3: a live value at or past pre is not lowered");
        /* T2222's W2 on B: 0.00 -> the cap 0.999 of 1.00 crosses any line in (0, 0.999] */
        const float s = cb::BuildWallCrossFrom(0, 0.0f, 54.94f, cb::BuildWallCrossPre(1.0f, 0.5f), &w);
        if (cb::BuildWallCrossNeeded(1, s, 0.999f, 1.0f, 0.5f) != 1 || cb::BuildWallCrossNeeded(1, 54.94f, 0.999f, 1.0f, 0.5f) != 0)
            Fail("t1294 fold 3: the helper's cap write crosses from the pre-step progress (the raised step's value would say no crossing)");
    }
    /* the rows, both builds */
    const std::string t65 = T1260Flat("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
    const std::string t68 = T1260Flat("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
    if (t65.find("PlacementRegionAdd                             code 004D21F0 004D21F0") == std::string::npos
        || t65.find("WalkMapDeferInterior                           code 004D2340 004D2340") == std::string::npos
        || t68.find("PlacementRegionAdd                             code 004D2C80 004D2C80") == std::string::npos
        || t68.find("WalkMapDeferInterior                           code 004D2DD0 004D2DD0") == std::string::npos)
        Fail("t1294: the PlacementRegionAdd (the box queue, bound as kBdWmBoxRva) / WalkMapDeferInterior rows (1.0.65 0x4D21F0 / 0x4D2340, 1.0.68 0x4D2C80 / 0x4D2DD0)");
    if (t65.find("BuildingCreatePhysical                         code 0055FF50 0055FF50 488BC4554154415541564157488DA8F8") == std::string::npos
        || t68.find("BuildingCreatePhysical                         code 005609E0 005609E0 488BC4554154415541564157488DA8F8") == std::string::npos)
        Fail("t1294 fold 2: the BuildingCreatePhysical row (1.0.65 0x55FF50, 1.0.68 0x5609E0)");
    /* the wiring: every call site */
    const std::string b = T1260Flat("../coop-plugin/build.cpp");
    const char* need[] = {
        "BdWalkMapNote(b, p.restore != 0 ? coopbuild::kWmCopyRestored : coopbuild::kWmCopyMade, m.key.c_str());",
        "if (applied > 0) BdWalkMapNote(b, coopbuild::kWmCopyRestored, m.key.c_str());",
        "BdWalkMapNote(b, coopbuild::kWmKeptMade, w.p.key.c_str());",
        "ItFurnMarkStale(3); BdWalkMapNote(b, coopbuild::kWmFinished, key.c_str()); }",
        "if (completes != 0 && c1 != 0) BdWalkMapNote(b, coopbuild::kWmFinished, m.key.c_str());",
        "else if (coopbuild::BuildWalkMapCrossed(wmSolid0 != 0 ? 1 : 0, BdWalkMapSolidNow(b) > 0 ? 1 : 0) != 0) BdWalkMapNote(b, coopbuild::kWmThreshold, m.key.c_str());",
        "if (completeCalled) BdWalkMapNote(b, coopbuild::kWmFinished, key.c_str());",
        "else if (coopbuild::BuildWalkMapCrossed(wmSolid0 != 0 ? 1 : 0, BdWalkMapSolidNow(b) > 0 ? 1 : 0) != 0) BdWalkMapNote(b, coopbuild::kWmThreshold, key.c_str());",
        "if (ok) BdWalkMapNote(b, coopbuild::kWmFinished, 0);",
        "        ++g_keptOwnRecComplete;\n        BdWalkMapNote(live, coopbuild::kWmFinished, lk.c_str());   /* T-1294 design A */\n    }\n    else if (ok != 0) ++g_wallCompleteNoop;",
        /* fold 1 */
        "const int after = coopbuild::BuildWalkMapStateAfter(before, *st);",
        "*set = coopbuild::BuildWalkMapDueNow(pending, bm, *st);",
        "BdWalkMapHeldTick();   /* T-1294 fold 1 (M1)",
        "if (held != 0) { ++g_wmHeld; g_wmHeldPending = 1; }",
        /* fold 2 */
        "if (ready != 0 && row.waitB == b) { row.waitB = 0; ++g_pcLateBody; }   /* its body came after an earlier check */",   /* T-1389: the piece check's own wait (F1114: holder and bodies) */
        "if (boxWait != 0) { BdBoxWaitAdd(b, key, road != 0 ? road : event, ::GetTickCount() - (DWORD)(waitedMs > 0 ? waitedMs : 0)); ++g_wmBoxWait; }",   /* T-1428: the box decides the wait, not the holder (fold 1: its own list) */
        "if (event == coopbuild::kWmRemoved) BdBodyWaitForget(b);",
        "void PcForgetWorld() { PcWaitEndSweep(0, coopbuild::kPcRoadWorldLeft, 1); g_pcDue.Clear(); g_pcAreaDue.clear(); BdBodyWaitClear(); g_pcSeen.clear(); PcPartsCacheClear(); }",   /* T-1389 */
        "g_hkCreatePhys = BdHook(base, kBdCreatePhysRva, (void*)&detour_createPhys, (void**)&orig_createPhys);",
        "static AddrReg kBdCreatePhysRva_reg(\"BuildingCreatePhysical\", &kBdCreatePhysRva);",
        "const unsigned long long r = orig_createPhys(b);",
        "if (::InterlockedCompareExchangePointer((void* volatile*)&g_wmArrivedOff[s], b, 0) == 0) return r;",
        "BdBodyArrivedTick();   /* T-1294 fold 2 (M2)",
        "if (b != 0) BdBodyArrivedMain(b);",
        "if (w.data != BdPtrAt(b, kObjData) || list != 1)",
        "if (BdWallCrossPod(b, p, upd, w.key.empty() ? 0 : w.key.c_str(), 1) == 1) ++g_wmBodyCrossReplayed;",
        "BdWalkMapNote(b, coopbuild::kWmBodyArrived, w.key.empty() ? 0 : w.key.c_str(), w.road, (long)(::GetTickCount() - w.since));",   /* T-1428 */
        "if (BdBodyListPod(b) != 1)   /* fold 2 (H2(b))",
        "if (replay == 0) BdBodyWaitAdd(b, key, coopbuild::kWmThreshold, 1);",
        "if (c != 0 || x != 0 || coopbuild::BuildWallCrossNeeded(1, start, target, n, t) == 0) return 0;",
        "const float start = coopbuild::BuildWallCrossFrom(replay, from, p, pre, &writePre);",
        "if (writePre != 0 && (upd == 0 || BdApplyStatePod(b, 1, pre, 0, 0, &ml, upd, &stage) == 0))",
        /* fold 3 (T2222): the helper's cap write on a copy */
        "BdWallCrossPod(b, capTo, upd, keyOk != 0 ? k : 0, 0, p0);",
        "const int wmSolid0 = BdWalkMapSolidAt(b, p0, n0);",
        "if (coopbuild::BuildWalkMapCrossed(wmSolid0 != 0 ? 1 : 0, BdWalkMapSolidNow(b) > 0 ? 1 : 0) != 0) BdWalkMapNote(b, coopbuild::kWmThreshold, keyOk != 0 ? k : 0);",
        "if (replay != 0 && c == 0 && upd != 0) BdApplyStatePod(b, 1, target, 0, 0, &ml, upd, &stage);",
        "const int put = BdWallNbrPutBackPod(nb, nv, nn, upd);",
        "if (coopbuild::BuildWallNbrPutBack(v[i], *own) == 0) continue;",
        "void* p = ((BdHandleResFn)fRes)((void*)tab, e);",
        "if (wall == 1 && upd != 0 && ln > 0.0f) BdWallCrossPod(b, pr, upd, 0);   /* T-1294 fold 2 (H2a)",
        "complete NOT TAKEN: vt+0x230(%s) ran",
        "key.c_str(), wallOwn > 0 ? \"own\" : \"group\", BdCompleteNowWord(), cr != 0",
        "int what0 = coopbuild::BuildWalkMapWhat(event, solid, interior, furn, wall);",   /* T-1428: what0, the box then decided by BuildWalkMapBoxWait */
        "if (ok == 0) { ++g_wallFinishFaulted; return 0; }",
        "BdWallCrossPod(b, wp, upd, key.c_str());   /* T-1294 fold 1 (H2): a gradual build crossing",
        "BdWallCrossPod(b, wr, upd, key.c_str());   /* T-1294 fold 1 (H2): a damaged wall re-finished */",
        "BdWallCrossPod(b, wr, upd, key.c_str());   /* T-1294 fold 1 (H2) */",
        "if (wall != 0) BdWallCrossPod(wb, p0 + mp, upd, m.key.c_str());",
        "if (writeProgress != 0) BdWallCrossPod(b, pr, upd, m.key.c_str());",
        "if (upd != 0) BdWallCrossPod(b, wr, upd, 0);",
        "if (BdProgressPod(b, coopbuild::BuildWallCrossStep(n, rate, k)) == 0",
        "stood unfinished - vt+0x230(%s) %s,",
        "reach needed: vt+0x230(%s) %s,",
        "BdWalkMapNote(b, coopbuild::kWmRemoved, 0);   /* T-1294 design A: every try",
        "BdWalkMapNote(b, coopbuild::kWmRemoved, 0);   /* T-1294 design A */\n        const int ok = (panel != 0) ? BdConfirmDismantlePod(b) : BdDismantlePod(b, kl.tries == 0",
        "BdWalkMapNote(b, coopbuild::kWmRemoved, 0);   /* T-1294 design A: its box rebuilt without it",
        "const int ok = BdCompleteNowPod(live);",
        "{ ok = BdCompleteNowPod(b); completeCalled = 1; }",
        "ok = BdCompleteNowPod(wallStep != 0 ? gLead : b);",
        "const int ok = BdCompleteNowPod(b);   /* the engine's own complete-now path (T-1294",
        "ok = BdCompleteNowPod(b);   /* T-1294: a wall through its threshold crossing */",
        "const int ok = BdProgressPod(b, coopbuild::kWallFinishAmount);",
        "((BdWmBoxFn)fBox)(list, box);",   /* T-1428: the grown copy */
        "((BdWmIntFn)fInt)(list, b, 0);",
        "if (BdOnMain() == 0) { ++g_wmOffMain; return 0; }",
        "return std::string(b) + BdWalkMapReportText();",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (b.find(need[i]) == std::string::npos) Fail(std::string("t1294 wiring: missing in build.cpp: ") + need[i]);
    /* no mod finish left on FLT_MAX alone (only BdCompleteNowPod's fallback) */
    size_t n = 0, at = 0;
    while ((at = b.find("BdProgressPod(b, FLT_MAX)", at)) != std::string::npos) { ++n; ++at; }
    if (n != 1 || b.find("BdProgressPod(live, FLT_MAX)") != std::string::npos) Fail("t1294 wiring: a mod finish still calls vt+0x230(FLT_MAX) directly");
}
/* the text of one function in build.cpp, from its head to the first line that is a lone closing brace */
static std::string T1428FnBody(const std::string& b, const char* head)
{
    const size_t i = b.find(head);
    if (i == std::string::npos) return std::string();
    const size_t j = b.find("\n}\n", i);
    return (j == std::string::npos) ? b.substr(i) : b.substr(i, j - i + 3);
}
/* T-1428 fold 1 (the independent review of 393487f16): 1 the ask waits for every model part (+0x230 at 0), with a time cap;
   2 the box waits have their own growable list - no cap, no drop; 3 the grown copy is tested; 4 the interior goes once, after its
   box; 5 a lone game's waits end at area unload on the same road */
void t_t1428_fold1(const std::string& b)
{
    namespace cb = coopbuild;
    const float inf = std::numeric_limits<float>::infinity();
    const float nan = std::numeric_limits<float>::quiet_NaN();
    const float nothing[6] = { 0.0f, 0.0f, 0.0f, -inf, -inf, -inf };
    const float flat[6] = { 0.0f, 0.0f, 0.0f, 5.0f, 0.0f, 5.0f };
    const float bad[6] = { 0.0f, 0.0f, 0.0f, nan, 1.0f, 1.0f };
    const float shack[6] = { -66675.0f, 959.0f, 21233.0f, 102.0f, 40.0f, 110.0f };
    /* 3: the grown copy - a box flat on one side counts (the engine's grown copy passes its test); nothing / NaN / no box stay not real */
    if (cb::BuildWalkMapBoxGrownReal(flat) != 1) Fail("t1428 fold 1 (3): a box flat on one side counts once grown, as the engine tests it");
    if (cb::BuildWalkMapBoxGrownReal(nothing) != 0 || cb::BuildWalkMapBoxGrownReal(bad) != 0 || cb::BuildWalkMapBoxGrownReal(0) != 0)
        Fail("t1428 fold 1 (3): the nothing box, a NaN box and no box are not real grown");
    if (cb::BuildWalkMapBoxGrownReal(shack) != 1) Fail("t1428 fold 1 (3): the shack's box is real grown");
    /* 1: every part in - a real box with parts still loading waits; at 0 it asks; at the cap it asks with what it has, or its interior alone */
    if (cb::BuildWalkMapBoxReady(1, 0) != 1 || cb::BuildWalkMapBoxReady(1, 2) != 0 || cb::BuildWalkMapBoxReady(0, 0) != 0 || cb::BuildWalkMapBoxReady(1, -1) != 1)
        Fail("t1428 fold 1 (1): ready = the grown box real and no part still loading");
    if (cb::BuildWalkMapBoxDue(1, 3, 100) != cb::kWmBoxKeep) Fail("t1428 fold 1 (1): one part in of four - it keeps waiting");
    if (cb::BuildWalkMapBoxDue(1, 0, 100) != cb::kWmBoxAsk) Fail("t1428 fold 1 (1): every part in - it asks");
    if (cb::BuildWalkMapBoxDue(0, 0, 100) != cb::kWmBoxKeep) Fail("t1428 fold 1 (1): no real box yet - it keeps waiting");
    if (cb::BuildWalkMapBoxDue(1, 1, cb::kWmBoxWaitMs - 1) != cb::kWmBoxKeep) Fail("t1428 fold 1 (1): under the cap - it keeps waiting");
    if (cb::BuildWalkMapBoxDue(1, 1, cb::kWmBoxWaitMs) != cb::kWmBoxAskPartial) Fail("t1428 fold 1 (1): a count stuck above 0 - at the cap it asks with the box it has");
    if (cb::BuildWalkMapBoxDue(0, 1, cb::kWmBoxWaitMs + 5) != cb::kWmBoxNoBox) Fail("t1428 fold 1 (1): no real box at the cap - its interior alone");
    if (cb::BuildWalkMapBoxDue(1, 0, cb::kWmBoxWaitMs + 5) != cb::kWmBoxAsk) Fail("t1428 fold 1 (1): ready past the cap is a plain ask");
    if (!(cb::kWmBoxWaitMs >= 10000)) Fail("t1428 fold 1 (1): the cap leaves a large base's models time to load");
    /* 4: nothing now while the box waits; box and interior together at the re-ask */
    {
        const int what = cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, 1, 0);
        if (cb::BuildWalkMapQueueNow(what, 1) != 0 || cb::BuildWalkMapQueueNow(what, 0) != what)
            Fail("t1428 fold 1 (4): the interior goes once, with its box");
    }
    /* 2: the box waits' own list - added without a cap or a drop line; a crossing wait takes a box wait over */
    if (cb::BuildWalkMapBoxWaitKeep(1) != 0 || cb::BuildWalkMapBoxWaitKeep(0) != 1) Fail("t1428 fold 1 (2): a piece whose crossing waits is asked by its arrival");
    {
        const std::string add = T1428FnBody(b, "void BdBoxWaitAdd(void* b, const char* key, int road, DWORD since)");
        if (add.empty()) Fail("t1428 fold 1 (2): BdBoxWaitAdd missing");
        else if (add.find("Cap") != std::string::npos || add.find("NOT KEPT") != std::string::npos || add.find("g_wmBoxWaits.push_back(w);") == std::string::npos)
            Fail("t1428 fold 1 (2): a box wait is added with no cap and never dropped");
        const std::string ba = T1428FnBody(b, "void BdBodyWaitAdd(void* b, const char* key, int event, int cross)");
        if (ba.find("BdBoxWaitTake(b);") == std::string::npos) Fail("t1428 fold 1 (2): a crossing wait takes the piece's box wait over");
        const std::string fg = T1428FnBody(b, "void BdBodyWaitForget(void* b)");
        if (fg.find("BdBoxWaitTake(b);") == std::string::npos) Fail("t1428 fold 1 (2): a removed piece's box wait ends");
        const std::string note = T1428FnBody(b, "int BdWalkMapNote(void* b, int event, const char* key, int road, long waitedMs, int force)");
        if (note.empty() || note.find("BdBodyWaitAdd(") != std::string::npos) Fail("t1428 fold 1 (2): the ask's box wait is not in the capped body list");
    }
    /* 5: the area-unload road for every role - BdWalkWaitZonesNow runs from the zone scan before PieceRecZonesNow (which returns at
       once in a lone game), and asks no role */
    {
        const size_t z = b.find("BdWalkWaitZonesNow(g_bdZoneActiveNow);"), p = b.find("PieceRecZonesNow(g_bdZoneActiveNow);");
        if (z == std::string::npos || p == std::string::npos || z > p) Fail("t1428 fold 1 (5): the zone scan ends the walk-map waits for every role");
        const std::string zn = T1428FnBody(b, "void BdWalkWaitZonesNow(const unsigned char* now)");
        if (zn.empty() || zn.find("RoleIsSingle") != std::string::npos || zn.find("BdWalkWaitAreaEnd(left);") == std::string::npos)
            Fail("t1428 fold 1 (5): a lone game's area end gives its waits up");
        const std::string pr = T1428FnBody(b, "void PieceRecZonesNow(const unsigned char* now)");
        if (pr.empty() || pr.find("BdWalkWaitAreaEnd") != std::string::npos) Fail("t1428 fold 1 (5): one area-end road, not two");
        const std::string cl = T1428FnBody(b, "void BdBodyWaitClear()   /* MAIN THREAD: a world left */");
        if (cl.find("g_wmZonePrevHave = 0;") == std::string::npos || cl.find("g_wmBoxWaits.clear();") == std::string::npos)
            Fail("t1428 fold 1 (5): the world left ends every box wait and the area list");
    }
}
/* T-1428 attempt 2 (H-T1428-nocut, F1339 / F1340): an area whose pieces were made here from their record gets the engine's own
   whole-area walking-map rebuild 0x3AB700 once, after its pieces are made and their models loaded; the engine's own skip (0x3BF360)
   read as it reads it; the two rows on both builds; the wiring */
void t_t1428_zone_rebuild(const std::string& b)
{
    namespace cb = coopbuild;
    /* due: every piece loaded and the area quiet; at the cap with what stands; nothing for an area with no piece */
    if (cb::BuildZoneRebuildDue(3, 3, cb::kZoneRbQuietMs, 100) != cb::kZrbAsk) Fail("t1428 zone: every piece loaded and quiet - it asks");
    if (cb::BuildZoneRebuildDue(3, 3, cb::kZoneRbQuietMs - 1, 100) != cb::kZrbKeep) Fail("t1428 zone: a piece noted just now - its area's restores may not be done");
    if (cb::BuildZoneRebuildDue(3, 2, cb::kZoneRbQuietMs, cb::kZoneRbWaitMs - 1) != cb::kZrbKeep) Fail("t1428 zone: a piece's models still loading - it waits");
    if (cb::BuildZoneRebuildDue(3, 2, cb::kZoneRbQuietMs, cb::kZoneRbWaitMs) != cb::kZrbAskTimedOut) Fail("t1428 zone: at the cap it asks with what stands");
    if (cb::BuildZoneRebuildDue(0, 0, cb::kZoneRbQuietMs, cb::kZoneRbWaitMs) != cb::kZrbKeep) Fail("t1428 zone: no piece - no ask");
    if (!(cb::kZoneRbWaitMs >= cb::kWmBoxWaitMs) || !(cb::kZoneRbQuietMs >= 500)) Fail("t1428 zone: the waits leave the area's pieces time to be made and load");
    /* the engine's skip 0x3BF360: the running job of this area with type 1; a queued job of this area with type not 1 */
    if (cb::BuildZoneRebuildSkipCur(1, 1) != 1 || cb::BuildZoneRebuildSkipCur(1, 9) != 1 || cb::BuildZoneRebuildSkipCur(1, 2) != 0 || cb::BuildZoneRebuildSkipCur(0, 1) != 0)
        Fail("t1428 zone: the running job's skip is the engine's ((+0x58 & 7) == 1, this area)");
    if (cb::BuildZoneRebuildSkipQueued(1, 2) != 1 || cb::BuildZoneRebuildSkipQueued(1, 0) != 1 || cb::BuildZoneRebuildSkipQueued(1, 1) != 0 || cb::BuildZoneRebuildSkipQueued(0, 2) != 0)
        Fail("t1428 zone: the queued job's skip is the engine's ((+0x58 & 7) != 1, this area)");
    /* what is done */
    if (cb::BuildZoneRebuildAct(1, 1, 0, 0, 0) != cb::kZrbDoAsk) Fail("t1428 zone: a loaded area with no engine job - asked");
    if (cb::BuildZoneRebuildAct(1, 1, 0, 1, 1) != cb::kZrbDoneQueued || cb::BuildZoneRebuildAct(1, 1, 1, 1, 1) != cb::kZrbDoneQueued)
        Fail("t1428 zone: the engine's queued Full job covers it");
    if (cb::BuildZoneRebuildAct(1, 1, 1, 0, 0) != cb::kZrbAgainRunning || cb::BuildZoneRebuildAct(1, 1, 1, 1, 0) != cb::kZrbAgainRunning)
        Fail("t1428 zone: the engine's running job - asked again after it");
    if (cb::BuildZoneRebuildAct(1, 1, 0, 1, 0) != cb::kZrbAgainQueued) Fail("t1428 zone fold 2: a queued Interior (not a Full) does not cover it - asked again after it");
    if (cb::BuildZoneRebuildAct(1, 0, 0, 0, 0) != cb::kZrbNoArea) Fail("t1428 zone: an area not loaded is never asked (0x3AB700 reads through its area)");
    if (cb::BuildZoneRebuildAct(0, 1, 0, 0, 0) != cb::kZrbNoRows) Fail("t1428 zone: no rows - not asked");
    /* fold 2 (F1361): only a queued Full (type 0) covers; Partial 1 / Interior 3 do not; type read as (& 7) */
    if (cb::BuildZoneRebuildQueuedFull(1, 0) != 1 || cb::BuildZoneRebuildQueuedFull(1, 8) != 1 || cb::BuildZoneRebuildQueuedFull(1, 1) != 0
        || cb::BuildZoneRebuildQueuedFull(1, 3) != 0 || cb::BuildZoneRebuildQueuedFull(0, 0) != 0)
        Fail("t1428 zone fold 2: only a queued Full of this area covers the pieces");
    /* fold 2 (F1361 NIT): a piece is ready only with its box, its parts in and a physics body */
    if (cb::BuildZoneRebuildPieceReady(1, 0, 1) != 1 || cb::BuildZoneRebuildPieceReady(1, 0, 0) != 0 || cb::BuildZoneRebuildPieceReady(1, 0, -1) != 0
        || cb::BuildZoneRebuildPieceReady(0, 0, 3) != 0 || cb::BuildZoneRebuildPieceReady(1, 1, 3) != 0)
        Fail("t1428 zone fold 2: a piece with 0 physics bodies is not ready (the area job carves physics objects only)");
    /* fold 2 (F1361 NIT): a read fault is tried again, bounded */
    if (cb::BuildZoneRebuildReadRetry(1) != 1 || cb::BuildZoneRebuildReadRetry(cb::kZoneRbReadRetries - 1) != 1 || cb::BuildZoneRebuildReadRetry(cb::kZoneRbReadRetries) != 0)
        Fail("t1428 zone fold 2: a job-list read fault is tried again next tick, a bounded number of times");
    /* which roads note a piece */
    if (cb::BuildZoneRebuildNotes(1, 0, 0, 0) != 1 || cb::BuildZoneRebuildNotes(0, 1, 0, 0) != 1 || cb::BuildZoneRebuildNotes(0, 0, 1, 0) != 1)
        Fail("t1428 zone: a restore, a re-make and a kept row each note their area");
    if (cb::BuildZoneRebuildNotes(0, 0, 0, 0) != 0 || cb::BuildZoneRebuildNotes(1, 0, 0, 1) != 0) Fail("t1428 zone: a live copy and furniture note none");
    for (int a = cb::kZrbDoAsk; a <= cb::kZrbAgainQueued; ++a)
        if (std::string(cb::BuildZoneRebuildActWord(a)) == "?") Fail("t1428 zone: every act has its word");
    /* the rows on both builds */
    {
        const std::string t65 = T1260Flat("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T1260Flat("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const std::string sig = T1260Flat("../coop-plugin/addresses/signatures.sig");
        if (t65.find("ZoneWalkMapRebuild                             code 003AB700 003AB700 488BC456574154415541564881ECB000") == std::string::npos
            || t68.find("ZoneWalkMapRebuild                             code 003AB840 003AB840 488BC456574154415541564881ECB000") == std::string::npos)
            Fail("t1428 zone: ZoneWalkMapRebuild on both builds (0x3AB700 / 0x3AB840)");
        if (t65.find("NavMeshManagerPtr                              var  02133560 02133560 -") == std::string::npos
            || t68.find("NavMeshManagerPtr                              var  021345C0 021345C0 -") == std::string::npos)
            Fail("t1428 zone: NavMeshManagerPtr on both builds (0x2133560 / 0x21345C0)");
        if (sig.find("\nZoneWalkMapRebuild code ") == std::string::npos || sig.find("\nNavMeshManagerPtr var ") == std::string::npos) Fail("t1428 zone: both rows have signatures");
    }
    /* wiring */
    const char* need[] = {
        "static AddrReg kBdZoneRbRva_reg(\"ZoneWalkMapRebuild\", &kBdZoneRbRva);",
        "static AddrReg kBdNavMgrRva_reg(\"NavMeshManagerPtr\", &kBdNavMgrRva);",
        "BdZoneRebuildTick();   /* T-1428 attempt 2:",
        "if (p.restore != 0 || remake != 0) BdZoneRebuildNote(b, m.key.c_str(), p.restore != 0 ? 1 : 2);",
        "BdZoneRebuildNote(b, w.p.key.c_str(), 4);",
        "BdZoneRebuildAreaEnd(0);",
        "if (n != 0 && g_zoneRb.empty() == false) BdZoneRebuildAreaEnd(left);",
        "const int act = coopbuild::BuildZoneRebuildAct(rowsOk, area, skipRun, skipQ, qFull);",
        "if (act == coopbuild::kZrbAgainRunning || act == coopbuild::kZrbAgainQueued)",
        "if (PcPhysPod(q.b, &ents, &bodies) != 1) bodies = -1;",
        "coopbuild::BuildZoneRebuildPieceReady(grown, loading, bodies)",
        "if (nav != 0 && zmap != 0 && coopbuild::BuildZoneRebuildReadRetry(++z.faults) != 0) { ++i; continue; }",
        "if (BdZoneRbCallPod(base + (uintptr_t)kBdZoneRbRva, nav, zmap) != 0)",
        "zoneRebuild[noted,asked,skipQueued,againRunning,timedOut,noArea,gaveUp,faulted,noRows,piecesGone]=",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (b.find(need[i]) == std::string::npos) Fail(std::string("t1428 zone wiring: missing in build.cpp: ") + need[i]);
    const std::string tick = T1428FnBody(b, "void BdZoneRebuildTick()   /* MAIN THREAD, every tick (BdWalkMapHeldTick) */");
    if (tick.empty() || tick.find("BdOnMain() == 0") == std::string::npos) Fail("t1428 zone: the rebuild is asked on the main thread only");
    const std::string held = T1428FnBody(b, "void BdWalkMapHeldTick()\n{");
    const size_t zt = held.find("BdZoneRebuildTick();"), ret = held.find("return;");
    if (zt == std::string::npos || ret == std::string::npos || zt > ret) Fail("t1428 zone: the rebuild tick runs every tick, before the held list's early return");
}
/* T-1428 (F1226): a walking-map ask waits for the building's REAL box (+0x27C half-size above zero on all three axes, the engine's
   job-adding test 0x3C68E0), not for its physics holder; it is asked again the first tick the box is real; every give-up is logged once */
void t_t1428_box_wait()
{
    namespace cb = coopbuild;
    const float inf = std::numeric_limits<float>::infinity();
    const float nothing[6] = { 0.0f, 0.0f, 0.0f, -inf, -inf, -inf };   /* BOX_NULL as logged: aabb=0,0,0,-1.$,... */
    const float shack[6] = { -66675.0f, 959.0f, 21233.0f, 102.0f, 40.0f, 110.0f };
    const float flat[6] = { 0.0f, 0.0f, 0.0f, 5.0f, 0.0f, 5.0f };
    const float nan = std::numeric_limits<float>::quiet_NaN();
    const float bad[6] = { 0.0f, 0.0f, 0.0f, nan, 1.0f, 1.0f };
    if (cb::BuildWalkMapBoxReal(nothing) != 0 || cb::BuildWalkMapBoxReal(flat) != 0 || cb::BuildWalkMapBoxReal(bad) != 0 || cb::BuildWalkMapBoxReal(0) != 0)
        Fail("t1428: the nothing box, a flat box, a NaN box and no box are not real");
    if (cb::BuildWalkMapBoxReal(shack) != 1) Fail("t1428: a box with a size on all three axes is real");
    /* the wait decision rows: an empty box waits (every road that owes the box), a real box asks, removals and box-less asks never wait */
    const int roads[] = { cb::kWmCopyMade, cb::kWmCopyRestored, cb::kWmKeptMade, cb::kWmFinished, cb::kWmThreshold, cb::kWmBodyArrived };
    for (size_t i = 0; i < sizeof(roads) / sizeof(roads[0]); ++i)
    {
        if (cb::BuildWalkMapBoxWait(roads[i], cb::kWmBox, 0) != 1 || cb::BuildWalkMapBoxWait(roads[i], cb::kWmBox | cb::kWmInterior, 0) != 1)
            Fail(std::string("t1428: an empty box waits on the road ") + cb::BuildWalkMapEventWord(roads[i]));
        if (cb::BuildWalkMapBoxWait(roads[i], cb::kWmBox, 1) != 0) Fail(std::string("t1428: a real box asks on the road ") + cb::BuildWalkMapEventWord(roads[i]));
    }
    if (cb::BuildWalkMapBoxWait(cb::kWmRemoved, cb::kWmBox, 0) != 0) Fail("t1428: a removal never waits");
    if (cb::BuildWalkMapBoxWait(cb::kWmCopyMade, cb::kWmInterior, 0) != 0 || cb::BuildWalkMapBoxWait(cb::kWmCopyMade, 0, 0) != 0)
        Fail("t1428: an ask that owes no box (an unfinished house copy's interior, furniture) does not wait");
    /* the F1223 shack: made finished by the mod, its holder set, its box empty - the old holder test asked at once; the box test waits */
    {
        const int what = cb::BuildWalkMapWhat(cb::kWmCopyMade, 1, 1, 0);
        if (cb::BuildWalkMapBodyWait(cb::kWmCopyMade, 1, 0) != 0) Fail("t1428: (the old test) a holder set never waited");
        const int wait = cb::BuildWalkMapBoxWait(cb::kWmCopyMade, what, cb::BuildWalkMapBoxReal(nothing));
        if (wait != 1) Fail("t1428: the F1223 shack waits for its box");
        if (cb::BuildWalkMapQueueNow(what, wait) != 0) Fail("t1428 fold 1 (review 4): while its box waits nothing goes now - its interior goes after its box");
        if (cb::BuildWalkMapQueueNow(what, 0) != (cb::kWmBox | cb::kWmInterior)) Fail("t1428: a real box goes with its interior");
        const int again = cb::BuildWalkMapWhat(cb::kWmBodyArrived, 1, 1, 0);
        if (cb::BuildWalkMapBoxWait(cb::kWmBodyArrived, again, 1) != 0 || cb::BuildWalkMapQueueNow(again, 0) != (cb::kWmBox | cb::kWmInterior))
            Fail("t1428: the re-ask once the box is real queues its box (and interior)");
    }
    /* the nudge: the engine's own asks grow the half-size by 5.0 (0x1684340 / 1.0.68 0x1685340); the centre is kept */
    {
        float n[6];
        cb::BuildWalkMapBoxNudged(shack, n);
        if (cb::kWmBoxNudge != 5.0f || n[0] != shack[0] || n[1] != shack[1] || n[2] != shack[2] || n[3] != 107.0f || n[4] != 45.0f || n[5] != 115.0f)
            Fail("t1428: the box queued is grown by 5.0 on each half-size");
    }
    /* give-ups: the area that ended, a wait with no key at any area end, the world left (no sectors) */
    {
        unsigned char left[cb::kBuildZoneSectorCells];
        for (int c = 0; c < cb::kBuildZoneSectorCells; ++c) left[c] = 0;
        left[17 * 64 + 36] = 1;
        if (cb::BuildWalkMapWaitAreaEnds(1, 17 * 64 + 36, left, cb::kBuildZoneSectorCells) != 1) Fail("t1428: its area ended - it gives up");
        if (cb::BuildWalkMapWaitAreaEnds(1, 17 * 64 + 37, left, cb::kBuildZoneSectorCells) != 0) Fail("t1428: another area ended - it keeps waiting");
        if (cb::BuildWalkMapWaitAreaEnds(0, -1, left, cb::kBuildZoneSectorCells) != 1) Fail("t1428: a wait with no key gives up at any area end");
        if (cb::BuildWalkMapWaitAreaEnds(1, 5, 0, cb::kBuildZoneSectorCells) != 1) Fail("t1428: the world left - every wait gives up");
        if (std::string(cb::BuildWalkMapGiveUpWord(cb::kWmGiveUpArea)) != "its area ended" || std::string(cb::BuildWalkMapGiveUpWord(cb::kWmGiveUpOther)) != "another object at that address")
            Fail("t1428: the give-up words");
    }
    /* wiring */
    const std::string b = T1260Flat("../coop-plugin/build.cpp");
    const char* need[] = {
        "int BdWalkMapNote(void* b, int event, const char* key, int road = 0, long waitedMs = -1, int force = 0);",
        "const int boxReal = (boxRead != 0) ? coopbuild::BuildWalkMapBoxGrownReal(bx) : 0;",   /* fold 1 (review 3): the grown copy */
        "const int boxReady = (boxRead != 0) ? coopbuild::BuildWalkMapBoxReady(boxReal, loading) : 0;",   /* fold 1 (review 1): every part in */
        "const int boxWait = (force != 0) ? 0 : coopbuild::BuildWalkMapBoxWait(event, what0, boxReady);",
        "if (force != 0 && boxReal == 0) what0 &= ~coopbuild::kWmBox;",
        "const int what = coopbuild::BuildWalkMapQueueNow(what0, boxWait);",
        "coopbuild::BuildWalkMapBoxNudged(bx, nb);",
        "if (BdWalkMapPod(list, b, nb, what, base + (uintptr_t)kBdWmBoxRva, base + (uintptr_t)kBdWmIntRva, &held, &kept) == 0)",
        "\" road=%s waited=%ld ms\"",
        "box WAITS: not ready aabb=",
        /* the tick re-check (fold 1: the box waits' own list, the parts count, the time cap), and the createPhysical arrival asking again */
        "how = coopbuild::BuildWalkMapBoxDue(rd != 0 ? coopbuild::BuildWalkMapBoxGrownReal(bx) : 0, rd != 0 ? loading : 1, (unsigned int)(now - w.since));",
        "BdWalkMapNote(due[i].b, coopbuild::kWmBodyArrived, due[i].key.empty() ? 0 : due[i].key.c_str(), due[i].road, ms, dueHow[i] != coopbuild::kWmBoxAsk ? 1 : 0);",
        "BdWalkMapNote(b, coopbuild::kWmBodyArrived, w.key.empty() ? 0 : w.key.c_str(), w.road, (long)(::GetTickCount() - w.since));",
        "*loading = *(const int*)((const char*)b + kBPartsLoading);",
        "const size_t kBPartsLoading = 0x230;",
        "TIMED OUT (%u ms): %s; partsLoading=%d",
        /* give-ups, each logged once with its key */
        "if (n != 0 && (g_wmBoxWaits.empty() == false || g_wmBodyWait.empty() == false)) BdWalkWaitAreaEnd(left);",
        "BdWalkWaitGiveUpLine(w.key, w.road, w.since, coopbuild::kWmGiveUpArea);",
        "BdWalkWaitGiveUpLine(g_wmBoxWaits[i].key, g_wmBoxWaits[i].road, g_wmBoxWaits[i].since, coopbuild::kWmGiveUpWorld);",
        "BdWalkWaitGiveUpLine(due[i].key, due[i].road, due[i].since, coopbuild::kWmGiveUpOther);",
        "coopbuild::BuildWalkMapGiveUpWord(why), g_wmBoxGaveUp);",
        "NOT KEPT (GAVE UP: its walking-map ask is not made)",
        "walkMapBox[wait,came,gaveUp]=%lld,%lld,%lld",
    };
    for (size_t i = 0; i < sizeof(need) / sizeof(need[0]); ++i)
        if (b.find(need[i]) == std::string::npos) Fail(std::string("t1428 wiring: missing in build.cpp: ") + need[i]);
    if (b.find("BuildWalkMapBodyWait(event, BdBodyListPod(b), furn)") != std::string::npos) Fail("t1428 wiring: the ask still waits on the holder");
    t_t1428_fold1(b);
    t_t1428_zone_rebuild(b);   /* T-1428 attempt 2 */
}
void t_t1260_screen_take()
{
    namespace cs = coopstake;
    {   /* the road, by the deathCheck call's return address (1.0.65 and 1.0.68 rows; the calls at 0x7136EB / 0x712FF5 and 0x7142BB / 0x713BC5) */
        const unsigned long long base = 0x140000000ull;
        if (cs::RetRoad(base + 0x7136F0ull, base, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadRClick) Fail("t1260 road: the right-click call (1.0.65) is not the right-click road");
        if (cs::RetRoad(base + 0x712FFAull, base, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadPickup) Fail("t1260 road: the pickup call (1.0.65) is not the pickup road");
        if (cs::RetRoad(base + 0x7142C0ull, base, 0x713D20ull, 0x714930ull, 0x7139A0ull, 0x713D20ull) != cs::kRoadRClick) Fail("t1260 road: the right-click call (1.0.68) is not the right-click road");
        if (cs::RetRoad(base + 0x713BCAull, base, 0x713D20ull, 0x714930ull, 0x7139A0ull, 0x713D20ull) != cs::kRoadPickup) Fail("t1260 road: the pickup call (1.0.68) is not the pickup road");
        if (cs::RetRoad(base + 0x749E80ull, base, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadNone) Fail("t1260 road: takeItemOut's own call is noted");
        if (cs::RetRoad(base + 0x713D60ull, base, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadNone) Fail("t1260 road: the next function is inside the right-click road");
        if (cs::RetRoad(base + 0x713150ull, base, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadNone) Fail("t1260 road: the right-click routine's first byte is a return address");
        if (cs::RetRoad(base + 0x7136F0ull, base, 0x713150ull, 0ull, 0x712DD0ull, 0x713150ull) != cs::kRoadNone || cs::RetRoad(base + 0x7136F0ull, 0ull, 0x713150ull, 0x713D60ull, 0x712DD0ull, 0x713150ull) != cs::kRoadNone)
            Fail("t1260 road: an unbound row or base still notes");
        if (cs::RoadsOk(0x712DD0ull, 0x713150ull, 0x713D60ull) != 1 || cs::RoadsOk(0x7139A0ull, 0x713D20ull, 0x714930ull) != 1) Fail("t1260 road: both Steam builds' routine order is refused");
        if (cs::RoadsOk(0x713150ull, 0x712DD0ull, 0x713D60ull) != 0 || cs::RoadsOk(0x600000ull, 0x713150ull, 0x713D60ull) != 0 || cs::RoadsOk(0x712DD0ull, 0x713150ull, 0x713150ull) != 0)
            Fail("t1260 road: a build whose pickup does not end where the right-click begins is accepted");
    }
    {   /* the decision: a noted source (or a split's original stack) flags; no note, another item, an old note do not */
        cs::Notes s; cs::NotesClear(&s);
        int road = -1;
        int stack = 0, other = 0, invA = 0, invB = 0;
        if (cs::Decide(&s, &stack, 0, 5ull, &road) != 0 || road != cs::kRoadNone) Fail("t1260 decide: no note flags a request");
        cs::NoteAdd(&s, &invA, &stack, 5ull, cs::kRoadRClick);
        if (cs::Decide(&s, &stack, 0, 5ull, &road) != 1 || road != cs::kRoadRClick) Fail("t1260 decide: the noted source does not flag in its own drain");
        if (cs::Decide(&s, &stack, 0, 6ull, &road) != 1) Fail("t1260 decide: the noted source does not flag in the next drain (the take paired there)");
        if (cs::Decide(&s, &stack, 0, 7ull, &road) != 0 || road != cs::kRoadNone) Fail("t1260 decide: a note two drains old flags a request");
        if (cs::Decide(&s, &other, 0, 6ull, &road) != 0) Fail("t1260 decide: another item flags a request");
        if (cs::Decide(&s, 0, 0, 6ull, &road) != 0) Fail("t1260 decide: a request with no source item flags");
        if (cs::Decide(&s, &stack, &invB, 6ull, &road) != 0 || cs::Decide(&s, &stack, &invA, 6ull, &road) != 1) Fail("t1260 decide: the inventory, when compared, is not");
        cs::NoteAdd(&s, &invA, 0, 6ull, cs::kRoadPickup);
        if (s.n[1].used != 0) Fail("t1260 decide: a call with no item is noted");
        for (int k = 0; k < cs::kNoteCap; ++k) cs::NoteAdd(&s, &invA, &other, 9ull, cs::kRoadPickup);
        if (cs::Decide(&s, &stack, 0, 6ull, &road) != 0) Fail("t1260 decide: the ring does not drop its oldest note");
        if (cs::Decide(&s, &other, 0, 10ull, &road) != 1 || road != cs::kRoadPickup) Fail("t1260 decide: the pickup road is not named");
        if (cs::NoteFresh(5ull, 4ull) != 0) Fail("t1260 decide: a note from a later drain than now is fresh");
    }
    {   /* the request field's round trip: STK1 just before ASK1, read as the session reads it (ASK1 off the end, then STK1, then HLD1) */
        for (int flag = 0; flag < 2; ++flag)
        {
            std::vector<char> b;
            b.push_back('x'); b.push_back('y'); b.push_back('z');
            coophold::HoldTail ht; ht.holdId = 77u; ht.how = 1; ht.slot = 2;
            coophold::PutHoldTail(&b, ht);
            cs::PutTail(&b, flag);
            coopbrec::AskTail at; at.askId = 9ull; at.slot = 1;
            coopbrec::PutAskTail(&b, at);
            coopbrec::AskTail ga; size_t al = 0;
            if (coopbrec::TakeAskTail(&b[0], b.size(), &ga, &al) != 1 || ga.askId != 9ull) { Fail("t1260 wire: the ASK1 trailer is not last"); continue; }
            b.resize(b.size() - al);
            int got = -1;
            if (cs::TakeTail(&b[0], b.size(), &got) != 1 || got != flag) { Fail("t1260 wire: screenTake " + I(flag) + " does not round-trip"); continue; }
            b.resize(b.size() - cs::kTailLen);
            coophold::HoldTail gh;
            if (coophold::TakeHoldTail(&b[0], b.size(), &gh) != 1 || gh.holdId != 77u || b.size() != 3u + coophold::kHoldTailLen) Fail("t1260 wire: the HLD1 block is not whole after the STK1 one");
        }
        std::vector<char> c; cs::PutTail(&c, 7);
        int got = -1;
        if (c.size() != cs::kTailLen || cs::TakeTail(&c[0], c.size(), &got) != 1 || got != 1) Fail("t1260 wire: any set flag is written as 1");
        c[0] = 2;
        if (cs::TakeTail(&c[0], c.size(), &got) != 0) Fail("t1260 wire: a flag word this build does not know is read");
        std::vector<char> d; cs::PutTail(&d, 1);
        if (cs::TakeTail(&d[0], d.size() - 1, &got) != 0 || cs::TakeTail(&d[0], 0, &got) != 0) Fail("t1260 wire: a cut STK1 block is read");
        coopbrec::AskTail at; std::vector<char> e; coopbrec::PutAskTail(&e, at);
        if (cs::TakeTail(&e[0], e.size(), &got) != 0) Fail("t1260 wire: an older game's request (no STK1) is read as having one");
    }
    {   /* the protocol number */
        if (cs::kGameProtocolScreenTake != 217u || hovrec::kGameProtocol != 237u) Fail("t1260 protocol: the STK1 block is not of protocol 217 or the game-to-game protocol is not 237");
        const std::string se = T1260Flat("../coop-plugin/net/session.cpp");
        if (se.find("const unsigned int kProtocolVersion = 237;") == std::string::npos
            || se.find("typedef char ScreenTakeProtocolAgrees[(kProtocolVersion >= coopstake::kGameProtocolScreenTake) ? 1 : -1];") == std::string::npos)
            Fail("t1260 protocol: the session does not speak 237");
        const size_t ph = se.find("coophold::PutHoldTail(&b, ht);"), ps = se.find("    coopstake::PutTail(&b, r.screenTake);"), pa = se.find("coopbrec::PutAskTail(&b, at);");
        if (ph == std::string::npos || ps == std::string::npos || pa == std::string::npos || !(ph < ps && ps < pa)) Fail("t1260 protocol: STK1 is not between HLD1 and ASK1 on the send");
        const size_t ta = se.find("!coopbrec::TakeAskTail(&m0.payload[0], m0.payload.size(), &ask, &askLen)"), ts = se.find("!coopstake::TakeTail(&m.payload[0], m.payload.size(), &screenTake)"),
                     th = se.find("!coophold::TakeHoldTail(&m.payload[0], m.payload.size(), &ht)");
        if (ta == std::string::npos || ts == std::string::npos || th == std::string::npos || !(ta < ts && ts < th)) Fail("t1260 protocol: the read is not ASK1, then STK1, then HLD1");
        if (se.find("r.screenTake = (screenTake != 0 && (r.dir == 0 || r.dir == coophold::kDirHold)) ? 1 : 0;") == std::string::npos
            || se.find("OnItemRequestBody(c, &ht, dir, ask, screenTake);") == std::string::npos || se.find("OnItemRequestBody(m, 0, 0, ask, screenTake);") == std::string::npos)
            Fail("t1260 protocol: the flag does not reach the request, or reaches a give / LAND");
    }
    {   /* the new counters and the undo's exits */
        if (cs::HalfMissing(0, 0, 0) != cs::kHalfDst || cs::HalfMissing(1, 0, 0) != cs::kHalfSrc || cs::HalfMissing(1, 1, 0) != cs::kHalfSrcInv || cs::HalfMissing(1, 1, 1) != cs::kHalfNone)
            Fail("t1260 exits: the missing half is not dst, then src, then srcInv");
        if (std::string(cs::HalfName(cs::kHalfDst)) != "dst" || std::string(cs::HalfName(cs::kHalfSrc)) != "src" || std::string(cs::HalfName(cs::kHalfSrcInv)) != "srcInv") Fail("t1260 exits: the half names");
        {   /* review fold 1: what a failed undo leaves, by direction and by reason - only what is known is said */
            const int all[8] = { cs::kRevNone, cs::kRevNotFound, cs::kRevCellTaken, cs::kRevTakeOutFailed, cs::kRevPlaceFailed, cs::kRevFault, cs::kRevRecreateFailed, cs::kRevSplit };
            for (int k = 0; k < 8; ++k) for (int dr = 0; dr < 2; ++dr)
            {
                const int w = all[k];
                const int want = (w == cs::kRevNotFound || w == cs::kRevFault || w == cs::kRevSplit || w == cs::kRevNone) ? cs::kLeftUnknown
                    : (dr != 0 ? cs::kLeftGiveGone : ((w == cs::kRevCellTaken || w == cs::kRevTakeOutFailed) ? cs::kLeftDuplicate : cs::kLeftShortHere));
                const std::string at = std::string(" (dir ") + I(dr) + ", " + cs::RevertWhyName(w) + ")";
                if (cs::RevertLeft(dr, w) != want) Fail("t1260 exits: what a failed undo leaves is wrong" + at);
                const std::string t = cs::RevertLeftText(dr, w);
                if (t.empty()) { Fail("t1260 exits: no line" + at); continue; }
                if ((t.find("(a duplicate)") != std::string::npos) != (want == cs::kLeftDuplicate)) Fail("t1260 exits: only a take whose move stands says a duplicate" + at);
                if (want == cs::kLeftUnknown && (t.find("unknown") == std::string::npos || t.find("may") == std::string::npos)) Fail("t1260 exits: an unknown end is not said as unknown - may" + at);
                if (want == cs::kLeftGiveGone && (t.find("own item") == std::string::npos || t.find("no duplicate") == std::string::npos)) Fail("t1260 exits: a give's line does not say this game's own item, no duplicate" + at);
                if (dr != 0 && t.find("until that game's next record") != std::string::npos) Fail("t1260 exits: a give's line says short until that game's next record" + at);
                if (t.find("nothing was asked") == std::string::npos && t.find("never asked") == std::string::npos) Fail("t1260 exits: the line does not say nothing was asked" + at);
            }
            if (std::string(cs::RevertLeftText(0, cs::kRevPlaceFailed)).find("no duplicate") == std::string::npos) Fail("t1260 exits: a take's destroyed object is not said as no duplicate");
            if (std::string(cs::RevertLeftText(0, cs::kRevPlaceFailed)) == cs::RevertLeftText(1, cs::kRevPlaceFailed)) Fail("t1260 exits: a give's destroyed item shares the take's line");
            if (std::string(cs::RevertLeftText(0, cs::kRevNotFound)) == cs::RevertLeftText(0, cs::kRevFault)) Fail("t1260 exits: notFound and fault share a line");
            const std::string h0 = cs::HalfMissingLeftText(0), h1 = cs::HalfMissingLeftText(1);
            if (h0.find("(a duplicate)") == std::string::npos || h1.find("(a duplicate)") != std::string::npos || h1.find("unknown") == std::string::npos)
                Fail("t1260 exits: the half-missing line claims a duplicate for a give, or not for a take");
        }
        const int whys[8] = { cs::kRevNone, cs::kRevNotFound, cs::kRevCellTaken, cs::kRevTakeOutFailed, cs::kRevPlaceFailed, cs::kRevFault, cs::kRevRecreateFailed, cs::kRevSplit };
        for (int a = 1; a < 8; ++a) for (int b2 = a + 1; b2 < 8; ++b2)
            if (std::string(cs::RevertWhyName(whys[a])) == cs::RevertWhyName(whys[b2])) Fail("t1260 exits: two reasons share a name");
        if (std::string(cs::RevertWhyName(cs::kRevNone)) != "unknown") Fail("t1260 exits: no reason is not 'unknown'");
        if (cs::SayNth(0) != 0 || cs::SayNth(1) != 1 || cs::SayNth(5) != 1 || cs::SayNth(6) != 0 || cs::SayNth(99) != 0 || cs::SayNth(100) != 1 || cs::SayNth(200) != 1) Fail("t1260 exits: the rate is not the first 5, then every 100th");
        if (cs::kRfHalfMissing != 0 || cs::kRfPutBack != 1 || cs::kRfGiveNoRecord != 2 || cs::kRfTakeNoRecord != 3 || cs::kRfCount != 4) Fail("t1260 exits: the counters' order");
        const std::string it = T1260Flat("../coop-plugin/items.cpp");
        if (it.find("+ \" revertFailedBy[halfMissing,putBack,giveNoRecord,takeNoRecord]=\"") == std::string::npos
            || it.find("+ \" screenTake[hooked,noted,reqFlagged,holdFlagged,ownerAsked,ownerKilled,ownerNoCall,ownerFault]=\"") == std::string::npos)
            Fail("t1260 exits: the report line lacks the new counters");
        if (it.find("const long long nRf = ++g_revertFailedBy[coopstake::kRfHalfMissing];") == std::string::npos || it.find("const long long nRf = ++g_revertFailedBy[coopstake::kRfPutBack];") == std::string::npos
            || it.find("++g_revertFailedBy[coopstake::kRfGiveNoRecord]") == std::string::npos || it.find("++g_revertFailedBy[coopstake::kRfTakeNoRecord]") == std::string::npos)
            Fail("t1260 exits: an exit that books revertFailed has no counter of its own");
        if (it.find("if (whyOut != 0) *whyOut = (ok == 0) ? why : coopstake::kRevNone;") == std::string::npos || it.find("(mergeRest != 0) ? src.quantity : 0, &revWhy,") == std::string::npos)   /* T-1266: the take's units follow */
            Fail("t1260 exits: ItRevert's reason does not reach the put-back exit");
        if (it.find("+ coopstake::RevertLeftText(dir, why)") == std::string::npos || it.find("+ coopstake::HalfMissingLeftText(dir) +") == std::string::npos
            || it.find("RevertWhyDuplicate") != std::string::npos)
            Fail("t1260 exits: the undo's two lines are not said by direction and reason");
    }
    {   /* the rows, both builds, and their signature */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        if (t65.find("RClickAutoTradeEnd                             code 00713D60 00713D60 4C8BDC49895B0849896B104989731857") == std::string::npos)
            Fail("t1260 rows: the 1.0.65 table lacks RClickAutoTradeEnd");
        if (t68.find("RClickAutoTradeEnd                             code 00714930 00714930 4C8BDC49895B0849896B104989731857") == std::string::npos)
            Fail("t1260 rows: the 1.0.68 table lacks RClickAutoTradeEnd");
        if (sig.find("\nRClickAutoTradeEnd ") == std::string::npos) Fail("t1260 rows: the signatures lack RClickAutoTradeEnd");
    }
    {   /* the wiring: the hook notes only on the main thread from the two roads and always runs the engine's; the owner's check after every refusal */
        const std::string it = T1260Flat("../coop-plugin/items.cpp");
        if (it.find("AddrReg kStDeathCheckRva_reg(\"Inventory_onOwnerDeath\", &kStDeathCheckRva)") == std::string::npos
            || it.find("AddrReg kRClickAutoTradeEndRva_reg(\"RClickAutoTradeEnd\", &kRClickAutoTradeEndRva)") == std::string::npos)
            Fail("t1260 wiring: items.cpp does not bind the rows");
        const size_t d = it.find("char detour_stDeathCheck(void* inv, void* item)\n{"), dEnd = (d == std::string::npos) ? d : it.find("\n}\n", d);
        if (d == std::string::npos || dEnd == std::string::npos) Fail("t1260 wiring: no deathCheck detour");
        else
        {
            const std::string b = it.substr(d, dEnd - d);
            if (b.find("if (road != coopstake::kRoadNone && ItOnMainThread() != 0)") == std::string::npos || b.find("    return orig_stDeathCheck(inv, item);") == std::string::npos)
                Fail("t1260 wiring: the detour notes off the main thread or does not always run the engine's check");
        }
        const size_t o = it.find("int ItOwnerTake(::Inventory* inv, ::InventorySection* sec, int x, int y, int want, ItEntry* fieldsOut, void** keptOut, int* reason,");
        const size_t oEnd = (o == std::string::npos) ? o : it.find("\n}\n", o);
        if (o == std::string::npos || oEnd == std::string::npos) Fail("t1260 wiring: no ItOwnerTake");
        else
        {
            const std::string b = it.substr(o, oEnd - o);
            const size_t lastRefusal = b.find("else if (ItReadFields(item, fieldsOut) != 1) *reason = kRefUnreadable;"), chk = b.find("const int stAns = ItScreenTakeOwnerCheck((void*)inv, (void*)item);"),
                         take = b.find("::Item* gone = inv->takeItemOut(item, (want >= q) ? -1 : want, true);");
            if (lastRefusal == std::string::npos || chk == std::string::npos || take == std::string::npos || !(lastRefusal < chk && chk < take) || b.find("if (screenTake != 0)") == std::string::npos)
                Fail("t1260 wiring: the owner's death check is not after every refusal and just before takeItemOut, or not only when flagged");
            const size_t lift = b.find("const int stLift = ((DWORD)::InterlockedCompareExchange(&g_itApplyingThread, 0, (LONG)stTid) == stTid) ? 1 : 0;"),
                         back = b.find("if (stLift != 0) ::InterlockedExchange(&g_itApplyingThread, (LONG)stTid);");
            if (lift == std::string::npos || back == std::string::npos || chk == std::string::npos || !(lift < chk && chk < back))
                Fail("t1260 wiring: the owner's death check runs under the applying guard (a HOLD's death would not be published)");
        }
        if (it.find("ok = ItOwnerTake(inv, sec, r.ownerX, r.ownerY, want, &fe, &kept, &reason, r.baseSid.empty() ? 0 : r.baseSid.c_str(), r.screenTake, &stAns); }") == std::string::npos
            || it.find("const int st = (r.dir == 0 && r.screenTake != 0) ? 1 : 0;") == std::string::npos)
            Fail("t1260 wiring: a flagged HOLD or TAKE does not reach the owner's check");
        if (it.find("const int ok = ItOwnerTake(inv, sec, w.x, w.y, w.qty > 0 ? w.qty : 1, &fe, &k, &reason, w.sid.c_str());") == std::string::npos
            || it.find("if (ItOwnerTake(h.saveInv, h.saveSec, h.saveX, h.saveY, h.units, &tfe, &clone, &why, g_hdHoldFe[i].baseSid) != 0") == std::string::npos)
            Fail("t1260 wiring: the capture strip or the save's hold take asks the death check");
        if (it.find("    a.rq.screenTake = 0;") == std::string::npos || it.find("if (dir == 0 && aiTakeOne == 0") == std::string::npos || it.find("    ++g_stGen;") == std::string::npos)
            Fail("t1260 wiring: a LAND or an AI take carries the flag, or the note never ages");
    }
}
void t_t1150_haul_pool_filter()
{
    using teamstub::HaulPoolPass;
    for (int e = 0; e < 2; ++e) for (int s = 0; s < 2; ++s) for (int m = 0; m < 2; ++m)
    {
        const int want = (e != 0 || (s != 0 && m != 0)) ? 1 : 0;
        if (HaulPoolPass(e, s, m) != want) Fail("t1150 pool: keep " + I(e) + " search " + I(s) + " mate " + I(m) + " gives " + I(HaulPoolPass(e, s, m)));
    }
    {   /* the cells: a teammate's faction found, a stranger's and no faction not */
        void* volatile c[16];
        for (int k = 0; k < 16; ++k) c[k] = 0;
        void* mates[2] = { (void*)0x2000, (void*)0x2100 };
        teamstub::MateCellsWrite(c, 16, mates, 2);
        if (teamstub::MateCellsHas(c, 16, (void*)0x2100) != 1) Fail("t1150 pool: a teammate's faction is held");
        if (teamstub::MateCellsHas(c, 16, (void*)0x3000) != 0) Fail("t1150 pool: a stranger's faction is not held");
        if (teamstub::MateCellsHas(c, 16, 0) != 0) Fail("t1150 pool: no faction is never a teammate (empty cells hold 0)");
        teamstub::MateCellsWrite(c, 16, 0, 0);
        if (teamstub::MateCellsHas(c, 16, (void*)0x2000) != 0) Fail("t1150 pool: leaving the team ends the match");
    }
    {   /* the rows, both builds, and their signatures */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const char* const r65[3] = { "HaulCandidatesGather                           code 008CAFD0 008CAFD0 488BC45741544155415641574883EC70",
                                     "OwnershipsMayUse                               code 006207A0 006207A0 48895C24084889742410574883EC2048",
                                     "HaulSearchGatherRet                            ret  0059A2C7 0059A2C2 E85B4FA7FF" };
        const char* const r68[3] = { "HaulCandidatesGather                           code 008CBEA0 008CBEA0 488BC45741544155415641574883EC70",
                                     "OwnershipsMayUse                               code 00621230 00621230 48895C24084889742410574883EC2048",
                                     "HaulSearchGatherRet                            ret  0059AD57 0059AD52 E8D044A7FF" };
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        const char* const names[3] = { "HaulCandidatesGather", "OwnershipsMayUse", "HaulSearchGatherRet" };
        for (int k = 0; k < 3; ++k)
        {
            if (t65.find(r65[k]) == std::string::npos) Fail(std::string("t1150 pool: the 1.0.65 table lacks ") + names[k]);
            if (t68.find(r68[k]) == std::string::npos) Fail(std::string("t1150 pool: the 1.0.68 table lacks ") + names[k]);
            if (sig.find(std::string("\n") + names[k] + " ") == std::string::npos) Fail(std::string("t1150 pool: the signatures lack ") + names[k]);
        }
    }
    {   /* the wiring: rows bound, the mark only from the search's own call, the filter's teammate pass, built only with the compare */
        std::string pol = T313ReadFile("../coop-plugin/policy.cpp");
        pol.erase(std::remove(pol.begin(), pol.end(), '\r'), pol.end());   /* the detour checks span lines: a CRLF checkout (the bench's build tree) reads the same as an LF one */
        if (pol.find("AddrReg kHaulGatherRva_reg(\"HaulCandidatesGather\", &kHaulGatherRva)") == std::string::npos
            || pol.find("AddrReg kHaulFilterRva_reg(\"OwnershipsMayUse\", &kHaulFilterRva)") == std::string::npos
            || pol.find("AddrReg kHaulGatherRetRva_reg(\"HaulSearchGatherRet\", &kHaulGatherRetRva)") == std::string::npos)
            Fail("t1150 pool: policy.cpp does not bind the three rows");
        const size_t g = pol.find("void detour_HaulGather(void* who, void* list, unsigned int kinds)\n{");
        const size_t gEnd = (g == std::string::npos) ? g : pol.find("\n}\n", g);
        if (g == std::string::npos || gEnd == std::string::npos) Fail("t1150 pool: no gather detour");
        else
        {
            const std::string b = pol.substr(g, gEnd - g);
            if (b.find("_ReturnAddress() != (unsigned long long)(g_base + (uintptr_t)kHaulGatherRetRva)") == std::string::npos) Fail("t1150 pool: the mark is not limited to the storage search's call");
            if (b.find("__finally { ::TlsSetValue(g_haulPoolTls, prev); }") == std::string::npos) Fail("t1150 pool: the mark is not restored after the gather");
        }
        const size_t f = pol.find("char detour_HaulFilter(void* record, void* building, void* who)\n{");
        const size_t fEnd = (f == std::string::npos) ? f : pol.find("\n}\n", f);
        if (f == std::string::npos || fEnd == std::string::npos) Fail("t1150 pool: no filter detour");
        else
        {
            const std::string b = pol.substr(f, fEnd - f);
            const size_t o = b.find("orig_HaulFilter(record, building, who)"), k = b.find("if (keep != 0 ");
            if (o == std::string::npos || k == std::string::npos || k < o) Fail("t1150 pool: the engine's answer is not asked first and kept");
            if (b.find("teamstub::MateCellsHas(g_haulCells->cell, kBoxCells, fac)") == std::string::npos || b.find("teamstub::MayUsePass(") == std::string::npos)
                Fail("t1150 pool: the filter does not use the teammate cells and the pure answer (T-1250: MayUsePass, which asks HaulPoolPass)");
        }
        if (pol.find("if (g_haulCells == 0) g_haulPoolWhy = \"the owner test is not patched\";") == std::string::npos) Fail("t1150 pool: the hooks are not tied to the compare's patch");
        if (pol.find("teamHaulPool[hooked,hits]=") == std::string::npos) Fail("t1150 pool: the report line has no teamHaulPool counter");
    }
}

/* T-1250 (parity with T-1150): (1) the owner filter 0x6207A0's answer for every caller (teamstub::MayUsePass); (2) the eating
   search's stub (teamstub::EatStubBuild) for the test at 1.0.65 0x8D9DD4 / 1.0.68 0x8DACA4 - golden bytes with one cell (decoded
   with capstone when written), every jump and cell offset with sixteen; (3) the rows, both builds, their signatures; (4) the
   wiring in policy.cpp. */
void t_t1250_team_use_and_eat()
{
    using namespace teamstub;
    {   /* (1) the pass: the engine's keep stands; only a teammate's building is ever kept; the search as T-1150; a job only for this
           game's player's record and never for the bed cost */
        for (int e = 0; e < 2; ++e) for (int s = 0; s < 2; ++s) for (int m = 0; m < 2; ++m) for (int a = 0; a < 2; ++a) for (int b = 0; b < 2; ++b)
        {
            int want = kMayUseEngine;
            if (e == 0 && m != 0) want = (s != 0) ? kMayUseKeptSearch : ((a != 0 && b == 0) ? kMayUseKeptJob : kMayUseEngine);
            const int got = MayUsePass(e, s, m, a, b);
            if (got != want) Fail("t1250 pass: keep " + I(e) + " search " + I(s) + " mate " + I(m) + " player " + I(a) + " bed " + I(b) + " gives " + I(got) + ", want " + I(want));
        }
        if (kMayUseEngine == kMayUseKeptSearch || kMayUseEngine == kMayUseKeptJob || kMayUseKeptSearch == kMayUseKeptJob) Fail("t1250 pass: the three answers differ");
    }
    {   /* (2) the stub: the original test (cmp qword [rax+0x250], 0) and the jne's opcode */
        static const unsigned char test8[8] = { 0x48, 0x83, 0xB8, 0x50, 0x02, 0x00, 0x00, 0x00 };
        if (kFoodSearchOrigLen != 10 || kFoodSearchTestLen != 8 || std::memcmp(kFoodSearchTestOrig, test8, 8) != 0
            || kFoodSearchTestOrig[8] != 0x0F || kFoodSearchTestOrig[9] != 0x85)
            Fail("t1250 eat: the checked bytes are the 8-byte test then jne (0F 85)");
        const int off = 0x400;
        if (EatStubLenFor(16) > off || off + 8 + 8 * 16 > 0x1000) Fail("t1250 eat: the stub ends before its cells and the cells fit the page");
        static const unsigned char gold[78] = {
            0x48, 0x83, 0xB8, 0x50, 0x02, 0x00, 0x00, 0x00,   /*  0 cmp qword [rax+0x250], 0 */
            0x0F, 0x84, 0x32, 0x00, 0x00, 0x00,               /*  8 je 64 (BACK) */
            0x50,                                             /* 14 push rax */
            0x48, 0x8B, 0x46, 0x10,                           /* 15 mov rax, [rsi+0x10] */
            0x48, 0x85, 0xC0,                                 /* 19 test rax, rax */
            0x0F, 0x84, 0x0D, 0x00, 0x00, 0x00,               /* 22 je 41 (NOTMATE) */
            0x48, 0x3B, 0x05, 0xE5, 0x03, 0x00, 0x00,         /* 28 cmp rax, [rip+0x3e5] (0x408, cell 0) */
            0x0F, 0x84, 0x0B, 0x00, 0x00, 0x00,               /* 35 je 52 (HIT) */
            0x58,                                             /* 41 pop rax */
            0x48, 0x83, 0xB8, 0x50, 0x02, 0x00, 0x00, 0x00,   /* 42 cmp qword [rax+0x250], 0 */
            0xEB, 0x0C,                                       /* 50 jmp 64 */
            0x58,                                             /* 52 pop rax */
            0xF0, 0x48, 0xFF, 0x05, 0xC3, 0x03, 0x00, 0x00,   /* 53 lock inc qword [rip+0x3c3] (0x400, hits) */
            0x48, 0x39, 0xC0,                                 /* 61 cmp rax, rax (ZF=1) */
            0xFF, 0x25, 0x00, 0x00, 0x00, 0x00,               /* 64 jmp [rip] */
            0xDC, 0x9D, 0x8D, 0x40, 0x01, 0x00, 0x00, 0x00    /* 70 site + 8 = 0x1408D9DDC (the jne) */
        };
        std::vector<unsigned char> p(0x1000, 0xCC);
        const int len = EatStubBuild(&p[0], 0x1408D9DD4ULL, 1, off);
        if (len != 78 || len != EatStubLenFor(1)) Fail("t1250 eat golden: one cell is 78 bytes, got " + I(len));
        for (int i = 0; i < 78; ++i)
            if (p[i] != gold[i]) { Fail("t1250 eat golden: byte " + I(i) + " is " + I((int)p[i]) + ", the decode says " + I((int)gold[i])); break; }
        if (p[78] != 0xCC) Fail("t1250 eat golden: nothing written past byte 78");
        const unsigned long long sites[2] = { 0x1408D9DD4ULL, 0x1408DACA4ULL };
        for (int s = 0; s < 2; ++s)
        {   /* sixteen cells (policy.cpp's count), both builds' sites */
            std::vector<unsigned char> q(0x1000, 0xCC);
            const int cells = 16;
            const int n = EatStubBuild(&q[0], sites[s], cells, off);
            const int N = 28 + 13 * cells, hit = N + 11, back = hit + 12;
            if (n != EatStubLenFor(cells) || n != back + 14) { Fail("t1250 eat: sixteen cells, the length"); continue; }
            int r = 0;
            std::memcpy(&r, &q[10], 4); if (14 + r != back) Fail("t1250 eat: a non-player eater goes straight back");
            std::memcpy(&r, &q[24], 4); if (28 + r != N) Fail("t1250 eat: no owner goes to NOTMATE");
            for (int k = 0; k < cells; ++k)
            {
                const int o = 28 + 13 * k;
                if (q[o] != 0x48 || q[o + 1] != 0x3B || q[o + 2] != 0x05 || q[o + 7] != 0x0F || q[o + 8] != 0x84) { Fail("t1250 eat: cell " + I(k) + " is cmp rax,[rip] then je"); break; }
                std::memcpy(&r, &q[o + 3], 4); if (o + 7 + r != off + 8 + 8 * k) { Fail("t1250 eat: cell " + I(k) + " reads its own slot"); break; }
                std::memcpy(&r, &q[o + 9], 4); if (o + 13 + r != hit) { Fail("t1250 eat: cell " + I(k) + " jumps to HIT"); break; }
            }
            if (q[N] != 0x58 || std::memcmp(&q[N + 1], test8, 8) != 0 || q[N + 9] != 0xEB || N + 11 + (int)q[N + 10] != back) Fail("t1250 eat: NOTMATE pops and re-does the test, then BACK");
            std::memcpy(&r, &q[hit + 5], 4);
            if (q[hit] != 0x58 || q[hit + 1] != 0xF0 || hit + 9 + r != off || q[hit + 9] != 0x48 || q[hit + 10] != 0x39 || q[hit + 11] != 0xC0) Fail("t1250 eat: HIT pops, counts and sets ZF=1");
            unsigned long long to = 0; std::memcpy(&to, &q[back + 6], 8);
            if (q[back] != 0xFF || q[back + 1] != 0x25 || to != sites[s] + 8) Fail("t1250 eat: BACK returns to the jne at site + 8");
            if (q[n] != 0xCC) Fail("t1250 eat: nothing written past the stub");
        }
    }
    {   /* (3) the rows, both builds, and their signatures */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        const char* const r65[2] = { "FoodStoreSearchOwnerTest                       code 008D9DD4 008D9DD4 4883B850020000000F85F0010000488B",
                                     "BedCostMayUseRet                               ret  00330BB2 00330BAD E834B1D0FF" };
        const char* const r68[2] = { "FoodStoreSearchOwnerTest                       code 008DACA4 008DACA4 4883B850020000000F85F0010000488B",
                                     "BedCostMayUseRet                               ret  00330BF2 00330BED E81CB1D0FF" };
        const char* const names[2] = { "FoodStoreSearchOwnerTest", "BedCostMayUseRet" };
        for (int k = 0; k < 2; ++k)
        {
            if (t65.find(r65[k]) == std::string::npos) Fail(std::string("t1250: the 1.0.65 table lacks ") + names[k]);
            if (t68.find(r68[k]) == std::string::npos) Fail(std::string("t1250: the 1.0.68 table lacks ") + names[k]);
            if (sig.find(std::string("\n") + names[k] + " ") == std::string::npos) Fail(std::string("t1250: the signatures lack ") + names[k]);
        }
    }
    {   /* (4) the wiring */
        std::string pol = T313ReadFile("../coop-plugin/policy.cpp");
        pol.erase(std::remove(pol.begin(), pol.end(), '\r'), pol.end());
        if (pol.find("AddrReg kBedCostRetRva_reg(\"BedCostMayUseRet\", &kBedCostRetRva)") == std::string::npos
            || pol.find("AddrReg kFoodSearchTestRva_reg(\"FoodStoreSearchOwnerTest\", &kFoodSearchTestRva)") == std::string::npos)
            Fail("t1250: policy.cpp does not bind the two rows");
        const size_t f = pol.find("char detour_HaulFilter(void* record, void* building, void* who)\n{");
        const size_t fEnd = (f == std::string::npos) ? f : pol.find("\n}\n", f);
        if (f == std::string::npos || fEnd == std::string::npos) Fail("t1250: no filter detour");
        else
        {
            const std::string b = pol.substr(f, fEnd - f);
            if (b.find("(kBedCostRetRva == 0 || ret == (unsigned long long)(g_base + (uintptr_t)kBedCostRetRva))") == std::string::npos)
                Fail("t1250: the bed cost (or a missing row) is not left to the engine");
            if (b.find("coop::IsPlayerFaction(*(::Faction**)((char*)record + 0x70))") == std::string::npos) Fail("t1250: the asker is not the record's own faction");
            const size_t m = b.find("if (mate == 0) return keep;"), a = b.find("coop::IsPlayerFaction(");
            if (m == std::string::npos || a == std::string::npos || a < m) Fail("t1250: a stranger's building is not left to the engine first");
            if (b.find("::InterlockedIncrement64(&g_haulPoolHits)") == std::string::npos || b.find("::InterlockedIncrement64(&g_mayUseJobHits)") == std::string::npos)
                Fail("t1250: the search's and the jobs' passes are not counted apart");
        }
        if (pol.find("else EatTestPatch(g_base + (uintptr_t)kFoodSearchTestRva);") == std::string::npos
            || pol.find("std::memcmp(now, kFoodSearchTestOrig, teamstub::kFoodSearchOrigLen) != 0") == std::string::npos
            || pol.find("teamstub::EatStubBuild(stub, (unsigned long long)site, kBoxCells, (int)kBoxCellsOff) != teamstub::EatStubLenFor(kBoxCells)") == std::string::npos)
            Fail("t1250: the eating site is not patched with its own bytes and stub");
        const size_t hw = pol.find("if (g_eatCells != 0) g_eatHeld = MateCellsWrite(g_eatCells, facs, n);");
        const size_t pt = pol.find("void PolicyTeammateFactions(");
        if (hw == std::string::npos || pt == std::string::npos || hw < pt) Fail("t1250: the eating cells are not written with the team's other cells");
        if (pol.find("teamMayUse[on,jobHits,lastRet,bedLeft]=") == std::string::npos || pol.find("teamEat[patched,cellsHeld,hits]=") == std::string::npos)
            Fail("t1250: the report line lacks the teamMayUse / teamEat counters");
    }
}

/* T-1250 fix attempt 2 (design A): a teammate's outpost passes the two engine town gates on this game. (1) the pure rules
   (teamstub::TeamTownTakeMate / TeamTownNearer / TeamTownGate2); (2) gate 2's stub (teamstub::TownGateStubBuild) for the test at
   1.0.65 0x59B261 / 1.0.68 0x59BCF1 - golden bytes with one cell (decoded with capstone when written), every jump and cell offset
   with sixteen; (3) the two rows, both builds, their signatures; (4) the wiring in policy.cpp. */
void t_t1250_town_gates()
{
    using namespace teamstub;
    {   /* (1) gate 1: the teammate's town only when no own town covers the spot and a teammate's does; the nearest of several;
           gate 2: the engine's yes stands, a no passes only for a teammate's town */
        for (int o = 0; o < 2; ++o) for (int m = 0; m < 2; ++m)
        {
            const int want = (o == 0 && m != 0) ? 1 : 0;
            if (TeamTownTakeMate(o, m) != want) Fail("t1250 town gate1: own covers " + I(o) + " mate covers " + I(m) + " gives " + I(TeamTownTakeMate(o, m)) + ", want " + I(want));
        }
        if (TeamTownNearer(0, 0.0f, 5.0f) != 1) Fail("t1250 town gate1: the first covering teammate town is taken");
        if (TeamTownNearer(1, 10.0f, 5.0f) != 1 || TeamTownNearer(1, 5.0f, 10.0f) != 0) Fail("t1250 town gate1: the nearer teammate town wins");
        if (TeamTownNearer(1, 5.0f, 5.0f) != 0) Fail("t1250 town gate1: of two at the same distance the first stays");
        for (int e = 0; e < 2; ++e) for (int m = 0; m < 2; ++m)
        {
            const int want = (e != 0 || m != 0) ? 1 : 0;
            if (TeamTownGate2(e, m) != want) Fail("t1250 town gate2: engine " + I(e) + " mate " + I(m) + " gives " + I(TeamTownGate2(e, m)) + ", want " + I(want));
        }
    }
    {   /* (2) the stub: the original bytes (test al,al / je -0x102) */
        static const unsigned char orig[8] = { 0x84, 0xC0, 0x0F, 0x84, 0xFE, 0xFE, 0xFF, 0xFF };
        if (kTownGateOrigLen != 8 || std::memcmp(kTownGateTestOrig, orig, 8) != 0) Fail("t1250 town gate2: the checked bytes are test al,al then je rel32 -0x102");
        const int off = 0x400;
        if (TownGateStubLenFor(16) > off || off + 8 + 8 * 16 + 8 > 0x1000) Fail("t1250 town gate2: the stub ends before its cells and the cells and calls fit the page");
        static const unsigned char gold[85] = {
            0xF0, 0x48, 0xFF, 0x05, 0x08, 0x04, 0x00, 0x00,   /*  0 lock inc qword [rip+0x408] (0x410, calls) */
            0x84, 0xC0,                                       /*  8 test al, al */
            0x0F, 0x85, 0x37, 0x00, 0x00, 0x00,               /* 10 jne 71 (PASS) */
            0x50,                                             /* 16 push rax */
            0x48, 0x8B, 0x46, 0x10,                           /* 17 mov rax, [rsi+0x10] */
            0x48, 0x85, 0xC0,                                 /* 21 test rax, rax */
            0x0F, 0x84, 0x0D, 0x00, 0x00, 0x00,               /* 24 je 43 (NOTMATE) */
            0x48, 0x3B, 0x05, 0xE3, 0x03, 0x00, 0x00,         /* 30 cmp rax, [rip+0x3e3] (0x408, cell 0) */
            0x0F, 0x84, 0x03, 0x00, 0x00, 0x00,               /* 37 je 46 (HIT) */
            0x58,                                             /* 43 pop rax */
            0xEB, 0x0B,                                       /* 44 jmp 57 (REFUSE) */
            0x58,                                             /* 46 pop rax */
            0xF0, 0x48, 0xFF, 0x05, 0xC9, 0x03, 0x00, 0x00,   /* 47 lock inc qword [rip+0x3c9] (0x400, hits) */
            0xEB, 0x0E,                                       /* 55 jmp 71 (PASS) */
            0xFF, 0x25, 0x00, 0x00, 0x00, 0x00,               /* 57 jmp [rip] */
            0x67, 0xB1, 0x59, 0x40, 0x01, 0x00, 0x00, 0x00,   /* 63 the je's target 0x14059B167 */
            0xFF, 0x25, 0x00, 0x00, 0x00, 0x00,               /* 71 jmp [rip] */
            0x69, 0xB2, 0x59, 0x40, 0x01, 0x00, 0x00, 0x00    /* 77 site + 8 = 0x14059B269 */
        };
        std::vector<unsigned char> p(0x1000, 0xCC);
        const int len = TownGateStubBuild(&p[0], 0x14059B261ULL, 0x14059B167ULL, 1, off);
        if (len != 85 || len != TownGateStubLenFor(1)) Fail("t1250 town gate2 golden: one cell is 85 bytes, got " + I(len));
        for (int i = 0; i < 85; ++i)
            if (p[i] != gold[i]) { Fail("t1250 town gate2 golden: byte " + I(i) + " is " + I((int)p[i]) + ", the decode says " + I((int)gold[i])); break; }
        if (p[85] != 0xCC) Fail("t1250 town gate2 golden: nothing written past byte 85");
        const unsigned long long sites[2] = { 0x14059B261ULL, 0x14059BCF1ULL };
        const unsigned long long refuses[2] = { 0x14059B167ULL, 0x14059BBF7ULL };   /* site + 8 - 0x102 on both builds */
        for (int s = 0; s < 2; ++s)
        {   /* sixteen cells (policy.cpp's count), both builds' sites */
            if (sites[s] + 8 - 0x102 != refuses[s]) Fail("t1250 town gate2: the refusal is the je's own target");
            std::vector<unsigned char> q(0x1000, 0xCC);
            const int cells = 16;
            const int n = TownGateStubBuild(&q[0], sites[s], refuses[s], cells, off);
            const int N = 30 + 13 * cells, hit = N + 3, refuse = N + 14, pass = N + 28;
            if (n != TownGateStubLenFor(cells) || n != pass + 14) { Fail("t1250 town gate2: sixteen cells, the length"); continue; }
            int r = 0;
            std::memcpy(&r, &q[4], 4); if (8 + r != off + 8 + 8 * cells) Fail("t1250 town gate2: every ask counts in calls, after the cells");
            if (q[8] != 0x84 || q[9] != 0xC0) Fail("t1250 town gate2: the original test al,al");
            std::memcpy(&r, &q[12], 4); if (q[10] != 0x0F || q[11] != 0x85 || 16 + r != pass) Fail("t1250 town gate2: the engine's yes goes straight to PASS");
            std::memcpy(&r, &q[26], 4); if (30 + r != N) Fail("t1250 town gate2: no owner goes to NOTMATE");
            for (int k = 0; k < cells; ++k)
            {
                const int o = 30 + 13 * k;
                if (q[o] != 0x48 || q[o + 1] != 0x3B || q[o + 2] != 0x05 || q[o + 7] != 0x0F || q[o + 8] != 0x84) { Fail("t1250 town gate2: cell " + I(k) + " is cmp rax,[rip] then je"); break; }
                std::memcpy(&r, &q[o + 3], 4); if (o + 7 + r != off + 8 + 8 * k) { Fail("t1250 town gate2: cell " + I(k) + " reads its own slot"); break; }
                std::memcpy(&r, &q[o + 9], 4); if (o + 13 + r != hit) { Fail("t1250 town gate2: cell " + I(k) + " jumps to HIT"); break; }
            }
            if (q[N] != 0x58 || q[N + 1] != 0xEB || N + 3 + (int)q[N + 2] != refuse) Fail("t1250 town gate2: NOTMATE pops, then REFUSE");
            std::memcpy(&r, &q[hit + 5], 4);
            if (q[hit] != 0x58 || q[hit + 1] != 0xF0 || hit + 9 + r != off || q[hit + 9] != 0xEB || hit + 11 + (int)q[hit + 10] != pass) Fail("t1250 town gate2: HIT pops, counts, then PASS");
            unsigned long long to = 0;
            std::memcpy(&to, &q[refuse + 6], 8);
            if (q[refuse] != 0xFF || q[refuse + 1] != 0x25 || to != refuses[s]) Fail("t1250 town gate2: REFUSE goes to the je's target");
            std::memcpy(&to, &q[pass + 6], 8);
            if (q[pass] != 0xFF || q[pass + 1] != 0x25 || to != sites[s] + 8) Fail("t1250 town gate2: PASS goes to site + 8");
            if (q[n] != 0xCC) Fail("t1250 town gate2: nothing written past the stub");
        }
    }
    {   /* (3) the rows, both builds, and their signatures */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        const char* const r65[2] = { "TownUpdateOwnSearchRet                         ret  005A47DD 005A47D8 E824A9AAFF",
                                     "GetFoodTownGateTest                            code 0059B261 0059B261 84C00F84FEFEFFFF4883BE2801000000" };
        const char* const r68[2] = { "TownUpdateOwnSearchRet                         ret  005A526D 005A5268 E8D09EAAFF",
                                     "GetFoodTownGateTest                            code 0059BCF1 0059BCF1 84C00F84FEFEFFFF4883BE2801000000" };
        const char* const names[2] = { "TownUpdateOwnSearchRet", "GetFoodTownGateTest" };
        for (int k = 0; k < 2; ++k)
        {
            if (t65.find(r65[k]) == std::string::npos) Fail(std::string("t1250 town: the 1.0.65 table lacks ") + names[k]);
            if (t68.find(r68[k]) == std::string::npos) Fail(std::string("t1250 town: the 1.0.68 table lacks ") + names[k]);
            if (sig.find(std::string("\n") + names[k] + " ") == std::string::npos) Fail(std::string("t1250 town: the signatures lack ") + names[k]);
        }
    }
    {   /* (4) the wiring */
        std::string pol = T313ReadFile("../coop-plugin/policy.cpp");
        pol.erase(std::remove(pol.begin(), pol.end(), '\r'), pol.end());
        if (pol.find("AddrReg kTownUpdOwnRetRva_reg(\"TownUpdateOwnSearchRet\", &kTownUpdOwnRetRva)") == std::string::npos
            || pol.find("AddrReg kTeamTownInsideRva_reg(\"TownContainsPoint\", &kTeamTownInsideRva)") == std::string::npos
            || pol.find("AddrReg kTownGateTestRva_reg(\"GetFoodTownGateTest\", &kTownGateTestRva)") == std::string::npos)
            Fail("t1250 town: policy.cpp does not bind the three rows");
        const size_t f = pol.find("void* TeamTownSearch(void* list, const float* pos, void* faction, void* left, void* p5, int kind)\n{");
        const size_t fEnd = (f == std::string::npos) ? f : pol.find("\n}\n", f);
        if (f == std::string::npos || fEnd == std::string::npos) Fail("t1250 town: no gate 1 search");
        else
        {
            const std::string b = pol.substr(f, fEnd - f);
            const size_t o = b.find("void* own = g_town1Orig(list, pos, faction, left, p5, kind);"), nt = b.find("if (n == 0) return own;");
            const size_t oc = b.find("ownCovers = (own != 0 && inside(own, pos, kTeamTownScale) != 0) ? 1 : 0;"), ms = b.find("g_town1Orig(list, pos, mates[i], left, p5, kind)");
            if (o == std::string::npos || nt == std::string::npos || nt < o) Fail("t1250 town: gate 1 does not ask the engine first and stop with no team");
            if (oc == std::string::npos || ms == std::string::npos || ms < oc) Fail("t1250 town: gate 1 does not test the own town's cover before asking the teammates");
            if (b.find("teamstub::TeamTownTakeMate(ownCovers, best != 0 ? 1 : 0)") == std::string::npos || b.find("teamstub::TeamTownNearer(") == std::string::npos)
                Fail("t1250 town: gate 1 does not use the pure rules");
            if (b.find("::InterlockedIncrement64(&g_town1Calls);") == std::string::npos || b.find("::InterlockedIncrement64(&g_town1Hits);") == std::string::npos)
                Fail("t1250 town: gate 1 is not counted");
        }
        if (pol.find("else TeamTownGate1Install(g_base + (uintptr_t)kTownUpdOwnRetRva - 5);") == std::string::npos
            || pol.find("std::memcmp(head, kTeamTownNearestHead, 11) != 0") == std::string::npos)
            Fail("t1250 town: gate 1's call is not checked and retargeted");
        if (pol.find("else TeamTownGate2Install(g_base + (uintptr_t)kTownGateTestRva);") == std::string::npos
            || pol.find("std::memcmp(now, kTownGateTestOrig, teamstub::kTownGateOrigLen) != 0") == std::string::npos
            || pol.find("teamstub::TownGateStubBuild(stub, (unsigned long long)site, refuseTo, kBoxCells, (int)kBoxCellsOff) != teamstub::TownGateStubLenFor(kBoxCells)") == std::string::npos)
            Fail("t1250 town: gate 2's site is not patched with its own bytes and stub");
        const size_t pt = pol.find("void PolicyTeammateFactions(");
        const size_t w1 = pol.find("g_town1Held = teamstub::MateCellsWrite(g_town1Cells, kBoxCells, facs, n);");
        const size_t w2 = pol.find("if (g_town2Cells != 0) g_town2Held = MateCellsWrite(g_town2Cells, facs, n);");
        if (pt == std::string::npos || w1 == std::string::npos || w2 == std::string::npos || w1 < pt || w2 < pt) Fail("t1250 town: the gates' cells are not written with the team's other cells");
        if (pol.find("[POLICY] T-1250 town gates: gate1") == std::string::npos) Fail("t1250 town: no POLICY line at install");
        if (pol.find("teamTown[gate1,gate2,cellsHeld,gate1Calls,gate1Hits,gate1Faults,gate2Calls,gate2Hits]=") == std::string::npos) Fail("t1250 town: the report line lacks the teamTown counters");
        if (pol.find("NOT CHANGED (design A): the 'is at home town' AI condition 0x997110 and the nearest friendly town 0x926AD0") == std::string::npos)
            Fail("t1250 town: the two engine readers left alone are not named");
    }
}

/* T-1309 (owner 1187 a, 512): a teammate's gate or door is "mine" to this player's characters at the engine's "is this object mine"
   test (isObjectMine 1.0.65 0x5A3180 / 1.0.68 0x5A3C10, its faction compare at 0x5A3341 / 0x5A3DD1). (1) the team rule
   (teamstub::MineTeamAnswer): no team / own / teammate / stranger / town / cage, the engine's yes always stands; (2) the stub
   (teamstub::MineStubBuild) - golden bytes decoded with capstone when written, both builds' return points; (3) the row on both
   builds and its signature; (4) the wiring in policy.cpp. */
void t_t1309_mine_team()
{
    using namespace teamstub;
    {   /* (1) every input: the engine's yes stands; a no turns to yes only with a teammate on one side, the team on both, no cage */
        for (int e = 0; e < 2; ++e) for (int am = 0; am < 2; ++am) for (int ap = 0; ap < 2; ++ap)
        for (int om = 0; om < 2; ++om) for (int op = 0; op < 2; ++op) for (int c = 0; c < 2; ++c)
        {
            int want = 0;
            if (e != 0) want = 1;
            else if ((am != 0 || om != 0) && (am != 0 || ap != 0) && (om != 0 || op != 0) && c == 0) want = 1;
            const int got = MineTeamAnswer(e, am, ap, om, op, c);
            if (got != want) Fail("t1309 mine: engine " + I(e) + " askerMate " + I(am) + " askerPlayer " + I(ap) + " objMate " + I(om)
                                  + " objPlayer " + I(op) + " cage " + I(c) + " gives " + I(got) + ", want " + I(want));
        }
        /* the named cases (asker = this game's player B unless said) */
        if (MineTeamAnswer(1, 0, 1, 0, 1, 0) != 1) Fail("t1309 mine: B's own gate - the engine's yes stays yes");
        if (MineTeamAnswer(1, 0, 1, 0, 1, 1) != 1) Fail("t1309 mine: the engine's yes stays yes whatever the object is");
        if (MineTeamAnswer(0, 0, 1, 1, 0, 0) != 1) Fail("t1309 mine: A's gate (A a current teammate) - yes, as A's own");
        if (MineTeamAnswer(0, 0, 1, 1, 0, 1) != 0) Fail("t1309 mine: a teammate's cage - no, as the engine answers for an own cage");
        if (MineTeamAnswer(0, 0, 1, 0, 0, 0) != 0) Fail("t1309 mine: a stranger's / a town's / an NPC's door - the engine's no");
        if (MineTeamAnswer(0, 0, 1, 0, 0, 1) != 0) Fail("t1309 mine: a stranger's cage - the engine's no");
        if (MineTeamAnswer(0, 0, 0, 0, 0, 0) != 0) Fail("t1309 mine: no player and no teammate on either side - the engine's no");
        if (MineTeamAnswer(0, 1, 0, 0, 1, 0) != 1) Fail("t1309 mine: a teammate's copy asking about B's own door - yes (one faction both ways)");
        if (MineTeamAnswer(0, 1, 0, 1, 0, 0) != 1) Fail("t1309 mine: one teammate's copy asking about another teammate's door - yes");
        if (MineTeamAnswer(0, 1, 0, 0, 0, 0) != 0) Fail("t1309 mine: a teammate's copy asking about a town's door - the engine's no");
        /* no team: the cells are empty, so neither side is a teammate - every differing pair keeps the engine's no */
        for (int ap = 0; ap < 2; ++ap) for (int op = 0; op < 2; ++op) for (int c = 0; c < 2; ++c)
            if (MineTeamAnswer(0, 0, ap, 0, op, c) != 0) Fail("t1309 mine: with no team nothing changes (askerPlayer " + I(ap) + " objPlayer " + I(op) + ")");
        /* the cells: a faction is a teammate's only while it is held; empty cells (0) never match */
        void* volatile cells[16];
        for (int k = 0; k < 16; ++k) cells[k] = 0;
        int fa = 0, fb = 0, fs = 0;
        void* const facs[2] = { (void*)&fa, (void*)&fb };
        if (MateCellsWrite(cells, 16, facs, 2) != 2) Fail("t1309 mine cells: two teammates held");
        if (MateCellsHas(cells, 16, (void*)&fa) != 1 || MateCellsHas(cells, 16, (void*)&fb) != 1) Fail("t1309 mine cells: a teammate is found");
        if (MateCellsHas(cells, 16, (void*)&fs) != 0 || MateCellsHas(cells, 16, 0) != 0) Fail("t1309 mine cells: a stranger and a null are not");
        if (MateCellsWrite(cells, 16, 0, 0) != 0 || MateCellsHas(cells, 16, (void*)&fa) != 0) Fail("t1309 mine cells: the team left - nobody is a teammate");
    }
    {   /* (2) the stub */
        static const unsigned char orig[16] = { 0x48, 0x3B, 0xC7, 0x0F, 0x94, 0xC0, 0x48, 0x8B, 0x6C, 0x24, 0x48, 0x48, 0x8B, 0x5C, 0x24, 0x40 };
        if (kMineFactionOrigLen != 16 || kMineFactionTestLen != 6 || std::memcmp(kMineFactionTestOrig, orig, 16) != 0)
            Fail("t1309 mine stub: the checked bytes are cmp rax,rdi / sete al and the epilogue's first two loads; 6 replaced");
        static const unsigned char gold[44] = {
            0x48, 0x3B, 0xC7,                                 /*  0 cmp rax, rdi */
            0x74, 0x17,                                       /*  3 je 28 (YES) */
            0x48, 0x89, 0xC1,                                 /*  5 mov rcx, rax */
            0x48, 0x89, 0xFA,                                 /*  8 mov rdx, rdi */
            0x49, 0x89, 0xF0,                                 /* 11 mov r8, rsi */
            0x48, 0xB8, 0x40, 0x23, 0x01, 0x80, 0x01, 0x00, 0x00, 0x00,   /* 14 movabs rax, 0x180012340 (the helper) */
            0xFF, 0xD0,                                       /* 24 call rax */
            0xEB, 0x02,                                       /* 26 jmp 30 (BACK) */
            0xB0, 0x01,                                       /* 28 YES: mov al, 1 */
            0xFF, 0x25, 0x00, 0x00, 0x00, 0x00,               /* 30 BACK: jmp [rip] */
            0x47, 0x33, 0x5A, 0x40, 0x01, 0x00, 0x00, 0x00    /* 36 site + 6 = 0x1405A3347 */
        };
        std::vector<unsigned char> p(0x100, 0xCC);
        const int len = MineStubBuild(&p[0], 0x1405A3341ULL, 0x180012340ULL);
        if (len != 44 || len != kMineStubLen) Fail("t1309 mine stub golden: 44 bytes, got " + I(len));
        for (int i = 0; i < 44; ++i)
            if (p[i] != gold[i]) { Fail("t1309 mine stub golden: byte " + I(i) + " is " + I((int)p[i]) + ", the decode says " + I((int)gold[i])); break; }
        if (p[44] != 0xCC) Fail("t1309 mine stub golden: nothing written past byte 44");
        std::vector<unsigned char> q(0x100, 0xCC);
        MineStubBuild(&q[0], 0x1405A3DD1ULL, 0x7FF812345678ULL);   /* the 1.0.68 site */
        unsigned long long to = 0, h = 0;
        std::memcpy(&to, &q[36], 8); std::memcpy(&h, &q[16], 8);
        if (to != 0x1405A3DD7ULL || h != 0x7FF812345678ULL) Fail("t1309 mine stub: 1.0.68 - back to site + 6, the helper's address as given");
    }
    {   /* (3) the row, both builds, and its signature */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const std::string sig = T313ReadFile("../coop-plugin/addresses/signatures.sig");
        if (t65.find("TaskObjectMineFactionTest                      code 005A3341 005A3341 483BC70F94C0488B6C2448488B5C2440") == std::string::npos)
            Fail("t1309 mine: the 1.0.65 table lacks TaskObjectMineFactionTest");
        if (t68.find("TaskObjectMineFactionTest                      code 005A3DD1 005A3DD1 483BC70F94C0488B6C2448488B5C2440") == std::string::npos)
            Fail("t1309 mine: the 1.0.68 table lacks TaskObjectMineFactionTest");
        if (sig.find("\nTaskObjectMineFactionTest ") == std::string::npos) Fail("t1309 mine: the signatures lack TaskObjectMineFactionTest");
    }
    {   /* (4) the wiring */
        std::string pol = T313ReadFile("../coop-plugin/policy.cpp");
        pol.erase(std::remove(pol.begin(), pol.end(), '\r'), pol.end());
        if (pol.find("AddrReg kMineFactionTestRva_reg(\"TaskObjectMineFactionTest\", &kMineFactionTestRva)") == std::string::npos) Fail("t1309 mine: policy.cpp does not bind the row");
        if (pol.find("std::memcmp(now, kMineFactionTestOrig, teamstub::kMineFactionOrigLen) != 0") == std::string::npos
            || pol.find("teamstub::MineStubBuild(stub, (unsigned long long)site, (unsigned long long)(uintptr_t)&MineTeamAsk) != teamstub::kMineStubLen") == std::string::npos)
            Fail("t1309 mine: the site is not checked with its own bytes and patched with its stub");
        if (pol.find("else MineTestInstall(g_base + (uintptr_t)kMineFactionTestRva);") == std::string::npos) Fail("t1309 mine: not installed at InstallPolicy");
        const size_t f = pol.find("int MineTeamAsk(void* askerFac, void* objFac, void* thing)\n{");
        const size_t fEnd = (f == std::string::npos) ? f : pol.find("\n}\n", f);
        if (f == std::string::npos || fEnd == std::string::npos) Fail("t1309 mine: no helper");
        else
        {
            const std::string b = pol.substr(f, fEnd - f);
            const size_t m = b.find("if (askerMate == 0 && objMate == 0) return 0;"), pl = b.find("MinePlayerPod(askerFac)"), cg = b.find("MineCagePod(thing)");
            if (m == std::string::npos || pl == std::string::npos || cg == std::string::npos || pl < m || cg < pl)
                Fail("t1309 mine: the helper does not stop with no teammate on either side before any engine read");
            if (b.find("teamstub::MineTeamAnswer(0, askerMate, askerPlayer, objMate, objPlayer, cage)") == std::string::npos) Fail("t1309 mine: the helper does not use the pure rule");
            if (b.find("teamstub::MateCellsHas(g_mineCells, kBoxCells, askerFac)") == std::string::npos || b.find("teamstub::MateCellsHas(g_mineCells, kBoxCells, objFac)") == std::string::npos)
                Fail("t1309 mine: the helper does not read the teammate cells");
            if (b.find("std::string") != std::string::npos) Fail("t1309 mine: the any-thread helper builds no string");
        }
        const size_t pt = pol.find("void PolicyTeammateFactions(");
        const size_t w = pol.find("g_mineHeld = teamstub::MateCellsWrite(g_mineCells, kBoxCells, facs, n);");
        if (pt == std::string::npos || w == std::string::npos || w < pt) Fail("t1309 mine: the cells are not written with the team's other cells");
        if (pol.find("[POLICY] T-1309 'is this object mine' faction compare") == std::string::npos) Fail("t1309 mine: no POLICY line at install");
        if (pol.find("teamMine[patched,cellsHeld,asks,hits,cageNo,faults]=") == std::string::npos) Fail("t1309 mine: the report line lacks the teamMine counters");
    }
}

/* T-1240: a source file read for a wiring check, without carriage returns (the test machine checks out with CRLF) */
static std::string T1240NoCr(const std::string& s)
{
    std::string o; o.reserve(s.size());
    for (size_t i = 0; i < s.size(); ++i) if (s[i] != '\r') o += s[i];
    return o;
}

/* T-1122 (owner 1499): a raid counts the base owner's teammates as the owner's own at its three find-near sites (announce,
   assaultStart, assaultTargets). The pure decisions (when the search is repeated, for which factions, stopping or not, whose call it
   is), the four rows on both builds and their signatures, the two P247-only rows gone, and the plugin's wiring. */
void t_t1122_raid_team_near()
{
    using teamstub::RaidNearWiden; using teamstub::RaidNearSameTeam; using teamstub::RaidNearPick;
    const int A = teamstub::kRaidSiteAnnounce, S = teamstub::kRaidSiteAssaultStart, T = teamstub::kRaidSiteAssaultTargets;
    if (A != 1 || S != 2 || T != 3 || teamstub::kRaidSites != 3) Fail("t1122 near: the site numbers");
    if (std::string(teamstub::RaidSiteName(A)) != "announce" || std::string(teamstub::RaidSiteName(S)) != "assaultStart"
        || std::string(teamstub::RaidSiteName(T)) != "assaultTargets" || std::string(teamstub::RaidSiteName(0)) != "?")
        Fail("t1122 near: the site names");
    for (int f = 0; f < 2; ++f)
    {
        if (RaidNearWiden(0, f) != 0 || RaidNearWiden(4, f) != 0) Fail("t1122 near: widened with no site's mark");
        if (RaidNearWiden(A, f) != (f == 0 ? 1 : 0) || RaidNearWiden(S, f) != (f == 0 ? 1 : 0)) Fail("t1122 near: a yes / no test widened when the engine found someone, or not when it found nobody");
        if (RaidNearWiden(T, f) != 1) Fail("t1122 near: the target list does not always take the teammates");
    }
    if (teamstub::RaidNearStopAtFirst(A) != 1 || teamstub::RaidNearStopAtFirst(S) != 1 || teamstub::RaidNearStopAtFirst(T) != 0) Fail("t1122 near: stop at the first teammate's faction");
    if (teamstub::RaidNearCallInside(0x1000 + 399, 0x1000, 399) != 1 || teamstub::RaidNearCallInside(0x1001, 0x1000, 399) != 1
        || teamstub::RaidNearCallInside(0x1000, 0x1000, 399) != 0 || teamstub::RaidNearCallInside(0x1000 + 400, 0x1000, 399) != 0
        || teamstub::RaidNearCallInside(0x50, 0, 399) != 0)
        Fail("t1122 near: the site's own call by its return address");
    if (RaidNearSameTeam(1, 7, 2, 7) != 1) Fail("t1122 near: a teammate of the owner counts");
    if (RaidNearSameTeam(1, 7, 3, 9) != 0) Fail("t1122 near: a player of another team counts");
    if (RaidNearSameTeam(1, 7, 3, 0) != 0) Fail("t1122 near: a player in no team counts");
    if (RaidNearSameTeam(1, 7, 1, 7) != 0) Fail("t1122 near: the owner's own slot is searched again");
    if (RaidNearSameTeam(1, 7, -1, 7) != 0) Fail("t1122 near: a faction of no player counts");
    if (RaidNearSameTeam(-1, 0, 2, 0) != 0 || RaidNearSameTeam(1, 0, 2, 0) != 0) Fail("t1122 near: two players in no team share one");
    {   /* owner slot 1 in team 7: this game's own (slot 2, team 7), an NPC entry, a stranger (slot 3, team 9), the owner's own record
           (slot 1), a third teammate (slot 4, team 7) - the two teammates, in order */
        const int slots[5] = { 2, -1, 3, 1, 4 };
        const unsigned teams[5] = { 7, 0, 9, 7, 7 };
        int out[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };
        if (RaidNearPick(1, 7, slots, teams, 5, out, 8) != 2 || out[0] != 0 || out[1] != 4) Fail("t1122 near: the pick is not the owner's two teammates in order");
        if (RaidNearPick(1, 7, slots, teams, 5, out, 1) != 1 || out[0] != 0) Fail("t1122 near: the pick passes its cap");
        if (RaidNearPick(-1, 7, slots, teams, 5, out, 8) != 0) Fail("t1122 near: an NPC town's owner gets teammates");
        if (RaidNearPick(1, 0, slots, teams, 5, out, 8) != 0) Fail("t1122 near: an owner in no team gets teammates");
        const unsigned none[5] = { 0, 0, 0, 0, 0 };
        if (RaidNearPick(1, 7, slots, none, 5, out, 8) != 0) Fail("t1122 near: the control (nobody else in a team) gets a teammate");
        if (RaidNearPick(1, 7, slots, teams, 0, out, 8) != 0 || RaidNearPick(1, 7, 0, teams, 5, out, 8) != 0) Fail("t1122 near: an empty candidate list picks");
    }
    {   /* the assault-start test's player-town gate (0x290484 / 0x2904C4): this player's own faction or a teammate's stand-in passes;
           an NPC's or a non-team player's stand-in does not; the expected bytes, on both builds */
        using teamstub::AssaultTownGate;
        if (AssaultTownGate(1, 0) != 1) Fail("t1122 gate: this player's own town no longer passes");
        if (AssaultTownGate(0, 1) != 1) Fail("t1122 gate: a teammate's town does not pass");
        if (AssaultTownGate(1, 1) != 1) Fail("t1122 gate: both");
        if (AssaultTownGate(0, 0) != 0) Fail("t1122 gate: an NPC's or a non-team player's town passes");
        const unsigned char want[10] = { 0x48, 0x83, 0xB8, 0x50, 0x02, 0x00, 0x00, 0x00, 0x0F, 0x84 };
        if (std::memcmp(teamstub::kAssaultTownTestOrig, want, 10) != 0 || teamstub::kAssaultTownTestLen != 8 || teamstub::kAssaultTownOrigLen != 10) Fail("t1122 gate: the expected bytes");
        void* volatile cells[16];
        for (int k = 0; k < 16; ++k) cells[k] = 0;
        void* mates[1] = { (void*)0x5100 };   /* B's game: A's stand-in, A in B's team */
        teamstub::MateCellsWrite(cells, 16, mates, 1);
        if (AssaultTownGate(0, teamstub::MateCellsHas(cells, 16, (void*)0x5100)) != 1) Fail("t1122 gate: the teammate's stand-in town is not let through");
        if (AssaultTownGate(0, teamstub::MateCellsHas(cells, 16, (void*)0x5200)) != 0) Fail("t1122 gate: a non-team player's stand-in town is let through");
        teamstub::MateCellsWrite(cells, 16, 0, 0);
        if (AssaultTownGate(0, teamstub::MateCellsHas(cells, 16, (void*)0x5100)) != 0) Fail("t1122 gate: leaving the team keeps the town passing");
        /* AssaultTownGate is only a model: the gate the plugin runs is Test8Patch's machine-code stub (policy.cpp). Built here as
           Test8Patch builds it (coopcrime::SightStubBuild, the default 8-byte test, 16 cells at 0x400) for this site on both builds:
           it opens with this site's own test; a player faction (ZF=0) or a cell hit jumps back to the je at site + 8 with ZF=0
           (the assault goes on); anything else re-does the test (ZF=1: the je to 'return 0') */
        const unsigned long long gateSites[2] = { 0x140290484ULL, 0x1402904C4ULL };
        for (int b = 0; b < 2; ++b)
        {
            static unsigned char p[0x1000];
            std::memset(p, 0xCC, sizeof p);
            const int nc = 16, off = 0x400;
            const int L = teamstub::kAssaultTownTestLen, H = L + 6, N = H + 13 * nc, hit = N + L + 2, back = hit + 12;
            const int len = coopcrime::SightStubBuild(p, gateSites[b], nc, off);
            const std::string at = b == 0 ? " (1.0.65)" : " (1.0.68)";
            if (len != 50 + 13 * nc || len > off || p[len] != 0xCC) { Fail("t1122 gate stub: its length" + at); continue; }
            int d = 0;
            if (std::memcmp(p, teamstub::kAssaultTownTestOrig, (size_t)L) != 0 || p[L] != 0x0F || p[L + 1] != 0x85) Fail("t1122 gate stub: it opens with the site's own test and a jne" + at);
            std::memcpy(&d, p + L + 2, 4); if (H + d != back) Fail("t1122 gate stub: a player faction does not jump straight back" + at);
            for (int k = 0; k < nc; ++k)
            {
                const int o = H + 13 * k;
                if (p[o] != 0x48 || p[o + 1] != 0x3B || p[o + 2] != 0x05 || p[o + 7] != 0x0F || p[o + 8] != 0x84) { Fail("t1122 gate stub: cell compare bytes" + at); break; }
                std::memcpy(&d, p + o + 3, 4); if (o + 7 + d != off + 8 + 8 * k) { Fail("t1122 gate stub: a cell compare reads another cell" + at); break; }
                std::memcpy(&d, p + o + 9, 4); if (o + 13 + d != hit) { Fail("t1122 gate stub: a cell hit does not jump to HIT" + at); break; }
            }
            if (std::memcmp(p + N, teamstub::kAssaultTownTestOrig, (size_t)L) != 0 || p[N + L] != 0xEB || N + L + 2 + p[N + L + 1] != back)
                Fail("t1122 gate stub: NOTPEER does not re-do the site's test and jump back" + at);
            std::memcpy(&d, p + hit + 4, 4);
            if (p[hit] != 0xF0 || p[hit + 1] != 0x48 || p[hit + 2] != 0xFF || p[hit + 3] != 0x05 || hit + 8 + d != off) Fail("t1122 gate stub: HIT does not count into hits" + at);
            if (p[hit + 8] != 0x48 || p[hit + 9] != 0x83 || p[hit + 10] != 0xF8 || p[hit + 11] != 0x00) Fail("t1122 gate stub: HIT does not leave ZF=0 (cmp rax, 0)" + at);
            unsigned long long to = 0; std::memcpy(&to, p + back + 6, 8);
            std::memcpy(&d, p + back + 2, 4);
            if (p[back] != 0xFF || p[back + 1] != 0x25 || d != 0 || to != gateSites[b] + (unsigned long long)L) Fail("t1122 gate stub: BACK is not the je at site + 8" + at);
            if (teamstub::kAssaultTownTestOrig[L] != 0x0F || teamstub::kAssaultTownTestOrig[L + 1] != 0x84) Fail("t1122 gate stub: the jcc left in place is not the je" + at);
        }
        {   /* ...and the plugin builds it that way for this site */
            const std::string pol = T1240NoCr(T313ReadFile("../coop-plugin/policy.cpp"));
            if (pol.find("const int kBoxCells = 16;") == std::string::npos || pol.find("const size_t kBoxCellsOff = 0x400;") == std::string::npos
                || pol.find("if (coopcrime::SightStubBuild(stub, (unsigned long long)site, kBoxCells, (int)kBoxCellsOff) != 50 + 13 * kBoxCells)") == std::string::npos
                || pol.find("else Test8Patch(g_base + (uintptr_t)kAssaultTownTestRva, kAssaultTownTestOrig, g_assaultCells, g_assaultWhy);") == std::string::npos)
                Fail("t1122 gate stub: policy.cpp no longer builds the assault gate with Test8Patch's stub (16 cells at 0x400)");
        }
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        if (t65.find("AssaultTownPlayerTest                          code 00290484 00290484 4883B850020000000F8426010000488B") == std::string::npos
            || t68.find("AssaultTownPlayerTest                          code 002904C4 002904C4 4883B850020000000F8426010000488B") == std::string::npos)
            Fail("t1122 gate: the AssaultTownPlayerTest rows on both builds");
        const std::string sig = T1240NoCr(T313ReadFile("../coop-plugin/addresses/signatures.sig"));
        if (sig.find("\nAssaultTownPlayerTest ") == std::string::npos) Fail("t1122 gate: the signatures lack AssaultTownPlayerTest");
    }
    {   /* the rule is team.cpp's: TeamSameAnyThread unchanged */
        const std::string tm = T1240NoCr(T313ReadFile("../coop-plugin/team.cpp"));
        if (tm.find("    if (a < 0 || b < 0 || a == b) return false;\n    const unsigned ta = TeamNoOfSlotAnyThread(a);\n    return ta != 0 && ta == TeamNoOfSlotAnyThread(b);") == std::string::npos)
            Fail("t1122 near: team.cpp TeamSameAnyThread changed - RaidNearSameTeam must follow it");
    }
    {   /* the rows, both builds, and their signatures; the P247-only rows are gone */
        const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
        const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
        const char* const r65[4] = { "TaskMakeAnnouncement_ownerNear                 code 00354930 00354930 4C8BDC574881ECC000000048C7442478",
                                     "Faction_findNear                               code 006BA4D0 006BA4D0 4C8BDC4154415541564883EC6048C744",
                                     "PassingByTownAssault_canStart                  code 00290410 00290410 40574883EC6048C7442430FEFFFFFF48",
                                     "PassingByTownAssault_fillTargets               code 00290080 00290080 488BC457415441554883EC6048C74424" };
        const char* const r68[4] = { "TaskMakeAnnouncement_ownerNear                 code 00354990 00354990 4C8BDC574881ECC000000048C7442478",
                                     "Faction_findNear                               code 006BA820 006BA820 4C8BDC4154415541564883EC6048C744",
                                     "PassingByTownAssault_canStart                  code 00290450 00290450 40574883EC6048C7442430FEFFFFFF48",
                                     "PassingByTownAssault_fillTargets               code 002900C0 002900C0 488BC457415441554883EC6048C74424" };
        const char* const names[4] = { "TaskMakeAnnouncement_ownerNear", "Faction_findNear", "PassingByTownAssault_canStart", "PassingByTownAssault_fillTargets" };
        const std::string sig = T1240NoCr(T313ReadFile("../coop-plugin/addresses/signatures.sig"));
        for (int k = 0; k < 4; ++k)
        {
            if (t65.find(r65[k]) == std::string::npos) Fail(std::string("t1122 near: the 1.0.65 table lacks ") + names[k]);
            if (t68.find(r68[k]) == std::string::npos) Fail(std::string("t1122 near: the 1.0.68 table lacks ") + names[k]);
            if (sig.find(std::string("\n") + names[k] + " ") == std::string::npos) Fail(std::string("t1122 near: the signatures lack ") + names[k]);
        }
        const char* const gone[2] = { "TaskMakeAnnouncement_update ", "Dialogue_startAnnouncement " };
        for (int k = 0; k < 2; ++k)
            if (t65.find(gone[k]) != std::string::npos || t68.find(gone[k]) != std::string::npos || sig.find(std::string("\n") + gone[k]) != std::string::npos)
                Fail(std::string("t1122 near: probe P247's row is still listed: ") + gone[k]);
    }
    {   /* the wiring */
        const std::string pol = T1240NoCr(T313ReadFile("../coop-plugin/policy.cpp"));
        if (pol.find("AddrReg kRaidOwnerNearRva_reg(\"TaskMakeAnnouncement_ownerNear\", &kRaidOwnerNearRva)") == std::string::npos
            || pol.find("AddrReg kRaidFindNearRva_reg(\"Faction_findNear\", &kRaidFindNearRva)") == std::string::npos
            || pol.find("AddrReg kRaidAssaultStartRva_reg(\"PassingByTownAssault_canStart\", &kRaidAssaultStartRva)") == std::string::npos
            || pol.find("AddrReg kRaidAssaultTargetsRva_reg(\"PassingByTownAssault_fillTargets\", &kRaidAssaultTargetsRva)") == std::string::npos)
            Fail("t1122 near: policy.cpp does not bind the four rows");
        if (pol.find("const unsigned long long kRaidSiteLen[4] = { 0, 399, 450, 470 };") == std::string::npos) Fail("t1122 near: the sites' function lengths");
        const char* const heads[3] = { "bool detour_RaidOwnerNear(void* task, void* obj, void* speaker, unsigned long long a4)\n{",
                                       "unsigned long long detour_RaidAssaultStart(void* package, unsigned long long a2, unsigned long long a3, unsigned long long a4)\n{",
                                       "unsigned long long detour_RaidAssaultTargets(void* package, unsigned long long a2, unsigned long long a3, unsigned long long a4)\n{" };
        const char* const marks[3] = { "::TlsSetValue(g_raidNearTls, (LPVOID)(uintptr_t)teamstub::kRaidSiteAnnounce);",
                                       "::TlsSetValue(g_raidNearTls, (LPVOID)(uintptr_t)teamstub::kRaidSiteAssaultStart);",
                                       "::TlsSetValue(g_raidNearTls, (LPVOID)(uintptr_t)teamstub::kRaidSiteAssaultTargets);" };
        for (int k = 0; k < 3; ++k)
        {
            const size_t o = pol.find(heads[k]);
            const size_t oEnd = (o == std::string::npos) ? o : pol.find("\n}\n", o);
            if (o == std::string::npos || oEnd == std::string::npos) { Fail(std::string("t1122 near: no site detour ") + teamstub::RaidSiteName(k + 1)); continue; }
            const std::string b = pol.substr(o, oEnd - o);
            if (b.find(marks[k]) == std::string::npos || b.find("__finally { ::TlsSetValue(g_raidNearTls, prev); }") == std::string::npos)
                Fail(std::string("t1122 near: the site does not mark its thread and put the mark back: ") + teamstub::RaidSiteName(k + 1));
        }
        const size_t f = pol.find("void detour_RaidFindNear(void* faction, void* list, void* centre, float radius, unsigned char flag)\n{");
        const size_t fEnd = (f == std::string::npos) ? f : pol.find("\n}\n", f);
        if (f == std::string::npos || fEnd == std::string::npos) Fail("t1122 near: no find-near detour");
        else
        {
            const std::string b = pol.substr(f, fEnd - f);
            const size_t a = b.find("orig_RaidFindNear(faction, list, centre, radius, flag);"), m = b.find("::TlsGetValue(g_raidNearTls)");
            if (a == std::string::npos || m == std::string::npos || m < a) Fail("t1122 near: the engine's search does not run first, as is");
            if (b.find("teamstub::RaidNearCallInside(ret, (unsigned long long)g_raidSiteAt[site], kRaidSiteLen[site])") == std::string::npos) Fail("t1122 near: a call not the site's own is widened");
            if (b.find("::TlsSetValue(g_raidNearTls, (LPVOID)0);") == std::string::npos) Fail("t1122 near: more than the site's one search is widened");
            if (b.find("teamstub::RaidNearWiden(site, ") == std::string::npos) Fail("t1122 near: the find-near does not use the pure answer");
        }
        const size_t t = pol.find("void RaidNearTeam(int site, void* owner, void* list, void* centre, float radius, unsigned char flag, int before)\n{");
        const size_t tEnd = (t == std::string::npos) ? t : pol.find("\n}\n", t);
        if (t == std::string::npos || tEnd == std::string::npos) Fail("t1122 near: no teammate search");
        else
        {
            const std::string b = pol.substr(t, tEnd - t);
            if (b.find("teamstub::RaidNearPick(ownerSlot, ownerTeam, slot, team, n, pick, kCand)") == std::string::npos) Fail("t1122 near: the teammates are not picked by the pure rule");
            if (b.find("StandInSlotAnyPod(owner)") == std::string::npos || b.find("g_kitMineAny") == std::string::npos || b.find("g_kitFac[k]") == std::string::npos)
                Fail("t1122 near: the owner's slot or the candidates are not the kit's");
            if (b.find("if (RaidFindNearPod(cand[k], list, centre, radius, flag) != 1) { ::InterlockedIncrement64(&g_raidNearFaults); faulted = 1; break; }") == std::string::npos
                || pol.find("    __try { orig_RaidFindNear(faction, list, centre, radius, flag); return 1; }\n    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }") == std::string::npos)
                Fail("t1122 near: the teammate's search is not the same search, fault-guarded (a fault stops the repeats)");
            if (b.find("teamstub::RaidNearStopAtFirst(site)") == std::string::npos) Fail("t1122 near: the stop rule is not the pure one");
        }
        if (pol.find("if (g_kitN != 0 || g_kitLike != 0 || g_kitMineAny != 0) KitBuild(false);") == std::string::npos || pol.find("    g_kitMineAny = mineAny;\n") == std::string::npos)
            Fail("t1122 near: the own-faction pointer is not cleared with the kit table");
        if (pol.find("    RaidNearLook();") == std::string::npos || pol.find("\"[RAIDCAMP] team near site=\"") == std::string::npos) Fail("t1122 near: no [RAIDCAMP] line printed");
        if (pol.find("raidTeamNear[site:hooked,tests,engineFound,teamFound,teamNone]=") == std::string::npos
            || pol.find("raidTeamNearOther[findNearHooked,faults,outside]=") == std::string::npos)
            Fail("t1122 near: the report line has no raidTeamNear counters");
        /* the assault-start test's player-town gate: the stub on its own 10 bytes, the cells the teammates' */
        if (pol.find("AddrReg kAssaultTownTestRva_reg(\"AssaultTownPlayerTest\", &kAssaultTownTestRva)") == std::string::npos
            || pol.find("Test8Patch(g_base + (uintptr_t)kAssaultTownTestRva, kAssaultTownTestOrig, g_assaultCells, g_assaultWhy)") == std::string::npos)
            Fail("t1122 gate: policy.cpp does not bind and patch the assault gate with its own bytes");
        const size_t tf = pol.find("void PolicyTeammateFactions(void* const* facs, int n)");
        const size_t aw = pol.find("g_assaultHeld = MateCellsWrite(g_assaultCells, facs, n)");
        if (tf == std::string::npos || aw == std::string::npos || aw < tf) Fail("t1122 gate: the gate's cells are not written from the teammates' list");
        if (pol.find("assaultGateTeam[patched,cellsHeld,opened]=") == std::string::npos || pol.find("\"[RAIDCAMP] assault gate: ") == std::string::npos)
            Fail("t1122 gate: no report counter or line for the assault gate");
        const std::string st = T313ReadFile("../coop-plugin/store.cpp");
        if (st.find("PROBE-START: P247") != std::string::npos || st.find("PROBE-START: P245") != std::string::npos
            || st.find("PROBE-START: P244") != std::string::npos || st.find("PROBE-START: P239") != std::string::npos)
            Fail("t1122 near: a removed probe (P239 / P244 / P245 / P247) is still in store.cpp");
    }
}
/* T-1240 (T2039 LEG F): the dead-handle gate's own-rows answer - a house owner whose store had no record yet (a load's overlay or a
   reset world's import, both "no-record") takes a handed piece in its first session; rows read as before; every other refusal holds */
void t_t1240_handed_rows()
{
    if (coopbuild::BuildHandedRowsState(1, 0, 0) != -1 || coopbuild::BuildHandedRowsState(1, 1, 1) != -1) Fail("t1240 f: answered before the restore edge ran");
    if (coopbuild::BuildHandedRowsState(0, 1, 0) != 1) Fail("t1240 f: own rows read did not answer 1");
    if (coopbuild::BuildHandedRowsState(0, 0, 1) != 1) Fail("t1240 f: an empty store (no-record: overlay or import) did not answer 1");
    if (coopbuild::BuildHandedRowsState(0, 0, 0) != 0) Fail("t1240 f: rows not read and a record present answered other than 0");
    /* through the gate: the T2039 case (B's first session, empty store) now takes the rule; identity / single / claim-busy keep the hold */
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, coopbuild::BuildHandedRowsState(0, 0, 1), 0, 0) != 1) Fail("t1240 f: the empty-store owner still held the handed piece");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, coopbuild::BuildHandedRowsState(0, 0, 0), 0, 0) != 0) Fail("t1240 f: a refused load took the rule");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 0, coopbuild::BuildHandedRowsState(0, 0, 1), 0, 0) != 0) Fail("t1240 f: a true restore took the rule at an empty store");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, coopbuild::BuildHandedRowsState(0, 0, 1), 0, 1) != 0) Fail("t1240 f: a piece made here took the rule at an empty store");
    /* the store's own reason: the same word the edge reports, final, used by both whole-load arms and read by the accessor */
    if (std::string(coopown::kRsWhyAllNoRecord) != coopown::RestoreWhyName(coopown::kRsAbsent) || !coopown::RestoreRefusalFinal(coopown::kRsWhyAllNoRecord))
        Fail("t1240 f: the no-record word");
    const std::string st = T1240NoCr(T313ReadFile("../coop-plugin/store.cpp"));
    size_t n = 0;
    for (size_t at = st.find("OwnRestoreArmAll(coopown::kRsWhyAllNoRecord);"); at != std::string::npos; at = st.find("OwnRestoreArmAll(coopown::kRsWhyAllNoRecord);", at + 1)) ++n;
    if (n != 2 || st.find("OwnRestoreArmAll(\"no-record\")") != std::string::npos
        || st.find("int StoreOwnRestoreNoRecord() { return g_ownRsWhyAll == coopown::kRsWhyAllNoRecord ? 1 : 0; }") == std::string::npos
        || st.find("g_ownBuildRowsRead = (g_ownRsWhyAll.empty() && g_ownBuildRowsArmed != 0) ? 1 : 0;") == std::string::npos)
        Fail("t1240 f: the store's no-record arms (overlay and import) or its accessor");
    const std::string b = T1240NoCr(T313ReadFile("../coop-plugin/build.cpp"));
    if (b.find("return coopbuild::BuildHandedRowsState(StoreOwnRestorePending() ? 1 : 0, StoreOwnBuildRowsRead(), StoreOwnRestoreNoRecord());") == std::string::npos
        || b.find("const int rowsRead = (fresh != 0) ? (PcaOwnRowsState() > 0 ? 1 : 0) : 1;") == std::string::npos
        || b.find("BdCursorHouseLine(pos, r);") == std::string::npos
        || b.find("[BUILD] cursor house test at (%.1f,%.1f)") == std::string::npos)
        Fail("t1240 f: the wiring in build.cpp (the gate's answer, the make road unchanged, the cursor house line)");
}
/* T-1240: a restore takes the dead-handle rule only for a handed piece never made here; a true restore keeps the hold */
void t_t1240_handed_restore()
{
    if (coopbuild::BuildDeadHandlesEntryOk(0, 0, -1, 1, 1) != 1) Fail("t1240 b: a copy lost the dead-handle rule");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, 1, 0, 0) != 1) Fail("t1240 b: a handed piece never made here stayed held");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 0, 1, 0, 0) != 0) Fail("t1240 b: a true restore (own pp.build row) took the rule");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, 0, 0, 0) != 0 || coopbuild::BuildDeadHandlesEntryOk(1, 1, -1, 0, 0) != 0)
        Fail("t1240 b: the rule ran before this load's own rows were read");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, 1, 1, 0) != 0) Fail("t1240 b: a key with an own pp.build row took the rule");
    if (coopbuild::BuildDeadHandlesEntryOk(1, 1, 1, 0, 1) != 0) Fail("t1240 b: a key this game placed took the rule");
    const std::string b = T1240NoCr(T313ReadFile("../coop-plugin/build.cpp"));
    if (b.find("&& coopbuild::BuildDeadHandlesEntryOk(p.restore, p.recMake, (p.restore != 0) ? PcaHandedRowsState() : 1, g_pcaOwnRowKeys.count(m.key) != 0 ? 1 : 0,") == std::string::npos
        || b.find("g_pcaOwnRowKeys.insert(rows[i].key);") == std::string::npos || b.find("g_pcaOwnRowKeys.clear();") == std::string::npos
        || b.find("p.restore == 0 && lv == kObjKeyTruncated") != std::string::npos || b.find("restore of a handed piece (never made here)") == std::string::npos)
        Fail("t1240 b: the wiring in build.cpp");
}
/* T-1241 (decision 1487 a): the box hover cursor the `cursortest hover` lever reports - PlayerInterface::buildingSelected's hover
   order (swaccess::BoxHoverCursor) and the mod's ownership answer at the hover's sites (swaccess::HoverOwned), plus the wiring: the
   lever only reads, and the mirror keeps the hook's steps */
void t_t1241_hover_cursor()
{
    using namespace swaccess;
    /* a finished chest with items: a box by kind 9 */
    HoverTerms t = { 0, 1, 0, 1, 0, 0, 0, 9, 1, 2, 0 };
    if (BoxHoverCursor(t) != kHoverSteal) Fail("t1241 hover: a stranger's stocked chest shows the stealing cursor 0x18");
    t.owned = 1;
    if (BoxHoverCursor(t) != kHoverOpen) Fail("t1241 hover: an owned chest shows the open cursor 2");
    t.owned = 0; t.factionFree = 1;
    if (BoxHoverCursor(t) != kHoverOpen) Fail("t1241 hover: a chest of a faction marked free (+0x1D0) shows the open cursor");
    t.factionFree = 0; t.invCount = 0;
    if (BoxHoverCursor(t) != kHoverNoCursor) Fail("t1241 hover: an EMPTY chest not owned sets no cursor (the plain pointer)");
    t.owned = 1;
    if (BoxHoverCursor(t) != kHoverOpen) Fail("t1241 hover: an empty owned chest still shows the open cursor");
    t.owned = 0; t.invCount = 2; t.haveInv = 0;
    if (BoxHoverCursor(t) != kHoverNoCursor) Fail("t1241 hover: a box with no inventory sets no cursor");
    t.haveInv = 1;
    /* the order before the box test */
    HoverTerms u = t; u.selectable = 0;
    if (BoxHoverCursor(u) != kHoverNoCursor) Fail("t1241 hover: neither owned nor selectable - the hover gives up");
    u.owned = 1;
    if (BoxHoverCursor(u) != kHoverOpen) Fail("t1241 hover: owned skips the selectable test");
    u = t; u.busy = 1;
    if (BoxHoverCursor(u) != kHoverNoCursor) Fail("t1241 hover: the interface's busy byte sets no cursor");
    u = t; u.built = 0;
    if (BoxHoverCursor(u) != kHoverUnbuilt) Fail("t1241 hover: an unfinished building shows 0xB");
    u = t; u.inUse = 1;
    if (BoxHoverCursor(u) != kHoverInUse) Fail("t1241 hover: a building in use shows 0x13");
    u = t; u.seat = 1;
    if (BoxHoverCursor(u) != kHoverSeatRoad) Fail("t1241 hover: a seat takes the furniture road, not read");
    u = t; u.kind = 3;
    if (BoxHoverCursor(u) != kHoverOwnGetter) Fail("t1241 hover: a building that is no box takes its own getMouseCursor, not read");
    u.fnType = 0x12;
    if (BoxHoverCursor(u) != kHoverSteal) Fail("t1241 hover: function type 0x12 is a box");
    if (!HoverIsBox(0, 0xC) || !HoverIsBox(0, 7) || HoverIsBox(0, 8)) Fail("t1241 hover: the box kinds are 0xC, 9 and 7");
    if (std::string(HoverCursorMeaning(kHoverSteal)) != "steal" || std::string(HoverCursorMeaning(kHoverOpen)) != "open"
        || std::string(HoverCursorMeaning(kHoverNoCursor)) != "plain" || std::string(HoverCursorMeaning(0x55)) != "other")
        Fail("t1241 hover: the cursor names");
    /* the mod's answer at the hover's sites */
    if (HoverOwned(1, 0, false, false, false, false, false) != 1) Fail("t1241 owned: the engine's own answer is kept");
    if (HoverOwned(0, 1, false, false, false, false, false) != 1) Fail("t1241 owned: a world node is answered as ours");
    if (HoverOwned(0, 0, false, false, false, true, true) != 0) Fail("t1241 owned: no team and not shared - the engine's answer");
    if (HoverOwned(0, 0, false, true, true, true, false) != 1) Fail("t1241 owned: a teammate's building of any class is ours");
    if (HoverOwned(0, 0, true, true, true, true, false) != 1) Fail("t1241 owned: a teammate's building under shared is ours");
    if (HoverOwned(0, 0, true, false, false, true, true) != 1) Fail("t1241 owned: under shared a stranger's StorageBuilding is answered as ours");
    if (HoverOwned(0, 0, true, false, false, true, false) != 0) Fail("t1241 owned: under shared a stranger's plain Building keeps the engine's answer");
    if (HoverOwned(0, 0, false, true, false, true, true) != 0) Fail("t1241 owned: a stranger's box outside shared keeps the engine's answer");
    if (HoverOwned(0, 0, true, false, false, false, true) != 0) Fail("t1241 owned: an NPC's box (no stand-in) keeps the engine's answer");
    /* wiring: the hook still takes the steps HoverOwned mirrors, in that order */
    const std::string p = T313ReadFile("../coop-plugin/policy.cpp");
    const size_t d = p.find("char detour_OwnedByAPlayerFaction(void* building)");
    const size_t s1 = d == std::string::npos ? d : p.find("if (a != 0) return a;", d);
    const size_t s2 = s1 == std::string::npos ? s1 : p.find("swaccess::NodeClickOpens(a, clickGate || clickHandler,", s1);
    const size_t s3 = s2 == std::string::npos ? s2 : p.find("if (!inTeam && !shared) return a;", s2);
    const size_t s4 = s3 == std::string::npos ? s3 : p.find("if (!member && (!standIn || !shared)) return a;", s3);
    const size_t s5 = s4 == std::string::npos ? s4 : p.find("if (member) { ::InterlockedIncrement64(&g_memberClick); return 1; }", s4);
    const size_t s6 = s5 == std::string::npos ? s5 : p.find("if (vt != kVtStorageBuilding) { ::InterlockedIncrement64(&g_ownedByPeerStranger);", s5);
    if (s6 == std::string::npos) Fail("t1241 wiring: detour_OwnedByAPlayerFaction no longer takes the steps swaccess::HoverOwned mirrors - update both");
    /* wiring: the lever's reads are made in the hover's order, and it never calls the hover or a click, moves a counter or writes */
    const size_t r = p.find("bool PolicyBoxHoverRead(void* building, std::string* text)");
    const size_t pod = p.find("int HoverReadPod(void* b, void* pi, HoverReads* r)");
    const size_t podEnd = pod == std::string::npos ? pod : p.find("__except (EXCEPTION_EXECUTE_HANDLER) { return 0; }", pod);
    const size_t rEnd = r == std::string::npos ? r : p.find("    return true;", r);
    if (r == std::string::npos || pod == std::string::npos || podEnd == std::string::npos || rEnd == std::string::npos) Fail("t1241 wiring: the hover reader is missing");
    else
    {
        const std::string body = p.substr(pod, podEnd - pod) + p.substr(r, rEnd - r);
        if (body.find("kBuildingSelectedRva") != std::string::npos || body.find("ClickPod(") != std::string::npos || body.find("Interlocked") != std::string::npos)
            Fail("t1241 wiring: the hover reader calls the hover or a click, or moves a counter");
        if (body.find("swaccess::HoverOwned(r.engineOwned, node, shared, inTeam, member, standIn, vt != 0 && vt == kVtStorageBuilding)") == std::string::npos
            || body.find("orig_OwnedByAPlayerFaction(b)") == std::string::npos)
            Fail("t1241 wiring: the reader answers ownership as the hook does, from the engine's own answer");
        const char* order[] = { "vt[0x58 / 8])(b)", "vt[0x108 / 8])(b)", "kPiBusyByte", "vt[0x228 / 8])(b)", "vt[0x308 / 8])(b)", "kBldSeatByte",
                                "vt[0x2F0 / 8])(b)", "vt[0x358 / 8])(b)", "vt[0x160 / 8])(b)", "kFacFreeByte) != 0" };
        size_t at = 0;
        for (int k = 0; k < 10; ++k)
        {
            const size_t f = body.find(order[k], at);
            if (f == std::string::npos) { Fail(std::string("t1241 wiring: the hover read is out of order or missing at ") + order[k]); break; }
            at = f;
        }
    }
    const std::string it = T313ReadFile("../coop-plugin/items.cpp");
    if (it.find("if (!PolicyBoxHoverRead(b, &text)) return \"error cursortest hover box '\"") == std::string::npos
        || it.find("v == \"square\" || v == \"hover\") && tok.size() >= 2)") == std::string::npos)
        Fail("t1241 wiring: `cursortest hover` resolves its box as open does (placed / copyof:) and reads it through PolicyBoxHoverRead");
    /* T-1241 (run T2045 VACUOUS): the getter road - a player-built chest is a UseableStuff (fnType 0xD, kind 2), no box by the hover's
       tests, so its cursor is UseableStuff::getMouseCursor's answer, which reads the owner itself, remapped as detour_UseableCursor */
    if (UseableCursorMod(kHoverSteal, 0, true, true, false) != kHoverOwnUse) Fail("t1241 getter: a teammate's UseableStuff chest (loot) shows this player's own cursor 9");
    if (UseableCursorMod(kHoverPickLock, 0, true, false, false) != kHoverOwnUse) Fail("t1241 getter: a teammate's locked chest shows 9");
    if (UseableCursorMod(kHoverSteal, 0, false, true, false) != kHoverSteal) Fail("t1241 getter: a stranger's UseableStuff chest under shared keeps loot 0x18");
    if (UseableCursorMod(kHoverSteal, 0, false, true, true) != kHoverOwnUse) Fail("t1241 getter: a stranger's StorageBuilding under shared shows 9");
    if (UseableCursorMod(kHoverSteal, 0, false, false, true) != kHoverSteal) Fail("t1241 getter: an NPC's chest keeps loot 0x18");
    if (UseableCursorMod(kHoverSteal, 1, false, false, false) != kHoverOwnUse) Fail("t1241 getter: a world resource node shows 9");
    if (UseableCursorMod(kHoverTypeEight, 1, true, true, true) != kHoverTypeEight) Fail("t1241 getter: a type-8 answer 0xD is never remapped");
    if (UseableCursorMod(kHoverOwnUse, 0, false, false, false) != kHoverOwnUse || UseableCursorMod(0, 0, true, true, true) != 0)
        Fail("t1241 getter: answers other than 0xF / 0x18 / 0xD are kept");
    /* T-1241 (run T2056 PARTIAL): the cursor asks the take's question - an allowed friend's chest shows the teammate's cursor exactly
       where the take is no theft (ClearsStealing(PairClass(kOwn, who))), with the who from the same Classify */
    for (int pol = kPolicyUnknown; pol <= kPolicyLocked; ++pol)
    {
        const int fr = Classify(false, true, false, true, pol), st = Classify(false, true, false, false, pol);
        const int mate = Classify(false, true, true, true, pol), npc = Classify(false, false, false, false, pol);
        const bool shared = pol == kPolicyShared;
        if (UseableCursorMod(kHoverSteal, 0, CursorLikeOwn(false, fr), true, false) != (shared ? kHoverOwnUse : kHoverSteal))
            Fail("t1241 friend cursor: a friend's UseableStuff chest shows 9 under shared only, else loot 0x18, option " + I(pol));
        if (CursorLikeOwn(false, fr) != ClearsStealing(PairClass(kOwn, fr)) || CursorLikeOwn(false, st) != ClearsStealing(PairClass(kOwn, st))
            || CursorLikeOwn(false, mate) != ClearsStealing(PairClass(kOwn, mate)) || CursorLikeOwn(false, npc) != ClearsStealing(PairClass(kOwn, npc)))
            Fail("t1241 friend cursor: the cursor's like-own answer is not the take's stealing answer, option " + I(pol));
        if (UseableCursorMod(kHoverSteal, 0, CursorLikeOwn(false, st), true, false) != kHoverSteal)
            Fail("t1241 friend cursor: a stranger's UseableStuff chest keeps loot 0x18, option " + I(pol));
        if (UseableCursorMod(kHoverSteal, 0, CursorLikeOwn(false, npc), false, false) != kHoverSteal)
            Fail("t1241 friend cursor: an NPC's chest keeps loot 0x18, option " + I(pol));
        if (UseableCursorMod(kHoverSteal, 0, CursorLikeOwn(true, kNotPlayer), true, false) != kHoverOwnUse)
            Fail("t1241 friend cursor: a teammate by the team table shows 9 before the kit table is written, option " + I(pol));
        if (UseableCursorMod(kHoverTypeEight, 0, CursorLikeOwn(false, fr), true, false) != kHoverTypeEight)
            Fail("t1241 friend cursor: a type-8 answer 0xD stays for a friend, option " + I(pol));
    }
    if (CursorLikeOwn(false, kFriendRefused) || CursorLikeOwn(false, kStranger) || CursorLikeOwn(false, kOwn) || !CursorLikeOwn(false, kFriendAllowed)
        || !CursorLikeOwn(false, kTeam))
        Fail("t1241 friend cursor: like-own = a teammate or an allowed friend only");
    if (GetterRoadCursor(0, 0xD, 1, kHoverSteal) != kHoverSteal) Fail("t1241 getter road: a UseableStuff chest takes its getter's answer");
    if (GetterRoadCursor(1, 0xD, 1, kHoverSteal) != kHoverCharacterRoad) Fail("t1241 getter road: +0x300's character road is not read");
    if (GetterRoadCursor(0, 8, 1, kHoverSteal) != kHoverCageRoad) Fail("t1241 getter road: a cage (type 8) is not read");
    if (GetterRoadCursor(0, 0xD, 0, kHoverSteal) != kHoverOwnGetter) Fail("t1241 getter road: another class's getter is not called");
    if (std::string(HoverCursorMeaning(kHoverOwnUse)) != "own-use" || std::string(HoverCursorMeaning(kHoverPickLock)) != "pick-lock"
        || std::string(HoverCursorMeaning(kHoverCharacterRoad)) != "character-road-not-read")
        Fail("t1241 getter: the cursor names");
    {
        const size_t u = p.find("unsigned int detour_UseableCursor(void* self)");
        const size_t g1 = u == std::string::npos ? u : p.find("if (a != kCursorPickLock && a != kCursorLoot && a != kCursorTypeEightNoContainer) return a;", u);
        const size_t g2 = g1 == std::string::npos ? g1 : p.find("if (swaccess::NodeClickOpens(0, a != kCursorTypeEightNoContainer,", g1);
        const size_t g3a = g2 == std::string::npos ? g2 : p.find("const bool mate = CursorTeammateObject(self);", g2);
        const size_t g3 = g3a == std::string::npos ? g3a : p.find("const bool member = swaccess::CursorLikeOwn(mate, mate ? (int)swaccess::kTeam : coop::PolicyKitClassOf(FactionOfBuildingPod(self)));", g3a);
        const size_t g4 = g3 == std::string::npos ? g3 : p.find("if (!member && !CursorIsPeerObject(self)) return a;", g3);
        const size_t g5 = g4 == std::string::npos ? g4 : p.find("if (vt != kVtStorageBuilding) { ::InterlockedIncrement64(&g_cursorStranger);", g4);
        const size_t g6 = g5 == std::string::npos ? g5 : p.find("if (a == kCursorTypeEightNoContainer)", g5);
        const size_t g7 = g6 == std::string::npos ? g6 : p.find("return kCursorOwnUse;", g6);
        if (g7 == std::string::npos) Fail("t1241 wiring: detour_UseableCursor no longer takes the steps swaccess::UseableCursorMod mirrors - update both");
        const size_t gpod = p.find("int HoverReadPod(void* b, void* pi, HoverReads* r)");
        const size_t gpodEnd = gpod == std::string::npos ? gpod : p.find("__except (EXCEPTION_EXECUTE_HANDLER) { return 0; }", gpod);
        const size_t gr = p.find("bool PolicyBoxHoverRead(void* building, std::string* text)");
        const size_t grEnd = gr == std::string::npos ? gr : p.find("    return true;", gr);
        if (gpodEnd == std::string::npos || grEnd == std::string::npos) Fail("t1241 wiring: the getter-road reader is missing");
        else
        {
            const std::string pb = p.substr(gpod, gpodEnd - gpod), rb = p.substr(gr, grEnd - gr);
            const char* order[] = { "if (!swaccess::HoverIsBox(r->fnType, r->kind))", "vt[0x300 / 8])(b)", "vt[0x410 / 8]", "dest == g_base + (uintptr_t)kUseableCursorRva",
                                    "kFacPlayerInterface) != 0", "vt[0x408 / 8])(b)", "orig_UseableCursor(b)" };
            size_t at = 0;
            for (int k = 0; k < 7; ++k)
            {
                const size_t f = pb.find(order[k], at);
                if (f == std::string::npos) { Fail(std::string("t1241 wiring: the getter road's read is out of order or missing at ") + order[k]); break; }
                at = f;
            }
            /* the verdict is the live hook's answer (the real hover's road, counters and all); the mirror stays as a cross-check */
            if (pb.find("r->liveGetter = (int)detour_UseableCursor(b)") == std::string::npos
                || rb.find("? r.liveGetter : mirrorGetter") == std::string::npos || rb.find("MIRROR-MISMATCH") == std::string::npos)
                Fail("t1241 wiring: the reader takes its verdict from the live cursor hook and prints the mirror's disagreement");
            if (rb.find("? swaccess::UseableCursorMod(r.engineGetter, gNode, likeOwn, shared && standIn, vt != 0 && vt == kVtStorageBuilding)") == std::string::npos
                || rb.find("const bool likeOwn = swaccess::CursorLikeOwn(member, ownerWho);") == std::string::npos
                || rb.find("const int ownerWho = PolicyKitClassOf(r.fac);") == std::string::npos
                || rb.find("swaccess::GetterRoadCursor(r.character, r.fnType, r.useableGetter, modGetter)") == std::string::npos
                || rb.find("if (cursor == swaccess::kHoverOwnGetter && r.getterRoad != 0)") == std::string::npos)
                Fail("t1241 wiring: the getter road is answered as the cursor hook answers, only where the box road gave up");
        }
    }
}

/* T-1243 (owner 1518, 1520 d / e): a small area file in the engine's layout (src/common/dupsquad.h): two records - the second a
   building with one long string - and the zone file's closing list. *valueAt: the byte where the long string's length is. */
void T1243I(std::vector<char>* b, int v) { char t[4]; std::memcpy(t, &v, 4); b->insert(b->end(), t, t + 4); }
void T1243S(std::vector<char>* b, const std::string& s) { T1243I(b, (int)s.size()); b->insert(b->end(), s.begin(), s.end()); }
void T1243Rec(std::vector<char>* b, int type, const std::string& sid, const std::string& key, const std::string& val, size_t* valueAt)
{
    T1243I(b, 0); T1243I(b, type); T1243I(b, 7); T1243S(b, "name"); T1243S(b, sid); T1243I(b, 0);   /* instances, type, id, name, record id, flag */
    T1243I(b, 0); T1243I(b, 0); T1243I(b, 0); T1243I(b, 0); T1243I(b, 0);   /* bools, floats, ints, vec3s, vec4s */
    if (key.empty()) T1243I(b, 0);
    else { T1243I(b, 1); T1243S(b, key); if (valueAt != 0) *valueAt = b->size(); T1243S(b, val); }   /* strings */
    T1243I(b, 0); T1243I(b, 0); T1243I(b, 0);   /* files, references, instances */
}
std::vector<char> T1243Area(size_t* valueAt)
{
    std::vector<char> b;
    T1243I(&b, 16); T1243I(&b, 2); T1243I(&b, 2);   /* version, last id, two records */
    T1243Rec(&b, 33, "1--INGAME", std::string(), std::string(), 0);
    T1243Rec(&b, 35, "2--INGAME", "description", std::string(3000, 'A'), valueAt);
    T1243I(&b, 2); T1243I(&b, 5); T1243I(&b, 6);   /* the zone file's closing list: a count and that many ints */
    return b;
}
/* T-1243: the reader's answer and where it stopped; the receipt decision; the start choice; the TEST-ONLY zonedamage lever */
void t_t1243_zonecheck()
{
    using namespace zonecheck;
    size_t valueAt = 0, stop = 99;
    const std::vector<char> good = T1243Area(&valueAt);
    if (valueAt == 0 || good.size() < valueAt + 1200) { Fail("t1243: the fixture is not built as meant"); return; }
    /* a whole area file reads to its end; the duplicate report's own ParseAll says the same */
    if (ReadableBytes(good, &stop) != 1 || stop != good.size()) Fail("t1243: a whole area file did not read to its end");
    {
        std::vector<dupsquad::Rec> recs;
        if (!dupsquad::ParseAll((const unsigned char*)&good[0], good.size(), &recs) || recs.size() != 2) Fail("t1243: ParseAll no longer reads the whole file");
        if (!dupsquad::ParseAllAt((const unsigned char*)&good[0], good.size(), &recs, 0)) Fail("t1243: ParseAllAt with no stop asked");
    }
    /* run T2079's damage: 1,180 zero bytes inside the building record - the long string's length reads 0, the rest reads as empty
       lists, and reading ends 20 bytes on with bytes left over */
    std::vector<char> bad(good);
    if (DamageApply(&bad, (long long)valueAt, 1180) != 1180) Fail("t1243: the damage did not set 1,180 bytes");
    stop = 0;
    if (ReadableBytes(bad, &stop) != 0) Fail("t1243: 1,180 zero bytes inside a building record read as whole");
    if (stop != valueAt + 20) Fail("t1243: the stop byte is not where reading ended (the length, three counts and the closing count)");
    {
        std::vector<dupsquad::Rec> recs;
        if (dupsquad::ParseAll((const unsigned char*)&bad[0], bad.size(), &recs)) Fail("t1243: ParseAll read the damaged file");
    }
    /* other damage: one byte short, one byte over, nothing at all, a zeroed head */
    stop = 0;
    if (Readable((const unsigned char*)&good[0], good.size() - 1, &stop) != 0) Fail("t1243: one byte short read as whole");
    {
        std::vector<char> over(good); over.push_back(0);
        stop = 0;
        if (ReadableBytes(over, &stop) != 0 || stop != good.size()) Fail("t1243: a byte left over read as whole, or its stop is not the first byte left over");
    }
    stop = 7;
    if (ReadableBytes(std::vector<char>(), &stop) != 0 || stop != 0) Fail("t1243: no bytes read as whole");
    if (Readable(0, 0, 0) != 0) Fail("t1243: a null buffer read as whole");
    { std::vector<char> head(good); DamageApply(&head, 0, 12); if (ReadableBytes(head, 0) != 0) Fail("t1243: a zeroed head read as whole"); }
    /* only area records are judged */
    if (IsAreaId("zone.18.35") != 1 || IsAreaId("zone.-1.4") != 1) Fail("t1243: an area record's id was not seen as one");
    if (IsAreaId("box.18.35.#1.2.3") != 0 || IsAreaId("zone.") != 0 || IsAreaId("Faction_1#4") != 0 || IsAreaId("ground.18.35") != 0) Fail("t1243: another record was seen as an area record");
    /* at receipt */
    const int badRead = ReadableBytes(bad, 0), goodRead = ReadableBytes(good, 0);
    if (ReceiptJudge(badRead) != kReceiptRefuseUnreadable) Fail("t1243: an unreadable area record was taken");
    if (ReceiptJudge(goodRead) != kReceiptTake) Fail("t1243: a whole area record was refused");
    /* at start */
    if (StartChoose(goodRead, 1, goodRead) != kStartCurrent || StartChoose(goodRead, 0, 0) != kStartCurrent) Fail("t1243: a whole current copy was not served");
    if (StartChoose(badRead, 1, goodRead) != kStartPrev) Fail("t1243: an unreadable current copy with a whole earlier one did not take the earlier one");
    if (StartChoose(badRead, 1, badRead) != kStartCurrentPrevUnreadable) Fail("t1243: both unreadable did not keep today's behaviour");
    if (StartChoose(badRead, 0, goodRead) != kStartCurrentNoPrev || StartChoose(badRead, 0, 0) != kStartCurrentNoPrev) Fail("t1243: an earlier copy whose index line does not validate was used");
    /* the TEST-ONLY lever: its arming */
    DamageArm a;
    if (a.when != kDamageNone || DamageTakes(a, kDamageBefore, "zone.18.35") != 0 || DamageTakes(a, kDamageAfter, "zone.18.35") != 0) Fail("t1243 lever: active without the command");
    if (ParseDamage("zone.18.35 before 100 1180", &a) != 1 || a.when != kDamageBefore || a.id != "zone.18.35" || a.offset != 100 || a.length != 1180) Fail("t1243 lever: the before form");
    if (ArmReply(a) != "ok zonedamage armed zone.18.35 before offset=100 length=1180") Fail("t1243 lever: the reply is " + ArmReply(a));
    if (DamageTakes(a, kDamageBefore, "zone.18.35") != 1) Fail("t1243 lever: the armed send was not taken");
    if (DamageTakes(a, kDamageAfter, "zone.18.35") != 0 || DamageTakes(a, kDamageBefore, "zone.18.36") != 0) Fail("t1243 lever: another stage or another record was taken");
    DamageArm b;
    if (ParseDamage("  zone.2.3   after 0 1  ", &b) != 1 || b.when != kDamageAfter || b.offset != 0 || b.length != 1) Fail("t1243 lever: the after form");
    if (ParseDamage("zone.1.2 before 1073741824 16777216", &b) != 1) Fail("t1243 lever: the largest offset and length");
    const char* refused[] = { "", "zone.1.2", "zone.1.2 before 0", "box.1.2.#3.4.5 before 0 1", "zone.1.2 during 0 1", "zone.1.2 BEFORE 0 1",
                              "zone.1.2 before -1 5", "zone.1.2 before +1 5", "zone.1.2 before 0x10 5", "zone.1.2 before 0 0", "zone.1.2 before 1073741825 1",
                              "zone.1.2 before 0 16777217", "zone.1.2 before 0 5 extra", "zone.1.2 before 1.5 5" };
    for (size_t k = 0; k < sizeof(refused) / sizeof(refused[0]); ++k)
    {
        DamageArm c;
        if (ParseDamage(refused[k], &c) != 0 || c.when != kDamageNone) Fail(std::string("t1243 lever: a malformed form was taken: '") + refused[k] + "'");
    }
    if (UsageReply().find("error zonedamage usage: ") != 0) Fail("t1243 lever: the usage reply");
    /* ... and its damage: cut at the end, nothing past it */
    std::vector<char> ten(10, 'x');
    if (DamageApply(&ten, 8, 5) != 2 || ten[7] != 'x' || ten[8] != 0 || ten[9] != 0) Fail("t1243 lever: the damage is not cut at the end");
    if (DamageApply(&ten, 10, 1) != 0 || DamageApply(&ten, -1, 4) != 0 || DamageApply(&ten, 0, 0) != 0 || DamageApply(0, 0, 4) != 0) Fail("t1243 lever: damage outside the bytes");
    if (ten[0] != 'x') Fail("t1243 lever: a refused damage changed a byte");
    if (std::string(WhenWord(kDamageBefore)) != "before" || std::string(WhenWord(kDamageAfter)) != "after") Fail("t1243 lever: the stage words");
    /* T-1243 (owner 1523): the lever's third stage, mirror (this game's mirror FILE at its next write of that area) */
    {
        DamageArm m;
        if (ParseDamage("zone.18.35 mirror 100 1180", &m) != 1 || m.when != kDamageMirror || m.id != "zone.18.35" || m.offset != 100 || m.length != 1180) Fail("t1243 lever: the mirror form");
        if (ArmReply(m) != "ok zonedamage armed zone.18.35 mirror offset=100 length=1180") Fail("t1243 lever: the mirror reply is " + ArmReply(m));
        if (DamageTakes(m, kDamageMirror, "zone.18.35") != 1 || DamageTakes(m, kDamageBefore, "zone.18.35") != 0 || DamageTakes(m, kDamageAfter, "zone.18.35") != 0
            || DamageTakes(m, kDamageMirror, "zone.18.36") != 0)
            Fail("t1243 lever: the mirror arming is taken at another stage or record, or not at its own");
        if (DamageTakes(a, kDamageMirror, "zone.18.35") != 0 || DamageTakes(b, kDamageMirror, "zone.1.2") != 0) Fail("t1243 lever: a before or after arming is taken at the mirror stage");
        if (std::string(WhenWord(kDamageMirror)) != "mirror") Fail("t1243 lever: the mirror stage word");
        const char* refusedM[] = { "zone.1.2 MIRROR 0 1", "zone.1.2 mirror 0 0", "box.1.2.#3.4.5 mirror 0 1", "zone.1.2 mirror 0", "zone.1.2 mirror 0 5 extra" };
        for (size_t k = 0; k < sizeof(refusedM) / sizeof(refusedM[0]); ++k)
        {
            DamageArm c;
            if (ParseDamage(refusedM[k], &c) != 0 || c.when != kDamageNone) Fail(std::string("t1243 lever: a malformed mirror form was taken: '") + refusedM[k] + "'");
        }
        if (UsageReply().find("before|after|mirror") == std::string::npos) Fail("t1243 lever: the usage reply does not name the mirror stage");
    }
    /* T-1243 (owner 1523): the name an unreadable kept area file is moved aside under - never an existing one */
    if (SetAsideName("m/zone.1.2.zone", 0, 1730000000LL) != "m/zone.1.2.zone.unreadable") Fail("t1243 set-aside: the first name");
    if (SetAsideName("m/zone.1.2.zone", 1, 1730000000LL) != "m/zone.1.2.zone.unreadable-1730000000") Fail("t1243 set-aside: the name when the first is taken");
}
/* T-1243 wiring (CRLF-safe): the world server's check sits in OnRecordFrom's area branch after the holder rule and before the
   not-newer test, the checksum and the write; a refusal names no player and answers AREA_FRESH; the start check runs before the
   promotion arm and never deletes; the game's check sits after the read-back and before the send; the lever's two stages */
size_t T1243Count(const std::string& s, const std::string& what)
{
    size_t n = 0;
    for (size_t at = s.find(what); at != std::string::npos; at = s.find(what, at + what.size())) ++n;
    return n;
}
void t_t1243_wiring()
{
    std::string sv = T313ReadFile("../coop-store/store_main.cpp");
    sv.erase(std::remove(sv.begin(), sv.end(), '\r'), sv.end());
    const size_t fn = sv.find("void OnRecordFrom(ENetHost* host, ENetPeer* from, unsigned connect, const std::string& fromName, const std::vector<char>& payload, const std::string& fromId)\n{");
    const size_t judge = fn == std::string::npos ? fn : sv.find("if (zonerec::ZoneJudgeTakes(zwhy) == 0) { ZoneRefuse(fromName, r.worldId, holderId, senderId); return; }", fn);
    const size_t check = fn == std::string::npos ? fn : sv.find("if (zonecheck::ReceiptJudge(zread) == zonecheck::kReceiptRefuseUnreadable) { ZoneUnreadableRefuse(from, connect, r.worldId, bytes.size(), zstop); return; }", fn);
    const size_t branchEnd = fn == std::string::npos ? fn : sv.find("else if (zwhy == zonerec::kZrAcceptNoHolder) ++g_zoneNoHolderTaken;", fn);
    const size_t notNewer = check == std::string::npos ? check : sv.find("Log(\"RECORD \" + SanitizeForLog(r.worldId) + \" not newer - ignored\"); return; }", check);
    const size_t crc = notNewer == std::string::npos ? notNewer : sv.find("r.len = (long long)bytes.size(); r.crc = coopstore::Crc32(&bytes[0], bytes.size());   /* P8b", notNewer);
    const size_t commit = crc == std::string::npos ? crc : sv.find("WriterQueueCommit(kFromSquad, r, &bytes, kRotateBoth, from, connect, r, fromName);", crc);
    if (fn == std::string::npos || judge == std::string::npos || check == std::string::npos || branchEnd == std::string::npos || notNewer == std::string::npos
        || crc == std::string::npos || commit == std::string::npos || !(fn < judge && judge < check && check < branchEnd && check < notNewer && notNewer < crc && crc < commit))
        Fail("t1243 wiring: the world server's check is not in OnRecordFrom's area branch after the holder rule and before the not-newer test, the checksum and the write");
    if (T1243Count(sv, "zonecheck::ReceiptJudge(") != 1) Fail("t1243 wiring: the receipt check is made other than once");
    {
        const size_t rf = sv.find("void ZoneUnreadableRefuse(ENetPeer* from, unsigned connect, const std::string& id, size_t bytes, size_t stop)\n{");
        const size_t re = rf == std::string::npos ? rf : sv.find("\n}\n", rf);
        const std::string body = (rf == std::string::npos || re == std::string::npos) ? std::string() : sv.substr(rf, re - rf);
        if (body.empty() || body.find("++g_zoneRefusedUnreadable;") == std::string::npos || body.find("AreaFreshRefused(id, slot, connect);") == std::string::npos
            || body.find("reading stopped at byte ") == std::string::npos || body.find("from slot ") == std::string::npos)
            Fail("t1243 wiring: a refused area record is not counted, logged with its stop byte and slot, or told to the waiting games");
        if (body.find("fromName") != std::string::npos || body.find("PeerName") != std::string::npos || body.find("PeerIdOf") != std::string::npos || body.find("Address") != std::string::npos)
            Fail("t1243 wiring: the refusal line names a player or an address");
    }
    {
        const size_t af = sv.find("void AreaFreshRefused(const std::string& id, int slot, unsigned connect)\n{");
        const size_t ae = af == std::string::npos ? af : sv.find("\n}\n", af);
        const std::string body = (af == std::string::npos || ae == std::string::npos) ? std::string() : sv.substr(af, ae - af);
        const size_t hold = body.find("if (slot < 0 || it->second.holder != slot || it->second.holderConnect != connect) return;");
        const size_t ans = body.find("AfAnswerRow(it, false, areafresh::kWhyServerWrite, 0);");
        if (body.empty() || ans == std::string::npos)
            Fail("t1243 wiring: the games waiting for the area are not told CANT at once");
        if (hold == std::string::npos || !(hold < ans))   /* T-1243 fold (finding 2) */
            Fail("t1243 wiring: a refused record answers the row without being the row holder's");
        if (T1243Count(sv, "AreaFreshRefused(") != 4)   /* T-1429 s2 fold 3: the stale-base refusal is its second call */ Fail("t1243 wiring: AreaFreshRefused is declared, defined or called other than once each");
    }
    {
        const size_t im = sv.find("bool IndexRecordFromMeta(const coopstore::MetaLine& m, bool isCurrentMeta, const std::string& sourceName)\n{");
        const size_t ch = im == std::string::npos ? im : sv.find("coopstore::Choice c = coopstore::ChooseVersion(ff);\n    const int zstart = ZoneStartCheck(r.worldId, ff, pr, &c);", im);
        const size_t arm = im == std::string::npos ? im : sv.find("else if (c.kind == coopstore::kChoosePrevMetaCurrent || c.kind == coopstore::kChoosePrevPair)", im);
        if (im == std::string::npos || ch == std::string::npos || arm == std::string::npos || !(ch < arm)) Fail("t1243 wiring: the start check does not run before the promotion arm");
        const size_t word = arm == std::string::npos ? arm : sv.find("(zstart == zonecheck::kStartPrev ? \"an area record that cannot be read to its end (set aside - T-1243)\"", arm);
        if (word == std::string::npos) Fail("t1243 wiring: the promotion line does not say the current area record cannot be read");   /* T-1243 fold (finding 4) */
        const size_t zs = sv.find("int ZoneStartCheck(const std::string& id, const coopstore::FolderFacts& ff, const RecordProbes& pr, coopstore::Choice* c)\n{");
        const size_t ze = zs == std::string::npos ? zs : sv.find("\n}\n", zs);
        const std::string body = (zs == std::string::npos || ze == std::string::npos) ? std::string() : sv.substr(zs, ze - zs);
        if (body.empty() || body.find("U8MoveFileEx(payloadPath.c_str(), aside.c_str(), MOVEFILE_WRITE_THROUGH)") == std::string::npos
            || body.find("c->kind = coopstore::kChoosePrevPair;") == std::string::npos || body.find("zonecheck::StartChoose(curOk, prevPair, prevOk)") == std::string::npos)
            Fail("t1243 wiring: the start check does not set the unreadable copy aside and promote the earlier one");
        if (body.find("DeleteFile") != std::string::npos || body.find("MOVEFILE_REPLACE_EXISTING") != std::string::npos || body.find("Recycle") != std::string::npos)
            Fail("t1243 wiring: the start check can delete or write over a file");
    }
    std::string st = T313ReadFile("../coop-plugin/store.cpp");
    st.erase(std::remove(st.begin(), st.end(), '\r'), st.end());
    {
        const size_t fn2 = st.find("void ZoneSaveApplyImpl(const std::string& path, const std::string& emptyId)\n{");   /* T-1329: one body for a file and an EMPTY area */
        const size_t rb = fn2 == std::string::npos ? fn2 : st.find("if (!ReadFileBytes(path, &bytes)) { ++g_zoneReadFail; ErrorLog(\"[ZONE] could not read back \" + path); return; }", fn2);
        const size_t dmg = fn2 == std::string::npos ? fn2 : st.find("ZoneDamageMaybe(zonecheck::kDamageBefore, zoneId, &bytes);", fn2);
        const size_t chk = fn2 == std::string::npos ? fn2 : st.find("if (zonecheck::ReadableBytes(bytes, &zstop) == 0)", fn2);
        const size_t send = fn2 == std::string::npos ? fn2 : st.find("if (ZoneMirrorWriteOrPark(kZoneWriteSave, r, bytes, isEmpty ? std::string(\"(EMPTY: Kenshi saved nothing for this area)\") : path) == 1)", fn2);
        if (fn2 == std::string::npos || rb == std::string::npos || dmg == std::string::npos || chk == std::string::npos || send == std::string::npos || !(rb < dmg && dmg < chk && chk < send))
            Fail("t1243 wiring: the game's check is not after the read-back (and the lever's before stage) and before the send");
        const size_t chkEnd = chk == std::string::npos ? chk : st.find("return;", chk);
        if (chkEnd == std::string::npos || chkEnd > send || st.substr(chk, chkEnd - chk).find("++g_zoneReadFail;") == std::string::npos)
            Fail("t1243 wiring: an unreadable area file is not counted in readFail (the eight exits' sum)");
        /* T-1243 fold (finding 1): the outage-journal road - checked after its read-back and before the journal write */
        const size_t qb = fn2 == std::string::npos ? fn2 : st.find("std::vector<char> qbytes;", fn2);
        const size_t qchk = qb == std::string::npos ? qb : st.find("if (zonecheck::ReadableBytes(qbytes, &zstop) == 0)", qb);
        const size_t qwr = qchk == std::string::npos ? qchk : st.find("else if (StoreQueueWriteImpl(coopqueue::kQueueFamilyZone, zoneId, qbytes, ZoneBaseOf(zoneId)) != 0) ++g_zoneQueuedNoNotebook;", qchk);
        if (qb == std::string::npos || qchk == std::string::npos || qwr == std::string::npos || !(qb < qchk && qchk < qwr && qwr < rb))
            Fail("t1243 wiring: the outage-journal road does not check the area file before journaling it");
        else
        {
            const std::string qbody = st.substr(qchk, qwr - qchk);
            if (qbody.find("++g_zoneQueueRefused;") == std::string::npos || qbody.find("++g_zoneUnreadableNotSent;") == std::string::npos || qbody.find("StoreQueueWriteImpl(") != std::string::npos)
                Fail("t1243 wiring: an unreadable area file on the journal road is journaled, or not counted in queueRefused and zoneUnreadableNotSent");
        }
    }
    {   /* T-1243 fold (finding 1): the replay of a journaled area file - checked before its send and its mirror write */
        const size_t qs = st.find("int QueueSendEntry(const coopqueue::QueueEntry& e)\n{");
        const size_t rchk = qs == std::string::npos ? qs : st.find("if (zonecheck::ReadableBytes(e.payload, &zstop) == 0)", qs);
        const size_t rsend = rchk == std::string::npos ? rchk : st.find("if (!SendRecordAny(e.key, \"\", \"\", 0.0f, 0.0f, 0.0f, r.writtenAt, r.owner, e.payload, 0u, e.hasBase != 0 ? e.base : 0ULL)) return 0;", rchk);
        const size_t rwr = rsend == std::string::npos ? rsend : st.find("ZoneMirrorWriteOrPark(kZoneWriteReplay, r, e.payload, std::string());", rsend);
        if (qs == std::string::npos || rchk == std::string::npos || rsend == std::string::npos || rwr == std::string::npos || !(qs < rchk && rchk < rsend && rsend < rwr))
            Fail("t1243 wiring: the journal replay does not check the area file before sending and writing it");
        else
        {
            const std::string rbody = st.substr(rchk, rsend - rchk);
            if (rbody.find("++g_zoneUnreadableNotSent;") == std::string::npos || rbody.find("return -1;") == std::string::npos)
                Fail("t1243 wiring: an unreadable journaled area file does not leave the journal as a bad entry, counted");
        }
    }
    if (T1243Count(st, "zonecheck::ReadableBytes(") != 7)
        Fail("t1243 wiring: the game checks an area file other than on its seven roads (save, journal, replay, the kept table's load, the host's index copy, a held record's file, the mirror write)");
    {   /* T-1243 (owner 1523): ZoneMirrorCommit checks an area copy before it writes it; an unreadable one is not written, the held record
           is kept only while its own file reads (ZoneHeldAreaFileCheck), and the answer is 0 (not written) */
        const size_t mc = st.find("int ZoneMirrorCommit(int kind, const Record& r, const std::vector<char>& bytes, const std::string& src, bool deferred)\n{");
        const size_t ck = mc == std::string::npos ? mc : st.find("if (zonecheck::ReadableBytes(bytes, &zstop) == 0)", mc);
        const size_t hd = ck == std::string::npos ? ck : st.find("ZoneHeldAreaFileCheck(r.worldId, ", ck);
        const size_t rt = hd == std::string::npos ? hd : st.find("return 0;", hd);
        const size_t wf = mc == std::string::npos ? mc : st.find("if (!WriteFileBytes(r.file, bytes))", mc);
        const size_t df = mc == std::string::npos ? mc : st.find("if (deferred) g_zoneKeptMark.erase(r.worldId);", mc);
        if (mc == std::string::npos || ck == std::string::npos || hd == std::string::npos || rt == std::string::npos || wf == std::string::npos || df == std::string::npos
            || !(mc < ck && ck < hd && hd < rt && rt < df && df < wf))
            Fail("t1243 wiring: ZoneMirrorCommit does not check an area copy, and answer not written, before anything else it does");
        else
        {
            const std::string cb = st.substr(ck, rt - ck);
            if (cb.find("++g_zoneMirrorUnreadable;") == std::string::npos || cb.find("not written; ") == std::string::npos || cb.find("Kenshi loads its own file") == std::string::npos
                || cb.find("ZoneSwapPublish(r.worldId);") == std::string::npos || cb.find("g_records[") != std::string::npos || cb.find("WriteFileBytes(") != std::string::npos)
                Fail("t1243 wiring: an unreadable area copy at the mirror write is written, recorded, not counted or not logged");
        }
        if (st.find(" zoneMirrorUnreadable=\" + N(g_zoneMirrorUnreadable)") == std::string::npos) Fail("t1243 wiring: zoneMirrorUnreadable= is not on the report line");
    }
    {   /* T-1243 re-check fold (owner 1523): a held area record whose mirror file is missing or unreadable is dropped - the unreadable file
           set aside, never deleted - so the swap names no file for it; asked at both failed-copy arms of LoadIndex and at MirrorKeepLoad's
           rejection when the held record names the file set aside */
        const size_t hc = st.find("int ZoneHeldAreaFileCheck(const std::string& zoneId, const std::string& road)\n{");
        const size_t he = hc == std::string::npos ? hc : st.find("\n}\n", hc);
        const std::string body = (hc == std::string::npos || he == std::string::npos) ? std::string() : st.substr(hc, he - hc);
        const size_t ok = body.find("if (opened && zonecheck::ReadableBytes(b, &stop) != 0) return 1;");
        const size_t mv = body.find("U8MoveFileEx(file.c_str(), aside.c_str(), 0)");
        const size_t er = body.find("g_records.erase(it);");
        const size_t pb = body.find("ZoneSwapPublish(zoneId);");
        if (body.empty() || ok == std::string::npos || mv == std::string::npos || er == std::string::npos || pb == std::string::npos || !(ok < mv && mv < er && er < pb)
            || body.find("zonecheck::SetAsideName(") == std::string::npos || body.find("++g_zoneHeldDropped;") == std::string::npos)
            Fail("t1243 wiring: a held area record with an unreadable or missing file is not set aside and dropped from the swap");
        if (body.find("DeleteFile") != std::string::npos || body.find("MOVEFILE_REPLACE_EXISTING") != std::string::npos) Fail("t1243 wiring: the held-record check can delete or write over a file");
        if (T1243Count(st, "ZoneHeldAreaFileCheck(") != 6 || st.find("const int kept = ZoneHeldAreaFileCheck(zid, \"the area read's swap check: its file is missing\");") == std::string::npos) Fail("t1243 wiring: the held-record check is defined or asked other than once and at its five places (T-1279 fold 2: the fifth is the area read's missing swap file)");
        const size_t li = st.find("void LoadIndex()\n{");
        const size_t fc = li == std::string::npos ? li : st.find("const bool zoneCopyFailed = IsZoneId(r.worldId) && !ZoneIndexMirrorCopy(&r);", li);
        const size_t a1 = fc == std::string::npos ? fc : st.find("ZoneHeldAreaFileCheck(r.worldId, ", fc);
        const size_t c1 = a1 == std::string::npos ? a1 : st.find("continue;", a1);
        const size_t tk = c1 == std::string::npos ? c1 : st.find("g_records[r.worldId] = r; ZoneSwapPublish(r.worldId); ++g_indexRecords;", c1);
        const size_t a2 = tk == std::string::npos ? tk : st.find("if (zoneCopyFailed) ZoneHeldAreaFileCheck(r.worldId, ", tk);
        const size_t le = li == std::string::npos ? li : st.find("\n}\n", li);
        if (li == std::string::npos || fc == std::string::npos || a1 == std::string::npos || c1 == std::string::npos || tk == std::string::npos || a2 == std::string::npos
            || le == std::string::npos || !(fc < a1 && a1 < c1 && c1 < tk && tk < a2 && a2 < le))
            Fail("t1243 wiring: LoadIndex does not check the held record's file at both arms of a failed copy");
        const size_t ml = st.find("void MirrorKeepLoad()\n{");
        const size_t mv2 = ml == std::string::npos ? ml : st.find("U8MoveFileEx(file.c_str(), aside.c_str(), 0)", ml);
        const size_t hk = mv2 == std::string::npos ? mv2 : st.find("if (heldNamesIt) ZoneHeldAreaFileCheck(k.key, ", mv2);
        const size_t c2 = hk == std::string::npos ? hk : st.find("continue;", hk);
        const size_t c2m = mv2 == std::string::npos ? mv2 : st.find("continue;", mv2);
        if (ml == std::string::npos || mv2 == std::string::npos || hk == std::string::npos || c2 == std::string::npos || !(mv2 < hk && hk < c2 && c2 == c2m))
            Fail("t1243 wiring: MirrorKeepLoad's rejection does not check a held record naming the file set aside before it moves on");
    }
    {   /* T-1243 (owner 1523): the kept table's load reads a kept area file to its end before its row is taken; an unreadable one is
           moved aside (never deleted, never onto another file) and its row rejected */
        const size_t ml = st.find("void MirrorKeepLoad()\n{");
        const size_t me = ml == std::string::npos ? ml : st.find("\n}\n", ml);
        const std::string body = (ml == std::string::npos || me == std::string::npos) ? std::string() : st.substr(ml, me - ml);
        const size_t notes = body.find("if (mirrorkeep::RowLoadNotes(lv) == 0) { ++g_mkSkipped; continue; }");
        const size_t area = body.find("if (IsZoneId(k.key))\n        {   /* T-1243 (owner 1523");
        const size_t chk = body.find("if (!zopen || zonecheck::ReadableBytes(zb, &zstop) == 0)");
        const size_t rej = chk == std::string::npos ? chk : body.find("++g_mkRejected; ++g_mkUnreadable;", chk);
        const size_t mv = chk == std::string::npos ? chk : body.find("U8MoveFileEx(file.c_str(), aside.c_str(), 0)", chk);
        const size_t cont = mv == std::string::npos ? mv : body.find("continue;", mv);
        const size_t take = body.find("else g_records[k.key] = r;");
        if (body.empty() || notes == std::string::npos || area == std::string::npos || chk == std::string::npos || rej == std::string::npos || mv == std::string::npos
            || cont == std::string::npos || take == std::string::npos || !(notes < area && area < chk && chk < rej && rej < mv && mv < cont && cont < take))
            Fail("t1243 wiring: the kept table's load does not check an area row's file before the row is taken, or does not reject and set aside an unreadable one");
        if (body.find("DeleteFile") != std::string::npos || body.find("MOVEFILE_REPLACE_EXISTING") != std::string::npos) Fail("t1243 wiring: the kept table's load can delete or write over a file");
        if (body.find("zonecheck::SetAsideName(file, StoreFileThere(file + \".unreadable\") ? 1 : 0, (long long)::time(0))") == std::string::npos)
            Fail("t1243 wiring: the set-aside name is not the helper's");
    }
    {   /* T-1243 (owner 1523): the host's copy from the world server's folder is checked before it is written into the mirror */
        const size_t zc = st.find("bool ZoneIndexMirrorCopy(Record* r)\n{");
        const size_t ze = zc == std::string::npos ? zc : st.find("\n}\n", zc);
        const std::string body = (zc == std::string::npos || ze == std::string::npos) ? std::string() : st.substr(zc, ze - zc);
        const size_t chk = body.find("const bool unreadable = readOk && zonecheck::ReadableBytes(bytes, &zstop) == 0;");
        const size_t cp = body.find("const bool ok = readOk && !unreadable && WriteFileBytes(r->file, bytes);");
        if (body.empty() || chk == std::string::npos || cp == std::string::npos || !(chk < cp) || body.find("++g_zoneIndexUnreadable;") == std::string::npos)
            Fail("t1243 wiring: the host's index copy is not checked before it is written, or an unreadable one is not counted");
    }
    {
        const size_t mc = st.find("int ZoneMirrorCommit(int kind, const Record& r, const std::vector<char>& bytes, const std::string& src, bool deferred)\n{");
        const size_t wf = mc == std::string::npos ? mc : st.find("if (!WriteFileBytes(r.file, bytes))", mc);
        const size_t af = mc == std::string::npos ? mc : st.find("ZoneDamageMaybe(zonecheck::kDamageAfter, r.worldId, &dmg);", mc);
        const size_t s1 = mc == std::string::npos ? mc : st.find("sent = SendRecordAny(r.worldId, \"\", \"\", 0.0f, 0.0f, 0.0f, r.writtenAt, r.owner, dmg, 0u, zoneBase);", mc);
        if (mc == std::string::npos || wf == std::string::npos || af == std::string::npos || s1 == std::string::npos || !(wf < af && af < s1))
            Fail("t1243 wiring: the lever's after stage does not damage only the copy sent, after the mirror write");
    }
    if (T1243Count(st, "g_zoneDamage = a;") != 1 || T1243Count(st, "ZoneDamageMaybe(zonecheck::") != 3) Fail("t1243 wiring: the lever is armed or applied somewhere other than its command and its three stages");
    {   /* T-1243 (owner 1523): the mirror stage runs after ZoneMirrorCommit's write (and a save's send), damages the FILE and writes the kept table again */
        const size_t mc = st.find("int ZoneMirrorCommit(int kind, const Record& r, const std::vector<char>& bytes, const std::string& src, bool deferred)\n{");
        const size_t me = mc == std::string::npos ? mc : st.find("\n}\n", mc);
        const size_t s1 = mc == std::string::npos ? mc : st.find("sent = SendRecordAny(r.worldId, \"\", \"\", 0.0f, 0.0f, 0.0f, r.writtenAt, r.owner, bytes, 0u, zoneBase);", mc);
        const size_t mm = mc == std::string::npos ? mc : st.find("    ZoneDamageMirrorMaybe(r);", mc);
        if (mc == std::string::npos || me == std::string::npos || s1 == std::string::npos || mm == std::string::npos || !(s1 < mm && mm < me))
            Fail("t1243 wiring: the lever's mirror stage is not at the end of ZoneMirrorCommit, after the send");
        const size_t df = st.find("void ZoneDamageMirrorMaybe(const Record& r)\n{");
        const size_t de = df == std::string::npos ? df : st.find("\n}\n", df);
        const std::string body = (df == std::string::npos || de == std::string::npos) ? std::string() : st.substr(df, de - df);
        const size_t ap = body.find("ZoneDamageMaybe(zonecheck::kDamageMirror, r.worldId, &fb);");
        const size_t fw = body.find("WriteFileBytes(r.file, fb);");
        const size_t kw = body.find("MirrorKeepWrite(");
        if (body.empty() || ap == std::string::npos || fw == std::string::npos || kw == std::string::npos || !(ap < fw && fw < kw))
            Fail("t1243 wiring: the mirror stage does not damage the file and then write the kept table again");
        {   /* T-1243 re-check #5: an offset at or past the file's end zeroes nothing - said so, and the file is not rewritten */
            const size_t pe = body.find("if (pastEnd)");
            const size_t pr = pe == std::string::npos ? pe : body.find("return;", pe);
            if (pe == std::string::npos || pr == std::string::npos || !(ap < pe && pr < fw) || body.find("nothing zeroed (offset past the end)") == std::string::npos)
                Fail("t1243 wiring: the mirror stage rewrites the file, or does not say so, when nothing was zeroed");
        }
        if (T1243Count(st, "ZoneDamageMirrorMaybe(r);") != 1) Fail("t1243 wiring: the mirror stage is applied other than once");
    }
    std::string cc = T313ReadFile("../coop-plugin/command_channel.cpp");
    cc.erase(std::remove(cc.begin(), cc.end(), '\r'), cc.end());
    if (cc.find("else if (verb == \"zonedamage\")\n    {\n        std::string rest; std::getline(is, rest);\n        WriteStatus(coop::ZoneDamageLever(Trim(rest))); finished = true;\n    }") == std::string::npos)
        Fail("t1243 wiring: the zonedamage command does not reach the lever");
}

/* T-1262: THE REASON BEFORE THE FLAG (removalreason.h) - 'incinerated or cooked' (the carrier's job 'feed corpse into machine')
   ends the body under either engine flag, whatever hasDied says; 'ZoneMapContent::deactivate' (the other site that hard-codes the
   flag to 1) and every other reason keep the flag's word. */
void t_t1262_reason_before_flag()
{
    using namespace coopremoval;
    if (EngineRemovalReasonClass("incinerated or cooked") != kReasonFinal || EngineRemovalReasonClass(kIncineratedOrCooked) != kReasonFinal)
        Fail("t1262: 'incinerated or cooked' is not a final end");
    if (EngineRemovalReasonClass("incinerated") != kReasonAmbiguous || EngineRemovalReasonClass("incinerated or cooked ") != kReasonAmbiguous)
        Fail("t1262: the burn's reason is not compared whole");
    for (int flag = 0; flag <= 1; ++flag)
        for (int dead = -1; dead <= 1; ++dead)
        {
            if (RemovalIsUnload(flag, EngineRemovalReasonClass(kIncineratedOrCooked), dead) != 0) Fail("t1262: a burned body is told UNLOAD (put away), not DESPAWN");
            if (RemovalIsUnload(flag, EngineRemovalReasonClass("ZoneMapContent::deactivate"), dead) != 1) Fail("t1262: a zone's deactivate is not an UNLOAD");
            if (RemovalIsUnload(flag, EngineRemovalReasonClass("corpse unloaded"), dead) != 1) Fail("t1262: corpse unloaded is not an UNLOAD");
        }
    if (RemovalIsUnload(1, EngineRemovalReasonClass("eaten"), 1) != 1 || RemovalIsUnload(1, EngineRemovalReasonClass("platoon destructor"), 1) != 1)
        Fail("t1262: the engine's unload flag no longer decides for a reason other than the burn");
    if (RemovalIsUnload(0, EngineRemovalReasonClass("eaten"), 0) != 0) Fail("t1262: eaten without the flag is no longer a DESPAWN");
    if (RemovalIsBurn(kIncineratedOrCooked) != 1 || RemovalIsBurn("incinerated or cooked") != 1) Fail("t1262: the burn is not named");
    if (RemovalIsBurn("eaten") != 0 || RemovalIsBurn("ZoneMapContent::deactivate") != 0 || RemovalIsBurn(0) != 0) Fail("t1262: another reason is named a burn");
}

cooffect::EffectMsg T1262Req()
{
    cooffect::EffectMsg m;
    m.dir = cooffect::kDirRequest; m.kind = cooffect::kKindBurn; m.reqId = 41u; m.targetUid = 0x00400007u; m.actorUid = 0x00100003u;
    return m;
}
/* T-1262: MSG_EFFECT kind 7 BURN - the request is the 14-byte header (body = target, carrier = actor), the answer 16 bytes; never DONE. */
void t_t1262_burn_wire()
{
    using namespace cooffect;
    if (kKindBurn != 7) Fail("t1262: BURN is not kind 7");
    if (!(KindKnown(kKindEat) && KindKnown(kKindKo) && KindKnown(kKindBurn)) || KindKnown(2) || KindKnown(4) || KindKnown(5) || KindKnown(6) || KindKnown(8))
        Fail("t1262: the known kinds are not EAT, KO and BURN alone (2, 4..6 stay reserved)");
    const EffectMsg m = T1262Req();
    std::vector<char> b(1, 'x');
    if (kBurnRequestSize != 14u || kBurnAnswerSize != 16u || EffectMsgSize(kDirRequest, kKindBurn) != 14u || EffectMsgSize(kDirAnswer, kKindBurn) != 16u)
        Fail("t1262: the BURN sizes are not 14 / 16");
    if (!EncodeEffect(&b, m) || b.size() != 1u + kBurnRequestSize) { Fail("t1262: a BURN request did not encode to its 14-byte header"); return; }
    if (b[0] != 'x' || b[1] != 1 || b[2] != 7) Fail("t1262: a BURN request's bytes are not dir, kind first");
    EffectMsg d;
    if (DecodeEffect(&b[1], b.size() - 1, &d) != kDecodeOk || d.dir != kDirRequest || d.kind != kKindBurn || d.reqId != 41u || d.targetUid != m.targetUid
        || d.actorUid != m.actorUid)
        Fail("t1262: a BURN request did not round-trip");
    if (DecodeEffect(&b[1], 13, &d) != kDecodeTooShort) Fail("t1262: a 13-byte BURN request was accepted");
    { EffectMsg x = m; x.actorUid = 0; std::vector<char> z; if (EncodeEffect(&z, x) || !z.empty()) Fail("t1262: a BURN naming no carrier was encoded"); }
    { EffectMsg x = m; x.actorUid = x.targetUid; std::vector<char> z; if (EncodeEffect(&z, x)) Fail("t1262: a body named as its own carrier was encoded"); }
    { std::vector<char> y(b.begin() + 1, b.end()); y[1] = 8; if (DecodeEffect(&y[0], y.size(), &d) != kDecodeBadKind) Fail("t1262: kind 8 was accepted"); }
    const unsigned char res[3] = { kResultApplied, kResultAlready, kResultRefused };
    const unsigned char why[3] = { (unsigned char)kReasonNone, (unsigned char)kReasonNone, (unsigned char)kReasonBusy };
    for (int i = 0; i < 3; ++i)
    {
        EffectMsg a = m; a.dir = kDirAnswer; a.result = res[i]; a.reason = why[i];
        std::vector<char> e;
        if (!EncodeEffect(&e, a) || e.size() != kBurnAnswerSize) { Fail("t1262: a BURN answer did not encode to 16 bytes"); continue; }
        if (DecodeEffect(&e[0], e.size(), &d) != kDecodeOk || d.kind != kKindBurn || d.result != res[i] || d.reason != why[i] || d.reqId != 41u)
            Fail("t1262: a BURN answer did not round-trip");
        if (i == 0)
        {
            std::vector<char> y = e; y[14] = (char)kResultDone;
            if (DecodeEffect(&y[0], y.size(), &d) != kDecodeBadField) Fail("t1262: a DONE BURN answer was decoded");
        }
    }
    { EffectMsg a = m; a.dir = kDirAnswer; a.result = kResultDone; std::vector<char> z; if (EncodeEffect(&z, a)) Fail("t1262: a DONE BURN answer was encoded"); }
    { EffectMsg a = m; a.dir = kDirAnswer; a.result = kResultRefused; a.reason = kReasonNone; std::vector<char> z; if (EncodeEffect(&z, a)) Fail("t1262: a REFUSED BURN with no reason was encoded"); }
}

cooffect::BurnRow T1262Row(unsigned int body, unsigned int carrier, unsigned int req)
{
    cooffect::BurnRow r;
    r.body = body; r.carrier = carrier; r.reqId = req;
    return r;
}
/* T-1262: THE CARRIER'S GAME'S BURN-PENDING ROWS - open, a re-sent copy held back, closed by the owner's DESPAWN, REFUSED falls back
   to the lost copy (with its spot), the re-send on the owner's return (an event, not a timer), the bound. */
void t_t1262_burn_pending()
{
    using namespace cooffect;
    BurnTable t;
    if (BurnHoldsCopy(t, 100)) Fail("t1262: an empty table holds a copy back");
    if (BurnOpen(&t, T1262Row(100, 7, 1)) != 1 || !BurnHoldsCopy(t, 100) || BurnHoldsCopy(t, 101) || BurnHoldsCopy(t, 0))
        Fail("t1262: open - the burned body is not held back, or another is");
    if (BurnOpen(&t, T1262Row(0, 7, 2)) != 0 || BurnOpen(&t, T1262Row(102, 0, 2)) != 0 || BurnOpen(&t, T1262Row(102, 7, 0)) != 0
        || BurnOpen(&t, T1262Row(7, 7, 2)) != 0 || t.rows.size() != 1u)
        Fail("t1262: a row with no body, no carrier, no request or the body as its own carrier was opened");
    if (BurnOpen(&t, T1262Row(100, 8, 3)) != 2 || t.rows.size() != 1u || t.rows[0].reqId != 3u || t.rows[0].carrier != 8u)
        Fail("t1262: a second burn of the same body did not refresh its one row");
    if (!BurnOnDespawn(&t, 100) || BurnHoldsCopy(t, 100) || BurnOnDespawn(&t, 100) || BurnOnDespawn(&t, 0))
        Fail("t1262: the owner's DESPAWN did not close the row once");
    BurnRow closed;
    BurnOpen(&t, T1262Row(200, 7, 10));
    if (BurnOnAnswer(&t, 200, 9, kResultApplied, &closed) != kBurnAnsStale) Fail("t1262: an answer to another request was taken");
    if (BurnOnAnswer(&t, 201, 10, kResultApplied, &closed) != kBurnAnsStale) Fail("t1262: an answer for another body was taken");
    if (BurnOnAnswer(&t, 200, 10, kResultApplied, &closed) != kBurnAnsWait || !BurnHoldsCopy(t, 200) || t.rows[0].state != kBurnAnswered)
        Fail("t1262: APPLIED did not keep the row (answered) until the DESPAWN");
    if (BurnOnAnswer(&t, 200, 10, kResultAlready, &closed) != kBurnAnsWait || !BurnHoldsCopy(t, 200)) Fail("t1262: ALREADY did not keep the row");
    BurnOnDespawn(&t, 200);
    BurnRow r = T1262Row(300, 7, 11); r.hasPos = 1; r.x = 1.5f; r.y = 2.0f; r.z = -3.0f;
    BurnOpen(&t, r);
    if (BurnOnAnswer(&t, 300, 11, kResultRefused, &closed) != kBurnAnsFallback || BurnHoldsCopy(t, 300) || closed.body != 300u || closed.hasPos != 1
        || closed.x != 1.5f || closed.y != 2.0f || closed.z != -3.0f)
        Fail("t1262: REFUSED did not close the row and hand back its spot for the lost-copy re-ask");
    if (BurnOnAnswer(&t, 300, 11, kResultRefused, &closed) != kBurnAnsStale) Fail("t1262: a second REFUSED fell back twice");
    if (BurnResendDue(kBurnWaiting, 0, 0, 0) || BurnResendDue(kBurnWaiting, 0, 0, 1) || BurnResendDue(kBurnWaiting, 1, 0, 1)) Fail("t1262: sent while its owner is unreachable");
    if (!BurnResendDue(kBurnWaiting, 0, 1, 0)) Fail("t1262: not sent again when its owner became reachable");
    if (BurnResendDue(kBurnWaiting, 1, 1, 0)) Fail("t1262: sent again while reachable all along (a timer)");
    if (!BurnResendDue(kBurnWaiting, 1, 1, 1)) Fail("t1262: not sent again on a new link to its owner");
    if (BurnResendDue(kBurnAnswered, 0, 1, 1)) Fail("t1262: an answered row was sent again");
    BurnTable full;
    for (unsigned int u = 1; u <= (unsigned int)kBurnRowsMax; ++u) BurnOpen(&full, T1262Row(1000 + u, 7, u));
    if (full.rows.size() != kBurnRowsMax || full.dropped != 0) Fail("t1262: the table did not take 64 rows");
    if (BurnOpen(&full, T1262Row(5000, 7, 99)) != 1 || full.rows.size() != kBurnRowsMax || full.dropped != 1 || BurnHoldsCopy(full, 1001)
        || !BurnHoldsCopy(full, 5000) || !BurnHoldsCopy(full, 1002))
        Fail("t1262: a full table did not drop its oldest row (counted) for the new one");
    /* the report's sequence: the owner re-sent the burned body (its resend answers and its catch-up) - never built while pending */
    BurnTable q;
    BurnOpen(&q, T1262Row(77, 5, 1));
    int built = 0;
    for (int k = 0; k < 4; ++k) if (!BurnHoldsCopy(q, 77)) ++built;
    if (built != 0) Fail("t1262: a re-sent copy of a burned body was built (the report's body was burned four times)");
    BurnOnDespawn(&q, 77);
    if (BurnHoldsCopy(q, 77)) Fail("t1262: after its owner's DESPAWN the body is still held back");
}

/* T-1262: THE OWNER'S SIDE - the check (ALREADY first, then notMine, notSenders - answered for a BURN -, gone), the apply's answer, the wait
   while engine writes are blocked; the body's state is read at the apply (t1262_burn_step: BurnOwnerMayRemove, review fold 4). */
void t_t1262_burn_owner()
{
    using namespace cooffect;
    if (BurnOwnerCheck(true, false, false, false) != kBurnOwnAlready) Fail("t1262: a body this game burned on an earlier request is not ALREADY");
    if (BurnOwnerCheck(false, false, true, true) != kReasonNotMine) Fail("t1262: another game's body is not refused notMine");
    if (BurnOwnerCheck(false, true, false, true) != kReasonNotSenders) Fail("t1262: a sender that does not drive the carrier is not refused notSenders");
    {   /* a BURN answers notSenders (an unanswered row would hold the body back on the carrier's game) - its REFUSED encodes */
        EffectMsg a; a.dir = kDirAnswer; a.kind = kKindBurn; a.reqId = 6u; a.targetUid = 0x00400009u; a.actorUid = 0x00100001u;
        a.result = kResultRefused; a.reason = (unsigned char)kReasonNotSenders;
        std::vector<char> e;
        if (!EncodeEffect(&e, a)) Fail("t1262: a REFUSED notSenders BURN answer does not encode");
    }
    if (BurnOwnerCheck(false, true, true, false) != kReasonGone) Fail("t1262: a body not here is not refused gone");
    if (BurnOwnerCheck(false, true, true, true) != kBurnOwnApply) Fail("t1262: a good request is not applied");
    unsigned char why = 99;
    if (BurnApplyAnswer(1, &why) != kResultApplied || why != kReasonNone) Fail("t1262: a removed body is not APPLIED");
    if (BurnApplyAnswer(0, &why) != kResultRefused || why != kReasonGone) Fail("t1262: a body gone at the apply is not REFUSED gone");
    if (BurnApplyAnswer(-2, &why) != kResultRefused || why != kReasonBusy) Fail("t1262: a body another character carries is not REFUSED busy");
    if (BurnApplyAnswer(-1, &why) != kResultRefused || why != kReasonState) Fail("t1262: a refused or faulted removal is not REFUSED state");
    if (BurnOwnerWhen(false, 0) != kBurnOwnRun || BurnOwnerWhen(false, 999999u) != kBurnOwnRun) Fail("t1262: an allowed write waited");
    if (BurnOwnerWhen(true, 0) != kBurnOwnWait || BurnOwnerWhen(true, kBurnOwnerWaitMs) != kBurnOwnWait || BurnOwnerWhen(true, kBurnOwnerWaitMs + 1) != kBurnOwnRefuse)
        Fail("t1262: a blocked write does not wait 30 s and then refuse");
    const int rcs[4] = { 1, 0, -2, -1 };
    for (int i = 0; i < 4; ++i)
    {
        EffectMsg a; a.dir = kDirAnswer; a.kind = kKindBurn; a.reqId = 5u; a.targetUid = 0x00400009u; a.actorUid = 0x00100001u;
        a.result = BurnApplyAnswer(rcs[i], &a.reason);
        std::vector<char> e;
        if (!EncodeEffect(&e, a)) Fail("t1262: an answer the owner gives does not encode");
    }
}

/* T-1262: the sites - the burned copy's owner asked after the unload test and before the not-ours exit, a SPAWN held before it is
   built, the owner's DESPAWN closing the row after its authority check, the lost-copy book held back, the owner's removal with the
   engine's own flag and reason, BURN dispatched and ticked, protocol 216. */
void t_t1262_wiring()
{
    std::string sp = T313ReadFile("../coop-plugin/spawn.cpp"), se = T313ReadFile("../coop-plugin/net/session.cpp"), ef = T313ReadFile("../coop-plugin/effect.cpp");
    sp.erase(std::remove(sp.begin(), sp.end(), '\r'), sp.end());
    se.erase(std::remove(se.begin(), se.end(), '\r'), se.end());
    ef.erase(std::remove(ef.begin(), ef.end(), '\r'), ef.end());
    const size_t npos = std::string::npos;
    const size_t nd = sp.find("void NotifyDespawn(unsigned int uid, const void* obj, bool justUnloaded, const char* reason, int dead)\n{");
    const size_t un = nd == npos ? npos : sp.find("if (coopremoval::RemovalIsUnload(", nd);
    const size_t cb = nd == npos ? npos : sp.find("if (!net::IsUidMine(uid) && coopremoval::RemovalIsBurn(reason) != 0) CopyBurnedHere(uid, lostHasPos, lostX, lostY, lostZ);", nd);
    const size_t no = cb == npos ? npos : sp.find("if (!net::IsUidMine(uid)) { ++g_despawnNotOurs;", cb);
    if (un == npos || cb == npos || no == npos || !(un < cb)) Fail("t1262 wiring: NotifyDespawn does not ask a burned copy's owner after the unload test and before the not-ours exit");
    if (sp.find("w->destroy((RootObject*)body, true, coopremoval::kIncineratedOrCooked)") == npos) Fail("t1262 wiring: the owner does not remove the body with the engine's flag and reason");
    if (sp.find("if (carrier != 0 && net::IsUidMine(carrier) && EffectBurnOpen(uid, carrier, hasPos, x, y, z)) return;") == npos)
        Fail("t1262 wiring: a burned copy with this game's carrier does not open its burn");
    const size_t os = se.find("void OnSpawn(const Message& m)");
    const size_t oh = os == npos ? npos : se.find("if (coop::EffectBurnHoldSpawn(sm.uid)) return;", os);
    const size_t oa = os == npos ? npos : se.find("coop::ApplyRemoteSpawn(sm.uid", os);
    if (oh == npos || oa == npos || !(oh < oa)) Fail("t1262 wiring: a SPAWN of a burned body is not held back before it is built");
    const size_t od = se.find("void OnDespawn(const Message& m)");
    const size_t ow = od == npos ? npos : se.find("if (!RemoteMayWrite(uid, m.peer))", od);
    const size_t oc = od == npos ? npos : se.find("coop::EffectBurnOwnerDespawned(uid);", od);
    const size_t oe = od == npos ? npos : se.find("coop::ApplyRemoteDespawn(uid);", od);
    if (ow == npos || oc == npos || oe == npos || !(ow < oc && oc < oe)) Fail("t1262 wiring: the owner's DESPAWN does not close the burn after its authority check");
    if (se.find("if (coop::EffectBurnHoldsLost(uid)) return;") == npos || se.find("if (coop::EffectBurnPending(uid)) return false;") == npos)
        Fail("t1262 wiring: the lost-copy book does not hold a burned body back");
    if (ef.find("if (m.kind == cooffect::kKindBurn)") == npos || ef.find("BurnTick(now);") == npos) Fail("t1262 wiring: BURN is not dispatched or not ticked");
    if (se.find("const unsigned int kProtocolVersion = 237;") == npos || hovrec::kGameProtocol != 237u) Fail("t1262 wiring: the game-to-game protocol is not 237");
}

/* T-1262 review folds 1-4, 6, 8: ONE ROW'S STEP (cooffect::BurnRowStep / BurnRowAfter) by behaviour - a failed send is sent again,
   a change of the body's owner sends again, a held SPAWN sends again whatever the row's state up to the cap and then closes the row;
   the owner's awake refusal and its postponed-removal answer. */
void t_t1262_burn_step()
{
    using namespace cooffect;
    BurnRow r = T1262Row(100, 7, 1);
    r.ownerKey = 5; r.reach = 1;   /* sent at the open to owner 5 */
    int why = -1;
    if (BurnRowStep(r, 1, 0, 5, 0, &why) != kBurnStepKeep || why != kBurnWhyNone) Fail("t1262 step: sent again with nothing new (a timer)");
    if (BurnRowStep(r, 1, 1, 5, 0, &why) != kBurnStepSend || why != kBurnWhyLink) Fail("t1262 step: not sent again on a new link");
    {   /* fold 1 + re-check: a failed send is not repeated at the next look (no send every frame); the next event sends it again */
        BurnRow f = T1262Row(101, 7, 2);
        f.ownerKey = 5;
        BurnRowAfter(&f, kBurnStepSend, kBurnWhyReach, 1, 5, kRoadNone);
        if (f.reach != 1 || f.ownerKey != 5u) Fail("t1262 step fold 1: a failed send did not keep the look");
        for (int k = 0; k < 3; ++k)
            if (BurnRowStep(f, 1, 0, 5, 0, &why) != kBurnStepKeep) { Fail("t1262 step re-check: a failed send is sent again at every look"); break; }
        if (BurnRowStep(f, 1, 1, 5, 0, &why) != kBurnStepSend || why != kBurnWhyLink) Fail("t1262 step fold 1: a failed send is not sent again on a new link");
        BurnRowAfter(&f, kBurnStepKeep, kBurnWhyNone, 0, 5, kRoadNone);
        if (BurnRowStep(f, 1, 0, 5, 0, &why) != kBurnStepSend || why != kBurnWhyReach) Fail("t1262 step fold 1: a failed send is not sent again when its owner is reachable again");
        BurnRowAfter(&f, kBurnStepSend, why, 1, 5, kRoadSession);
        if (f.reach != 1 || BurnRowStep(f, 1, 0, 5, 0, &why) != kBurnStepKeep) Fail("t1262 step fold 1: a send that went is sent again");
    }
    {   /* unreachable: nothing; the look's reach is kept, the owner is not */
        BurnRow u = r;
        if (BurnRowStep(u, 0, 1, 6, 0, &why) != kBurnStepKeep) Fail("t1262 step: sent while its owner is unreachable");
        BurnRowAfter(&u, kBurnStepKeep, why, 0, 6, kRoadNone);
        if (u.reach != 0 || u.ownerKey != 5u) Fail("t1262 step: a look without a send did not keep reach, or moved the owner");
    }
    {   /* fold 3: the body's owner changed (a hand-over, a release) */
        BurnRow o = r;
        if (BurnRowStep(o, 1, 0, 6, 0, &why) != kBurnStepSend || why != kBurnWhyOwner) Fail("t1262 step fold 3: a new owner is not asked");
        BurnRowAfter(&o, kBurnStepSend, why, 1, 6, kRoadLive);
        if (o.ownerKey != 6u || o.reach != 1 || o.spawnResends != 0 || o.state != kBurnWaiting) Fail("t1262 step fold 3: the new owner is not kept after the send");
        if (BurnRowStep(o, 1, 0, 6, 0, &why) != kBurnStepKeep) Fail("t1262 step fold 3: one change of owner sent twice");
        BurnRow o2 = r;
        BurnRowAfter(&o2, kBurnStepSend, kBurnWhyOwner, 1, 6, kRoadNone);
        if (o2.ownerKey != 6u || BurnRowStep(o2, 1, 0, 6, 0, &why) != kBurnStepKeep) Fail("t1262 step re-check: a failed send to the new owner is sent again at every look");
        if (BurnRowStep(o2, 1, 0, 6, 1, &why) != kBurnStepSend || why != kBurnWhySpawn) Fail("t1262 step fold 3: a failed send to the new owner is not sent again on its held SPAWN");
        if (BurnRowStep(r, 1, 0, 0, 0, &why) != kBurnStepKeep) Fail("t1262 step fold 3: no owner record was taken as a change");
        if (BurnRowStep(r, 0, 0, 6, 0, &why) != kBurnStepKeep) Fail("t1262 step fold 3: a new owner not reachable was sent to");
        BurnRow a = r;
        a.state = kBurnAnswered;
        if (BurnRowStep(a, 1, 1, 6, 0, &why) != kBurnStepKeep) Fail("t1262 step: an answered row was sent again on a look");
    }
    {   /* fold 2: a held SPAWN - its owner still runs the body: sent again whatever the state and the reach, up to the cap, then closed */
        BurnRow s = r;
        s.state = kBurnAnswered;
        for (int k = 0; k < kBurnSpawnResendsMax; ++k)
        {
            if (BurnRowStep(s, k % 2, 0, 5, 1, &why) != kBurnStepSend || why != kBurnWhySpawn) { Fail("t1262 step fold 2: a held SPAWN did not send the request again"); break; }
            BurnRowAfter(&s, kBurnStepSend, why, k % 2, 5, (k % 2 == 0) ? kRoadNone : kRoadSession);
            if (s.spawnResends != k + 1 || s.state != kBurnWaiting) { Fail("t1262 step fold 2: a held SPAWN's send was not counted, or the row not waiting again"); break; }
        }
        if (BurnRowStep(s, 1, 0, 5, 1, &why) != kBurnStepClose || why != kBurnWhyCap) Fail("t1262 step fold 2: past the cap the row is not closed");
        BurnRow c = s;
        BurnRowAfter(&c, kBurnStepClose, kBurnWhyCap, 1, 9, kRoadSession);
        if (c.spawnResends != s.spawnResends || c.reach != s.reach || c.ownerKey != s.ownerKey) Fail("t1262 step fold 2: a close changed the row");
    }
    {   /* the review's story: the REFUSED answer is lost (no answer, no DESPAWN) and the owner keeps sending the body - the row does not wait forever */
        BurnTable t;
        BurnRow o = T1262Row(300, 7, 9);
        o.ownerKey = 5; o.reach = 1;
        BurnOpen(&t, o);
        int sends = 0, closed = 0;
        for (int k = 0; k < 20; ++k)
        {
            const int at = BurnFind(t, 300);
            if (at < 0) break;
            const int st = BurnRowStep(t.rows[(size_t)at], 1, 0, 5, 1, &why);
            if (st == kBurnStepClose) { t.rows.erase(t.rows.begin() + at); closed = 1; break; }
            if (st == kBurnStepSend) ++sends;
            BurnRowAfter(&t.rows[(size_t)at], st, why, 1, 5, kRoadSession);
        }
        if (sends != kBurnSpawnResendsMax || closed != 1 || BurnHoldsCopy(t, 300))
            Fail("t1262 step fold 2: held SPAWNs do not send the request again up to the cap and then close the row");
    }
    {   /* a refreshed row (a second burn of the body) starts its count again */
        BurnTable t;
        BurnRow o = T1262Row(400, 7, 3);
        o.spawnResends = kBurnSpawnResendsMax;
        BurnOpen(&t, o);
        BurnOpen(&t, T1262Row(400, 7, 4));
        if (t.rows.size() != 1u || t.rows[0].spawnResends != 0 || t.rows[0].ownerKey != 0u) Fail("t1262 step: a refreshed row kept its old count");
    }
    const int ws[6] = { kBurnWhyNone, kBurnWhyReach, kBurnWhyLink, kBurnWhyOwner, kBurnWhySpawn, kBurnWhyCap };
    for (int i = 0; i < 6; ++i)
        for (int k = i + 1; k < 6; ++k)
            if (std::string(BurnWhyName(ws[i])) == BurnWhyName(ws[k])) Fail("t1262 step: two reasons share a log name");
    /* fold 4: the owner removes a body nobody of the sender's carries only when it is down there */
    if (!BurnOwnerMayRemove(false, 0)) Fail("t1262 fold 4: a knocked-out or dead body was not burned");
    if (BurnOwnerMayRemove(false, 1) || BurnOwnerMayRemove(false, -1)) Fail("t1262 fold 4: an awake (or unread) body that nobody carries was burned");
    if (!BurnOwnerMayRemove(true, 1) || !BurnOwnerMayRemove(true, -1) || !BurnOwnerMayRemove(true, 0)) Fail("t1262 fold 4: a body the sender's carrier holds was not burned");
    unsigned char rw = 0;
    if (BurnApplyAnswer(-3, &rw) != kResultRefused || rw != kReasonState) Fail("t1262 fold 4: an awake body is not REFUSED state");
    /* fold 6: the engine's postponed removal after the detour took the body out of the table is APPLIED; a fault never is (re-check) */
    if (BurnDestroyOutcome(1, true) != 1 || BurnDestroyOutcome(1, false) != 1) Fail("t1262 fold 6: an accepted removal is not APPLIED");
    if (BurnDestroyOutcome(0, false) != 1) Fail("t1262 fold 6: a postponed removal that reached the detour is not APPLIED");
    if (BurnDestroyOutcome(-1, false) != -1) Fail("t1262 re-check: a faulted removal (its DESPAWN maybe never sent) is APPLIED");
    if (BurnDestroyOutcome(0, true) != -1 || BurnDestroyOutcome(-1, true) != -1) Fail("t1262 fold 6: a removal that did not reach the detour is APPLIED");
    if (BurnApplyAnswer(BurnDestroyOutcome(0, false), &rw) != kResultApplied) Fail("t1262 fold 6: a postponed removal is not answered APPLIED");
}

/* T-1262 review folds: the sites - the reach test is the send's road test, both BurnTick and a held SPAWN take BurnRowStep, a world
   load answers the owner's queued requests and clears the ring, the owner reads the body before removing it and takes a postponed
   removal as done, the report carries the no-carrier count. */
void t_t1262_review_wiring()
{
    std::string sp = T313ReadFile("../coop-plugin/spawn.cpp"), se = T313ReadFile("../coop-plugin/net/session.cpp"), ef = T313ReadFile("../coop-plugin/effect.cpp");
    sp.erase(std::remove(sp.begin(), sp.end(), '\r'), sp.end());
    se.erase(std::remove(se.begin(), se.end(), '\r'), se.end());
    ef.erase(std::remove(ef.begin(), ef.end(), '\r'), ef.end());
    if (sp.empty() || se.empty() || ef.empty()) { Fail("t1262 review wiring: a source file is not readable"); return; }
    const size_t npos = std::string::npos;
    if (ef.find("return net::EffectRequestRoadNow(body) != 0 ? 1 : 0;") == npos || ef.find("(StoreLiveReady() || net::SessionLinked())") != npos)
        Fail("t1262 review wiring fold 1: the owner's reach is not the request's own road test");
    if (se.find("int EffectRequestRoadNow(unsigned int targetUid) { unsigned int key = 0; return EffectRequestRoadTo(targetUid, &key); }") == npos
        || se.find("const int road = EffectRequestRoadTo(targetUid, &key);") == npos)
        Fail("t1262 review wiring fold 1: the reach test and the send do not share one road test");
    if (ef.find("cooffect::BurnRowStep(r, reach, linkChanged, ownerNow, 0, &why);") == npos || ef.find("cooffect::BurnRowStep(r, reach, 0, ownerNow, 1, &why);") == npos)
        Fail("t1262 review wiring fold 8: BurnTick or the held SPAWN does not take BurnRowStep");
    if (ef.find("cooffect::BurnRowAfter(&r, step, why, reach, ownerNow, road);") == npos) Fail("t1262 review wiring fold 1: a send's result does not set the row");
    if (ef.find("r.ownerKey = BurnOwnerNow(body);") == npos) Fail("t1262 review wiring fold 3: the row does not keep its owner");
    const size_t bc = ef.find("void BurnClear(const char* why)\n{");
    const size_t be = bc == npos ? npos : ef.find("\n}\n", bc);
    const size_t ba = bc == npos ? npos : ef.find("BurnOwnAnswer(q[k], cooffect::kResultRefused, (unsigned char)cooffect::kReasonBusy);", bc);
    const size_t br = bc == npos ? npos : ef.find("for (int i = 0; i < kBurnedHereRows; ++i) g_burnedHere[i] = 0;", bc);
    if (be == npos || ba == npos || ba > be) Fail("t1262 review wiring fold 2: a world load does not answer the owner's queued requests REFUSED busy");
    if (be == npos || br == npos || br > be) Fail("t1262 review wiring fold 5: a world load does not clear the ring of bodies burned here");
    const size_t ob = sp.find("int BurnOwnBody(unsigned int bodyUid, unsigned int carrierUid, unsigned int* heldBy, int* letGo, int* awake, int* destroyRc)\n{");
    const size_t om = ob == npos ? npos : sp.find("if (!cooffect::BurnOwnerMayRemove(false, a)) return -3;", ob);
    const size_t od = ob == npos ? npos : sp.find("const int d = BurnDestroyPod(w, body);", ob);
    const size_t oo = ob == npos ? npos : sp.find("return cooffect::BurnDestroyOutcome(d, FindSpawned(bodyUid) != 0);", ob);
    if (om == npos || od == npos || !(om < od)) Fail("t1262 review wiring fold 4: the owner does not read the body before removing it");
    if (oo == npos || !(od < oo)) Fail("t1262 review wiring fold 6: a postponed removal is not checked against the uid table");
    if (ef.find("<< BurnCopyNoCarrierCount()") == npos || sp.find("long long BurnCopyNoCarrierCount() { return g_burnCopyNoCarrier; }") == npos)
        Fail("t1262 review wiring fold 7: the no-carrier count is not on the report line");
}

/* T-1280: the shared three-way file check (fileprobe.cpp) on REAL files under this worktree's build folder (<worktree>\build\t1280_probe:
   the exe's ..\..\build, as t1202's disk test; never the system temp). Nothing is deleted: the files are written again on every run. */
static std::string T1280Dir()
{
    char exe[MAX_PATH] = { 0 };
    const DWORD n = ::GetModuleFileNameA(0, exe, MAX_PATH);
    std::string root(exe, n);
    const std::string::size_type cut = root.find_last_of("\\/");
    if (n == 0 || n >= MAX_PATH || cut == std::string::npos) return std::string();
    root = root.substr(0, cut) + "\\..\\..\\build";
    if (!coopdir::AttrIsDir(::GetFileAttributesA(root.c_str()))) return std::string();
    const std::string dir = root + "\\t1280_probe";
    ::CreateDirectoryA(dir.c_str(), 0);
    return coopdir::AttrIsDir(::GetFileAttributesA(dir.c_str())) ? dir : std::string();
}
static bool T1280Write(const std::string& path, const std::string& text)
{
    std::FILE* f = std::fopen(path.c_str(), "wb");
    if (f == 0) return false;
    const size_t put = text.empty() ? 0 : std::fwrite(text.data(), 1, text.size(), f);
    std::fclose(f);
    return put == text.size();
}
/* T-1269 [t1269a-A]: the list hold - held from the WELCOME to the LIST END, only squads with a record and no listed runner, lifted by
   going offline; the walk of one join */
void t_t1269_list_hold()
{
    using namespace sqwreg;
    if (ListHoldAfter(0, kLhWelcome, 1) != 1 || ListHoldAfter(1, kLhWelcome, 1) != 1) Fail("t1269 A: a WELCOME with a list to come does not hold");
    if (ListHoldAfter(0, kLhWelcome, 0) != 0 || ListHoldAfter(1, kLhWelcome, 0) != 0) Fail("t1269 A: a WELCOME of another protocol (no list follows) holds");
    if (ListHoldAfter(1, kLhListEnd, 1) != 0 || ListHoldAfter(1, kLhOffline, 0) != 0) Fail("t1269 A: the LIST END or going offline does not end the hold");
    if (ListHoldAfter(1, 0, 1) != 1 || ListHoldAfter(0, 0, 1) != 0) Fail("t1269 A: an event that is none of the three moved the hold (no timer ends it)");
    if (ListHoldBlocks(1, 1, 1, 0) != 1) Fail("t1269 A: a squad with a record and no listed runner is not held while the list is not whole");
    if (ListHoldBlocks(0, 1, 1, 0) != 0) Fail("t1269 A: held after the list ended");
    if (ListHoldBlocks(1, 1, 0, 0) != 0) Fail("t1269 A (check change 2): a squad with NO record here is held - a held wake is destroyed and nothing builds it again");
    if (ListHoldBlocks(1, 0, 1, 0) != 0) Fail("t1269 A: an id that is not a squad is held");
    if (ListHoldBlocks(1, 1, 1, 1) != 0) Fail("t1269 A: a squad another game is listed as running counts as held (it is a refusal for that game)");
    if (OtherOrHeld(1, 0) != 1 || OtherOrHeld(0, 1) != 1 || OtherOrHeld(1, 1) != 1 || OtherOrHeld(0, 0) != 0) Fail("t1269 A: the gate before the refusal is not 'another runs it, or held'");
    /* going offline: held, link down, the outage seen and past the list's grace - a blip keeps the hold, a wrap of the tick count does not lift it */
    if (ListHoldOfflineLift(1, 0, 1, 1001u + kOtherListGraceMs, 1000u) != 1) Fail("t1269 A: going offline past the grace does not lift the hold");
    if (ListHoldOfflineLift(1, 0, 1, 1000u + kOtherListGraceMs, 1000u) != 0) Fail("t1269 A: the hold lifted within the grace (a blip)");
    if (ListHoldOfflineLift(1, 1, 1, 1001u + kOtherListGraceMs, 1000u) != 0 || ListHoldOfflineLift(1, 0, 0, 1001u + kOtherListGraceMs, 1000u) != 0)
        Fail("t1269 A: the hold lifted with the link up, or with no outage seen");
    if (ListHoldOfflineLift(0, 0, 1, 1001u + kOtherListGraceMs, 1000u) != 0) Fail("t1269 A: an offline lift with nothing held");
    if (ListHoldOfflineLift(1, 0, 1, 0x00000100u, 0xFFFFFF00u) != 0) Fail("t1269 A: a tick-count wrap lifted the hold early");
    /* the walk of one join: WELCOME; three roads ask during the push (a squad another game runs, one nobody runs, one with no record here);
       the list names the first; the LIST END's loop builds only the one nobody runs */
    {
        int hold = ListHoldAfter(0, kLhWelcome, 1);
        std::map<std::string, int> listed; std::set<std::string> wait; int held = 0;
        const char* ids[3] = { "f_1", "f_2", "f_3" }; const int rec[3] = { 1, 1, 0 };
        for (int i = 0; i < 3; ++i)
        {
            const int other = listed.count(ids[i]) != 0 ? 1 : 0;
            if (OtherOrHeld(other, ListHoldBlocks(hold, 1, rec[i], other)) != 0) { wait.insert(ids[i]); ++held; }
        }
        if (held != 2 || wait.count("f_3") != 0) Fail("t1269 A walk: the push window did not hold exactly the two squads with a record");
        listed["f_1"] = 1;   /* RUNS f_1 (slot 1) arrives in the list */
        hold = ListHoldAfter(hold, kLhListEnd, 1);
        int built = 0;
        const std::vector<std::string> w(wait.begin(), wait.end());
        for (size_t i = 0; i < w.size(); ++i) if (BuildAtRelease(1, listed.count(w[i]) != 0 ? 1 : 0) != 0) { wait.erase(w[i]); ++built; }
        if (hold != 0 || built != 1 || wait.count("f_1") != 1 || wait.count("f_2") != 0) Fail("t1269 A walk: the LIST END did not build the unlisted squad and keep the listed one waiting");
        if (ListHoldBlocks(hold, 1, 1, 0) != 0) Fail("t1269 A walk: a road after the LIST END is still held");
    }
}
/* T-1269 [t1269a-B]: the restart - 'maybe running' for a writer not back, the start's SLOT GONE, the re-claim batch and its end mark */
void t_t1269_restart()
{
    using namespace sqwreg;
    if (kProtocol != 170u || kMsgSquadRelease != 86u) Fail("t1269 B: the end mark does not ride SQUAD_RELEASE 86 of world-server protocol 170");
    {   /* the end mark: SQUAD_RELEASE with the id "*", which no squad id is */
        std::string id; const std::vector<char> b = EncodeReclaimEnd();
        if (DecodeRelease(b, &id) != 1 || IsReclaimEnd(id) != 1 || id != std::string(kNoteAllId)) Fail("t1269 B: the end mark does not decode as SQUAD_RELEASE \"*\"");
        if (IsReclaimEnd("faction_12") != 0 || IsReclaimEnd("") != 0) Fail("t1269 B: a squad's own release reads as the end mark");
    }
    if (MaybeRunning(1, 0, 1, 0) != 1) Fail("t1269 B: a registered squad with no marks whose writer is not back does not count as running");
    if (MaybeRunning(0, 0, 1, 0) != 0 || MaybeRunning(1, 1, 1, 0) != 0 || MaybeRunning(1, 0, 0, 0) != 0 || MaybeRunning(1, 0, 1, 1) != 0)
        Fail("t1269 B: maybe running without a writer, with marks, with the writer back, or for a gone record");
    if (RunsNow(1, 0, 1, 0, 1, 0, 0, 0) != 1) Fail("t1269 B: the 'who runs it' test misses a squad of a writer not back since the restart");
    if (RunsNow(1, 0, 0, 0, 1, 0, 0, 0) != 0) Fail("t1269 B: a squad with no marks of a writer away and not 'not back' counts as running (today's released)");
    if (RunsNow(1, 1, 0, 1, 0, 1, 0, 0) != 1 || RunsNow(1, 1, 0, 1, 1, 1, 0, 0) != 0 || RunsNow(1, 1, 0, 1, 0, 0, 0, 0) != 0 || RunsNow(1, 1, 0, 1, 0, 1, 1, 0) != 0)
        Fail("t1269 B: the 'who runs it' test differs from NoteRuns for a live writer with marks");
    if (RunsNow(1, 0, 1, 1, 0, 1, 0, 0) != 1) Fail("t1269 B: the test does not read 'live, or not back yet' for a writer with marks");
    if (NotBackAtStart(1, 2, 0) != 1 || NotBackAtStart(1, -1, 0) != 0 || NotBackAtStart(1, 2, 1) != 0 || NotBackAtStart(0, 2, 0) != 0) Fail("t1269 B: the start's not-back seed");
    {   /* the start's SLOT GONE goes kSlotGoneStartGraceSec after the start through the link-close hold's own step */
        const double at = SlotGoneStartAt(100.0, kSlotGoneStartGraceSec, 10.0);
        if (SlotGoneHoldStep(at, 100.0 + kSlotGoneStartGraceSec - 0.5, 10.0, 0) != kSgWait || SlotGoneHoldStep(at, 100.0 + kSlotGoneStartGraceSec, 10.0, 0) != kSgSend
            || SlotGoneHoldStep(at, 120.0, 10.0, 1) != kSgCancel)
            Fail("t1269 B: the start's SLOT GONE is not sent at the start grace, or not cancelled by the game's return");
        if (kSlotGoneStartGraceSec < 30.0) Fail("t1269 B: the start's grace is shorter than a game's link timeout and re-dial");
    }
    if (ReclaimNoted(1, kBasisRuns) != 1 || ReclaimNoted(0, kBasisRuns) != 0 || ReclaimNoted(1, kBasisKeep) != 0) Fail("t1269 B: a re-claim is not exactly a RUNS take from a game not back");
    if (ReclaimEndStep(1, 0, 1) != kReRuns || ReclaimEndStep(1, 0, 0) != kReRelease || ReclaimEndStep(1, 1, 0) != kReUnchanged || ReclaimEndStep(0, 0, 0) != kReUnchanged)
        Fail("t1269 B: the end mark's step - re-claimed runs, unclaimed released, a landed take or another writer's squad unchanged");
    if (ReclaimSendNow(1, 1) != 1 || ReclaimSendNow(1, 0) != 0 || ReclaimSendNow(0, 1) != 0) Fail("t1269 B: the batch is not sent once owed and the link is up");
    if (ReclaimWanted(1, 1, 1, 1, 0, 0) != 1 || ReclaimWanted(1, 1, 1, 0, 0, 0) != 0 || ReclaimWanted(1, 1, 1, 1, 1, 0) != 0 || ReclaimWanted(1, 1, 1, 1, 0, 1) != 0
        || ReclaimWanted(1, 0, 1, 1, 0, 0) != 0 || ReclaimWanted(1, 1, 0, 1, 0, 0) != 0 || ReclaimWanted(0, 1, 1, 1, 0, 0) != 0)
        Fail("t1269 B: the batch re-claims a squad this game did not run, a refused one, one with a take out, an unwritten or a non-NPC one");
    /* the walk of a restart: slot 2 registered g1, g2 (g4 gone); slot 3 registered g3. Slot 2 comes back, re-claims g1 and sends the end mark;
       slot 3 stays away until its SLOT GONE */
    {
        const char* ids[4] = { "g_1", "g_2", "g_3", "g_4" }; const int ws[4] = { 2, 2, 3, 2 }; const int gone[4] = { 0, 0, 0, 1 };
        std::set<int> notBack; std::map<std::string, int> marksRuns;   /* id -> runs mark (present = has marks; released 0) */
        for (int i = 0; i < 4; ++i) if (NotBackAtStart(1, ws[i], gone[i]) != 0) notBack.insert(ws[i]);
        std::set<int> live;
        int run[4];
        for (int i = 0; i < 4; ++i) run[i] = RunsNow(1, live.count(ws[i]) != 0 ? 1 : 0, notBack.count(ws[i]) != 0 ? 1 : 0, 0, 1, 0, 0, gone[i]);
        if (notBack.size() != 2 || run[0] != 1 || run[1] != 1 || run[2] != 1 || run[3] != 0) Fail("t1269 B walk: the start's list is not g1, g2, g3");
        live.insert(2);
        std::set<std::string> got; if (ReclaimNoted(notBack.count(2) != 0 ? 1 : 0, kBasisRuns) != 0) got.insert("g_1");
        notBack.erase(2);
        for (int i = 0; i < 4; ++i)
        {
            const int st = ReclaimEndStep(ws[i] == 2 ? 1 : 0, marksRuns.count(ids[i]) != 0 ? 1 : 0, got.count(ids[i]) != 0 ? 1 : 0);
            if (st == kReRuns) marksRuns[ids[i]] = 1;
        }
        for (int i = 0; i < 4; ++i)
        {
            const int have = marksRuns.count(ids[i]) != 0 ? 1 : 0;
            run[i] = RunsNow(1, live.count(ws[i]) != 0 ? 1 : 0, notBack.count(ws[i]) != 0 ? 1 : 0, have, have != 0 ? 0 : 1, have != 0 ? 1 : 0, 0, gone[i]);
        }
        if (run[0] != 1 || run[1] != 0 || run[2] != 1) Fail("t1269 B walk: after slot 2's end mark g1 is not still its, g2 not released, or g3 lost");
        notBack.erase(3);   /* slot 3's SLOT GONE */
        if (RunsNow(1, 0, 0, 0, 1, 0, 0, 0) != 0) Fail("t1269 B walk: g3 still runs after its writer's SLOT GONE");
    }
}
