/* T-1269 fold 1 (H1): the race of a held engine wake against the list end - in both orders the group is built once, never lost */
void t_t1269f1_held_wake_race()
{
    using namespace sqwreg;
    if (SweepWaitOnDoomed(1, 0, 1) != 1 || SweepWaitOnDoomed(1, 1, 1) != 0 || SweepWaitOnDoomed(0, 0, 1) != 0 || SweepWaitOnDoomed(1, 0, 0) != 0)
        Fail("t1269 H1: the sweep's wait on a copy being removed is not exactly 'waiting, no live copy, a copy being removed'");
    if (WakeDupSettledAsks(1) != 1 || WakeDupSettledAsks(0) != 0) Fail("t1269 H1: a removal's end does not ask a waiting id again");
    /* the model: one group G with a record; during the hold its engine wake is refused (copy doomed, id waiting). Order 1: the LIST END comes
       first (the sweep meets the doomed copy), then the removal. Order 2: the removal first (still held), then the LIST END. */
    for (int order = 1; order <= 2; ++order)
    {
        int hold = ListHoldAfter(0, kLhWelcome, 1), waiting = 0, doomed = 0, live = 0, built = 0, lost = 0, queued = 0;
        if (OtherOrHeld(0, ListHoldBlocks(hold, 1, 1, 0)) != 0) { waiting = 1; doomed = 1; }   /* the held wake: put on ice, waits */
        for (int step = 0; step < 2; ++step)
        {
            const int listEnd = (order == 1) == (step == 0);
            if (listEnd)
            {
                hold = ListHoldAfter(hold, kLhListEnd, 1);
                if (BuildAtRelease(waiting, 0) != 0) queued = 1;
            }
            else
            {   /* CtxDropTick removes the doomed copy, then asks a waiting id again */
                doomed = 0;
                if (WakeDupSettledAsks(waiting) != 0 && BuildAtRelease(waiting, 0) != 0) queued = 1;
            }
            while (queued != 0)
            {   /* the sweep's pass on G (a writer-left entry) */
                queued = 0;
                if (SweepWaitOnDoomed(1, live, doomed) != 0) continue;   /* keeps waiting: the removal asks again */
                if (live != 0) { waiting = 0; continue; }   /* a copy stayed: kept, nothing built */
                if (OtherOrHeld(0, ListHoldBlocks(hold, 1, 1, 0)) != 0) continue;   /* still held at the SWEEP road: waits for the list end */
                waiting = 0; ++built; live = 1;
            }
        }
        if (waiting == 0 && built == 0 && live == 0) lost = 1;
        if (built != 1 || lost != 0 || waiting != 0 || hold != 0)
            Fail(std::string("t1269 H1: a held engine wake is not built exactly once when ") + (order == 1 ? "the list end comes before its copy's removal" : "its copy's removal comes before the list end"));
    }
}
/* T-1269 fold 1 (M1 / M2): the take judge and the sent list agree on a squad of a writer not back; the batch claims what this game runs now */
void t_t1269f1_judge_and_batch()
{
    using namespace sqwreg;
    /* a registered squad (writer slot 0) and a take or write by slot 1, the area held by slot 1: every combination of the writer's state */
    for (int haveMarks = 0; haveMarks <= 1; ++haveMarks)
    for (int notBack = 0; notBack <= 1; ++notBack)
    for (int live = 0; live <= 1; ++live)
    {
        const int released = haveMarks != 0 ? 0 : 1, runs = haveMarks, keeper = 0;   /* no marks = today's released default */
        JudgeIn in; in.kind = kKindTake; in.basis = kBasisRuns; in.sender = 1; in.registered = 1; in.writer = 0; in.holder = 1; in.holderLive = 1; in.senderLoadedHere = 1;
        in.writerLive = live; in.writerReleased = released; in.writerKeeper = keeper;
        ApplyNotBack(&in, haveMarks, notBack, 0);
        const int listSaysRuns = RunsNow(1, live, notBack, haveMarks, released, runs, keeper, 0);
        const int judgeGrants = Takes(Judge(in));
        if (listSaysRuns != 0 && judgeGrants != 0)
            Fail("t1269 M1: the take judge grants another game's RUNS take of a squad the sent list says its writer runs (marks " + std::string(haveMarks ? "1" : "0")
                 + ", not back " + (notBack ? "1" : "0") + ", live " + (live ? "1" : "0") + ")");
        if (listSaysRuns == 0 && judgeGrants == 0) Fail("t1269 M1: the take judge refuses a squad the sent list says nobody runs");
        JudgeIn pos = in; pos.kind = kKindPosition;
        if (MaybeRunning(1, haveMarks, notBack, 0) != 0 && Judge(pos) == kSwTakeover) Fail("t1269 M1: the holder's note takes over a squad still maybe running");
        JudgeIn full = in; full.kind = kKindFull;
        if (MaybeRunning(1, haveMarks, notBack, 0) != 0 && Takes(Judge(full)) != 0) Fail("t1269 M1: another game's full write takes over a squad still maybe running");
        JudgeIn own = in; own.sender = 0;
        if (Judge(own) != kSwWriter) Fail("t1269 M1: the writer's own re-claim is not taken");
    }
    if (ReclaimRunsNow(2, 2, 0) != 1 || ReclaimRunsNow(2, -1, 3) != 1 || ReclaimRunsNow(2, 1, 0) != 0 || ReclaimRunsNow(-1, -1, 3) != 0)
        Fail("t1269 M2: the batch does not claim a squad this game runs the majority of, or some of (split), or claims one it runs none of");
    if (ReclaimEndMayGo(0) != 1 || ReclaimEndMayGo(1) != 0) Fail("t1269 M2: the end mark goes after a claim that did not go out");
}
