void t_t1280_probe_real_files()
{
    const std::string dir = T1280Dir();
    if (dir.empty()) { Fail("t1280: no build folder beside the test exe (..\\..\\build) to write the probe's files in"); return; }
    /* 1. a file held with a no-sharing CreateFile (what a scanner or backup program does): UNREADABLE - never absent, never empty -
          with the sharing violation and the size the folder reports */
    const std::string held = dir + "\\held.txt";
    if (!T1280Write(held, "abc")) { Fail("t1280: could not write held.txt"); return; }
    const HANDLE h = ::CreateFileA(held.c_str(), GENERIC_READ, 0, 0, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, 0);
    if (h == INVALID_HANDLE_VALUE) { Fail("t1280: could not hold held.txt with no sharing"); return; }
    const coopstore::FileProbe hp = coopstore::ProbeFile(held);
    ::CloseHandle(h);
    if (hp.kind != coopstore::kFileUnreadable) Fail("t1280: a file held with no sharing is not kFileUnreadable");
    if (hp.err != (unsigned long)ERROR_SHARING_VIOLATION) Fail("t1280: a held file's error is not the sharing violation (32)");
    if (hp.attrLen != 3) Fail("t1280: a held file's size, from the folder, is not named");
    if (!hp.bytes.empty() || hp.len != 0) Fail("t1280: a held file's probe carries bytes");
    /* 2. let go: the same file reads, its bytes and checksum in hand */
    const coopstore::FileProbe rp = coopstore::ProbeFile(held);
    if (rp.kind != coopstore::kFileReadable || rp.len != 3 || rp.bytes.size() != 3 || rp.crc != coopstore::Crc32("abc", 3))
        Fail("t1280: a file let go does not read back whole");
    /* 3. absent: a name never written, and a name in a folder that is not there (the two not-found errors) */
    if (coopstore::ProbeFile(dir + "\\t1280_never_written.txt").kind != coopstore::kFileAbsent) Fail("t1280: a name never written is not kFileAbsent");
    if (coopstore::ProbeFile(dir + "\\t1280_no_such_folder\\x.txt").kind != coopstore::kFileAbsent) Fail("t1280: a name in a missing folder is not kFileAbsent");
    /* 4. zero bytes: READABLE with a length of 0 - a fact about the file, not a failure to read it */
    const std::string zero = dir + "\\zero.txt";
    if (!T1280Write(zero, std::string())) { Fail("t1280: could not write zero.txt"); return; }
    const coopstore::FileProbe zp = coopstore::ProbeFile(zero);
    if (zp.kind != coopstore::kFileReadable || zp.len != 0 || !zp.bytes.empty() || zp.crc != 0u) Fail("t1280: a zero-byte file is not readable with length 0");
    /* 5. a directory of that name: UNREADABLE (ERROR_DIRECTORY), never read as a file */
    const coopstore::FileProbe dp = coopstore::ProbeFile(dir);
    if (dp.kind != coopstore::kFileUnreadable || dp.err != (unsigned long)ERROR_DIRECTORY) Fail("t1280: a directory is not kFileUnreadable (ERROR_DIRECTORY)");
}
/* the two numbers of " fileLocked[seen,retried]=<a>,<b>" */
static bool T1280Token(long long* seen, long long* retried)
{
    const std::string t = coopstore::FileLockedToken();
    const std::string key = " fileLocked[seen,retried]=";
    if (t.compare(0, key.size(), key) != 0) return false;
    return std::sscanf(t.c_str() + key.size(), "%lld,%lld", seen, retried) == 2;
}
/* T-1280: one site's step on a held file (the decision every site takes: unreadable -> skip the write, said once; the attempt that finds
   it readable again goes ahead and counts as retried; absent stays the road it always was), the counter, and the one log line */
void t_t1280_locked_step()
{
    using namespace coopstore;
    int held = 0;
    if (FileLockedStep(kFileReadable, &held) != kLockGo || held != 0) Fail("t1280: a readable file with nothing held is not Go");
    if (FileLockedStep(kFileAbsent, &held) != kLockGo || held != 0) Fail("t1280: an absent file with nothing held is not Go (the first-creation road)");
    if (FileLockedStep(kFileUnreadable, &held) != kLockSkipFirst || held != 1) Fail("t1280: the first unreadable answer is not SkipFirst");
    if (FileLockedStep(kFileUnreadable, &held) != kLockSkipAgain || held != 1) Fail("t1280: a second unreadable answer is not SkipAgain (said once)");
    if (FileLockedStep(kFileReadable, &held) != kLockRecovered || held != 0) Fail("t1280: the readable answer after a held run is not Recovered");
    if (FileLockedStep(kFileReadable, &held) != kLockGo) Fail("t1280: a readable answer after the recovery is not Go");
    held = 1;
    if (FileLockedStep(kFileAbsent, &held) != kLockRecovered || held != 0) Fail("t1280: a held file that went away does not let the site go on");
    if (!FileLockSkips(kLockSkipFirst) || !FileLockSkips(kLockSkipAgain) || FileLockSkips(kLockGo) || FileLockSkips(kLockRecovered))
        Fail("t1280: FileLockSkips does not skip exactly the two unreadable steps");
    long long s0 = 0, r0 = 0, s1 = 0, r1 = 0;
    if (!T1280Token(&s0, &r0)) { Fail("t1280: the REPORT token is not fileLocked[seen,retried]=a,b"); return; }
    int site = 0;
    FileLockedNote(kFileUnreadable, &site);
    FileLockedNote(kFileUnreadable, &site);
    FileLockedNote(kFileReadable, &site);
    FileLockedNote(kFileReadable, &site);
    if (!T1280Token(&s1, &r1) || s1 - s0 != 1 || r1 - r0 != 1) Fail("t1280: one held run (two skipped writes) that went ahead is not counted seen +1, retried +1 (fold 1, L8: a retry is not counted again in seen)");
    FileProbe p;
    p.kind = kFileUnreadable; p.err = 32; p.attrLen = 7;
    const std::string line = FileLockedLine("[X] site", "C:\\Users\\SomeOne\\AppData\\Local\\x\\own.index", p, "kept in memory");
    if (line.find("[X] site: own.index is ON DISK (7 bytes) and could NOT BE READ (Windows error 32)") == std::string::npos
        || line.find("SomeOne") != std::string::npos || line.find("kept in memory.") == std::string::npos || line.find(" fileLocked[seen,retried]=") == std::string::npos)
        Fail("t1280: the log line does not name the file only, its size, the Windows error, what is kept and the counter");
    if (ProbeLeafName("C:\\a\\b.txt") != "b.txt" || ProbeLeafName("a/b/c.txt") != "c.txt" || ProbeLeafName("plain.txt") != "plain.txt")
        Fail("t1280: ProbeLeafName does not give the file's own name");
    if (coopui::PanelNotebookText(coopui::kNbStoppedEarly, 0, swformat::kServerExitSlotsUnreadable).find("slots.txt") == std::string::npos)
        Fail("t1280: the panel does not word the world server's held-slots.txt refusal (exit 37)");
}
/* T-1280: every site of the design's table reads through ProbeFile and skips its write on an unreadable answer; the TEST-ONLY lever */
static size_t T1280Count(const std::string& s, const std::string& what)
{
    size_t n = 0;
    for (size_t at = s.find(what); at != std::string::npos; at = s.find(what, at + what.size())) ++n;
    return n;
}
void t_t1280_wiring()
{
    const std::string os = T313ReadFile("../coop-plugin/ownstore.cpp"), st = T313ReadFile("../coop-plugin/store.cpp"), it = T313ReadFile("../coop-plugin/items.cpp");
    const std::string sm = T313ReadFile("../coop-store/store_main.cpp"), cc = T313ReadFile("../coop-plugin/command_channel.cpp");
    if (os.find("const coopstore::FileProbe ip = coopstore::ProbeFile(indexPath);") == std::string::npos || os.find("ReadAll(Join(dir, coopown::IndexFile()), &b)") != std::string::npos)
        Fail("t1280 wiring: OwnStoreOpen does not probe the index");
    if (st.find("OwnLeftNoteCommit(dir, &e, uid);") == std::string::npos || st.find("OwnLeftNoteRetryHeld();   /* T-1280") == std::string::npos)
        Fail("t1280 wiring: a death's left note is not held and retried at the next death or save");
    if (st.find("if (leftLocked) coopown::RosterNoSettle(&sq);") == std::string::npos) Fail("t1280 wiring: a held left-note file still lets the load copy people back");
    if (st.find("if (!pendLocked) { g_ownPend = pl; g_ownPendDir = sdir; }") == std::string::npos || st.find("const std::string opath = saveDir + ") == std::string::npos)
        Fail("t1280 wiring: the pending strips or the squad file each names are not probed");
    if (st.find("if (g_queueUnmerged != 0) { QueueLoad(); return 1; }") == std::string::npos || st.find("const coopstore::FileProbe qp = coopstore::ProbeFile(QueueFile());") == std::string::npos
        || st.find("const coopstore::FileProbe np = coopstore::ProbeFile(QueueFile());") == std::string::npos || st.find("ReadFileBytes(QueueFile()") != std::string::npos)
        Fail("t1280 wiring: the outage journal is read with the collapsing test somewhere");
    if (st.find("const bool besideLocked = use == coopbrec::kOwUseBeside") == std::string::npos) Fail("t1280 wiring: the owed box changes at a load are not probed");
    if (st.find("SwReportToken() + coopstore::FileLockedToken()") == std::string::npos) Fail("t1280 wiring: the game's REPORT line lacks fileLocked");
    if (it.find("if (dirFinal && !journalLocked) g_lootJournalReady = 1;") == std::string::npos) Fail("t1280 wiring: a held loot journal is still marked ready");
    if (sm.find("struct FileProbe") != std::string::npos || sm.find("using coopstore::ProbeFile;") == std::string::npos) Fail("t1280 wiring: the world server keeps its own copy of the check");
    if (sm.find("g_wgLoadDeferred = 1;") == std::string::npos || sm.find("g_ohLoadDeferred = 1;") == std::string::npos || sm.find("g_profLoadDeferred = 1;") == std::string::npos
        || sm.find("WorldGenDeferredRetry();       /* T-1280") == std::string::npos)
        Fail("t1280 wiring: world.gen, own_high.txt or profiles.txt does not defer and retry");
    if (sm.find("if (!gensLocked)") == std::string::npos || T1280Count(sm, "if (storedLocked) return;") != 8)   /* T-860: the cage record's read is the sixth; T-1333: the building record's the seventh; T-4: the town clock record's the eighth */
        Fail("t1280 wiring: the .gens read or one of the five stored-header reads does not drop its write");
    if (sm.find("if (modsLocked) { ++g_modsSetRefused; AdminReply(from, r, admincmd::kRepUnreadable, 0, std::string()); return; }") == std::string::npos || sm.find("const int v = modsLocked ? (int)coopmods::kModsHelloAdmitUnchecked") == std::string::npos)
        Fail("t1280 wiring: a held mods.txt can still be written over");
    if (sm.find("coopstore::FileLockedLine(\"aliases: REFUSED\"") == std::string::npos || sm.find("return swformat::kServerExitSlotsUnreadable;") == std::string::npos
        || sm.find("g_slotsFileHeld = 1;") == std::string::npos)
        Fail("t1280 wiring: --alias or the start does not refuse a held slots.txt");
    if (sm.find("+ coopstore::FileLockedToken()   /* T-1280") == std::string::npos) Fail("t1280 wiring: the world server's REPORT line lacks fileLocked");
    const size_t dev = cc.find("#ifdef SW_DEV_BUILD\n    else if (verb == \"camlook\")") != std::string::npos ? cc.find("#ifdef SW_DEV_BUILD\n    else if (verb == \"camlook\")")
                     : cc.find("#ifdef SW_DEV_BUILD\r\n    else if (verb == \"camlook\")");
    const size_t fh = dev == std::string::npos ? dev : cc.find("else if (verb == \"filehold\")", dev);
    const size_t end = fh == std::string::npos ? fh : cc.find("#endif", fh);
    const size_t aif = cc.find("else if (verb == \"aifreeze\")");
    if (dev == std::string::npos || fh == std::string::npos || end == std::string::npos || aif == std::string::npos || !(end < aif) || cc.find("    FileHoldStep();          /* T-1280") == std::string::npos)
        Fail("t1280 wiring: the TEST-ONLY filehold lever is not inside the DEV-build verbs, or its step is not on the frame");
}
/* T-1280 fold 1: the review's findings - the pure halves (L1 the second look, L8 the counter, M1 the held owed files, M4 the profiles
   merge) and the wiring of the rest (H1 the world server's names before LoadSlots, M2, M3, L2-L7) */
static coopprof::Row T1280Row(const char* person, unsigned num, const char* name)
{
    coopprof::Row r;
    r.person = person; r.num = num; r.name = name; r.slot = 1; r.created = 100; r.active = 1;
    return r;
}
void t_t1280_fold1()
{
    using namespace coopstore;
    /* L1: the caller's own open failed and the probe then read the file - the caller has nothing: UNREADABLE, said as such */
    FileProbe p;
    p.kind = kFileReadable; p.bytes.push_back('x'); p.len = 1; p.attrLen = 1;
    ProbeAfterOwnOpen(&p);
    if (p.kind != kFileUnreadable || p.ownOpenFailed != 1 || !p.bytes.empty() || p.len != 0) Fail("t1280 fold1 L1: a second look that read the file still counts as read");
    if (FileLockedLine("[X]", "a.txt", p, "kept").find("its own open failed") == std::string::npos) Fail("t1280 fold1 L1: the line does not say the caller's own open failed");
    FileProbe a; ProbeAfterOwnOpen(&a);
    if (a.kind != kFileAbsent || a.ownOpenFailed != 0) Fail("t1280 fold1 L1: an absent file is no longer absent after the second look");
    FileProbe u; u.kind = kFileUnreadable; u.err = 32; ProbeAfterOwnOpen(&u);
    if (u.kind != kFileUnreadable || u.err != 32 || u.ownOpenFailed != 0) Fail("t1280 fold1 L1: an unreadable answer is changed by the second look");
    /* L8: a site retrying every second counts its held run ONCE in seen; the run that went ahead once in retried */
    long long s0 = 0, r0 = 0, s1 = 0, r1 = 0;
    if (!T1280Token(&s0, &r0)) { Fail("t1280 fold1 L8: no fileLocked token"); return; }
    int site = 0;
    for (int i = 0; i < 5; ++i) FileLockedNote(kFileUnreadable, &site);
    FileLockedNote(kFileReadable, &site);
    if (!T1280Token(&s1, &r1) || s1 - s0 != 1 || r1 - r0 != 1) Fail("t1280 fold1 L8: five skips of one held run are not seen +1, retried +1");
    /* M1: an owed file whose last read was unreadable is kept (no delete, no write over it) until a read that works */
    std::set<std::string> held;
    HeldPathNote(&held, "C:\\s\\multiplayer.boxowed", kFileUnreadable);
    if (!HeldPathKeeps(held, "C:\\s\\multiplayer.boxowed") || HeldPathKeeps(held, "C:\\t\\multiplayer.boxowed")) Fail("t1280 fold1 M1: a held owed file is not kept, or another is");
    HeldPathNote(&held, "C:\\s\\multiplayer.boxowed", kFileUnreadable);
    if (!HeldPathKeeps(held, "C:\\s\\multiplayer.boxowed")) Fail("t1280 fold1 M1: a second unreadable read lets the held owed file go");
    HeldPathNote(&held, "C:\\s\\multiplayer.boxowed", kFileReadable);
    if (HeldPathKeeps(held, "C:\\s\\multiplayer.boxowed")) Fail("t1280 fold1 M1: a readable read does not let the owed file go");
    HeldPathNote(&held, "C:\\s\\multiplayer.boxowed", kFileUnreadable);
    HeldPathNote(&held, "C:\\s\\multiplayer.boxowed", kFileAbsent);
    if (HeldPathKeeps(held, "C:\\s\\multiplayer.boxowed")) Fail("t1280 fold1 M1: a file gone does not let the hold go");
    HeldPathNote(&held, std::string(), kFileUnreadable);
    if (HeldPathKeeps(held, std::string()) || !held.empty()) Fail("t1280 fold1 M1: an empty path is held");
    /* M4: profiles made while profiles.txt was held are merged; only a real clash keeps the file read-only */
    std::vector<coopprof::Row> file, mem, out;
    file.push_back(T1280Row("p1", 1, "Ann"));
    mem.push_back(T1280Row("p2", 1, "Bob"));
    int added = -1;
    if (coopprof::RowsMergeHeld(file, mem, &out, &added) != 0 || added != 1 || out.size() != 2 || coopprof::FindRow(out, "p2", 1) < 0)
        Fail("t1280 fold1 M4: a new person's profile made meanwhile is not merged");
    mem.clear(); mem.push_back(T1280Row("p1", 1, "Ann"));
    if (coopprof::RowsMergeHeld(file, mem, &out, &added) != 0 || added != 0 || out.size() != 1) Fail("t1280 fold1 M4: a row the file already holds as it is is a clash or a second row");
    mem.clear(); mem.push_back(T1280Row("p1", 1, "Cid"));
    if (coopprof::RowsMergeHeld(file, mem, &out, &added) != 1 || added != 0 || out.size() != 1 || out[0].name != "Ann") Fail("t1280 fold1 M4: one number given twice is not a clash (the file's row kept)");
    mem.clear(); mem.push_back(T1280Row("p3", 1, "Ann"));
    if (coopprof::RowsMergeHeld(file, mem, &out, &added) != 1 || added != 0) Fail("t1280 fold1 M4: a name the file gives another profile is not a clash");
    mem.clear(); mem.push_back(T1280Row("p2", 1, "Bob")); mem.push_back(T1280Row("p1", 1, "Cid"));
    if (coopprof::RowsMergeHeld(file, mem, &out, &added) != 1 || added != 1) Fail("t1280 fold1 M4: a clash and a join together are not counted apart");
    /* the wiring of the findings that have no pure half */
    const std::string st = T313ReadFile("../coop-plugin/store.cpp"), sm = T313ReadFile("../coop-store/store_main.cpp"), os = T313ReadFile("../coop-plugin/ownstore.cpp");
    const size_t use = sm.find("using coopstore::ProbeFile;"), slots = sm.find("void LoadSlots()");
    if (use == std::string::npos || slots == std::string::npos || !(use < slots)) Fail("t1280 fold1 H1: the world server's ProbeFile name comes after its first use (LoadSlots)");
    if (sm.find("if (gensLocked) { g = 0; pending = 1; }") == std::string::npos) Fail("t1280 fold1 M3: BOX_ASK with a held .gens file does not answer pending");
    if (sm.find("coopprof::RowsMergeHeld(g_profiles, mem, &merged, &added)") == std::string::npos) Fail("t1280 fold1 M4: the profiles retry does not merge");
    if (sm.find("if ((ch & 1) != 0 && !wgHeld)") == std::string::npos) Fail("t1280 fold1 L3: a WORLD_SAVED during a world.gen hold still makes a repair copy");
    if (sm.find("return swformat::kServerExitSlotsUnreadable;   /* T-1280 fold 1 (L7)") == std::string::npos) Fail("t1280 fold1 L7: --alias on a held file still answers 2");
    if (sm.find("coopstore::ProbeAfterOwnOpen(&p);") == std::string::npos || T1280Count(sm, "/* T-1280 fold 1 (L1): the probe's bytes - never a second open */") != 5)
        Fail("t1280 fold1 L1: a stored-header read or one of the five loads still opens the file a second time");
    if (st.find("const int where = coopstore::HeldWriteWhere(g_bjOwedHeldPaths, path, pp);") == std::string::npos || st.find("if (coopstore::HeldPathKeeps(g_bjOwedHeldPaths, pp)) return;") == std::string::npos)
        Fail("t1280 fold1 M1: a later save can still remove or write over a held owed file");
    if (st.find("if (heldHere) for (size_t i = 0; i < g_ownLeftHeld.size(); ++i) coopown::LeftNoteAdd(&notes, g_ownLeftHeld[i]);") == std::string::npos
        || st.find("if (heldHere && !leftLocked) OwnLeftNoteCommit(sdir, 0, 0);") == std::string::npos)
        Fail("t1280 fold1 M2: held died notes are not part of the load's notes, or not written once the file reads");
    if (st.find("if (g_ownStoreName != name) OwnLeftHeldStoreSwitch(name);") == std::string::npos) Fail("t1280 fold1 L2: held died notes survive a records-store switch");
    if (T1280Count(st, "coopown::PendStripAdd(&g_ownPendHeld, g_ownPend[i]);") != 2) Fail("t1280 fold1 L6: strips made at a held load are still dropped");
    if (os.find("if (lp.kind == coopstore::kFileUnreadable) { written = false; err = lp.err; }") == std::string::npos) Fail("t1280 fold1 L4: a held live record file is still taken as not indexed");
    if (st.find("coopstore::FileProbe dp;") == std::string::npos || st.find("const coopstore::FileProbe lfp = coopstore::ProbeFile(fp);") == std::string::npos
        || st.find("coopstore::FileProbe lgp;") == std::string::npos || st.find("const coopstore::FileProbe mlp = coopstore::ProbeFile(") == std::string::npos)
        Fail("t1280 fold1 L5: the discovered, lent or money files are still read with the collapsing test");
}
/* T-1280 fold 1c: a held owed file is let go only by a load that read it (N3); a landed save's rows go to the free file, else memory, and
   that memory answers its load ahead of the copy (N1) */
void t_t1280_fold1c()
{
    using namespace coopstore;
    std::set<std::string> held;
    const std::string f = "C:\\s\\multiplayer.boxowed", c = "C:\\st\\boxowed\\0A.boxowed";
    HeldPathNoteUse(&held, f, kFileUnreadable, false);
    if (!HeldPathKeeps(held, f)) Fail("t1280 fold1c N3: an unreadable owed file is not held");
    HeldPathNoteUse(&held, f, kFileReadable, false);
    if (!HeldPathKeeps(held, f)) Fail("t1280 fold1c N3: a held file a load did not use is let go unread");
    HeldPathNoteUse(&held, f, kFileReadable, true);
    if (HeldPathKeeps(held, f)) Fail("t1280 fold1c N3: a held file a load read is not let go");
    HeldPathNoteUse(&held, f, kFileUnreadable, true);
    HeldPathNoteUse(&held, f, kFileAbsent, false);
    if (HeldPathKeeps(held, f)) Fail("t1280 fold1c N3: a held file that is gone is not let go");
    HeldPathNoteUse(&held, f, kFileReadable, false);
    if (HeldPathKeeps(held, f)) Fail("t1280 fold1c N3: a readable file never held becomes held");
    if (HeldWriteWhere(held, f, c) != kHeldWriteFirst) Fail("t1280 fold1c N1: a free beside file does not take the rows");
    held.insert(f);
    if (HeldWriteWhere(held, f, c) != kHeldWriteSecond) Fail("t1280 fold1c N1: a held beside file with a free copy does not send the rows to the copy");
    held.insert(c);
    if (HeldWriteWhere(held, f, c) != kHeldWriteMemory) Fail("t1280 fold1c N1: both files held does not keep the rows in memory");
    if (HeldWriteWhere(held, f, std::string()) != kHeldWriteMemory) Fail("t1280 fold1c N1: a held beside file with no copy does not keep the rows in memory");
    using namespace coopbrec;
    if (BoxOwedChooseMem(kOwUseCopy, 1, 50ULL, 100ULL) != kOwUseMemory || BoxOwedChooseMem(kOwUseNone, 1, 50ULL, 100ULL) != kOwUseMemory)
        Fail("t1280 fold1c N1: a save's rows in memory do not answer ahead of the copy or none");
    if (BoxOwedChooseMem(kOwUseBeside, 1, 50ULL, 100ULL) != kOwUseBeside) Fail("t1280 fold1c N1: memory answers ahead of a current file beside the save");
    if (BoxOwedChooseMem(kOwUseCopy, 0, 50ULL, 100ULL) != kOwUseCopy || BoxOwedChooseMem(kOwUseCopy, 1, 150ULL, 100ULL) != kOwUseCopy
        || BoxOwedChooseMem(kOwUseNone, 1, 50ULL, 0ULL) != kOwUseNone)
        Fail("t1280 fold1c N1: memory answers with none kept, or kept by a request after the quick.save, or with no quick.save");
    const std::string st = T313ReadFile("../coop-plugin/store.cpp");
    if (st.find("if (BoxOwedWrite(dir, ob, g_bjOwedCopyAt[i], g_bjOwedReqFt[i]) != 0)") == std::string::npos || T1280Count(st, "BoxOwedMemFlush();") < 3
        || st.find("coopstore::HeldPathNoteUse(&g_bjOwedHeldPaths, fp, bp.kind, use == coopbrec::kOwUseBeside);") == std::string::npos)
        Fail("t1280 fold1c wiring: the landing, the flush after a load or the beside file's let-go rule is missing");
}

/* T-840: 'is this a player's character' reads the faction's RECORD id, not only the refillable stand-in table. The after-load
   window: the table is EMPTY (inTable 0) and the record id names a player's slot - the answer is 'player', never 'NPC'. */
void t_t840_player_char_record_rule()
{
    using namespace coopsp;
    /* the after-load window: table empty, record id present */
    if (PlayerCharClass(0, 1, 0, 0) != 1 || PlayerCharClass(0, 1, 0, 3) != 1) Fail("t840: table empty, record id coop-p<n> - not answered 'player' (the after-load window)");
    if (PlayerCharClass(0, 1, 0, -2) != 1) Fail("t840: table empty, the old two-player record id - not answered 'player'");
    /* the table still answers when it holds the faction; the watched player / own player faction always */
    if (PlayerCharClass(0, 1, 1, -1) != 1) Fail("t840: a faction in the stand-in table - not 'player'");
    if (PlayerCharClass(1, 0, 0, -1) != 1 || PlayerCharClass(1, 1, 0, -3) != 1) Fail("t840: the watched player / own player faction - not 'player'");
    /* an NPC: any other record id, not in the table */
    if (PlayerCharClass(0, 1, 0, -1) != 0) Fail("t840: another faction's character - not 'NPC'");
    /* unreadable: the faction pointer, or the record id with the table empty - never 'NPC' (a leaver's copy is then never taken) */
    if (PlayerCharClass(0, 0, 0, -1) != -1 || PlayerCharClass(0, 1, 0, -3) != -1) Fail("t840: an unreadable faction / record id - not -1");
    /* GoneTakeOverDecide takes only a 0: the after-load player answer is a drop, never a take */
    if (cooppg::GoneTakeOverDecide(PlayerCharClass(0, 1, 0, 2) == 0 ? 0 : 1, 1, 2, 0, 0, 0) != cooppg::kGtDrop)
        Fail("t840: a leaving player's character right after a load is taken over as an NPC");
    /* wiring: one rule for every caller */
    const std::string sp = T313ReadFile("../coop-plugin/spawn.cpp"), st = T313ReadFile("../coop-plugin/store.cpp");
    const size_t cl = sp.find("static int PlayerCharClassOf(::Character* c)");
    const size_t ru = (cl == std::string::npos) ? cl : sp.find("return coopsp::PlayerCharClass(own, plaus, inTable, rec);", cl);
    const size_t en = (cl == std::string::npos) ? cl : sp.find("}", cl);
    if (cl == std::string::npos || ru == std::string::npos || en == std::string::npos || ru > en) Fail("t840 wiring: PlayerCharClassOf does not answer by coopsp::PlayerCharClass");
    if (sp.find("static int PlayerCharSweepClassOf(::Character* c) { return PlayerCharClassOf(c); }") == std::string::npos) Fail("t840 wiring: the sweep does not share PlayerCharClassOf's rule");
    if (sp.find("const int rec = (plaus != 0 && inTable == 0) ? StandInRecordSlot(f) : -1;") == std::string::npos) Fail("t840 wiring: PlayerCharClassOf does not read the record id");
    if (st.find("if (IsPlayerFaction(f) || IsPeerFaction(f) || coopsp::IsStandInRecord(StandInRecordSlot(f)) != 0) continue;   // P3: not world state; T-840") == std::string::npos)
        Fail("t840 wiring: PublishSleepingPositions still reads the table only");
}

/* T-850: a game never discards a squad whose LIVING people another game runs; a received discard is not a death (squadbirth.h
   OtherRunRemovedMark, DestroyDeleteRun, GoneSetsDeletedMark). */
void t_t850_other_run_keep()
{
    using namespace sqbirth;
    /* the mark: an unload removal of another game's puppet read alive - only that */
    if (OtherRunRemovedMark(1, 1, 0) != 1) Fail("t850: a living puppet member put away at an unload did not mark its squad");
    if (OtherRunRemovedMark(1, 1, 1) != 0 || OtherRunRemovedMark(1, 1, -1) != 0) Fail("t850: a dead (or unread) puppet's body marked its squad - a dead squad's record would stay (ghost)");
    if (OtherRunRemovedMark(1, 0, 0) != 0) Fail("t850: this game's own person put away marked its squad");
    if (OtherRunRemovedMark(0, 1, 0) != 0) Fail("t850: a removal that is not an unload marked its squad");
    /* living puppet member -> keep: the incident's verdict (discarding, emptied by the unload: -2) and the plain and mod-removal roads */
    if (DestroyDeleteRun(1, 0, 1, 0, 1, -2, 1, 0) != kDelRunKept) Fail("t850: the incident - a discarding squad emptied by the unload of another game's living people - still sent the discard delete");
    if (DestroyDeleteRun(1, 0, 1, 0, 1, 3, 0, 0) != kDelRunKept || DestroyDeleteRun(1, 0, 1, 0, 1, -1, 0, 0) != kDelRunKept) Fail("t850: a marked discarding squad still sent the discard delete");
    if (DestroyDeleteRun(1, 0, 1, 0, 0, -1, 0, 0) != kDelRunKept || DestroyDeleteRun(1, 0, 1, 0, 0, -2, 0, 0) != kDelRunKept) Fail("t850: a marked squad still sent the plain delete");
    if (DestroyDeleteRun(1, 1, 1, 0, 0, -1, 0, 0) != kDelRunKept) Fail("t850: a marked squad also mod-removed took the mod keep (its not-placed-again rule) - its people live elsewhere");
    if ((int)kDelRunKept == (int)kDelModKept || (int)kDelRunKept == (int)kDelDiscard || (int)kDelRunKept == (int)kDelPlain || (int)kDelRunKept == (int)kDelNone) Fail("t850: kDelRunKept is not its own verdict");
    /* the running game's own death and the wipe-out the death watch saw: deleted as before; the same-id keep and an unbound squad stay */
    if (DestroyDeleteRun(1, 0, 1, 1, 1, -2, 1, 0) != kDelPlain || DestroyDeleteRun(1, 1, 1, 1, 0, -1, 0, 0) != kDelPlain) Fail("t850: a wipe-out was kept because the squad also lost another game's people");
    if (DestroyDeleteRun(1, 0, 1, 0, 1, -2, 1, 1) != kDelNone) Fail("t850: the mark overrode the same-id keep");
    if (DestroyDeleteRun(1, 0, 0, 0, 1, -2, 1, 0) != kDelNone) Fail("t850: an unbound squad's destroy sent or kept something");
    /* all copies dead, or this game's own people only (no mark): every input answers as before */
    {
        int same = 1, keptOnlyWhenMarked = 1;
        for (int m = 0; m <= 1; ++m) for (int b = 0; b <= 1; ++b) for (int d = 0; d <= 1; ++d) for (int g = 0; g <= 1; ++g)
        for (int l = -2; l <= 3; ++l) for (int u = 0; u <= 1; ++u) for (int sh = 0; sh <= 1; ++sh)
        {
            const int was = DestroyDeleteMod(m, b, d, g, l, u, sh);
            if (DestroyDeleteRun(0, m, b, d, g, l, u, sh) != was) same = 0;
            const int now = DestroyDeleteRun(1, m, b, d, g, l, u, sh);
            const int want = (d == 0 && (was == kDelDiscard || was == kDelPlain || was == kDelModKept)) ? (int)kDelRunKept : was;
            if (now != want) keptOnlyWhenMarked = 0;
        }
        if (same != 1) Fail("t850: an unmarked squad (dead copies, or this game's own people only) answered differently from before");
        if (keptOnlyWhenMarked != 1) Fail("t850: the mark did not turn exactly the discard / plain / mod keep (no wipe-out) into the keep");
    }
    /* a walk: three living puppets put away (one mark), the destroy keeps the record and takes the mark; a later squad at the address
       (nothing marked) discards as before; a squad whose only removed puppet was dead discards as before */
    {
        std::set<void*> marks; void* const pa = (void*)0x10000100; void* const pb = (void*)0x10000200;
        for (int i = 0; i < 3; ++i) if (OtherRunRemovedMark(1, 1, 0) != 0) marks.insert(pa);
        if (OtherRunRemovedMark(1, 1, 1) != 0) marks.insert(pb);
        if (DestroyDeleteRun(ModRemovedTake(&marks, pa), 0, 1, 0, 1, -2, 1, 0) != kDelRunKept) Fail("t850 walk: the squad that lost living puppets sent a delete");
        if (DestroyDeleteRun(ModRemovedTake(&marks, pa), 0, 1, 0, 1, -2, 1, 0) != kDelDiscard) Fail("t850 walk: the mark outlived its destroy");
        if (DestroyDeleteRun(ModRemovedTake(&marks, pb), 0, 1, 0, 1, -2, 1, 0) != kDelDiscard) Fail("t850 walk: a squad whose removed puppet was dead kept its record");
    }
    /* a received gone: a discard sets no permanent mark, a death does; the forwarded payload's DISCARD word is read after the stamp */
    if (GoneSetsDeletedMark(1) != 0) Fail("t850: a received discard set the permanent deleted mark");
    if (GoneSetsDeletedMark(0) != 1) Fail("t850: a received death delete did not set the permanent deleted mark");
    {
        std::vector<char> head(10, 'x'); head.insert(head.end(), 8, '\0');   /* a string's bytes, then the stamp's two halves */
        std::vector<char> disc = head; townrefill::AppendGoneDiscard(&disc);
        std::vector<char> town = head; townrefill::AppendGoneTown(&town, "12-gamedata.base");
        if (townrefill::GoneIsDiscard(&disc[0], disc.size(), 18) != 1) Fail("t850: a discard's payload was not read as a discard");
        if (townrefill::GoneIsDiscard(&town[0], town.size(), 18) != 0 || townrefill::GoneIsDiscard(&head[0], head.size(), 18) != 0) Fail("t850: a death's payload (a town, or nothing after the stamp) was read as a discard");
        if (GoneSetsDeletedMark(townrefill::GoneIsDiscard(&disc[0], disc.size(), 18)) != 0 || GoneSetsDeletedMark(townrefill::GoneIsDiscard(&head[0], head.size(), 18)) != 1) Fail("t850: the payload's answer did not decide the mark");
    }
}
/* T-850: the wiring - both destroy roads (main and off-thread drain) ask DestroyDeleteRun with the mark; the mark is set from the puppet
   flag at the unload removal, on both threads; the received gone and the dropped gone honour the DISCARD word; the refused put-away logs. */
void t_t850_wiring()
{
    const std::string st = T313ReadFile("../coop-plugin/store.cpp"), sp = T313ReadFile("../coop-plugin/spawn.cpp");
    if (st.empty() || sp.empty()) { Fail("t850 wiring: a source file could not be read"); return; }
    /* the main destroy */
    if (st.find("const int otherRun = OtherRunTake(platoon, &notes);") == std::string::npos
        || st.find("const int del = sqbirth::DestroyDeleteRun(otherRun, modRemoved, 1, diedOut ? 1 : 0, discarding, livingNow, emptiedByUnload, heldByOther);") == std::string::npos
        || st.find("if (del == sqbirth::kDelRunKept) OtherRunKeptNote(worldId, was, \"\");") == std::string::npos) Fail("t850 wiring: the main-thread destroy does not decide with the 'other game runs its people' mark");
    /* the off-thread twin: the same answer */
    if (st.find("const int offRun = boundHere ? OtherRunTake(platoon, &offNotes) : sqbirth::kRunNo;") == std::string::npos
        || st.find("const int offDel = sqbirth::DestroyDeleteRun(offRun, offMod, boundHere ? 1 : 0,") == std::string::npos
        || st.find("offDel == sqbirth::kDelRunKept)") == std::string::npos) Fail("t850 wiring: the off-thread destroy drain does not decide the same way");
    {
        const size_t dg = st.find("void DrainGoneEntry(const std::string& engineId, void* platoon, long long stamp, unsigned long long gen, int living)");
        const size_t dr = dg == std::string::npos ? dg : st.find("coop::DrainOffThreadDespawns();", dg);
        const size_t bh = dg == std::string::npos ? dg : st.find("const bool boundHere", dg);
        if (dg == std::string::npos || dr == std::string::npos || bh == std::string::npos || dr > bh) Fail("t850 wiring: the off-thread destroy drain does not apply the queued removals before it decides");
    }
    if (st.find("g_otherRunRemoved.clear();") == std::string::npos) Fail("t850 wiring: the mark is not cleared at the world teardown");
    { size_t n = 0; for (size_t at = st.find("g_otherRunRemoved.erase(platoon);"); at != std::string::npos; at = st.find("g_otherRunRemoved.erase(platoon);", at + 1)) ++n; if (n < 3) Fail("t850 wiring: the mark does not go with the platoon (forget, unbind, reused address)"); }
    /* the mark's source: the puppet flag, read before the puppet goes; the squad and alive read on both threads */
    {
        const size_t re = sp.find("const int runElsewhere = HasPuppet(uid) ? 1 : 0;");
        const size_t dp = re == std::string::npos ? re : sp.find("DropPuppet(uid);", re);
        if (re == std::string::npos || dp == std::string::npos || dp - re > 400) Fail("t850 wiring: the puppet flag is not read just before the puppet is dropped");
    }
    const std::string note = "coop::StoreNoteOtherRunRemoved(noteSq, uid, (g_drainingOffThread == 0 ? runElsewhere : g_drainingNotMine) != 0 ? 1 : 0, noteDead);";
    if (sp.find(note) == std::string::npos) Fail("t850 wiring: the unload removal does not note the squad from the puppet flag and the alive read");
    if (sp.find("g_offThreadDespawn[i].sq = sq; g_offThreadDespawn[i].deadRead =") == std::string::npos || sp.find("g_drainingSq = dsq; g_drainingDeadRead = ddr; g_drainingNotMine = dnm; NotifyDespawn(") == std::string::npos)
        Fail("t850 wiring: an off-thread removal does not carry its squad and alive read to the drain");
    if (st.find("if (!OnMainThread() || kind == sqbirth::kLostNone || uid == 0) return;") == std::string::npos || st.find("void StoreNoteOtherRunRemoved(void* platoon, unsigned int uid, int kind, int deadRead)") == std::string::npos)
        Fail("t850 wiring: StoreNoteOtherRunRemoved is not the main-thread note keyed on the puppet flag");
    /* D2: the received gone and the dropped gone */
    if (st.find("ApplyRemoteGoneImpl(wid, (long long)(((unsigned long long)hi << 32) | lo), \"store\", townrefill::GoneIsDiscard(payload.empty() ? 0 : &payload[0], payload.size(), at + 8));") == std::string::npos)
        Fail("t850 wiring: the received RECORD_GONE does not read the DISCARD word");
    if (st.find("if (sqbirth::GoneSetsDeletedMark(discard) == 0) { DropEntryHere(worldId, false); ++g_goneDiscardRecv; }") == std::string::npos) Fail("t850 wiring: a received discard still sets the deleted mark");
    {
        const size_t gb = st.find("void GoneBitBeforeDrop(const std::vector<char>& payload)");
        const size_t sk = gb == std::string::npos ? gb : st.find("if (sqbirth::GoneSetsDeletedMark(townrefill::GoneIsDiscard(", gb);
        const size_t bs = gb == std::string::npos ? gb : st.find("if (DeletedBitSet(wid)) ++g_goneBitAtDrop;", gb);
        if (gb == std::string::npos || sk == std::string::npos || bs == std::string::npos || sk > bs) Fail("t850 wiring: a dropped discard still sets the deleted mark before its type is read");
    }
    {
        const size_t ds = st.find("void DiscardDeleteSend(");
        const size_t dd = ds == std::string::npos ? ds : st.find("DropEntryHere(worldId, false);", ds);
        const size_t gi = ds == std::string::npos ? ds : st.find("g_goneDiscard.insert(worldId);", ds);
        if (ds == std::string::npos || dd == std::string::npos || gi == std::string::npos || gi - dd > 80) Fail("t850 wiring: the sent discard's own no-mark rule changed");
    }
    /* 3: the refused put-away's line */
    if (st.find("\"[STORE] SLEEP REFUSED worldId=\" + sleepId") == std::string::npos || st.find("if (g_sleepRefusedDeletedLines < 20)") == std::string::npos) Fail("t850 wiring: the refused put-away has no capped line");
    if (st.find(" otherRun[noted,notedAtGoneDrain,deadSkipped,unbound,capFull,kept,held]=") == std::string::npos || st.find(" goneDiscard[recvNoMark,dropNoMark]=") == std::string::npos) Fail("t850 wiring: the REPORT counters are missing");
}

/* T-850: the world server's applied delete - a DISCARD sets no permanent deleted mark (or a relink's DELETED_BITS brings it back to a
   game whose living copy then cannot be written); a plain or wipe-out delete keeps it. The payload is read whole (townrefill.h
   GonePayloadIsDiscard), as the server's delete job holds it. */
void t_t850_server_discard_no_bit()
{
    const std::string wid = "Hub Natives_30";
    std::vector<char> head; townrefill::PutU32(&head, (unsigned)wid.size()); head.insert(head.end(), wid.begin(), wid.end());
    townrefill::PutU32(&head, 1794105624u); townrefill::PutU32(&head, 0u);   /* the stamp's two halves */
    std::vector<char> disc = head; townrefill::AppendGoneDiscard(&disc);
    std::vector<char> town = head; townrefill::AppendGoneTown(&town, "12-gamedata.base");
    if (townrefill::GonePayloadIsDiscard(disc) != 1) Fail("t850 server: a discard delete's payload was not read as a discard");
    if (townrefill::GonePayloadIsDiscard(head) != 0 || townrefill::GonePayloadIsDiscard(town) != 0) Fail("t850 server: a plain / wipe-out delete's payload was read as a discard");
    std::vector<char> shortp(disc.begin(), disc.begin() + 6), badLen = disc; badLen[0] = (char)0x7F;
    if (townrefill::GonePayloadIsDiscard(shortp) != 0 || townrefill::GonePayloadIsDiscard(badLen) != 0 || townrefill::GonePayloadIsDiscard(std::vector<char>()) != 0)
        Fail("t850 server: an unreadable payload was read as a discard (it must keep the mark, as before)");
    if (sqbirth::GoneSetsDeletedMark(townrefill::GonePayloadIsDiscard(disc)) != 0) Fail("t850 server: an applied discard sets the permanent deleted mark");
    if (sqbirth::GoneSetsDeletedMark(townrefill::GonePayloadIsDiscard(head)) != 1 || sqbirth::GoneSetsDeletedMark(townrefill::GonePayloadIsDiscard(town)) != 1)
        Fail("t850 server: an applied death delete does not set the permanent deleted mark");
    /* wiring: the delete job's completion decides the bit from its payload */
    const std::string sv = T313ReadFile("../coop-store/store_main.cpp");
    const size_t fd = sv.find("else if (j->from == kFromDelete)");
    const size_t gd = fd == std::string::npos ? fd : sv.find("const int goneDiscard = townrefill::GonePayloadIsDiscard(j->payload);", fd);
    const size_t sb = fd == std::string::npos ? fd : sv.find("if (sqbirth::GoneSetsDeletedMark(goneDiscard) != 0) SetBit(id);", fd);
    const size_t bc = fd == std::string::npos ? fd : sv.find("MSG_RECORD_GONE", fd);
    if (fd == std::string::npos || gd == std::string::npos || sb == std::string::npos || bc == std::string::npos || gd > sb || sb > bc)
        Fail("t850 server wiring: the delete's completion does not decide the deleted mark by the DISCARD word");
    { size_t n = 0; for (size_t at = sv.find("SetBit(id);"); at != std::string::npos; at = sv.find("SetBit(id);", at + 1)) ++n; if (n != 1) Fail("t850 server wiring: another unconditional SetBit(id) site exists"); }
    if (sv.find(",noDeletedMark=\" + N(g_discardNoBit)") == std::string::npos) Fail("t850 server wiring: the noDeletedMark counter is not on the REPORT");
}

/* T-850 fold 1: the live answer at the destroy (M1 / M3 / M4) - each lost person's fate now, the squad's answer, the held delete's
   resolution, the notes' clearing, the discard's same-second rule (L2). Decisions, not source text. */
void t_t850f1_live_answer()
{
    using namespace sqbirth;
    /* a person: another game's puppet put away here, or its copy removed on its runner's say-so alive -> runs elsewhere until it died */
    if (PersonRunsElsewhere(kLostRunsThere, 0, 0, 0) != kRunYes || PersonRunsElsewhere(kLostAwayThere, 0, 0, 0) != kRunYes) Fail("t850f1: a living person run (or put away) by another game did not answer 'runs elsewhere'");
    if (PersonRunsElsewhere(kLostRunsThere, 1, 0, 1) != kRunNo || PersonRunsElsewhere(kLostAwayThere, 1, 0, 1) != kRunNo) Fail("t850f1: a person its runner said died still keeps its squad (ghost)");
    if (PersonRunsElsewhere(kLostNone, 0, 0, 1) != kRunNo) Fail("t850f1: no note answered 'runs elsewhere'");
    /* M4: this game's own person offered at its put-away - the hand-over's outcome decides, never its timing */
    if (PersonRunsElsewhere(kLostHandedOff, 0, 1, 0) != kRunPending || PersonRunsElsewhere(kLostHandedOff, 0, 1, 1) != kRunPending) Fail("t850f1: an open hand-over was decided before it settled");
    if (PersonRunsElsewhere(kLostHandedOff, 0, 0, 1) != kRunYes) Fail("t850f1: a person another game took at the hand-over did not keep its squad");
    if (PersonRunsElsewhere(kLostHandedOff, 0, 0, 0) != kRunNo) Fail("t850f1: a person nobody took (put away asleep here) kept its squad");
    if (PersonRunsElsewhere(kLostHandedOff, 1, 0, 1) != kRunNo) Fail("t850f1: a handed-off person that died since kept its squad");
    /* the squad: any one living elsewhere keeps it; else an open hand-over holds; else nobody */
    if (SquadRunAnswer(1, 1) != kRunYes || SquadRunAnswer(1, 0) != kRunYes || SquadRunAnswer(0, 1) != kRunPending || SquadRunAnswer(0, 0) != kRunNo) Fail("t850f1: the squad's answer from its people's is wrong");
    /* the destroy: pending holds exactly where 'yes' keeps; no answer = as before */
    {
        int ok = 1;
        for (int m = 0; m <= 1; ++m) for (int d = 0; d <= 1; ++d) for (int g = 0; g <= 1; ++g) for (int l = -2; l <= 3; ++l) for (int u = 0; u <= 1; ++u) for (int sh = 0; sh <= 1; ++sh)
        {
            const int was = DestroyDeleteMod(m, 1, d, g, l, u, sh);
            const int keeps = DestroyDeleteRun(kRunYes, m, 1, d, g, l, u, sh), holds = DestroyDeleteRun(kRunPending, m, 1, d, g, l, u, sh);
            if (DestroyDeleteRun(kRunNo, m, 1, d, g, l, u, sh) != was) ok = 0;
            if ((keeps == kDelRunKept) != (holds == kDelRunHeld)) ok = 0;
            if (keeps != kDelRunKept && holds != was) ok = 0;
        }
        if (ok != 1) Fail("t850f1: the held delete does not stand exactly where the keep stands");
        if ((int)kDelRunHeld == (int)kDelRunKept || (int)kDelRunHeld == (int)kDelModKept || (int)kDelRunHeld == (int)kDelDiscard || (int)kDelRunHeld == (int)kDelPlain || (int)kDelRunHeld == (int)kDelNone) Fail("t850f1: kDelRunHeld is not its own verdict");
    }
    /* the held delete at each look: taken -> kept; settled with nobody -> the destroy's own delete; open -> still held */
    if (RunHeldResolve(kRunYes, kDelDiscard) != kDelRunKept || RunHeldResolve(kRunPending, kDelDiscard) != kDelRunHeld) Fail("t850f1: a held delete did not keep (taken) or wait (open)");
    if (RunHeldResolve(kRunNo, kDelDiscard) != kDelDiscard || RunHeldResolve(kRunNo, kDelPlain) != kDelPlain || RunHeldResolve(kRunNo, kDelModKept) != kDelModKept) Fail("t850f1: a hand-over nobody took did not send the destroy's own delete");
    /* a walk of M4: the offer open at the destroy -> held; a tick with it open -> held; it settles taken -> kept / asleep -> the discard */
    {
        int pending = 1, taken = 0;
        const int atDestroy = DestroyDeleteRun(SquadRunAnswer(0, PersonRunsElsewhere(kLostHandedOff, 0, pending, taken) == kRunPending), 0, 1, 0, 1, -2, 1, 0);
        if (atDestroy != kDelRunHeld) Fail("t850f1 walk: an open hand-over did not hold the discard");
        pending = 0; taken = 1;
        const int pa = PersonRunsElsewhere(kLostHandedOff, 0, pending, taken);
        if (RunHeldResolve(SquadRunAnswer(pa == kRunYes, pa == kRunPending), kDelDiscard) != kDelRunKept) Fail("t850f1 walk: the hand-over taken did not keep the record");
        taken = 0;
        const int pb = PersonRunsElsewhere(kLostHandedOff, 0, pending, taken);
        if (RunHeldResolve(SquadRunAnswer(pb == kRunYes, pb == kRunPending), kDelDiscard) != kDelDiscard) Fail("t850f1 walk: the hand-over nobody took did not send the discard");
    }
    /* M1: living members here again at the keep question, or the squad's sleep, forget the notes */
    if (OtherRunNotesCleared(3) != 1 || OtherRunNotesCleared(0) != 0 || OtherRunNotesCleared(-2) != 0 || OtherRunNotesCleared(-1) != 0) Fail("t850f1: the notes are not cleared exactly when living members are here again");
    {
        std::map<void*, std::map<unsigned int, int> > notes; void* const pa = (void*)0x10000100;
        notes[pa][77u] = kLostRunsThere;   /* a straggler of another game's people wandered out */
        if (OtherRunNotesCleared(4) != 0) notes.erase(pa);   /* the next keep question: this game's own members still live here */
        const int answer = notes.count(pa) != 0 ? kRunYes : kRunNo;
        if (DestroyDeleteRun(answer, 0, 1, 0, 0, -2, 0, 0) != kDelPlain) Fail("t850f1 walk (M1): a squad later emptied by hiring kept its record from an old straggler's note");
    }
    /* L2: a discard loses to a write in its own second; a death delete only to a newer write */
    if (GoneIgnoredAsOlder(1, 100, 100) != 1 || GoneIgnoredAsOlder(1, 101, 100) != 1 || GoneIgnoredAsOlder(1, 99, 100) != 0) Fail("t850f1: a discard was not ignored against a same-second or newer write");
    if (GoneIgnoredAsOlder(0, 100, 100) != 0 || GoneIgnoredAsOlder(0, 101, 100) != 1) Fail("t850f1: a death delete's older-than rule changed");
}
/* T-850 fold 1: the wiring of the live answer - the notes from every removal road, the drain before both destroys, the hold's tick */
void t_t850f1_wiring()
{
    const std::string st = T313ReadFile("../coop-plugin/store.cpp"), sp = T313ReadFile("../coop-plugin/spawn.cpp");
    if (st.empty() || sp.empty()) { Fail("t850f1 wiring: a source file could not be read"); return; }
    {   /* M2: the main destroy applies the queued off-thread removals before it takes the notes */
        const size_t dp = st.find("void detour_destroyPlatoon(void* faction, void* platoon)");
        const size_t dr = dp == std::string::npos ? dp : st.find("coop::DrainOffThreadDespawns();", dp);
        const size_t ot = dp == std::string::npos ? dp : st.find("const int otherRun = OtherRunTake(platoon, &notes);", dp);
        if (dp == std::string::npos || dr == std::string::npos || ot == std::string::npos || dr > ot) Fail("t850f1 wiring (M2): the main-thread destroy does not apply queued removals before it decides");
    }
    if (st.find("else if (del == sqbirth::kDelRunHeld) OtherRunHoldDelete(worldId, stamp, was, modMade, notes, \"\");") == std::string::npos
        || st.find("offDel == sqbirth::kDelRunHeld)") == std::string::npos) Fail("t850f1 wiring (M4): a destroy does not hold its delete for an open hand-over");
    if (st.find("RunHeldTick") != std::string::npos) Fail("t850f1 wiring (fold 1b): a per-tick look at the held deletes is back");
    if (st.find("if (sqbirth::OtherRunNotesCleared(living) != 0 && g_otherRunRemoved.erase(platoon) != 0) ++g_otherRunCleared;") == std::string::npos) Fail("t850f1 wiring (M1): the keep question does not clear the notes");
    {
        const size_t od = st.find("if (g_otherRunRemoved.erase(platoon) != 0) ++g_otherRunCleared;   /* T-850 fold 1 (M1): put to sleep here");
        if (od == std::string::npos) Fail("t850f1 wiring (M1): the sleep does not clear the notes");
    }
    if (sp.find("if (HandoffReleaseHolds(uid) != 0) coop::StoreNoteOtherRunRemoved(noteSq, uid, 3, noteDead);") == std::string::npos) Fail("t850f1 wiring (M4): an own person offered at its put-away is not noted");
    {   /* M3: a copy removed on its runner's say-so alive, noted while the object is whole (before the destroy) */
        const size_t rl = sp.find("static int RemoveLocalCopy(unsigned int uid, ::Character* c, const char* what, bool keepMedical = false)");
        const size_t nt = rl == std::string::npos ? rl : sp.find("coop::StoreNoteOtherRunRemoved(sq, uid, 2, coop::StoreIsDeadPod((void*)c));", rl);
        const size_t ds = rl == std::string::npos ? rl : sp.find("bool destroyed = DestroyLocalObject(c);", rl);
        if (rl == std::string::npos || nt == std::string::npos || ds == std::string::npos || nt > ds) Fail("t850f1 wiring (M3): a copy removed on its runner's say-so is not noted before its destroy");
        if (sp.find("if (std::strcmp(what, \"DESPAWN\") != 0 || g_copyRemovalAlive != 0)") == std::string::npos) Fail("t850f1 wiring (M3): a death (DESPAWN) is not told from an UNLOAD");
    }
    if (sp.find("g_copyRemovalAlive = 1;") == std::string::npos || sp.find("if (g_copyRemovalAlive == 0) coop::StoreOtherRunDied(uid);") == std::string::npos) Fail("t850f1 wiring: the runner's DESPAWN does not mark the person died, or an UNLOAD is taken for one");
    if (sp.find("g_offThreadDespawn[i].notMine = (uid != 0 && !net::IsUidMineAnyThread(uid)) ? 1 : 0;") == std::string::npos) Fail("t850f1 wiring (L1): an off-thread removal is not decided at its hook");
    if (st.find("sqbirth::GoneIgnoredAsOlder(discard, it->second.writtenAt, stamp) != 0") == std::string::npos) Fail("t850f1 wiring (L2): the received gone does not use the discard's same-second rule");
}

/* T-850 fold 1 (T2198, the reverse case): a runner leaving an area another game still has LOADED keeps its born-not-kept squads (they
   sleep with their records; the people are offered to that game) - never the engine's discard under the other game's eyes. */
void t_t850f1_reverse_keep()
{
    using namespace sqbirth;
    if (OtherShowsArea(1, 0) != 1 || OtherShowsArea(0, 1) != 1 || OtherShowsArea(1, 1) != 1) Fail("t850f1 reverse: another game holding or having the area loaded did not count");
    if (OtherShowsArea(0, 0) != 0 || OtherShowsArea(-1, -1) != 0 || OtherShowsArea(0, -1) != 0 || OtherShowsArea(-1, 0) != 0) Fail("t850f1 reverse: nobody else there (or no fresh map) counted as another game showing the area");
    /* T2198's Wolves_7: born not kept, no home, no player's character - A leaves while B still has the Hub loaded: kept, not discarded */
    if (KeepDecide(5, kBirthDiscard, 0, 0, 0, OtherShowsArea(0, 1), 1) != kKeepOtherHolder || KeepAnswers(KeepDecide(5, kBirthDiscard, 0, 0, 0, OtherShowsArea(0, 1), 1)) != 1)
        Fail("t850f1 reverse: a squad whose area another game has loaded was left to the engine's discard");
    /* the last game to leave: nobody else has the area - the engine's own answer, as in single player */
    if (KeepDecide(5, kBirthDiscard, 0, 0, 0, OtherShowsArea(0, 0), 1) != kKeepEngine) Fail("t850f1 reverse: the last game's discard changed");
    /* a dead squad is not kept for the other game's view */
    if (KeepDecide(0, kBirthDiscard, 0, 0, 0, OtherShowsArea(0, 1), 1) != kKeepDeadRelease) Fail("t850f1 reverse: a squad with nobody living was kept because another game has the area loaded");
    const std::string st = T313ReadFile("../coop-plugin/store.cpp");
    const size_t f = st.find("int OneKeepAt(void* platoon, int asleep, float x, float z, void* faction)");   /* T-1046 fix 2: the bare bits are the stale-map answer */
    const size_t u = f == std::string::npos ? f : st.find("const int shows = sqbirth::OtherShowsArea(held, held == 1 ? 0 : OtherLoadedTS(sec));", f);
    if (f == std::string::npos || u == std::string::npos || u - f > 1600) Fail("t850f1 reverse wiring: the keep question does not read whether another game has the area loaded");   /* T-1046 attempt 2: 1200 -> 1600 (the kept-part read ahead of it) */
}

/* T-850 fold 1b: the held deletes are decided by EVENTS - each release end of a person (RunHeldSettle) and the bind of the id again
   (RunHeldRebound) - not a per-tick look. A model of the registry over the real decisions: settle-taken -> kept, settle-nobody -> the
   destroy's own delete, rebind -> dropped; another person's open offer keeps the hold through one settle. */
namespace {
struct T850Held { int was; std::map<unsigned int, int> notes; };
/* one release end, as RunHeldSettle: the person's state is (pending, taken) per uid in `st` */
int T850Settle(std::map<std::string, T850Held>* held, unsigned int uid, const std::map<unsigned int, std::pair<int, int> >& st, std::map<std::string, int>* out)
{
    int n = 0;
    std::vector<std::string> done;
    for (std::map<std::string, T850Held>::iterator h = held->begin(); h != held->end(); ++h)
    {
        if (h->second.notes.count(uid) == 0) continue;
        int anyYes = 0, anyPending = 0;
        for (std::map<unsigned int, int>::const_iterator k = h->second.notes.begin(); k != h->second.notes.end(); ++k)
        {
            const std::map<unsigned int, std::pair<int, int> >::const_iterator f = st.find(k->first);
            const int a = sqbirth::PersonRunsElsewhere(k->second, 0, f != st.end() ? f->second.first : 0, f != st.end() ? f->second.second : 0);
            if (a == sqbirth::kRunYes) anyYes = 1; else if (a == sqbirth::kRunPending) anyPending = 1;
        }
        const int r = sqbirth::RunHeldResolve(sqbirth::SquadRunAnswer(anyYes, anyPending), h->second.was);
        if (r == sqbirth::kDelRunHeld) continue;
        (*out)[h->first] = r; done.push_back(h->first); ++n;
    }
    for (size_t i = 0; i < done.size(); ++i) held->erase(done[i]);
    return n;
}
}
void t_t850f1b_events()
{
    using namespace sqbirth;
    std::map<std::string, T850Held> held; std::map<std::string, int> out; std::map<unsigned int, std::pair<int, int> > st;
    held["Wolves_7"].was = kDelDiscard; held["Wolves_7"].notes[11u] = kLostHandedOff;
    held["HNO_30"].was = kDelPlain; held["HNO_30"].notes[21u] = kLostHandedOff; held["HNO_30"].notes[22u] = kLostHandedOff;
    held["Dust_3"].was = kDelDiscard; held["Dust_3"].notes[31u] = kLostHandedOff;
    st[11u] = std::make_pair(1, 0); st[21u] = std::make_pair(1, 0); st[22u] = std::make_pair(1, 0); st[31u] = std::make_pair(1, 0);
    /* settle-taken -> kept (only the squad naming the uid is decided) */
    st[11u] = std::make_pair(0, 1);
    if (T850Settle(&held, 11u, st, &out) != 1 || out["Wolves_7"] != kDelRunKept || held.count("Wolves_7") != 0 || held.size() != 2) Fail("t850f1b: a settle that another game took did not keep exactly that squad's record");
    /* settle-nobody while another person's offer is open -> still held; then nobody at all -> the destroy's own delete */
    st[21u] = std::make_pair(0, 0);
    if (T850Settle(&held, 21u, st, &out) != 0 || held.count("HNO_30") != 1) Fail("t850f1b: a squad was decided while another of its people's offers was open");
    st[22u] = std::make_pair(0, 0);
    if (T850Settle(&held, 22u, st, &out) != 1 || out["HNO_30"] != kDelPlain) Fail("t850f1b: a squad whose offers all ended with nobody taking one did not send its own delete");
    /* a settle naming no held squad decides nothing */
    if (T850Settle(&held, 99u, st, &out) != 0 || held.size() != 1) Fail("t850f1b: a settle of an unnoted person decided a held squad");
    /* rebind -> dropped, nothing sent */
    if (RunHeldOnRebind(held.count("Dust_3") != 0 ? 1 : 0) != 1 || RunHeldOnRebind(0) != 0) Fail("t850f1b: a rebind did not drop the hold");
    held.erase("Dust_3");
    if (!held.empty() || out.count("Dust_3") != 0) Fail("t850f1b: a rebound squad's delete was sent");
    /* wiring: the release ends call the settle after the release state is updated; the bind calls the rebound */
    const std::string ho = T313ReadFile("../coop-plugin/handoff.cpp"), st2 = T313ReadFile("../coop-plugin/store.cpp");
    {
        const size_t ra = ho.find("static void RelAccept(const RelMember& rm, int slot, unsigned int peer, unsigned int gen)");
        const size_t ow = ra == std::string::npos ? ra : ho.find("net::ReleaseLocalOwner(uid, peer, gen);", ra);
        const size_t se = ra == std::string::npos ? ra : ho.find("StoreRunHeldSettle(uid);", ra);
        if (ra == std::string::npos || ow == std::string::npos || se == std::string::npos || se < ow) Fail("t850f1b wiring: RelAccept does not settle after the owner record moves");
        const size_t as = ho.find("static int RelAsleep(const RelMember& rm, int cancelled, unsigned int settleGen)");
        const size_t wh = as == std::string::npos ? as : ho.find("if (net::IsUidMine(uid)) WithdrawHeldUnload(uid);", as);
        const size_t s2 = as == std::string::npos ? as : ho.find("StoreRunHeldSettle(uid);", as);
        if (as == std::string::npos || wh == std::string::npos || s2 == std::string::npos || s2 < wh) Fail("t850f1b wiring: RelAsleep does not settle at its end");
        if (ho.find("r.mem.erase(r.mem.begin() + (long)k); StoreRunHeldSettle(gone); }") == std::string::npos) Fail("t850f1b wiring: a member no longer this game's does not settle");
    }
    if (st2.find("void StampBind(void* platoon) { g_bindGenOf[platoon] = (unsigned long long)(++g_bindGen); RunHeldRebound(platoon); }") == std::string::npos) Fail("t850f1b wiring: the bind does not end a hold for its id");
    if (st2.find("if (h->second.notes.count(uid) == 0) continue;   /* not this person's squad */") == std::string::npos) Fail("t850f1b wiring: RunHeldSettle does not resolve only the squads naming the uid");
}

/* T-850 fold 2 (T2217, FIX 1): another game's delete of a squad whose live keeper holds its area is HELD (the held-delete list), applied
   once the keeper lets the squad go or the sender writes it, refused when the record is written again; every other verdict unchanged */
void t_t850f2_keeper_hold()
{
    using namespace sqwreg;
    /* T2217's Drifters: A (slot 0) deletes a squad B (slot 1) registered as its keeper and holds the area of - held, plain and discard */
    JudgeIn in; in.kind = kKindDelete; in.registered = 1; in.writer = 1; in.storedGen = 4; in.writerLive = 1; in.writerReleased = 0; in.writerKeeper = 1;
    in.holder = 1; in.holderLive = 1; in.sender = 0; in.writerLoadedHere = 1;
    if (KeeperHoldsDelete(in) != 1 || Judge(in) != kSwHoldDelete) Fail("t850f2: A's plain delete of a squad B keeps and holds the area of was not held (T2217's TAKEN)");
    in.kind = kKindDiscard; if (Judge(in) != kSwHoldDelete) Fail("t850f2: A's discard delete of a squad B keeps and holds the area of was not held");
    if (DeleteReleases(kSwHoldDelete, kKindDiscard) != 0 || Takes(kSwHoldDelete) != 0) Fail("t850f2: a held delete released the squad or counted as taken");
    in.kind = kKindDelete;
    /* the keeper lets the squad go: released, its game gone, the area another game's (here the sender's), or nobody live holds it */
    { JudgeIn x = in; x.writerReleased = 1; if (KeeperHoldsDelete(x) != 0 || Judge(x) != kSwTakeover) Fail("t850f2: a released keeper still held another game's delete"); }
    { JudgeIn x = in; x.writerLive = 0; if (KeeperHoldsDelete(x) != 0 || Judge(x) != kSwTakeover) Fail("t850f2: a keeper whose game left still held another game's delete"); }
    { JudgeIn x = in; x.holder = 0; if (KeeperHoldsDelete(x) != 0 || Judge(x) != kSwTakeover) Fail("t850f2: a keeper that no longer holds the area still held the new holder's delete"); }
    { JudgeIn x = in; x.holder = 2; if (Judge(x) != kSwTakeover) Fail("t850f2: a keeper that lost the area to a third game still held a delete"); }
    { JudgeIn x = in; x.holderLive = 0; if (KeeperHoldsDelete(x) != 0 || Judge(x) != kSwTakeover) Fail("t850f2: a keeper standing for an area nobody live holds held a delete (only the live holder holds)"); }
    /* unchanged: a writer that runs the people refuses (T2217's EP_2); the writer's own delete is the writer's; a full write and a RUNS take of
       the game that runs the people take over a keeper as before */
    { JudgeIn x = in; x.writerKeeper = 0; if (Judge(x) != kSwRefuseNotWriter) Fail("t850f2: (control) a non-holder's delete of a squad its writer runs was not refused"); }
    { JudgeIn x = in; x.sender = 1; if (Judge(x) != kSwWriter) Fail("t850f2: (control) the keeper's own delete was not the writer's"); }
    { JudgeIn x = in; x.kind = kKindFull; if (Judge(x) != kSwTakeover) Fail("t850f2: (control) the runner's full write no longer takes over a keeper"); }
    { JudgeIn x = in; x.kind = kKindTake; x.basis = kBasisRuns; if (Judge(x) != kSwTakeover) Fail("t850f2: (control) the runner's RUNS take no longer takes over a keeper"); }
    { JudgeIn x = in; x.kind = kKindPosition; if (Judge(x) == kSwHoldDelete) Fail("t850f2: a position note was held"); }
    /* the held delete judged again (KeeperHeldStep): kept while the keeper holds; applied (run again) when it let go, then judged as a take-over */
    if (KeeperHeldStep(1, 1, 0, 5, 5, 1) != kHdKeep) Fail("t850f2: a keeper-held delete was not kept while the keeper still holds the area");
    { JudgeIn x = in; x.writerReleased = 1; const int still = Judge(x) == kSwHoldDelete ? 1 : 0;
      if (KeeperHeldStep(1, 1, 0, 5, 5, still) != kHdApply || Judge(x) != kSwTakeover) Fail("t850f2: a keeper-held delete was not applied after the keeper's release"); }
    { JudgeIn x = in; x.writerLive = 0; const int still = Judge(x) == kSwHoldDelete ? 1 : 0;
      if (KeeperHeldStep(1, 1, 0, 5, 5, still) != kHdApply || Judge(x) != kSwTakeover) Fail("t850f2: a keeper-held delete was not applied after the keeper's game left"); }
    /* the keeper writes the group again: refused (the squad lives; the sender's local delete and mark are taken back) */
    if (KeeperHeldStep(1, 1, 0, 9, 5, 1) != kHdRefuse || KeeperHeldStep(1, 1, 0, 9, 5, 0) != kHdRefuse) Fail("t850f2: a keeper-held delete survived a new write of the record");
    /* the keeper runs the people now (its RUNS take: keeper mark gone, record unchanged): run again and refused */
    { JudgeIn x = in; x.writerKeeper = 0; const int still = Judge(x) == kSwHoldDelete ? 1 : 0;
      if (KeeperHeldStep(1, 1, 0, 5, 5, still) != kHdApply || Judge(x) != kSwRefuseNotWriter) Fail("t850f2: a keeper-held delete was taken after the keeper began running the people"); }
    /* the record gone: dropped */
    if (KeeperHeldStep(0, -1, 0, 0, 5, 0) != kHdDrop) Fail("t850f2: a keeper-held delete of a gone record was not dropped");
    /* A REAL DEATH BY A NON-HOLDER still lands: its RUNS take made it the writer -> its delete is the writer's (taken at once, or a held one
       applied); a RUNS take that never landed -> held until the keeper lets the squad go, then taken over */
    { JudgeIn x = in; x.writer = 0; x.writerKeeper = 0; if (Judge(x) != kSwWriter) Fail("t850f2: the runner's own death delete was not taken"); }
    if (KeeperHeldStep(1, 0, 0, 9, 5, 0) != kHdApply) Fail("t850f2: a held death delete was not applied once its sender became the writer");
    /* the hold reaches a DELETED_BITS number too (judged as a plain delete) and the list's bound is the existing one */
    if (SwHeldDeleteAdmit(255, kSwHeldDeleteCap, 0) != 1 || SwHeldDeleteAdmit(256, kSwHeldDeleteCap, 0) != 0) Fail("t850f2: the held-delete bound");
    /* the existing writer hold is unchanged */
    if (HeldDeleteStep(1, 1, 1, 5, 5, 1) != kHdKeep || HeldDeleteStep(1, 2, 1, 5, 5, 0) != kHdRefuse) Fail("t850f2: (control) the released writer's hold changed");
}
/* T-850 fold 2 (T2217, FIX 2): the plain delete of a destroyed copy goes only for the squad's own end here */
void t_t850f2_shell()
{
    using namespace sqbirth;
    /* T2217's EP_2: A refused the copy's wake (B runs it), the engine destroyed the empty shell first */
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, -2, 0, 0), 1, 1, 0, 0) != kDelShellKept) Fail("t850f2: a refused wake's empty copy sent the plain delete (T2217 EP_2)");
    /* T2217's Drifters: A's own copy woke empty beside B's copy of the same id, no runner note */
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, -2, 0, 0), 0, 0, 0, 1) != kDelShellKept) Fail("t850f2: an empty shell beside a same-id copy sent the plain delete (T2217 Drifters)");
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, -2, 0, 0), 0, 0, 0, 0) != kDelShellKept) Fail("t850f2: a copy that never had a living member of its own sent the plain delete");
    /* another game runs the squad: kept, even for a copy that had people of its own here once (hired away: -2) */
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, -2, 0, 1), 0, 1, 1, 0) != kDelShellKept) Fail("t850f2: a copy of a squad another game runs sent the plain delete");
    /* THE REAL DEATH still deletes: the death watch's mark; or all members dead with some this game's own (now, or seen alive by the watch) */
    if (ShellKeep(kDelPlain, ReallyDiedOut(1, -2, 0, 0), 1, 1, 0, 1) != kDelPlain) Fail("t850f2: a wipe-out the death watch marked was kept");
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, 0, 3, 0), 0, 1, 0, 0) != kDelPlain) Fail("t850f2: a squad whose own members all lie dead was kept (a stale runner note)");
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, 0, 0, 1), 1, 0, 1, 1) != kDelPlain) Fail("t850f2: a squad the watch saw alive here whose members all lie dead was kept");
    if (ReallyDiedOut(0, 0, 0, 0) != 0 || ReallyDiedOut(0, -1, 4, 1) != 0 || ReallyDiedOut(0, 2, 4, 1) != 0 || ReallyDiedOut(0, -2, 0, 1) != 0)
        Fail("t850f2: a squad with living members, unread members, other games' bodies only, or emptied by hiring read as died out");
    /* this game's own squad emptied by hiring or merging, nobody else on it: the plain delete as before */
    if (ShellKeep(kDelPlain, ReallyDiedOut(0, -2, 0, 1), 0, 0, 1, 0) != kDelPlain) Fail("t850f2: (control) this game's own emptied squad no longer sends its plain delete");
    /* every other answer passes through unchanged */
    const int others[] = { kDelNone, kDelDiscard, kDelModKept, kDelRunKept, kDelRunHeld };
    for (size_t i = 0; i < sizeof(others) / sizeof(others[0]); ++i)
        for (int w = 0; w <= 1; ++w) for (int o = 0; o <= 1; ++o) for (int l = 0; l <= 1; ++l)
            if (ShellKeep(others[i], 0, w, o, l, 1) != others[i]) Fail("t850f2: the shell rule changed an answer other than the plain delete");
    if (kDelShellKept == kDelNone || kDelShellKept == kDelPlain || kDelShellKept == kDelDiscard || kDelShellKept == kDelModKept || kDelShellKept == kDelRunKept || kDelShellKept == kDelRunHeld)
        Fail("t850f2: the shell keep shares a value with another answer");
}
void t_t850f2_wiring()
{
    const std::string st = T313ReadFile("../coop-plugin/store.cpp"), sm = T313ReadFile("../coop-store/store_main.cpp");
    if (st.empty() || sm.empty()) { Fail("t850f2 wiring: a source not read"); return; }
    /* FIX 2, both destroy roads: the rule asked, its answer acted on before the plain delete's own gate */
    if (st.find("const int delShell = sqbirth::ShellKeep(del, shDied, shWake, shOther, shLived, shPair);") == std::string::npos
        || st.find("const int offDelShell = sqbirth::ShellKeep(offDel, offDied, offWake, offOther, offLived, offPair);") == std::string::npos)
        Fail("t850f2 wiring: a destroy road does not ask the shell rule");
    {
        const size_t a = st.find("else if (delShell == sqbirth::kDelShellKept) ShellKeptNote(worldId, shWake, shOther, shLived, shPair, \"\");");
        const size_t b = st.find("else if (!SwMaySend(worldId, \"engine destroy delete\")) {}");
        if (a == std::string::npos || b == std::string::npos || a > b) Fail("t850f2 wiring: the main destroy does not keep a shell before its plain delete");
        const size_t c = st.find("offDelShell == sqbirth::kDelShellKept)");
        const size_t d = st.find("!SwMaySend(id, \"engine destroy delete (drained off the main thread)\")");
        if (c == std::string::npos || d == std::string::npos || c > d) Fail("t850f2 wiring: the drained destroy does not keep a shell before its plain delete");
    }
    if (st.find("const int shWake = g_wakeDup.count(platoon) != 0 ? 1 : 0;") == std::string::npos || st.find("const int shOther = SwOtherRunner(worldId) >= 0 ? 1 : 0;") == std::string::npos)
        Fail("t850f2 wiring: the main destroy does not read the refused wake or the runner note");
    if (st.find("if (OwnMembersPod(p, &ownLiving) > 0 && ownLiving > 0) { if (g_ownLivedHere.size() < kOwnLivedCap) g_ownLivedHere.insert(p);") == std::string::npos)
        Fail("t850f2 wiring: the death watch does not mark a copy with a living member of this game's own");
    { size_t n = 0; for (size_t at = st.find("g_ownLivedHere.erase(platoon);"); at != std::string::npos; at = st.find("g_ownLivedHere.erase(platoon);", at + 1)) ++n;
      if (n < 2 || st.find("g_ownLivedHere.clear();") == std::string::npos) Fail("t850f2 wiring: the own-lived mark does not go with the platoon, a reused address or the teardown"); }
    /* FIX 1, the world server: the keeper hold reuses the held-delete list, is judged by its own step, and the release judges it again */
    if (sm.find("SwHeldDeleteHold(wid, 0, from, connect, fromName, fromId, payload, SquadSenderSlot(from, connect, fromId), kind) != 0) return;") == std::string::npos)
        Fail("t850f2 wiring: a held discard delete is not held with its kind");
    if (sm.find("step = sqwreg::KeeperHeldStep(") == std::string::npos || sm.find("h.keeper = (rec->second.wslot >= 0 && rec->second.wslot != sender) ? 1 : 0;") == std::string::npos)
        Fail("t850f2 wiring: the world server does not judge a keeper hold by its own step");
    if (sm.find("SwHeldDeleteRejudgeGate(coopwq::GateKey(id));   /* T-850 fold 2") == std::string::npos) Fail("t850f2 wiring: a keeper's release does not judge the deletes held for it again");
    if (sm.find(",keeperHeld=") == std::string::npos || st.find(" shellKept[kept,") == std::string::npos) Fail("t850f2 wiring: the counters are not on the REPORT lines");
}


/* T-1131 design A: MSG_CRIME kind 3 CAUGHT - the bytes, an older reader's refusal, the thief's-game send decision (forward / the
   copy's own reaction with no road) and the watcher's-owner decision (not the owner: refused), and the wiring of both games. */
void t_t1131_caught_kind3()
{
    coopcrime::CrimeState s;
    s.crime = 3; s.expiry = 30.0f; s.victimUid = 388u; s.factionSid = "12-gamedata.base";
    coopcrime::CrimeCaught c;
    c.watcherUid = 388u; c.ev = coopcrime::kCaughtEvCaught;
    std::vector<char> b;
    if (!coopcrime::EncodeCrimeCaught(&b, 4194305u, s, c)) Fail("t1131 kind3: a caught event must encode");
    const size_t off = coopcrime::kCrimeFixedBytes + s.factionSid.size();
    if (b.size() != off + 9 || (unsigned char)b[off] != coopcrime::kCrimeKindCaught) Fail("t1131 kind3: kind 0's bytes, the byte 3, watcher u32, event i32");
    unsigned int uid = 0; coopcrime::CrimeState o; unsigned char kind = 99; coopcrime::CrimeRelEvent rel; coopcrime::CrimeCaught oc;
    if (coopcrime::DecodeCrimeMsg(&b[0], b.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeOk || kind != coopcrime::kCrimeKindCaught
        || uid != 4194305u || o.crime != 3 || o.expiry != 30.0f || o.victimUid != 388u || o.factionSid != "12-gamedata.base"
        || oc.watcherUid != 388u || oc.ev != 8)
        Fail("t1131 kind3: must round-trip (the thief's crime and the watcher's event)");
    coopcrime::CrimeCaught c2; c2.watcherUid = 388u; c2.ev = coopcrime::kCaughtEvLetOff;
    coopcrime::CrimeState none;
    std::vector<char> b2;
    if (!coopcrime::EncodeCrimeCaught(&b2, 7u, none, c2) || coopcrime::DecodeCrimeMsg(&b2[0], b2.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeOk
        || oc.ev != 0x2F || o.crime != 0 || kind != 3)
        Fail("t1131 kind3: the let-off event 0x2F with no crime must round-trip");
    std::vector<char> x;
    coopcrime::CrimeCaught bad = c; bad.ev = 9;
    if (coopcrime::EncodeCrimeCaught(&x, 7u, s, bad) || coopcrime::EncodeCrimeCaught(&x, 0u, s, c) || coopcrime::EncodeCrimeCaught(&x, 388u, s, c) || !x.empty())
        Fail("t1131 kind3: an event not 8 / 0x2F, thief uid 0 or the watcher as the thief must not encode");
    std::vector<char> cut(b); cut.resize(cut.size() - 1);
    if (coopcrime::DecodeCrimeMsg(&cut[0], cut.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeCaughtTrunc) Fail("t1131 kind3: a cut kind 3 must be refused");
    std::vector<char> ev9(b); int nine = 9; std::memcpy(&ev9[off + 5], &nine, 4);
    if (coopcrime::DecodeCrimeMsg(&ev9[0], ev9.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeCaughtBad) Fail("t1131 kind3: event 9 must be refused");
    std::vector<char> w0(b); unsigned int zero = 0; std::memcpy(&w0[off + 1], &zero, 4);
    if (coopcrime::DecodeCrimeMsg(&w0[0], w0.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeCaughtBad) Fail("t1131 kind3: watcher 0 must be refused");
    std::vector<char> more(b); more.push_back((char)0x55);
    if (coopcrime::DecodeCrimeMsg(&more[0], more.size(), &uid, &o, &kind, &rel, &oc) != coopcrime::kCrimeDecodeOk || oc.watcherUid != 388u) Fail("t1131 kind3: bytes after its fields must be ignored");
    /* an older reader (protocol 222: kinds 0..2) refuses the kind byte 3 as a bad kind - the rule its DecodeCrimeMsg applied */
    if (!((unsigned char)b[off] > coopcrime::kCrimeKindMaxBefore223) || coopcrime::kCrimeKindMaxBefore223 != coopcrime::kCrimeKindRelEvent)
        Fail("t1131 kind3: a protocol-222 reader must see a kind above its last (2) and refuse it");
    if (coopcrime::CrimeMsgKeptThroughLoad(&b[0], b.size())) Fail("t1131 kind3: kind 3 must not be kept through a load");
    /* the thief's game */
    if (coopcrime::CaughtForwardDecide(8, true, true, true, true) != coopcrime::kCaughtForward
        || coopcrime::CaughtForwardDecide(0x2F, true, true, true, true) != coopcrime::kCaughtForward)
        Fail("t1131 kind3: a copy watcher's event about our thief with a road must be forwarded");
    if (coopcrime::CaughtForwardDecide(8, true, true, true, false) != coopcrime::kCaughtLocalNoRoute)
        Fail("t1131 kind3: with no road to the watcher's owner the copy's own reaction must run here");
    if (coopcrime::CaughtForwardDecide(8, true, true, false, true) != coopcrime::kCaughtLocalOffMain) Fail("t1131 kind3: off the main thread the copy's reaction runs here");
    if (coopcrime::CaughtForwardDecide(8, false, true, true, true) != coopcrime::kCaughtPass || coopcrime::CaughtForwardDecide(8, true, false, true, true) != coopcrime::kCaughtPass
        || coopcrime::CaughtForwardDecide(0x2A, true, true, true, true) != coopcrime::kCaughtPass)
        Fail("t1131 kind3: our own watcher, another game's thief, or another event must pass to the engine untouched");
    /* the watcher's owner */
    if (coopcrime::CaughtOwnerDecide(true, true, true, true, 8) != coopcrime::kCaughtRaise) Fail("t1131 kind3: our watcher, the sender's thief: raise");
    if (coopcrime::CaughtOwnerDecide(false, true, true, true, 8) != coopcrime::kCaughtNotOwner) Fail("t1131 kind3: a watcher this game does not run must be refused");
    if (coopcrime::CaughtOwnerDecide(true, false, true, true, 8) != coopcrime::kCaughtNoWatcher || coopcrime::CaughtOwnerDecide(true, true, false, true, 8) != coopcrime::kCaughtThiefNotSenders
        || coopcrime::CaughtOwnerDecide(true, true, true, false, 8) != coopcrime::kCaughtNoThief || coopcrime::CaughtOwnerDecide(true, true, true, true, 3) != coopcrime::kCaughtBadEv)
        Fail("t1131 kind3: no watcher here, a thief not the sender's, no thief copy or a bad event must be refused");
    /* wiring */
    const std::string cr = T313ReadFile("../coop-plugin/crime.cpp");
    const std::string se = T313ReadFile("../coop-plugin/net/session.cpp");
    if (se.find("if (kind == coopcrime::kCrimeKindCaught) { coop::ApplyRemoteCaught(uid, s, caught, m.peer); return; }") == std::string::npos
        || se.find("if (SideSendToOwnerOf(MSG_CRIME, c.watcherUid, &b[0], b.size(), &to, &why)) return 1;") == std::string::npos
        || se.find("const unsigned int kProtocolVersion = 237;") == std::string::npos)
        Fail("t1131 kind3 wiring: the session does not take kind 3, does not send it to the watcher's owner, or does not speak 224");
    if (cr.find("if (ra == 0 || (ra != g_caughtEv8At && ra != g_caughtEv2FAt)) return orig_caughtAlert(dlg, who, ev, flag);") == std::string::npos
        || cr.find("if ((int)ev == coopcrime::kCaughtEvCaught) { g_caughtPend = p; return 0; }") == std::string::npos
        || cr.find("if (atRoll) { g_caughtInNotifyTid = 0; CaughtAfterNotify(againstFaction, againstWho, expirySeconds, g_caughtRecorded); }") == std::string::npos
        || cr.find("if (atRoll) CaughtAfterNotify(againstFaction, againstWho, expirySeconds, 0);") == std::string::npos
        || cr.find("if (g_caughtInNotifyTid != 0 && g_caughtInNotifyTid == ::GetCurrentThreadId()) g_caughtRecorded = r ? CrRecordedCrime(bountyManager) : 0;") == std::string::npos
        || cr.find("if (r > 0) { ++g_caughtFwd[1]; g_caughtPend.sent = 1; CaughtSentLog(p, s, \"at the roll's crime record\"); return; }") == std::string::npos
        || cr.find("if (p.sent != 0) return;   /* sent at the crime record: the copy's memory note is not written here */") == std::string::npos
        || cr.find("    CrimeApplyDrainBody();") == std::string::npos || cr.find("    CaughtRaiseDrain();") < cr.find("    CrimeApplyDrainBody();")
        || cr.find("if (s.crime != 0) ApplyRemoteCrime(thiefUid, s, fromPeer);") == std::string::npos)
        Fail("t1131 kind3 wiring: crime.cpp does not hold the roll's event back, send it after the crime write, or raise it after the queued crimes");
    const std::string t65 = T313ReadFile("../coop-plugin/addresses/65D604D7-0232C000-B914BEE3-02303600.txt");
    if (t65.find("PlatoonMemoryNote                               code 00672F90") == std::string::npos
        || t65.find("TheftCaughtEv8Ret                               ret  00793D50 00793D4B") == std::string::npos
        || t65.find("TheftCaughtEv2FRet                              ret  00793D00 00793CFB") == std::string::npos
        || t65.find("TheftCaughtMemoryRet                            ret  00793D8D 00793D88") == std::string::npos)
        Fail("t1131 kind3: the 1.0.65 table lacks a row of the roll's calls");
    /* review fold 1 (L6): the 1.0.68 rows (each return address = its call + 5; the 1.0.68 roll moved by +0xBA0) */
    const std::string t68 = T313ReadFile("../coop-plugin/addresses/6602D59D-0232D000-BBA641C8-02304800.txt");
    if (t68.find("PlatoonMemoryNote                              code 00673A20") == std::string::npos
        || t68.find("TheftCaughtEv2FRet                             ret  007948A0 0079489B") == std::string::npos
        || t68.find("TheftCaughtEv8Ret                              ret  007948F0 007948EB") == std::string::npos
        || t68.find("TheftCaughtMemoryRet                           ret  0079492D 00794928") == std::string::npos
        || t68.find("TheftCaughtNotifyRet                           ret  0079491C 00794917") == std::string::npos
        || t65.find("TheftCaughtNotifyRet                            ret  00793D7C 00793D77") == std::string::npos)
        Fail("t1131 fold1: a 1.0.68 row of the roll's calls (or the 1.0.65 crime-record row) is missing or moved");
    /* no road at the crime record: the copy's event runs then, before the record (the roll's order), and the hold ends so the engine's
       own memory note runs once; the backstops send with the characters looked up again (fold 2: the send follows the record) */
    const size_t an = cr.find("bool CaughtBeforeNotify()\r\n{") != std::string::npos ? cr.find("bool CaughtBeforeNotify()\r\n{") : cr.find("bool CaughtBeforeNotify()\n{");
    const size_t anEnd = (an == std::string::npos) ? an : cr.find("void CaughtAfterNotify(", an);
    const std::string atn = (an == std::string::npos || anEnd == std::string::npos) ? std::string() : cr.substr(an, anEnd - an);
    const size_t en = atn.find("g_caughtPend.active = 0;"), fl = atn.find("++g_caughtFwd[2];", en == std::string::npos ? 0 : en),
                 lo = atn.find("CaughtRunLocal(p, w, t, dlg, false, 0, \"before the roll's crime record, single player's order\");");
    if (atn.empty() || fl == std::string::npos || en == std::string::npos || lo == std::string::npos || !(en < fl && fl < lo)
        || atn.find("if (net::CaughtRouteOpen(g_caughtPend.watcherUid)) return true;") == std::string::npos
        || atn.find("if (!CaughtResolve(p, &w, &t, &dlg))") == std::string::npos)
        Fail("t1131 fold1: the failed send at the crime record does not run the copy's event once, before the record, on characters looked up again");
    if (cr.find("const int evOk = (orig_caughtAlert != 0) ? CaughtCallAlertPod(orig_caughtAlert, dlg, t, (unsigned int)p.ev, p.flag, &er) : 0;") == std::string::npos
        || cr.find("if (runMem && p.ev == coopcrime::kCaughtEvCaught && orig_caughtMem != 0) memOk = CaughtCallMemPod(orig_caughtMem, w, t, 4);") == std::string::npos)
        Fail("t1131 fold1: the local fallback does not raise the copy's event (and memory note) through the engine's own entries");
    /* the held-event flush: dropped with a line while the world loads, sent after the teardown check otherwise */
    const size_t ctk = cr.find("void CrimeTick()");
    const size_t fBlocked = cr.find("CaughtPendFlush(true);", ctk), fLive = cr.find("CaughtPendFlush(false);", ctk), wb = cr.find("if (EngineWritesBlocked())", ctk);
    if (ctk == std::string::npos || wb == std::string::npos || fBlocked == std::string::npos || fLive == std::string::npos || !(wb < fBlocked && fBlocked < fLive)
        || cr.find("if (blocked) { ++g_caughtFwd[7]; CaughtGoneLog(p, \"the world is loading or tearing down\"); return; }") == std::string::npos
        || cr.find("if (p.sent != 0) return;   /* already sent at the crime record") > cr.find("if (blocked) { ++g_caughtFwd[7];"))
        Fail("t1131 fold1: the held event is not dropped while loading, or is flushed before the teardown check");
    if (cr.find("CaughtSendHeld(p, false, \"at the event (0x2F: no crime record follows)\");") == std::string::npos)
        Fail("t1131 fold1: the let-off event 0x2F is not sent at its event call");
    /* the second owner check at the raise, the roll's stop of the watcher first (M2), and A's answer logged */
    const size_t rd = cr.find("void CaughtRaiseDrain()");
    if (rd == std::string::npos || cr.find("coopcrime::CaughtOwnerDecide(net::IsUidMine(in.watcherUid), w != 0, net::UidOwnedByPeer(in.thiefUid, in.fromPeer), t != 0, in.ev);", rd) == std::string::npos
        || cr.find("stopOk = CaughtStopPod(w, &state, &stopped);", rd) == std::string::npos
        || cr.find("stopOk = CaughtStopPod(w, &state, &stopped);", rd) > cr.find("CaughtCallAlertPod((CaughtAlertFn)(base + (uintptr_t)kCaughtAlertRva)", rd)
        || cr.find("answer=%d stop[ok,state,stopped]=", rd) == std::string::npos)
        Fail("t1131 fold1: the raise does not check the owner again, stop the watcher before event 8, or log its answer");
    if (cr.find("const bool tMine = tu != 0 && (onMain ? net::IsUidMine(tu) : net::IsUidMineAnyThread(tu));") == std::string::npos)
        Fail("t1131 fold1: the thief's owner is not read from the exact owner table on the main thread");
}

/* T-860: a cage / bed inside a building is named WITH its building even when its interior came from an area file (no layout link):
   coopbed::PickOuterRoad over a fake handle reader, then LayoutOuterKey's wiring and the counter. */
struct T860FakeOuter
{
    void* layoutHost; int readOk; unsigned int ids[5]; void* resolved; int resolveCalls; unsigned int asked[5];
    void* LayoutHost(void*) { return layoutHost; }
    int InsideIds(void*, unsigned int* f) { if (readOk == 0) return 0; std::memcpy(f, ids, sizeof(ids)); return 1; }
    void* Resolve(const unsigned int* f) { ++resolveCalls; std::memcpy(asked, f, sizeof(asked)); return resolved; }
};
static T860FakeOuter T860Fake(void* layoutHost, int readOk, unsigned int type, unsigned int idx, unsigned int serial, void* resolved)
{
    T860FakeOuter r;
    r.layoutHost = layoutHost; r.readOk = readOk; r.resolved = resolved; r.resolveCalls = 0;
    r.ids[0] = type; r.ids[1] = 7; r.ids[2] = 9; r.ids[3] = idx; r.ids[4] = serial;
    std::memset(r.asked, 0, sizeof(r.asked));
    return r;
}
void t_t860_outer_key_road()
{
    using namespace coopbed;
    char pieceB, layoutBld, insideBld;
    void* const piece = &pieceB;
    void* host = (void*)1;
    /* a piece furnished from a layout: road 1, the inside hand is not consulted */
    T860FakeOuter r = T860Fake(&layoutBld, 1, kHandTypeBuilding, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadLayout || host != &layoutBld || r.resolveCalls != 0) Fail("t860 outer: a layout piece is not named by its layout's building");
    /* a piece from an area file (no layout): its own inside-building hand names the building (the T2180 cage) */
    r = T860Fake(0, 1, kHandTypeBuilding, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadInside || host != &insideBld) Fail("t860 outer: an area-file piece is not named by its inside-building hand");
    if (r.resolveCalls != 1 || r.asked[0] != kHandTypeBuilding || r.asked[1] != 7 || r.asked[2] != 9 || r.asked[3] != 5 || r.asked[4] != 6)
        Fail("t860 outer: the inside hand's five words are not passed to the resolve in order");
    /* stands inside nothing (type 0xB), another type, an empty hand, a fault, an unresolvable hand, a hand naming itself: empty as before */
    r = T860Fake(0, 1, kHandTypeNone, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || host != 0 || r.resolveCalls != 0) Fail("t860 outer: a piece inside nothing (0xB) gets an outer building");
    r = T860Fake(0, 1, 3, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || r.resolveCalls != 0) Fail("t860 outer: a hand of another type is resolved");
    r = T860Fake(0, 1, kHandTypeBuilding, 0, 0, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || r.resolveCalls != 0) Fail("t860 outer: an empty hand is resolved");
    r = T860Fake(0, 0, kHandTypeBuilding, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || host != 0) Fail("t860 outer: a faulted hand read names a building");
    r = T860Fake(0, 1, kHandTypeBuilding, 5, 6, 0);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || host != 0) Fail("t860 outer: an unresolvable hand names a building");
    r = T860Fake(0, 1, kHandTypeBuilding, 5, 6, piece);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadNone || host != 0) Fail("t860 outer: a piece is named as its own outer building");
    r = T860Fake(piece, 1, kHandTypeBuilding, 5, 6, &insideBld);
    if (PickOuterRoad(r, piece, &host) != kOuterRoadInside || host != &insideBld) Fail("t860 outer: a layout naming the piece itself does not fall to the inside hand");
    if (PickOuterRoad(r, 0, &host) != kOuterRoadNone || host != 0) Fail("t860 outer: no piece names a building");
    /* wiring: LayoutOuterKey decides by PickOuterRoad, reads +0x88 guarded, resolves the hand as PoseBedKeyFromHand does; the counter is reported */
    std::string it = T313ReadFile("../coop-plugin/items.cpp"), sp = T313ReadFile("../coop-plugin/spawn.cpp");
    if (it.empty() || sp.empty()) { Fail("t860 outer wiring: a source file is not readable"); return; }
    it.erase(std::remove(it.begin(), it.end(), '\r'), it.end());   /* the work folder may hold CRLF lines */
    const size_t fn = it.find("int LayoutOuterKey(void* piece, char* out, int cap)\n{");
    const size_t fnEnd = (fn == std::string::npos) ? fn : it.find("\n}\n", fn);
    if (fn == std::string::npos || fnEnd == std::string::npos || it.substr(fn, fnEnd - fn).find("coopbed::PickOuterRoad(rd, piece, &outer)") == std::string::npos)
        Fail("t860 outer wiring: LayoutOuterKey does not decide by coopbed::PickOuterRoad");
    if (it.find("const size_t kBldInsideHandIds      = 0x88;") == std::string::npos || it.find("__try { std::memcpy(f, (const char*)piece + kBldInsideHandIds, 5 * sizeof(unsigned int)); return 1; }") == std::string::npos)
        Fail("t860 outer wiring: the inside-building hand is not read guarded at +0x88");
    if (it.find("        hand h(f[3], f[4], (itemType)f[0], f[1], f[2]);\n        void* b = (void*)h.asBuilding();\n        return ItPlaus(b) ? b : 0;") == std::string::npos)
        Fail("t860 outer wiring: the inside hand is not resolved with hand(...).asBuilding()");
    if (it.find("\" outerKey[layout,insideHandle,none]=%lld,%lld,%lld\"") == std::string::npos || sp.find("+ OuterKeyReportToken()") == std::string::npos)
        Fail("t860 outer wiring: the outerKey counter is not reported");
    if (sp.find("if (LayoutOuterKey(bld, outerOut, outerCap) == 0) outerOut[0] = 0;") == std::string::npos) Fail("t860 outer wiring: PoseBedKeyFromHand no longer names the outer building by LayoutOuterKey");
}


/* T-850 (T2230): a hand-over's ACK passed a squad's people to another game - the heartbeat's writer re-check runs for it, so the release
   goes out; a squad this game still runs (or a split one) is kept; with no awake copy left it is released by its record */
void t_t850_handover_release()
{
    using namespace sqwreg;
    /* which road: nothing passed -> none; a filed (awake) copy -> the re-check, kept people or not; no copy, nothing kept -> by record */
    if (HandOverStep(0, 0, 1, 0) != kHandNone || HandOverStep(0, 0, 0, 0) != kHandNone) Fail("t850 hand-over: a squad none of whose people were passed was judged");
    if (HandOverStep(1, 0, 1, 0) != kHandRejudge || HandOverStep(1, 1, 1, 0) != kHandRejudge) Fail("t850 hand-over: a filed copy did not get the heartbeat's re-check");
    if (HandOverStep(1, 0, 0, 0) != kHandByRecord) Fail("t850 hand-over: a squad whose copy is asleep or destroyed was not released by its record");
    if (HandOverStep(1, 1, 0, 0) != kHandNone) Fail("t850 hand-over: a squad whose people the ACK kept here was released with no copy to read who runs them");
    if (HandOverStep(1, 0, 0, 1) != kHandNone) Fail("t850 hand-over: an awake copy the heartbeat does not file was released");
    /* the re-check (HbRegister's existing-entry rule, then RunnerMovedRelease), this game slot 0, the receiver slot 1 */
    {   /* T2230: every person passed - slot 1 runs the majority: the entry turns another game's and the release goes */
        const int now = coopsquad::HbForeignAfter(0, 0, 0, 1, 0, 0);
        if (now != 1 || RunnerMovedRelease(0, 1, 1, 1, 0) != 1) Fail("t850 hand-over: the handed-over squad is not marked another game's and released");
    }
    {   /* a forced hand-over whose receiver kept only some: this game still runs most of the living people - kept, nothing sent */
        if (coopsquad::HbForeignAfter(0, 0, 0, 0, 0, 0) != 0 || RunnerMovedRelease(0, 0, 1, 1, 0) != 0) Fail("t850 hand-over: a squad this game still runs was released");
    }
    {   /* a split (no strict majority): no runner - kept, nothing sent */
        if (coopsquad::HbForeignAfter(0, 0, 0, -1, 0, 0) != 0 || RunnerMovedRelease(0, -1, 1, 1, 0) != 0) Fail("t850 hand-over: a split squad was released");
    }
    {   /* by record: the receiver as the runner; a refused squad, a player's squad or a non-squad id sends none */
        if (RunnerMovedRelease(0, 1, 1, 1, 0) != 1) Fail("t850 hand-over: a gone copy's squad is not released by its record");
        if (RunnerMovedRelease(0, 1, 1, 1, 1) != 0 || RunnerMovedRelease(0, 1, 1, 0, 0) != 0 || RunnerMovedRelease(0, 1, 0, 1, 0) != 0) Fail("t850 hand-over: a refused squad, a player's squad or a non-squad id was released by record");
    }
    /* wiring: the ACK collects each person's squad and calls the store after the loop; the store runs HbRegister / SwRunnerSeen from the
       step; a squad marked another game's is not written by the heartbeat (its ring skips foreign entries); the counter is reported */
    const std::string ho = T313ReadFile("../coop-plugin/handoff.cpp"), st = T313ReadFile("../coop-plugin/store.cpp");
    const char* const hv[] = { "{ const std::string hk = HoSquadIdOf(uid, rel, p); if (!hk.empty()) ++hoSquads[hk].first; }",
                               "{ const std::string hk = HoSquadIdOf(uid, FindSpawned(uid), p); if (!hk.empty()) ++hoSquads[hk].second; }",
                               "if (hs->second.first > 0) coop::StoreHandOverJudge(hs->first, p.targetSlot, hs->second.first, hs->second.second);" };
    for (size_t i = 0; i < sizeof(hv) / sizeof(hv[0]); ++i) if (ho.find(hv[i]) == std::string::npos) Fail(std::string("t850 hand-over: handoff.cpp lacks: ") + hv[i]);
    const size_t call = ho.find("coop::StoreHandOverJudge(hs->first"), rel = ho.find("net::ReleaseLocalOwner(uid, fromPeer);"), erase = call == std::string::npos ? call : ho.find("    const Pending flown(p);", call);
    if (call == std::string::npos || rel == std::string::npos || erase == std::string::npos || !(rel < call && call < erase)) Fail("t850 hand-over: the store is not called after the ACK's release loop");
    const char* const sv[] = { "const int step = sqwreg::HandOverStep(released > 0 ? 1 : 0, kept > 0 ? 1 : 0, filed.empty() ? 0 : 1, awakeUnfiled);",
                               "HbRegister(filed[i]);   /* the heartbeat's own writer re-check",
                               "SwRunnerSeen(id, f, toSlot, 0);",
                               "if (now != 0 && runner >= 0 && runner != g_mySlot) { Pod fq; SwRunnerSeen(WorldIdOf(platoon), ReadPod(platoon, &fq) ? fq.faction : 0, runner, 0); }",
                               "if (it->first == at) g_hbRingAt = g_hbRing.size();   /* keep the cursor's place across a rebuild */",
                               "\",handOverRel[seen,sent,owed,already,notMine,kept]=\"",
                               "DebugLog(\"[STORE] hand-over released \" + id + \" -> runner slot \"" };
    for (size_t i = 0; i < sizeof(sv) / sizeof(sv[0]); ++i) if (st.find(sv[i]) == std::string::npos) Fail(std::string("t850 hand-over: store.cpp lacks: ") + sv[i]);
}

/* T-1001 (F1054): a piece inside a building follows its host's town - the engine's rule (0x296900: a building's town is its top
   parent's; setPowerOn joins the grid of that town). A re-towned host writes its new words onto each piece inside it and switches each
   switched-on power piece inside it off before its copy and on after; nothing moves when the host's copy failed */
void t_t1001_inside_follow()
{
    using namespace piecerec;
    /* words: only a piece that reads inside, after the host's copy was written */
    if (InsideWordsStep(0, 1, 1, 0) != kInsideWrite) Fail("t1001 inside: a piece inside a re-towned host does not take the host's new words");
    if (InsideWordsStep(0, 1, 1, 1) != kInsideKept) Fail("t1001 inside: a piece already naming the new town is written again");
    if (InsideWordsStep(0, 1, 0, 0) != kInsideUnread) Fail("t1001 inside: a piece whose words do not read is written");
    if (InsideWordsStep(0, 0, 1, 0) != kInsideLeave || InsideWordsStep(0, -1, 1, 0) != kInsideLeave) Fail("t1001 inside: a piece moved although its host's copy failed");
    if (InsideWordsStep(1, 1, 1, 0) != kInsideLeave || InsideWordsStep(-1, 1, 1, 0) != kInsideLeave) Fail("t1001 inside: a top-level piece (or one that does not read) on the host's list is moved as an inside piece");
    /* power: as the host's own cycle */
    if (InsidePowerCycle(0, 0) != kCycleNone || InsidePowerCycle(0, 1) != kCycleNone) Fail("t1001 inside: a piece not switched off reports a cycle");
    if (InsidePowerCycle(1, 1) != kCycleBack) Fail("t1001 inside: a piece switched off and on again is not re-switched");
    if (InsidePowerCycle(1, 0) != kCycleFailed) Fail("t1001 inside: a failed switch-on is not reported");
    /* lines: the first 40, then every 100th; never for none */
    if (InsideLineDue(0, 40) != 0 || InsideLineDue(1, 40) != 1 || InsideLineDue(40, 40) != 1 || InsideLineDue(41, 40) != 0 || InsideLineDue(200, 40) != 1)
        Fail("t1001 inside: the line cap is wrong");
    /* fold LOW 3: a host with no interior is "nothing inside"; one whose interior is there but whose list (or interior) does not read is counted */
    if (InsideListStep(0, -1) != kInsideListNone) Fail("t1001 inside: a building with no interior is counted as an unread list");
    if (InsideListStep(1, 0) != kInsideListRead || InsideListStep(1, 3) != kInsideListRead) Fail("t1001 inside: a read interior list is not taken as read");
    if (InsideListStep(1, -1) != kInsideListUnread || InsideListStep(-1, -1) != kInsideListUnread) Fail("t1001 inside: an interior whose list does not read is taken for nothing inside");
    /* fold MED 1: at the host's look (it stands in its town), a piece inside it whose own words are not its host's town's - it loaded
       before its host, so 0x296900 read its own words and it joined that town's grid - is set; one already naming it, unread, or top-level is not */
    if (InsideLookStep(0, 1, 0) != 1) Fail("t1001 inside: a piece inside whose words differ from its host's town is left at the host's look");
    if (InsideLookStep(0, 1, 1) != 0) Fail("t1001 inside: a piece already naming its host's town is switched at every look");
    if (InsideLookStep(0, 0, 0) != 0 || InsideLookStep(1, 1, 0) != 0 || InsideLookStep(-1, 1, 0) != 0) Fail("t1001 inside: an unread or top-level piece is set at the host's look");
    if (InsideWordsStep(0, 1, 1, 0) != kInsideWrite) Fail("t1001 inside: the look's piece (host 'written' = it stands) does not take its host's words");
    /* wiring: inside the one set-town every road calls - the inside pieces read first, their grid left before the host's copy, followed
       after it; the take-out's put-back, the record relink and the key-row link still go through it; the report carries the counters */
    const std::string s = T313ReadFile("../coop-plugin/build.cpp");
    if (s.empty()) { Fail("t1001 inside: build.cpp not read"); return; }
    const size_t fn = s.find("int BdBuildingSetTownPod(void* b, void* t, int* cycle = 0)"), fnEnd = fn == std::string::npos ? fn : s.find("\n}", fn);
    if (fn == std::string::npos || fnEnd == std::string::npos) { Fail("t1001 inside: BdBuildingSetTownPod not found"); return; }
    const std::string body = s.substr(fn, fnEnd - fn);
    const size_t a = body.find("const int nIn = BdInsidePieces(b, &inListed, &inComplete);"), b = body.find("BdInsideLeave(nIn);"),
                 c = body.find("const int wasOn = BdPowerLeaveGrid(b);"), d = body.find("const int r = BdTownWordsCopyPod(b, t);"),
                 e = body.find("BdInsideFollow(b, inFrom, t, r, nIn, inListed, inComplete);");
    if (a == std::string::npos || b == std::string::npos || c == std::string::npos || d == std::string::npos || e == std::string::npos || !(a < b && b < c && c < d && d < e))
        Fail("t1001 inside: the set-town does not read the inside pieces, leave their grid before the host's copy and follow after it");
    const char* const roads[] = { "    const int set = BdBuildingSetTownPod(b, t);\n    if (set == 0) { ++g_slFault; return 0; }",   /* the take-out's put-back (19295 road) */
                                  "int Copy(int* cycle) { return BdBuildingSetTownPod(b, t, cycle); }",                                  /* the record relink after a load */
                                  "BdInsideCheck(b, t);   /* T-1001 fold (MED 1): the pieces inside it name its town */" };                     /* fold MED 1: the house's look */
    std::string sn;
    for (size_t i = 0; i < s.size(); ++i) if (s[i] != '\r') sn += s[i];
    for (size_t i = 0; i < sizeof(roads) / sizeof(roads[0]); ++i) if (sn.find(roads[i]) == std::string::npos) Fail(std::string("t1001 inside: build.cpp lacks: ") + roads[i]);
}

/* T-1082: a player's piece's door on the world door record - its field set (the lock word, a gate's open / closed state, the lock's
   hardness) and nothing else: the change mask, the seed, the held merge and the lay; a dismantle's removal of its records */
void t_t1082_player_door_record()
{
    using namespace doorrec;
    DoorRec live;
    live.key = "x@4,5@10,20gate"; live.gate = 1; live.state = 1; live.lockWord = 1; live.broken = 1; live.hasLock = 1; live.lockLevel = 60;
    live.lockBroken = 1; live.hardness = 2.5f; live.health = 80.0f; live.generation = 7; live.writerSlot = 2;
    /* the field set: the lock word, a gate's state, the hardness (with has-a-lock); level, broken flags and health are 0 */
    DoorRec p = DoorRecPlayerFields(live);
    if (p.key != live.key || p.gate != 1 || p.state != 1 || p.lockWord != 1 || p.hasLock != 1 || p.hardness != 2.5f)
        Fail("t1082: the player field set lost the lock word, a gate's state or the hardness");
    if (p.broken != 0 || p.lockLevel != 0 || p.lockBroken != 0 || p.health != kDrPlayerMark)
        Fail("t1082: the player field set carries level, a broken flag or health (the piece record's facts) or lacks the -1 mark");
    /* review MED 1: the record says its own kind - the mark wins over a town view, never over an unreadable one */
    if (DoorRecIsPlayer(p) != 1 || DoorRecIsPlayer(live) != 0) Fail("t1082: the player mark does not read");
    if (DoorRecKindFor(0, 1, p) != 1 || DoorRecKindFor(0, 1, live) != 0 || DoorRecKindFor(0, 0, p) != 0 || DoorRecKindFor(1, 1, live) != 1
        || DoorRecKindFor(-1, 1, p) != -1) Fail("t1082: the record's kind rule is wrong");
    DoorRec neg = live;
    neg.health = -3.0f;
    if (DoorRecTownFields(neg).health != 0.0f || DoorRecTownFields(live).health != 80.0f || DoorRecIsPlayer(DoorRecTownFields(neg)) != 0)
        Fail("t1082: a town record can carry the player mark");
    if (p.generation != 7 || p.writerSlot != 2) Fail("t1082: the player field set dropped the generation or writer");
    DoorRec d = live;
    d.gate = 0; d.state = 1; d.hasLock = 0; d.hardness = 3.0f;
    const DoorRec pd = DoorRecPlayerFields(d);
    if (pd.state != 1 || pd.hardness != 0.0f) Fail("t1082: an ordinary door's open / shut is not in the player record (T-1429 s4), or a lockless door's hardness rides it");
    /* the record encodes and decodes as any door record (no format change) */
    std::vector<char> bytes;
    DoorRec back;
    if (!EncodeDoorRec(&bytes, p) || DecodeDoorRec(&bytes[0], bytes.size(), &back) != kDrOk || back.lockWord != 1 || back.hardness != 2.5f || back.lockLevel != 0
        || DoorRecIsPlayer(back) != 1)
        Fail("t1082: a player door record does not encode and decode");
    /* the change mask: only the player facts move it */
    DoorRec rec = p;
    DoorRec l2 = live;
    l2.lockLevel = 10; l2.broken = 0; l2.lockBroken = 0; l2.health = 5.0f;
    if (DoorRecChangeMaskFor(1, 1, rec, l2) != 0) Fail("t1082: a level, broken or health change moves a player door's record");
    if (DoorRecChangeMaskFor(0, 1, live, l2) == 0) Fail("t1082: a town door's level, broken or health change no longer moves its record");
    l2 = live; l2.lockWord = 3;
    if (DoorRecChangeMaskFor(1, 1, rec, l2) != kDrChLock) Fail("t1082: a player door's lock does not move its record");
    l2 = live; l2.state = 0;
    if (DoorRecChangeMaskFor(1, 1, rec, l2) != kDrChState) Fail("t1082: a player gate's open / shut does not move its record");
    DoorRec dr = DoorRecPlayerFields(d), dl = d;
    dl.state = 0;
    if (DoorRecChangeMaskFor(1, 1, dr, dl) != kDrChState) Fail("t1082: an ordinary player door's open / shut does not move its record (T-1429 s4)");
    l2 = live; l2.hardness = 4.0f;
    if (DoorRecChangeMaskFor(1, 1, rec, l2) != kDrChHardness) Fail("t1082: a player door's hardness does not move its record");
    if (DoorRecChangeMaskFor(1, 0, rec, live) != (kDrChState | kDrChLock | kDrChHardness)) Fail("t1082: a player gate with no record does not name its whole field set");
    /* a bought house's town record: compared on the player fields only */
    DoorRec town = live;
    town.lockLevel = 90; town.broken = 0; town.health = 400.0f;
    if (DoorRecChangeMaskFor(1, 1, town, live) != 0) Fail("t1082: a bought house's town record moves on its level, broken or health");
    /* the held merge: the held player facts from the door, the rest of the field set from the record, nothing else */
    DoorRec hl = live;
    hl.lockWord = 2; hl.state = 0; hl.hardness = 9.0f;
    DoorRec m = DoorRecPlayerHeldMerge(town, hl, kDrChLock | kDrChBroken | kDrChLevel);
    if (m.lockWord != 2 || m.state != 1 || m.hardness != 2.5f) Fail("t1082: the held merge did not take the held lock alone");
    if (m.lockLevel != 0 || m.broken != 0 || m.health != kDrPlayerMark || m.lockBroken != 0) Fail("t1082: the held merge carries level, broken or health");
    m = DoorRecPlayerHeldMerge(town, hl, kDrChState | kDrChHardness);
    if (m.state != 0 || m.hardness != 9.0f || m.lockWord != 1) Fail("t1082: the held merge did not take a gate's state and the hardness");
    if (DoorRecChangeWords(kDrChHardness) != " lock-hardness") Fail("t1082: the hardness change has no word");
    /* the hardness a lay writes */
    if (DoorRecLayHardness(1, 1, 2.0f, 3.0f) != 1 || DoorRecLayHardness(1, 1, 2.0f, 2.0f) != 0 || DoorRecLayHardness(0, 1, 2.0f, 3.0f) != 0
        || DoorRecLayHardness(1, 0, 2.0f, 3.0f) != 0) Fail("t1082: the lay's hardness rule is wrong");
    /* a dismantle: only a real 0 -> 1 flip removes the piece's door records */
    if (DoorRecDismantleRemoves(0, 1) != 1 || DoorRecDismantleRemoves(1, 1) != 0 || DoorRecDismantleRemoves(0, 0) != 0
        || DoorRecDismantleRemoves(-1, 1) != 0 || DoorRecDismantleRemoves(0, -1) != 0) Fail("t1082: the dismantle removal rule is wrong");
    /* and the removal is sent by the holder only, once the area's list is complete */
    if (DoorRecGoneDecide(1, 1, 1) != kDrGoneSend || DoorRecGoneDecide(1, 0, 1) != kDrGoneDrop || DoorRecGoneDecide(0, 1, 1) != kDrGoneWait)
        Fail("t1082: the removal is not sent by the holder alone");
    /* the wiring: the player branch in the write and the lay, no piece fact laid for a player door, the dismantle hook */
    const std::string dsrc = T313ReadFile("../coop-plugin/doors.cpp"), bsrc = T313ReadFile("../coop-plugin/build.cpp");
    if (dsrc.empty() || bsrc.empty()) { Fail("t1082: could not read the sources"); return; }
    const char* const dneed[] = { "live = (player != 0) ? doorrec::DoorRecPlayerFields(live) : doorrec::DoorRecTownFields(live);",
                                  "const int player = DrRecKind(r, &byRecord);",
                                  "const int kind = doorrec::DoorRecKindFor(local, have, (have != 0) ? k->second.r : doorrec::DoorRec());",
                                  "if (r->recGone != 0) { ++g_drGoneRowSkip; return; }",
                                  "::InterlockedExchange(&r->recGone, 1);",
                                  "(long)g_drOffLost, g_drKindByRecord, g_drGoneRowSkip,",
                                  "doorrec::DoorRecChangeMaskFor(player, have, have != 0 ? k->second.r : live, live)",
                                  "const int wrote = (player == 0) ? DoorsRecApply(",
                                  "(player != 0) ? doorrec::DoorRecPlayerHeldMerge(rec, live, heldMask)",
                                  "const int sent = DrSend(id, (player != 0) ? doorrec::DoorRecPlayerFields(live) : doorrec::DoorRecTownFields(live), pos, 1,",
                                  "DrPieceGoneDrain();" };
    for (size_t i = 0; i < sizeof(dneed) / sizeof(dneed[0]); ++i) if (dsrc.find(dneed[i]) == std::string::npos) Fail(std::string("t1082: doors.cpp lacks: ") + dneed[i]);
    if (dsrc.find("DrPlayerDoor(") != std::string::npos) Fail("t1082: doors.cpp still filters player doors off the record");
    {   /* review LOW 5: an unreadable kind is checked before the row is marked laid */
        const size_t lay = dsrc.find("int DrLayRow(DoorRow* r)");
        const size_t kind = (lay == std::string::npos) ? lay : dsrc.find("const int player = DrRecKind(r, &byRecord);", lay);
        const size_t mark = (lay == std::string::npos) ? lay : dsrc.find("::InterlockedExchange(&r->recLaid, 1);\n    ::InterlockedExchange(&r->recOwn, 0);", lay);
        const size_t mark2 = (lay == std::string::npos) ? lay : dsrc.find("::InterlockedExchange(&r->recLaid, 1);\r\n    ::InterlockedExchange(&r->recOwn, 0);", lay);
        const size_t m = (mark != std::string::npos) ? mark : mark2;
        if (kind == std::string::npos || m == std::string::npos || m < kind) Fail("t1082: DrLayRow marks the row laid before its kind is read");
    }
    if (bsrc.find("DoorsRecPieceGoneByKey(key.c_str(), BdOnMain());") == std::string::npos)
        Fail("t1082: a REMOVE whose copy was already gone does not queue the gate's door record removal");
    if (bsrc.find("DoorsRecPieceDismantled(&dk, before, after, onMain);") == std::string::npos || bsrc.find("if (before == 0) DoorsRecPieceKeysRead(b, &dk, BdOnMain());") == std::string::npos)
        Fail("t1082: the dismantle step does not take the piece's door records away");
}

/* T-4: the town clock record - its id, bytes and the world server's rule (holder only, rising generation) */
void t_t4_towntime_record()
{
    using namespace towntime;
    if (kProtocol != 170u || coopbrec::kProtocol != 170u || shoprec::kProtocol != 170u) Fail("t4: the world-server protocol is not 170");
    const std::string id = MakeTownTimeId(24, 32, "1234-gamedata.base");
    if (id != "towntime.24.32.1234-gamedata.base") Fail("t4: the id is not towntime.<sx>.<sy>.<sid>: " + id);
    int sx = -1, sy = -1; std::string sid;
    if (TownTimeIdParse(id, &sx, &sy, &sid) != 1 || sx != 24 || sy != 32 || sid != "1234-gamedata.base") Fail("t4: the id does not parse back");
    if (!IsTownTimeId("TownTime.1.2.x") || IsTownTimeId("shop.1.2.x") || IsTownTimeId("towntim")) Fail("t4: the prefix test");
    if (TownTimeIdParse("towntime.024.32.x", 0, 0, 0) != 0 || TownTimeIdParse("towntime.64.1.x", 0, 0, 0) != 0 || TownTimeIdParse("towntime.1.2.", 0, 0, 0) != 0
        || TownTimeIdParse("towntime.1.x", 0, 0, 0) != 0 || TownTimeIdParse("towntime.1.2.a\tb", 0, 0, 0) != 0) Fail("t4: a bad id parsed");
    if (!MakeTownTimeId(-1, 2, "x").empty() || !MakeTownTimeId(1, 2, "").empty() || !MakeTownTimeId(1, 2, std::string(97, 'a')).empty()) Fail("t4: a bad id was made");
    TownTimeRec r; r.generation = 3; r.writerSlot = 1; r.sx = 24; r.sy = 32; r.sid = "1234-gamedata.base"; r.started = 100.5; r.due = 220.5; r.lastRebuilt = kTtNever; r.rebuilds = 0;
    std::vector<char> b;
    if (!EncodeTownTimeRec(&b, r) || b.empty()) { Fail("t4: a valid record does not encode"); return; }
    TownTimeRec d;
    if (DecodeTownTimeRec(&b[0], b.size(), &d) != kTtOk || d.generation != 3 || d.writerSlot != 1 || d.sx != 24 || d.sy != 32 || d.sid != r.sid
        || d.started != 100.5 || d.due != 220.5 || d.lastRebuilt != kTtNever || d.rebuilds != 0) Fail("t4: the record does not round-trip");
    if (DecodeTownTimeRec(&b[0], b.size() - 1, &d) != kTtShort) Fail("t4: a cut record decoded");
    { std::vector<char> t = b; t.push_back(0); if (DecodeTownTimeRec(&t[0], t.size(), &d) != kTtTrailing) Fail("t4: trailing bytes decoded"); }
    { std::vector<char> t = b; t[0] = 'X'; if (DecodeTownTimeRec(&t[0], t.size(), &d) != kTtBadMarker) Fail("t4: a wrong marker decoded"); }
    { TownTimeRec x = r; x.due = -5.0; std::vector<char> t; if (EncodeTownTimeRec(&t, x) || !t.empty()) Fail("t4: a negative due encoded"); }
    { TownTimeRec x = r; x.lastRebuilt = 7.0; x.rebuilds = 2; std::vector<char> t; if (!EncodeTownTimeRec(&t, x) || DecodeTownTimeRec(&t[0], t.size(), &d) != kTtOk || d.lastRebuilt != 7.0 || d.rebuilds != 2) Fail("t4: lastRebuilt / rebuilds do not round-trip"); }
    { TownTimeRec x = r; x.owed.push_back("Faction_12"); x.owed.push_back("Faction_12"); std::vector<char> t; if (EncodeTownTimeRec(&t, x)) Fail("t4 fold 2: a repeated owed id encoded"); }
    { TownTimeRec x = r; x.owed.push_back("Faction_12"); x.owed.push_back("Faction_9"); std::vector<char> t;
      x.marked.push_back("Faction_3");
      if (!EncodeTownTimeRec(&t, x) || DecodeTownTimeRec(&t[0], t.size(), &d) != kTtOk || d.owed != x.owed || d.marked != x.marked) Fail("t4 fold 2/3: the owed and marked lists do not round-trip"); }
    /* the world server's rule */
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 1, 0, 0, 0, 0) != coopbrec::kBrAccept) Fail("t4: the holder's first write was refused");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 2, 0, 0, 0, 0) != coopbrec::kBrRefuseNotWriter) Fail("t4: a write by a game that does not hold the area was taken");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, -1, 0, 0, 0, 0) != coopbrec::kBrRefuseNotWriter) Fail("t4: a write while nobody holds the area was taken");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 2, 2, 0, 0, 0, 0) != coopbrec::kBrRefuseWriter) Fail("t4: a record naming another writer was taken");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 1, 1, 2, 0, 0) != coopbrec::kBrAccept) Fail("t4: a rising generation was refused");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 1, 1, 3, 1, 0) != coopbrec::kBrRepeat) Fail("t4: the very same bytes again were not a repeat");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 1, 1, 3, 0, 0) != coopbrec::kBrRefuseSameGen) Fail("t4: other bytes at the stored generation were taken");
    if (TownTimeJudgeWrite(id, &b[0], b.size(), 1, 1, 1, 4, 0, 0) != coopbrec::kBrRefuseOlder) Fail("t4: an older generation was taken");
    if (TownTimeJudgeWrite(MakeTownTimeId(24, 33, r.sid), &b[0], b.size(), 1, 1, 0, 0, 0, 0) != coopbrec::kBrRefuseWrongBox) Fail("t4: a record under another town's id was taken");
    if (TownTimeJudgeWrite("towntime.x", &b[0], b.size(), 1, 1, 0, 0, 0, 0) != coopbrec::kBrRefuseBadId) Fail("t4: a bad id was taken");
    if (TtRefusalSendsStored(coopbrec::kBrRefuseOlder) != 1 || TtRefusalSendsStored(coopbrec::kBrRefuseSameGen) != 1 || TtRefusalSendsStored(coopbrec::kBrRefuseNotWriter) != 0)
        Fail("t4: the refusals answered with the stored record are not older / same generation only");
}

/* T-4: the clock - due arithmetic, the holder's step, the generation rule; fold 2: the owed list, the accepted record apart from the write in flight */
void t_t4_towntime_clock()
{
    using namespace towntime;
    TownTimeRec none;
    const std::vector<std::string> noOwed;
    if (TtClockStep(0, none, 500.0, 0) != kTtSeed) Fail("t4: no record known is not a seed");
    if (TtClockStep(0, none, -1.0, 0) != kTtNoClock || TtClockStep(1, none, -1.0, 1) != kTtNoClock) Fail("t4: no clock acted");
    TownTimeRec k; k.generation = 4; k.writerSlot = 0; k.sx = 1; k.sy = 2; k.sid = "t"; k.started = 10.0; k.due = 130.0; k.lastRebuilt = kTtNever; k.rebuilds = 0;
    if (TtClockStep(1, k, 129.9, 0) != kTtWait) Fail("t4: before due with nothing owed is not a wait");
    if (TtClockStep(1, k, 130.0, 0) != kTtDue || TtClockStep(1, k, 5000.0, 0) != kTtDue) Fail("t4: at / long past due is not due (a new holder's past due is ONE walk)");
    if (TtClockStep(1, k, 20.0, 1) != kTtDue) Fail("t4: a forced walk is not due");
    if (TtClockStep(1, k, 9.0, 0) != kTtWait) Fail("t4: a due 121 h ahead (inside the slack) is not a wait");
    if (TtClockStep(1, k, 5.0, 0) != kTtClockBack) Fail("t4: a due more than one period ahead is not the clock going back");
    /* the first record: due = now + 120, started = now */
    const TownTimeRec s = TtNextRecord(0, none, 0u, 2, 1, 2, "t", 300.0, 0, 1, noOwed, noOwed);
    if (s.generation != 1 || s.writerSlot != 2 || s.started != 300.0 || s.due != 420.0 || s.lastRebuilt != kTtNever || s.rebuilds != 0 || !s.owed.empty()) Fail("t4: the first record is not due = now + 120 h");
    if (TtNextGen(0, 0u, 0u) != 1u || TtNextGen(1, 4u, 0u) != 5u || TtNextGen(1, 4u, 9u) != 10u || TtNextGen(0, 0u, 7u) != 8u) Fail("t4: the next generation");
    /* the deferral classes: only sight makes a group owed; asleep is the engine's mark or a final skip; a living unique a final skip */
    if (coopt2::IsDeferral(coopt2::kSeen) != 1 || coopt2::IsDeferral(coopt2::kAsleep) != 0 || coopt2::IsDeferral(coopt2::kUniqueAlive) != 0 || coopt2::IsDeferral(coopt2::kQueue) != 0)
        Fail("t4 fold 2: only sight makes a group owed");
    {
        coopt2::GroupFacts g; std::memset(&g, 0, sizeof(g)); g.marked = 1; g.living = 2; g.regenerates = 1; g.homeTown = 1; g.held = 1;
        if (coopt2::AsleepAct(g, coopt2::kRecipeRead, 0, 0) != coopt2::kQueue) Fail("t4 fold 2: an asleep pick with a plain recipe is not marked");
        if (coopt2::AsleepAct(g, coopt2::kRecipeRead, 1, 0) != coopt2::kUniqueUnknown || coopt2::AsleepAct(g, coopt2::kRecipeFault, 0, 0) != coopt2::kUniqueUnknown)
            Fail("t4 fold 2: an asleep pick whose recipe holds a unique (or did not read) is marked");
        if (coopt2::AsleepAct(g, coopt2::kRecipeRead, 0, 1) != coopt2::kSubSquads) Fail("t4 fold 2: an asleep pick with blocked sub-squads is marked");
        {   /* fold 3 (re-check 3): every final refusal that applies to an asleep group comes before the mark; sight is not tested */
            coopt2::GroupFacts h = g; h.jailed = 1; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kJailed) Fail("t4 fold 3: a jailed asleep group is marked");
            h = g; h.carried = 1; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kCarried) Fail("t4 fold 3: a carried asleep group is marked");
            h = g; h.player = 1; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kPlayerGroup) Fail("t4 fold 3: a player's asleep group is marked");
            h = g; h.held = 0; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kNotHeld) Fail("t4 fold 3: an asleep group outside the held zones is marked");
            h = g; h.living = 0; h.regenerates = 0; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kNoneAlive) Fail("t4 fold 3: an asleep group with nobody left the engine does not keep is marked");
            h = g; h.seen = 1; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kQueue) Fail("t4 fold 3: sight was tested for an asleep group");
            h = g; h.jailed = 1; h.dead = 1; if (coopt2::AsleepAct(h, coopt2::kRecipeRead, 0, 0) != coopt2::kDead) Fail("t4 fold 3: the asleep refusals are not in GroupVerdict's order");
        }
        g.dead = 1; if (coopt2::AsleepAct(g, coopt2::kRecipeRead, 0, 0) != coopt2::kDead) Fail("t4 fold 2: a dead asleep group is marked");
    }
    /* THE PERIOD WALK FINISHES WITH OWED GROUPS: g1 rebuilt, g2 seen (owed), g3 a living unique (final); the walk writes due = now + 120 */
    TtWalk w; TtWalkBegin(&w, 1, 131.0);
    TtWalkQueued(&w); TtWalkQueued(&w);
    TtWalkGroupEnd(&w, kTtEndFinal, "g3", 0);
    if (TtWalkReady(w) != 0) Fail("t4 fold 2: a walk with queued groups left is ready");
    TtWalkGroupEnd(&w, kTtEndRebuilt, "g1", 1);
    TtWalkGroupEnd(&w, kTtEndOwe, "g2", 1);   /* seen at its commitment */
    if (TtWalkReady(w) != 1 || TtWalkWrites(w, noOwed, noOwed) != 1) Fail("t4 fold 2: a period walk with an owed group does not finish and write");
    const std::vector<std::string> owed1 = TtWalkOwedAfter(noOwed, w);
    if (owed1.size() != 1 || owed1[0] != "g2") Fail("t4 fold 2: the owed list after the walk is not [g2]");
    const TownTimeRec p1 = TtNextRecord(1, k, 0u, 0, 1, 2, "t", 131.5, w.asked, 1, owed1, noOwed);
    if (p1.due != 251.5 || p1.lastRebuilt != 131.5 || p1.rebuilds != 1 || p1.owed != owed1 || p1.started != 10.0) Fail("t4 fold 2: the period walk's record is not due = now + 120 h with [g2] owed");
    if (TtClockStep(1, p1, 140.0, 0) != kTtOwed) Fail("t4 fold 2: before due with groups owed is not an owed walk");
    /* INHERITED BY A NEW HOLDER: the record's bytes carry the owed list; the new holder's step is the owed walk */
    {
        std::vector<char> b; TownTimeRec d;
        if (!EncodeTownTimeRec(&b, p1) || DecodeTownTimeRec(&b[0], b.size(), &d) != kTtOk || d.owed != owed1) Fail("t4 fold 2: the owed list does not survive the record's bytes");
        TtKeep nk;
        if (TtOnArrive(&nk, d) != 1 || nk.have != 1 || nk.r.owed != owed1 || TtClockStep(nk.have, nk.r, 140.0, 0) != kTtOwed) Fail("t4 fold 2: a new holder does not inherit the owed walk");
    }
    /* THE OWED WALK, ONCE: still seen -> nothing written; then unseen -> rebuilt, dropped, written with due KEPT */
    TtWalk o; TtWalkBegin(&o, 0, 140.0);
    TtWalkGroupEnd(&o, kTtEndOwe, "g2", 0);
    if (TtWalkWrites(o, owed1, noOwed) != 0) Fail("t4 fold 2: an owed walk that changed nothing writes");
    TtWalkBegin(&o, 0, 141.0);
    TtWalkQueued(&o);
    TtWalkGroupEnd(&o, kTtEndRebuilt, "g2", 1);
    const std::vector<std::string> owed2 = TtWalkOwedAfter(owed1, o);
    if (TtWalkWrites(o, owed1, noOwed) != 1 || !owed2.empty()) Fail("t4 fold 2: the owed group rebuilt is not dropped and written");
    const TownTimeRec p2 = TtNextRecord(1, p1, 0u, 0, 1, 2, "t", 141.0, o.asked, 0, owed2, noOwed);
    if (p2.due != 251.5 || p2.rebuilds != 2 || p2.lastRebuilt != 141.0 || !p2.owed.empty() || TtClockStep(1, p2, 142.0, 0) != kTtWait) Fail("t4 fold 2: the owed walk moved due or miscounted (C)");
    /* A NEW PERIOD MERGES: g2 owed again and g4 newly owed - each once */
    {
        std::vector<std::string> add; add.push_back("g4"); add.push_back("g2");
        const std::vector<std::string> m = TtOwedMerge(owed1, add, noOwed);
        if (m.size() != 2 || m[0] != "g2" || m[1] != "g4") Fail("t4 fold 2: a new period's owed groups are not merged once each");
    }
    /* B: the accepted record apart from the write in flight; a refusal goes back to it */
    {
        TtKeep kp;
        if (TtOnArrive(&kp, p1) != 1 || kp.haveAcc != 1) Fail("t4 fold 2 B: an arrival is not the accepted record");
        TtOnWrite(&kp, p2, 77);
        if (kp.r.generation != p2.generation || kp.inflight != 1 || kp.acc.generation != p1.generation) Fail("t4 fold 2 B: a write in flight replaced the accepted record");
        TtOnRefuse(&kp, 9u);
        if (kp.inflight != 0 || kp.r.generation != p1.generation || kp.floorGen != 9u || TtNextGen(kp.have, kp.r.generation, kp.floorGen) != 10u) Fail("t4 fold 2 B: a refusal does not go back to the accepted record above the stored generation");
        TownTimeRec st = p1; st.generation = 9; st.writerSlot = 1; st.due = 300.0;
        if (TtOnArrive(&kp, st) != 1 || kp.r.due != 300.0) Fail("t4 fold 2 B: the stored record sent with the refusal is not taken");
        TtOnWrite(&kp, p2, 78); TtOnEcho(&kp, 79);
        if (kp.inflight != 1) Fail("t4 fold 2 B: another write's echo was taken");
        TtOnEcho(&kp, 78);
        if (kp.inflight != 0 || kp.acc.generation != p2.generation) Fail("t4 fold 2 B: the echo does not make the write the accepted record");
        TownTimeRec old = p1; old.generation = 3;
        if (TtOnArrive(&kp, old) != 0) Fail("t4 fold 2 B: an older arrival was taken");
    }
    /* B: the town's area lost before a queued group's commitment - the walk is dropped and writes nothing */
    {
        TtWalk lw; TtWalkBegin(&lw, 1, 200.0); TtWalkQueued(&lw); TtWalkQueued(&lw);
        TtWalkGroupEnd(&lw, kTtEndRebuilt, "g1", 1);
        TtWalkLostHold(&lw);
        if (TtWalkReady(lw) != 0 || TtWalkWrites(lw, noOwed, noOwed) != 0 || lw.active != 0) Fail("t4 fold 2 B: a walk whose hold was lost at commitment writes");
    }
    /* fold 3 (re-check 2b): THE MARKED LIST - an asleep pick is listed on the record; a new holder re-applies; it leaves at its wake */
    {
        TtWalk mw; TtWalkBegin(&mw, 1, 300.0);
        TtWalkGroupEnd(&mw, kTtEndMarked, "a1", 0);
        const std::vector<std::string> m1 = TtWalkMarkedAfter(noOwed, mw);
        if (mw.asked != 1 || m1.size() != 1 || m1[0] != "a1" || TtWalkWrites(mw, noOwed, noOwed) != 1) Fail("t4 fold 3: an asleep pick is not counted and listed");
        const TownTimeRec q1 = TtNextRecord(1, k, 0u, 0, 1, 2, "t", 300.0, mw.asked, 1, noOwed, m1);
        std::vector<char> b; TownTimeRec d; TtKeep nk;
        if (!EncodeTownTimeRec(&b, q1) || DecodeTownTimeRec(&b[0], b.size(), &d) != kTtOk || d.marked != m1) Fail("t4 fold 3: the marked list does not survive the record's bytes");
        if (TtOnArrive(&nk, d) != 1 || TtClockStep(nk.have, nk.r, 310.0, 0) != kTtOwed) Fail("t4 fold 3: a new holder does not walk a marked group before due");
        TtWalk rw; TtWalkBegin(&rw, 0, 310.0);
        TtWalkGroupEnd(&rw, kTtEndRemarked, "a1", 0);   /* still asleep: the mark re-applied, not counted again, nothing to write */
        if (rw.asked != 0 || TtWalkMarkedAfter(d.marked, rw) != d.marked || TtWalkWrites(rw, d.owed, d.marked) != 0) Fail("t4 fold 3: re-applying a listed mark counts or writes");
        TtWalk ww; TtWalkBegin(&ww, 0, 320.0);
        TtWalkGroupEnd(&ww, kTtEndWoke, "a1", 0);   /* woke: leaves the list */
        if (!TtWalkMarkedAfter(d.marked, ww).empty() || TtWalkWrites(ww, d.owed, d.marked) != 1 || ww.asked != 0) Fail("t4 fold 3: a woken group does not leave the marked list (or is counted twice)");
        TtWalk fw; TtWalkBegin(&fw, 0, 320.0);
        TtWalkGroupEnd(&fw, kTtEndFinal, "a1", 0);   /* fails a final test: leaves */
        if (!TtWalkMarkedAfter(d.marked, fw).empty()) Fail("t4 fold 3: a listed group failing a final test stays listed");
        TownTimeRec dd = d; dd.marked.push_back("a1");
        std::vector<char> b2; if (EncodeTownTimeRec(&b2, dd)) Fail("t4 fold 3: a repeated marked id encoded");
    }
    /* fold 3 (re-check 1c): a write in flight when the link dropped - the new link's WELCOME goes back to the accepted record */
    {
        TtKeep lk; TtOnArrive(&lk, p1); TtOnWrite(&lk, p2, 90);
        if (TtOnLinkNew(&lk) != 1 || lk.inflight != 0 || lk.r.generation != p1.generation || lk.r.due != p1.due) Fail("t4 fold 3: an unanswered write survives the new link");
        if (TtOnLinkNew(&lk) != 0) Fail("t4 fold 3: a second new link gives up a write again");
        TtKeep nk2; TtOnWrite(&nk2, s, 91);
        if (TtOnLinkNew(&nk2) != 1 || nk2.have != 0 || TtClockStep(nk2.have, nk2.r, 400.0, 0) != kTtSeed) Fail("t4 fold 3: an unanswered first write does not leave the town to be seeded again");
    }
    /* fold 3 (re-check 1a): the 65th id is counted, never silent */
    {
        std::vector<std::string> many;
        for (int i = 0; i < 65; ++i) { char nb[16]; std::sprintf(nb, "g%d", i); many.push_back(nb); }
        int capped = 0;
        const std::vector<std::string> m = TtOwedMerge(noOwed, many, noOwed, &capped);
        if (m.size() != kTtOwedMax || capped != 1) Fail("t4 fold 3: the 65th owed id is not counted as capped");
    }
}

/* T-4: the record's road on both sides - the in-memory clock gone, the world server's judge and list exclusions, the game's routes */
/* T-4 TEST-ONLY `towntime period`: the parse; every NEW due = now + the period; the clock-back test follows the period; the
   default is the players' 120 h; an owed walk keeps due; the verb reaches the lever outside the DEV-only block */
void t_t4_towntime_period()
{
    using namespace towntime;
    double h = -5.0;
    if (TtPeriodLeverParse("period 10", &h) != 1 || h != 10.0) Fail("t4 period: 'period 10' not taken as 10");
    if (TtPeriodLeverParse("  period   1 ", &h) != 1 || h != 1.0) Fail("t4 period: the lower bound 1 refused");
    if (TtPeriodLeverParse("period 120", &h) != 1 || h != 120.0) Fail("t4 period: the upper bound 120 refused");
    if (TtPeriodLeverParse("period 2.5", &h) != 1 || h != 2.5) Fail("t4 period: a fractional period refused");
    h = 7.0;
    const char* const bad[] = { "", "period", "period 0", "period 0.5", "period 121", "period -3", "period ten", "period 10h", "period 10 20", "perio 10", "10", "period nan" };
    for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); ++i) if (TtPeriodLeverParse(bad[i], &h) != 0) Fail(std::string("t4 period: refused form taken: '") + bad[i] + "'");
    if (h != 7.0) Fail("t4 period: a refused form changed the value");
    if (TtPeriodLeverParse("period show", &h) != 2 || h != 7.0) Fail("t4 period: show not a read");
    const std::vector<std::string> none, ow(1, "5-gamedata.base");
    TownTimeRec k; k.generation = 3; k.writerSlot = 0; k.sx = 43; k.sy = 11; k.sid = "t"; k.started = 10.0; k.due = 50.0; k.lastRebuilt = kTtNever; k.rebuilds = 0;
    {   /* the first record and a finished period walk: due = now + 10 */
        const TownTimeRec a = TtNextRecord(0, k, 0u, 1, 43, 11, "t", 200.0, 0, 1, none, none, 10.0);
        if (a.due != 210.0 || a.started != 200.0) Fail("t4 period: the first record's due is not now + 10");
        const TownTimeRec b = TtNextRecord(1, k, 0u, 1, 43, 11, "t", 60.0, 2, 1, ow, none, 10.0);
        if (b.due != 70.0 || b.lastRebuilt != 60.0 || b.rebuilds != 2 || b.owed != ow) Fail("t4 period: a period walk's due is not now + 10 or the rest moved");
        const TownTimeRec c = TtNextRecord(1, k, 0u, 1, 43, 11, "t", 45.0, 1, 0, none, none, 10.0);
        if (c.due != 50.0) Fail("t4 period: an owed walk moved due");
        const TownTimeRec d = TtNextRecord(1, k, 0u, 1, 43, 11, "t", 60.0, 0, 1, none, none);
        if (d.due != 60.0 + kTtPeriodHours || kTtPeriodHours != 120.0) Fail("t4 period: the default is not the players' 120 h");
    }
    {   /* the step with a 10 h period: before due wait, at due due, a due written under 120 h is the clock-back rewrite */
        if (TtClockStep(1, k, 45.0, 0, 10.0) != kTtWait) Fail("t4 period: 5 h before a 10 h due is not a wait");
        if (TtClockStep(1, k, 50.0, 0, 10.0) != kTtDue) Fail("t4 period: at due is not due under a 10 h period");
        TownTimeRec farRec = k; farRec.due = 200.0 + kTtPeriodHours;
        if (TtClockStep(1, farRec, 200.0, 0, 10.0) != kTtClockBack) Fail("t4 period: a 120 h due is not rewritten under a 10 h period");
        if (TtClockStep(1, farRec, 200.0, 0) != kTtWait) Fail("t4 period: the players' default judged a 120 h due as clock-back");
        TownTimeRec edge = k; edge.due = 200.0 + 10.0 + kTtClockBackSlack;
        if (TtClockStep(1, edge, 200.0, 0, 10.0) != kTtWait) Fail("t4 period: a due one period + slack ahead is clock-back");
    }
    {   /* the verb: outside the DEV-only block (the command file is the gate, as timeskip / gamespeed) and routed to the lever */
        std::string cc = T313ReadFile("../coop-plugin/command_channel.cpp");
        for (size_t a = 0; (a = cc.find('\r', a)) != std::string::npos; ) cc.erase(a, 1);
        const size_t v = cc.find("else if (verb == \"towntime\")"), r = cc.find("WriteStatus(coop::TownTimePeriodCommand(rest));"), dev = cc.find("#ifdef SW_DEV_BUILD\n    else if (verb == \"camlook\")");
        if (v == std::string::npos || r == std::string::npos || r < v) Fail("t4 period: command_channel.cpp does not route towntime to TownTimePeriodCommand");
        else if (dev != std::string::npos && v > dev) Fail("t4 period: the towntime verb sits after the DEV-only block start (expected beside townres)");
    }
}
/* T-4 design (d): the owed-not-run rule, the dead verdict from living resident groups, no verdict on an empty list */
void t_t4d_rules()
{
    using namespace coopt2;
    /* runs here: the runner test's slot decides; with no slot, another live game's note makes it not run here */
    if (RunsHere(1, 1, -1, 0) != 1 || RunsHere(0, 1, -1, 0) != 0 || RunsHere(0, 1, 1, 0) != 0) Fail("t4d: the runner's slot does not decide");
    if (RunsHere(-1, 1, -1, 0) != 1) Fail("t4d: an asleep / split group nobody else runs is not this game's");
    if (RunsHere(-1, 1, 0, 0) != 0) Fail("t4d: a group the world server says another game runs is run here");
    if (RunsHere(-1, 1, 1, 0) != 1) Fail("t4d: the world server's note naming this game is not run here");
    /* fold 1 (LOW-1): the list hold - before LIST END a copy asleep here (no runner, no note) is not run here; a runner's slot still decides */
    if (RunsHere(-1, 1, -1, 1) != 0) Fail("t4d f1: a copy held by the list hold reads run here");
    if (RunsHere(1, 1, -1, 1) != 1 || RunsHere(-1, 1, 0, 1) != 0) Fail("t4d f1: the list hold overrides the runner's slot or the note");
    /* the walk's step for a group not run here: never marked, queued or ended as final */
    if (NotRunStepOf(1, 0, 1, 1) != kNrKeepMarked || NotRunStepOf(1, 1, 0, 0) != kNrKeepMarked) Fail("t4d: a marked-list group not run here leaves the list");
    if (NotRunStepOf(0, 1, 0, 0) != kNrOwe || NotRunStepOf(0, 1, 1, 0) != kNrOwe) Fail("t4d: an owed group not run here is not carried");
    if (NotRunStepOf(0, 0, 1, 1) != kNrOwe) Fail("t4d: a period walk's pick not run here is not owed");
    if (NotRunStepOf(0, 0, 1, 0) != kNrLeave || NotRunStepOf(0, 0, 0, 1) != kNrLeave) Fail("t4d: an unpicked group, or an owed walk's group off its list, is carried");
    /* a living group */
    if (LivingGroup(0, 1) != 1 || LivingGroup(1, 5) != 0 || LivingGroup(0, 0) != 0) Fail("t4d: the living group test");
    /* the verdict: living groups win over the byte */
    if (TownVerdictOf(1, 3, 1, 0, 1) != kTvAlive) Fail("t4d: a town with a living resident group reads dead because of the byte");
    if (TownVerdictOf(1, 3, 2, 1, 1) != kTvAlive) Fail("t4d: an unread group hides a living one");
    if (TownVerdictOf(1, 3, 0, 0, 1) != kTvDead) Fail("t4d: resident groups none living with the byte set is not dead");
    if (TownVerdictOf(1, 3, 0, 0, 0) != kTvAlive) Fail("t4d: none living with the byte clear is not walked (the engine did not call it dead)");
    /* no verdict on an empty list, an unread list or an unread group with none living - whatever the byte */
    /* fold 1 (MEDIUM-2): an empty list with the byte CLEAR = alive, walked (the engine's own early exit; single player runs its marker then);
       an empty list with the byte SET = no verdict (T2323: A's copies withdrawn, the byte set at that check-up) */
    if (TownVerdictOf(1, 0, 0, 0, 0) != kTvAlive || TownByteDisagrees(1, 0, 0, 0, 0) != 0) Fail("t4d f1: an empty list with the byte clear is not walked (or disagrees)");
    if (TownVerdictOf(1, 0, 0, 0, 1) != kTvNoResidents || TownByteDisagrees(1, 0, 0, 0, 1) != 0) Fail("t4d f1: an empty list with the byte set gets a verdict");
    if (TownVerdictOf(0, 0, 0, 0, 1) != kTvUnread || TownVerdictOf(1, 3, 0, 1, 1) != kTvUnread) Fail("t4d: an unread list or group gets a verdict");
    if (TownVerdictName(kTvNoResidents) != std::string("noResidents") || TownVerdictName(kTvDead) != std::string("dead")) Fail("t4d: verdict names");
    /* T2323's two cases: B's byte set with its copies withdrawn (empty list) - no verdict; B's byte still set after B took the people
       over (22 groups, living) - alive, and the byte disagrees */
    if (TownVerdictOf(1, 0, 0, 0, 1) != kTvNoResidents || TownByteDisagrees(1, 0, 0, 0, 1) != 0) Fail("t4d: T2323 at 244.489 (empty list, byte 1)");
    if (TownVerdictOf(1, 22, 22, 0, 1) != kTvAlive || TownByteDisagrees(1, 22, 22, 0, 1) != 1) Fail("t4d: T2323 after the take-over (22 living, byte 1)");
    if (TownByteDisagrees(1, 3, 0, 0, 0) != 1) Fail("t4d: a clear byte over groups none living does not disagree");
    if (TownByteDisagrees(1, 3, 1, 0, 0) != 0 || TownByteDisagrees(1, 3, 0, 0, 1) != 0) Fail("t4d: an agreeing byte disagrees");
    if (TownByteDisagrees(0, 3, 0, 0, 1) != 0 || TownByteDisagrees(1, 3, 0, 2, 1) != 0) Fail("t4d: a list with no verdict disagrees");
    /* fold 1 (LOW-2): a dead town ends as final only resident ids this game runs; patrol ids (not on the resident list) and not-run ids stay */
    if (DeadTownEndsFinal(1, 1) != 1) Fail("t4d f1: a dead town does not end its own resident id");
    if (DeadTownEndsFinal(1, 0) != 0) Fail("t4d f1: a dead town ends a resident id another game runs");
    if (DeadTownEndsFinal(0, 1) != 0 || DeadTownEndsFinal(0, 0) != 0) Fail("t4d f1: a dead town ends a patrol id or an id not read here");
}
/* T-4 design (d): the walk, the commitment, the kill and the check-up wired to the rules; the store's runner facts; no write of the byte */
void t_t4d_wiring()
{
    std::string tg = T313ReadFile("../coop-plugin/towngen.cpp"), st = T313ReadFile("../coop-plugin/store.cpp");
    if (tg.empty() || st.empty()) { Fail("t4d wiring: a source did not read"); return; }
    for (size_t a = 0; (a = tg.find('\r', a)) != std::string::npos; ) tg.erase(a, 1);
    for (size_t a = 0; (a = st.find('\r', a)) != std::string::npos; ) st.erase(a, 1);
    const char* const needTg[] = {
        "const int here = coopt2::RunsHere(*runner, StoreMySlot(), *other, held);",
        "*runner = coop::StoreGroupRunner(platoon, other, &held);",
        "if (coopt2::DeadTownEndsFinal(ri != runIds.end() ? 1 : 0, (ri != runIds.end() && ri->second != 0) ? 1 : 0) != 0) TtEnd(T, towntime::kTtEndFinal, ls[o], 0);",
        "std::map<std::string, int> runIds; T2ResidentRunHere(town, &runIds);",
        "(*ids)[w] = T2RunsHere(G.platoon, &ru, &ot);",
        "/* towns2 */ Towns2Teardown(); g_t2ByteSaid.clear();",
        "if (T2RunsHere(G.platoon, &ru, &ot) == 0)\n                {\n                    ++g_t2NotRun;",
        ": coopt2::NotRunStepOf(towntime::TtOwedAt(T->k.r.marked, nw) >= 0 ? 1 : 0, towntime::TtOwedAt(T->k.r.owed, nw) >= 0 ? 1 : 0, T->w.period, G.f.marked);",
        "else if (st == coopt2::kNrOwe) { owedSeen.push_back(nw); ++g_t2NotRunOwed; TtEnd(*T, towntime::kTtEndOwe, nw, 0); }",
        "else if (T2RunsHere(G.platoon, &ru, &ot) == 0)\n        {   /* T-4 design (d): the moment of commitment",
        "++g_t2ActNotRun; ttEnd = towntime::kTtEndOwe;",
        "{ int ru = -1, ot = -1; if (T2RunsHere(G.platoon, &ru, &ot) == 0) { ++notRun; ++g_t2KillNotRun; continue; } }",
        "const int tv = coopt2::TownVerdictOf(tvRead, tvN, tvLiving, tvUnread, byteDead);",
        "if (tv == coopt2::kTvNoResidents || tv == coopt2::kTvUnread)",
        "townDead = (tv == coopt2::kTvDead) ? 1 : 0;\n    towntime::TtWalkBegin(&T.w, period, now);\n    if (townDead != 0)",
        "if (coopt2::LivingGroup(G.f.dead, G.f.living) != 0) ++*living;",
        "if (g_t2ByteSaid.insert(key).second)",
        " noVerdict=\" + N(g_t2NoVerdict) + \" byteDisagree=\" + N(g_t2ByteDisagree)" };
    for (size_t i = 0; i < sizeof(needTg) / sizeof(needTg[0]); ++i) if (tg.find(needTg[i]) == std::string::npos) Fail(std::string("t4d wiring: towngen.cpp lacks ") + needTg[i]);
    /* the walk's not-run test comes before the marked list, the owed walk and the verdict; the verdict before the walk begins */
    const size_t wNr = tg.find("++g_t2NotRun;"), wMk = tg.find("if (towntime::TtOwedAt(T->k.r.marked, ow) >= 0)"), wGv = tg.find("const int v = coopt2::GroupVerdict(G.f, nosight);");
    if (wNr == std::string::npos || wMk == std::string::npos || wGv == std::string::npos || !(wNr < wMk && wMk < wGv)) Fail("t4d wiring: the not-run test is not ahead of the marked list and the group verdict");
    const size_t cV = tg.find("const int tv = coopt2::TownVerdictOf("), cB = tg.find("towntime::TtWalkBegin(&T.w, period, now);");
    if (cV == std::string::npos || cB == std::string::npos || cV > cB) Fail("t4d wiring: the verdict is not decided before the walk begins");
    /* fold 1 (LOW-4): the no-verdict branch returns before the walk begins, with no write, no end and no walk step inside it */
    const size_t nvA = tg.find("if (tv == coopt2::kTvNoResidents || tv == coopt2::kTvUnread)");
    const size_t nvR = (nvA == std::string::npos) ? std::string::npos : tg.find("\n        return;\n    }\n", nvA);
    if (nvA == std::string::npos || nvR == std::string::npos || cB == std::string::npos || !(nvA < nvR && nvR < cB)) Fail("t4d f1 wiring: the no-verdict branch does not return before TtWalkBegin");
    else
    {
        const std::string nv = tg.substr(nvA, nvR - nvA);
        const char* const banned[] = { "TtWalkBegin", "TtWrite", "TtEnd(", "TtWalkMaybeEnd", "T2Walk(" };
        for (size_t i = 0; i < sizeof(banned) / sizeof(banned[0]); ++i) if (nv.find(banned[i]) != std::string::npos) Fail(std::string("t4d f1 wiring: the no-verdict branch calls ") + banned[i]);
        if (tg.find("towntime::TtWalkBegin(&T.w, period, now);", nvR) != cB) Fail("t4d f1 wiring: the walk begins somewhere other than after the no-verdict branch");
    }
    /* T-1341 (owner 1614 a): the engine's dead byte is written in exactly one place - T1341ClearPod's clear; nowhere else */
    {
        const std::string w = "*(volatile unsigned char*)(mgr + 8) = 0;";
        const size_t w1 = tg.find(w), cp = tg.find("static int T1341ClearPod(void* town)"), dm = tg.find("static void T1341DeadMarkCheck(void* town)");
        if (w1 == std::string::npos || tg.find(w, w1 + 1) != std::string::npos || cp == std::string::npos || dm == std::string::npos || !(cp < w1 && w1 < dm)) Fail("t4d wiring: the byte +8 is not written exactly once, inside T1341ClearPod");
        if (tg.find("(mgr + 8)) = ") != std::string::npos) Fail("t4d wiring: towngen.cpp writes the population manager's byte +8 another way");
        size_t c = 0; for (size_t a = 0; (a = tg.find("(mgr + 8) = ", a)) != std::string::npos; ++a) ++c;
        if (c != 1) Fail("t4d wiring: towngen.cpp writes the population manager's byte +8 outside the T-1341 clear");
    }
    if (st.find("int StoreGroupRunner(void* platoon, int* otherRunner, int* listHeld)") == std::string::npos
        || st.find("*otherRunner = SwOtherRunner(wid);\n    if (*otherRunner < 0) *listHeld = SwListHeld(wid);") == std::string::npos) Fail("t4d wiring: store.cpp lacks StoreGroupRunner (with the list hold)");
}
void t_t1341_rules()
{
    using namespace coopt2;
    /* byte clear: nothing to do, whatever else holds */
    if (DeadMarkStepOf(0, 1, 1, 3, 2, 1) != kDmByteClear) Fail("t1341: a clear byte is acted on");
    /* the list not read: kept */
    if (DeadMarkStepOf(1, 0, 1, 3, 2, 1) != kDmUnread) Fail("t1341: an unread list clears");
    /* not held: only the holder acts */
    if (DeadMarkStepOf(1, 1, 0, 3, 2, 1) != kDmNotHeld) Fail("t1341: a game that does not hold the town clears");
    /* runs none: a game holding only copies leaves the byte to the game that runs the people */
    if (DeadMarkStepOf(1, 1, 1, 0, 0, 3) != kDmRunsNone) Fail("t1341: a game running no resident group clears");
    /* no intact resident group: a truly dead town is never cleared */
    if (DeadMarkStepOf(1, 1, 1, 2, 0, 0) != kDmNoIntact) Fail("t1341: a truly dead town (no intact resident group) is cleared");
    if (DeadMarkStepOf(1, 1, 1, 1, 0, 0) == kDmClear || DeadMarkStepOf(1, 1, 1, 5, 0, 0) == kDmClear) Fail("t1341: run groups none intact clear");
    /* an intact copy only (this game runs a resident group, the intact one is a copy): cleared - copies count (T2323 copy=40 intact=40) */
    if (DeadMarkStepOf(1, 1, 1, 1, 0, 1) != kDmClear) Fail("t1341: an intact copy (with a run resident group) does not clear");
    /* an intact own group: cleared */
    if (DeadMarkStepOf(1, 1, 1, 1, 1, 0) != kDmClear || DeadMarkStepOf(1, 1, 1, 22, 22, 0) != kDmClear) Fail("t1341: an intact own group does not clear");
    if (DeadMarkStepName(kDmClear) != std::string("clear") || DeadMarkStepName(kDmNoIntact) != std::string("noIntact") || DeadMarkStepName(kDmRunsNone) != std::string("runsNone")) Fail("t1341: step names");
    /* fold 1: intact from the engine's own facts (0x7ABC10), read only */
    if (GroupIntact(1, 1, 5, 1) != 0 || GroupIntact(1, 0, 0, 1) != 0) Fail("t1341 f1: a group declared dead (+0x1F0) is intact");
    if (GroupIntact(0, 1, 1, 0) != 1 || GroupIntact(0, 1, 0, 1) != 0) Fail("t1341 f1: an awake group is not judged by its living members");
    if (GroupIntact(0, 0, 0, 1) != 1 || GroupIntact(0, 0, 7, 0) != 0) Fail("t1341 f1: an asleep group is not judged by its cached +0x100");
    /* the re-set watch */
    if (DeadMarkReSet(1, 1) != 1 || DeadMarkReSet(0, 1) != 0 || DeadMarkReSet(1, 0) != 0 || DeadMarkReSet(0, 0) != 0) Fail("t1341: the re-set watch");
}
