/* T-1046 fix 1: the "already queued for delete" search over the physics holder's two lists, and the skip decision */
/* T-1329 (design C): the EMPTY area record's bytes - encoded, decoded, read to their end by the world server's reader, taken at receipt */
void t_t1329_empty_record()
{
    std::vector<char> m; zonerec::ZoneEmptyEncode(&m);
    if (m.size() != zonerec::kZoneEmptyMarkLen || zonerec::ZoneEmptyIs(m) != 1) Fail("t1329: the EMPTY mark does not read back as EMPTY");
    if (std::string(&m[0], m.size()) != std::string(zonerec::kZoneEmptyMark)) Fail("t1329: the EMPTY mark's bytes are not kZoneEmptyMark");
    std::vector<char> none; if (zonerec::ZoneEmptyIs(none) != 0) Fail("t1329: no bytes read as EMPTY");
    std::vector<char> flip(m); flip[3] = (char)(flip[3] ^ 1); if (zonerec::ZoneEmptyIs(flip) != 0) Fail("t1329: a changed mark reads as EMPTY");
    std::vector<char> longer(m); longer.push_back('x'); if (zonerec::ZoneEmptyIs(longer) != 0) Fail("t1329: the mark with a byte more reads as EMPTY");
    std::vector<char> shorter(m.begin(), m.end() - 1); if (zonerec::ZoneEmptyIs(shorter) != 0) Fail("t1329: the mark with a byte less reads as EMPTY");
    size_t stop = 99;
    if (zonecheck::ReadableBytes(m, &stop) != 1 || stop != m.size()) Fail("t1329: the EMPTY record is not read to its end (receipt, start and send would refuse it)");
    if (zonecheck::ReceiptJudge(zonecheck::ReadableBytes(m, 0)) != zonecheck::kReceiptTake) Fail("t1329: the world server would refuse an EMPTY record at receipt");
    if (zonecheck::StartChoose(zonecheck::ReadableBytes(m, 0), 1, 1) != zonecheck::kStartCurrent) Fail("t1329: the world server's start would not serve a stored EMPTY record");
    if (zonecheck::ReadableBytes(flip, 0) != 0 || zonecheck::ReadableBytes(longer, 0) != 0) Fail("t1329: a damaged mark reads to its end");
    /* judged by the stamp as any area record: newer than the held copy -> taken; not newer and not the holder's -> refused */
    if (zonerec::ZoneRecvTakes(zonerec::ZoneRecvJudge(1, 100, 1, 101, 1, 1, 0)) != 1) Fail("t1329: a newer record is not taken");
    if (zonerec::ZoneRecvTakes(zonerec::ZoneRecvJudge(1, 101, 1, 100, 2, 1, 0)) != 0) Fail("t1329: an older record from a non-holder is taken");
}
/* T-1329: the area read's decision for an EMPTY record, its no-file path, and the WRITE round's fault rule */
void t_t1329_read_decision()
{
    using namespace zonerec;
    if (ZoneReadServe(1, 1, 1, 1) != kZrdNoFile) Fail("t1329: an EMPTY record does not give the read no file");
    if (ZoneReadServe(1, 1, 1, 0) != kZrdRecord) Fail("t1329: a record with a file is not served");
    if (ZoneReadServe(0, 1, 1, 1) != kZrdOwnFile || ZoneReadServe(1, 0, 1, 1) != kZrdOwnFile || ZoneReadServe(1, 1, 0, 1) != kZrdOwnFile)
        Fail("t1329: the swap off, no record or no file named does not leave Kenshi its own file");
    if (ZoneNoFilePath("C:\\w\\mirror\\zone.19.31.zone") != "C:\\w\\mirror\\no-file-empty-area\\zone.19.31.zone") Fail("t1329: the no-file path is not the mirror name in the never-made folder");
    if (ZoneNoFilePath("zone.1.2.zone") != "no-file-empty-area\\zone.1.2.zone") Fail("t1329: the no-file path of a bare name");
    if (ZoneNotPublishedIsFault(1, 0) != 1 || ZoneNotPublishedIsFault(0, 0) != 1 || ZoneNotPublishedIsFault(-1, 0) != 0 || ZoneNotPublishedIsFault(0, -1) != 1)
        Fail("t1329 fold 1 (F2): the not-published fault rule (a written file or a refused EMPTY of a read area = fault; not read = notPublished)");
    if (ZoneNotPublishedIsFault(0, 1) != 0 || ZoneNotPublishedIsFault(-1, 1) != 0) Fail("t1329 fold 2: an area whose read is still due here must answer notPublished (the asker waits for the record), not fault");
    /* fold 1 (F1): an EMPTY only when Kenshi saved nothing and the area's read ran here */
    if (ZoneEmptyMayPublish(0, 0) != 1 || ZoneEmptyMayPublish(0, 1) != 0 || ZoneEmptyMayPublish(1, 0) != 0 || ZoneEmptyMayPublish(-1, 0) != 0 || ZoneEmptyMayPublish(0, -1) != 0)
        Fail("t1329 fold 1 (F1): the EMPTY publish rule (nothing saved and the read not due)");
    /* fold 1 (F4): a queued EMPTY older than the area's last main-thread save is dropped */
    if (ZoneQueuedEmptyStale(5, 6) != 1 || ZoneQueuedEmptyStale(5, 4) != 0 || ZoneQueuedEmptyStale(5, 0) != 0) Fail("t1329 fold 1 (F4): the queued-EMPTY order rule");
}
