    const size_t r = g == std::string::npos ? g : st.find("if (coopsquad::HandedOverWakeRefuse(coopsquad::HandOverHoldsWake(given, open), T300WorldFaction(platoon)) == 1)", g);
    const size_t call = r == std::string::npos ? r : st.find("GivenWakeRefuse(platoon, wid, q, whole, takenSlot, 0, open);", r);
    const size_t ret = call == std::string::npos ? call : st.find("orig_activate(platoon);", call);
