        if (st.find("GivenWaitTick();   /* T-1318 fold 1") == std::string::npos) Fail("t1318 fold 1 (F3): GivenWaitTick not ticked");
        if (st.find("g_givenWait.clear(); g_givenWaitSeq = -1;") == std::string::npos) Fail("t1318 fold 1 (F3): the given-wait outlives its world");
