/* T-1318 a4 fold 2: one record of a sleeping container in 0x6BD220's layout (ownrec.h GdcSpans) - handS > 0 gives it its own hand (type 1),
   dead >= 0 a bool field "dead", inst one instance per entry naming those states */
static void T1318f2Str(std::vector<char>* v, const std::string& s) { coopown::GdcPutI32(v, (int)s.size()); v->insert(v->end(), s.begin(), s.end()); }
static void T1318f2Rec(std::vector<char>* v, int type, const std::string& sid, int handS, int dead, const std::vector<std::vector<std::string> >& inst)
{
    coopown::GdcPutI32(v, 0); coopown::GdcPutI32(v, type); coopown::GdcPutI32(v, 0); T1318f2Str(v, ""); T1318f2Str(v, sid); coopown::GdcPutI32(v, 0);
    if (dead >= 0) { coopown::GdcPutI32(v, 1); T1318f2Str(v, "dead"); v->push_back((char)(dead != 0 ? 1 : 0)); } else coopown::GdcPutI32(v, 0);
    coopown::GdcPutI32(v, 0);
    if (handS > 0) { coopown::GdcPutI32(v, 2); T1318f2Str(v, "handleS"); coopown::GdcPutI32(v, handS); T1318f2Str(v, "handleTYPE"); coopown::GdcPutI32(v, 1); } else coopown::GdcPutI32(v, 0);
    for (int m = 3; m < 7; ++m) coopown::GdcPutI32(v, 0);
    coopown::GdcPutI32(v, 0);   /* no reference lists */
    coopown::GdcPutI32(v, (int)inst.size());
    for (size_t i = 0; i < inst.size(); ++i)
    {
        T1318f2Str(v, "m"); T1318f2Str(v, "t");
        for (int k = 0; k < 7; ++k) coopown::GdcPutI32(v, 0);   /* 12 + 16 bytes */
        coopown::GdcPutI32(v, (int)inst[i].size());
        for (size_t j = 0; j < inst[i].size(); ++j) T1318f2Str(v, inst[i][j]);
    }
}
void t_t1318_a4f2_rule()
{
    using namespace cooplo;
    /* LOW-B: each record's death from the records the engine holds - the squad record's instance names the person's 0x39 medical record */
    {
        std::vector<char> b;
        coopown::GdcPutI32(&b, 0); coopown::GdcPutI32(&b, 0); coopown::GdcPutI32(&b, 8);
        std::vector<std::vector<std::string> > inst(4);
        inst[0].push_back("c1"); inst[0].push_back("m1"); inst[1].push_back("c2"); inst[1].push_back("m2"); inst[2].push_back("c3"); inst[3].push_back("c4"); inst[3].push_back("m4");
        T1318f2Rec(&b, 0x1E, "sq", 0, -1, inst);
        const std::vector<std::vector<std::string> > none;
        T1318f2Rec(&b, 0x24, "c1", 901, -1, none); T1318f2Rec(&b, 0x39, "m1", 0, 1, none);    /* a corpse removed before the living put-aways */
        T1318f2Rec(&b, 0x24, "c2", 902, -1, none); T1318f2Rec(&b, 0x39, "m2", 0, 0, none);    /* alive */
        T1318f2Rec(&b, 0x24, "c3", 903, -1, none);                                             /* no medical record among its states: unread */
        T1318f2Rec(&b, 0x24, "c4", 904, -1, none); T1318f2Rec(&b, 0x39, "m4", 0, -1, none);   /* no "dead" field: alive, as the engine's load reads it */
        std::vector<coopown::GdcRecSpan> rs; size_t end = 0;
        if (!coopown::GdcSpans(&b[0], b.size(), &end, &rs) || end != b.size() || rs.size() != 8) { Fail("t1318 a4f2: the test container does not parse"); return; }
        if (rs[2].dead != 1 || rs[4].dead != 0 || rs[7].dead != -1 || rs[1].dead != -1) Fail("t1318 a4f2: a record's \"dead\" field misread");
        std::vector<int> d; coopown::GdcCharDeadOf(rs, &d);
        if (d.size() != 4 || d[0] != 1 || d[1] != 0 || d[2] != -1 || d[3] != 0) Fail("t1318 a4f2: a person's death from the records misread");
        std::vector<std::string> recs; for (size_t i = 0; i < rs.size(); ++i) if (rs[i].type == 0x24) recs.push_back(rs[i].hand);
        int skipped = 0, unread = 0;
        const std::set<std::string> acc;
        if (SleepRecordsKept(recs, acc, &d, &skipped, &unread) != 3 || skipped != 1 || unread != 1) Fail("t1318 a4f2: a corpse's record counted kept, or an unread death not kept and counted");
        if (SleepRecordsKept(recs, acc) != 4) Fail("t1318 a4f2: the records rule without deaths changed");
        /* the same record accounted for (in the batch) is not counted at all */
        std::set<std::string> acc1; acc1.insert(recs[0]); acc1.insert(recs[2]); skipped = unread = 0;
        if (SleepRecordsKept(recs, acc1, &d, &skipped, &unread) != 2 || skipped != 0 || unread != 0) Fail("t1318 a4f2: an accounted record counted dead / unread");
        /* a death list shorter than the records: the rest unread - kept */
        std::vector<int> shortD(1, 1); skipped = unread = 0;
        if (SleepRecordsKept(recs, acc, &shortD, &skipped, &unread) != 3 || skipped != 1 || unread != 3) Fail("t1318 a4f2: a record with no death entry not kept");
        /* a record with no hand: kept whatever its death */
        std::vector<std::string> nh(1, std::string()); std::vector<int> nd(1, 1);
        if (SleepRecordsKept(nh, acc, &nd) != 1) Fail("t1318 a4f2: a record with no hand dropped as a corpse");
        /* T2343's Starving Bandits_19 with one of its 6 never-numbered a corpse removed first: 5 kept - never offered; all 6 corpses: offered whole */
        std::vector<std::string> sb; std::set<std::string> sbAcc; std::vector<int> sbD(9, 0);
        for (unsigned int i = 0; i < 9; ++i) sb.push_back(HandKey(700 + i, 1));
        for (unsigned int i = 0; i < 3; ++i) sbAcc.insert(HandKey(700 + i, 1));
        sbD[8] = 1;
        if (SleepRecordsKept(sb, sbAcc, &sbD) != 5 || HeldReleaseDecideUnacc(3, 0, 0, SleepRecordsKept(sb, sbAcc, &sbD), 0) != kHdKeptOut) Fail("t1318 a4f2: the living never-numbered not kept beside a corpse");
        for (int i = 3; i < 9; ++i) sbD[i] = 1;
        if (SleepRecordsKept(sb, sbAcc, &sbD) != 0 || HeldReleaseDecideUnacc(3, 0, 0, 0, 0) != kHdOffer) Fail("t1318 a4f2: a squad whose others are all corpses not offered whole");
    }
    /* LOW-A: no awake list and the records unread - held, never offered; ended by the records read, the squad gone, the cap */
    if (RecordsUnreadStep(1, 0, kRuTryCap) != kRuHold || RecordsUnreadStep(0, 0, kRuTryCap) != kRuHold || RecordsUnreadStep(0, 1, kRuTryCap) != kRuHold)
        Fail("t1318 a4f2: a squad whose records are not read yet (put away this frame) not held");
    if (RecordsUnreadStep(0, 2, kRuTryCap) != kRuKeptGone || RecordsUnreadStep(1, 2, kRuTryCap) != kRuHold || RecordsUnreadStep(1, kRuTryCap - 1, kRuTryCap) != kRuHold)
        Fail("t1318 a4f2: the hold's 'squad gone' end wrong");
    if (RecordsUnreadStep(1, kRuTryCap, kRuTryCap) != kRuKeptCap || RecordsUnreadStep(0, kRuTryCap + 5, kRuTryCap) != kRuKeptCap || kRuTryCap < 3 || kRuTryCap > 120)
        Fail("t1318 a4f2: the records-unread hold is not bounded");
    /* MEDIUM-A: a queued re-made given body destroyed only while its identity still holds */
    if (coopsquad::GivenRemakeDrainStep(1, 0, 0, 1, 1, 1) != coopsquad::kGrDestroy) Fail("t1318 a4f2: a re-made given body still so not removed");
    if (coopsquad::GivenRemakeDrainStep(0, 0, 0, 1, 1, 1) != coopsquad::kGrGone || coopsquad::GivenRemakeDrainStep(1, 77, 0, 1, 1, 1) != coopsquad::kGrNumbered)
        Fail("t1318 a4f2: a body gone or numbered since not dropped");
    if (coopsquad::GivenRemakeDrainStep(1, 0, 1, 1, 1, 1) != coopsquad::kGrPlayer || coopsquad::GivenRemakeDrainStep(1, 0, -1, 1, 1, 1) != coopsquad::kGrPlayer)
        Fail("t1318 a4f2: a player's character (or one whose faction did not read) destroyed");
    if (coopsquad::GivenRemakeDrainStep(1, 0, 0, 0, 1, 1) != coopsquad::kGrNoKey || coopsquad::GivenRemakeDrainStep(1, 0, 0, 1, 0, 1) != coopsquad::kGrNotGiven
        || coopsquad::GivenRemakeDrainStep(1, 0, 0, 1, -1, 1) != coopsquad::kGrNotGiven || coopsquad::GivenRemakeDrainStep(1, 0, 0, 1, 1, 0) != coopsquad::kGrNotWoke)
        Fail("t1318 a4f2: a body whose squad key, own hand or squad's wake no longer holds destroyed (an address reused since the queue)");
}
